window.CFA_DEEP_PM=[{"module_id":"CFA26-09-01","subject":"Portfolio Management","module_title":"Portfolio Risk and Return: Part I","level":"CFA Level I 2026","status":"Source-mapped detailed academic draft; not independently certified","language":"Vietnamese explanations, English financial terms and exam questions","source_policy":"Original explanations and questions; source-mapped to CFAI 2026 Volume 9, Kaplan Book 4 and SAPP PM slides; selected QBank patterns reviewed without copying stems","disclaimer_vi":"Bản học chi tiết dạng draft tự biên soạn. Dữ liệu lịch sử không đảm bảo lợi suất tương lai. Công thức dùng cùng kỳ, cùng đơn vị và điều kiện ghi rõ. Chưa thẩm định học thuật độc lập từng dòng và mọi câu hỏi.","los":[{"id":"CFA26-09-01-LOS01","letter":"a","title_en":"Major Asset Classes and Investment Characteristics","outcome_en":"describe the key characteristics of major asset classes used in portfolio construction","overview_vi":"Bài học 1.a: Major Asset Classes and Investment Characteristics. Học định nghĩa, điều kiện, cách áp dụng, ví dụ và English MCQ. Nội dung theo LOS CFAI 2026; ví dụ số do dự án tự viết, không sao chép câu hỏi nguồn.","source":[{"id":"CFA Institute Curriculum 2026 — Portfolio Management Volume 9","pages":"Physical PDF p. 13 (LOS), 14–22, 44–46 (content)"},{"id":"Kaplan SchweserNotes 2026 — Book 4, Reading 83","pages":"Physical PDF pp. 67–68"},{"id":"SAPP CFA Level I 2026 — Portfolio Management slides","pages":"Physical PDF pp. 5–7"}],"sections":[{"heading":"Historical risk and return / Lịch sử lợi suất","body":"Các nhóm tài sản có khác biệt dài hạn về return và volatility. Cổ phiếu là residual claim, nên thường có lợi suất kỳ vọng và biến động lớn hơn trái phiếu. Government bills có kỳ hạn ngắn, rủi ro giá do lãi suất thấp hơn bond dài hạn. Dữ liệu lịch sử là bằng chứng về trade-off chứ không phải cam kết thứ hạng tương lai; so sánh phải thống nhất thời kỳ, tiền tệ và phương pháp tính.","trap":"Không suy ra cổ phiếu chắc chắn vượt trái phiếu trong từng năm."},{"heading":"Nominal versus real returns","body":"Nominal return đo tăng trưởng số tiền; real return đo tăng trưởng sức mua sau lạm phát. Với lạm phát π, real return = (1+nominal return)/(1+π) − 1; phép trừ chỉ là xấp xỉ. Cash có thể bảo toàn nominal principal nhưng vẫn mất sức mua; real return trái phiếu coupon cố định cũng chịu unexpected inflation.","trap":"So sánh asset returns cùng cơ sở real hoặc nominal; không trộn lẫn."},{"heading":"Equity and bond characteristics","body":"Common stock có dividend không cố định và upside từ tăng giá; bond có contractual payments và priority cao hơn equity khi thanh lý. Long-term government debt vẫn chịu duration và inflation risk; corporate bonds có thêm credit/default và liquidity risks. Large-cap và small-cap có khác biệt về quy mô, liquidity và risk; không được coi small-cap luôn có premium ở mỗi kỳ.","trap":"Government bond không đồng nghĩa risk-free tại mọi investment horizon."},{"heading":"Distribution: skewness and tail risk","body":"Mean và variance không mô tả đầy đủ phân phối. Negative skewness: đuôi trái dài, nguy cơ tổn thất lớn dù nhiều kỳ lời nhỏ; positive skewness có đuôi phải dài. Leptokurtic distributions có kurtosis cao hơn normal (normal kurtosis = 3; excess = 0), thường có tail risk lớn. Normal distribution được xác định bởi mean và variance; thực tế return có thể lệch chuẩn.","trap":"Kurtosis không phải hướng của skew; negative skew không có nghĩa mean âm."},{"heading":"Liquidity and trading costs","body":"Liquidity là khả năng giao dịch nhanh với chi phí và price impact thấp. Bid–ask spread là chi phí giao dịch ngầm; commissions là chi phí trực tiếp; order lớn có thể gây market impact. Tài sản không thanh khoản thường cần compensation nhưng mức premium không chắc chắn. Net realized return phụ thuộc chi phí, quy mô và turnover.","trap":"Không coi báo giá midpoint là giá chắc chắn có thể mua hoặc bán."},{"heading":"Other market characteristics","body":"Market size, trading frequency, availability of market information và regulatory environment ảnh hưởng khả năng xây dựng và tái cân bằng portfolio. Cross-country data chịu exchange-rate effects, inflation khác nhau và market development; dữ liệu cổ phiếu sống sót có thể thiên lệch. Phân loại tài sản theo nguồn risk, cash flows và liquidity thay vì chỉ theo tên sản phẩm.","trap":"Không so sánh nominal local-currency returns như thể cùng một purchasing power."},{"heading":"Asset-class inclusion and cost","body":"Theo khung lựa chọn CFAI, nhóm tài sản cần đủ khác biệt về risk–return, mutually exclusive khi phân loại, đủ lớn để đầu tư và khả thi về access/transaction costs. Index funds có thể cho small portfolio exposure rộng với chi phí thấp hơn mua từng security. So sánh diversification benefit với trading và monitoring cost.","trap":"Không đưa tài sản mới chỉ vì tên asset class khác nếu exposures trùng nhau."}],"formulas":[{"name":"Real return","expr":"(1+Rnom)/(1+π) − 1","meaning":"Lợi suất sức mua sau lạm phát.","conditions":"Rnom, π cùng kỳ; decimal."},{"name":"Risk premium","expr":"E(Rasset) − Rf","meaning":"Phần bù kỳ vọng so với tài sản phi rủi ro.","conditions":"So sánh cùng kỳ và basis nominal/real."},{"name":"Round-trip quoted spread","expr":"Ask − Bid","meaning":"Chi phí spread mỗi đơn vị nếu mua ask bán bid ngay.","conditions":"Không gồm commission, impact, thuế; bid/ask cùng thời điểm."}],"examples":[{"question_en":"A pension plan must pay a fixed nominal liability in six months. It is considering small-company stocks or short-term government bills as the funding asset. Which asset better matches the short horizon, and why?","steps_vi":["Xác định liability nominal với kỳ hạn sáu tháng, nên ưu tiên stability of terminal nominal value.","Bills matching the horizon have lower interest-rate and equity-price risk; small-company stocks may have a long-run premium but high short-run volatility."],"answer":"Short-term government bills, subject to issuer and currency assumptions.","check":"Conceptual case; interpretation conditional on stated assumptions."},{"question_en":"An asset earns 8.6% nominally while inflation is 3.2%. What is its real return (%)?","steps_vi":["Real return dùng gross return ratio, không chỉ lấy 8.6−3.2.","Thay số: 100 × (1.086/1.032-1).","Kết quả: 5.23%."],"answer":"5.23%","check":"Original worked case; Decimal value compared with alternate Fraction expression (square root checked using float)."},{"question_en":"An asset has expected return 9.4% and the risk-free rate is 3.1%. What is its expected risk premium in percentage points?","steps_vi":["Trừ risk-free rate cùng kỳ khỏi expected nominal return.","Thay số: 9.4-3.1.","Kết quả: 6.30 pp."],"answer":"6.30 pp","check":"Original worked case; Decimal value compared with alternate Fraction expression (square root checked using float)."},{"question_en":"A stock is quoted bid $47.80, ask $48.20. An investor buys and immediately sells 300 shares at these quotes. Ignoring commissions and impact, what is the round-trip spread cost in dollars?","steps_vi":["Mua theo ask và bán theo bid; multiply spread by shares.","Thay số: 300 × (48.20-47.80).","Kết quả: 120.00 USD."],"answer":"120.00 USD","check":"Original worked case; Decimal value compared with alternate Fraction expression (square root checked using float)."}],"questions":[{"stem_en":"Which statement about historical asset-class returns is most accurate?","options":["Higher-risk asset classes have generally earned higher long-run returns, but not in every period.","Equities must outperform bills in each calendar year.","Historical averages are guaranteed future returns."],"correct":0,"why_vi":"Các nhóm tài sản có khác biệt dài hạn về return và volatility. Cổ phiếu là residual claim, nên thường có lợi suất kỳ vọng và biến động lớn hơn trái phiếu. Government bills có kỳ hạn ngắn, rủi ro giá do lãi suất thấp hơn bond dài hạn. Dữ liệu lịch sử là bằng chứng về trade-off chứ không phải cam kết thứ hạng tương lai; so sánh phải thống nhất thời kỳ, tiền tệ và phương pháp tính.","trap_vi":"Không suy ra cổ phiếu chắc chắn vượt trái phiếu trong từng năm."},{"stem_en":"A bill earns a positive nominal return below the inflation rate. Its real return is most likely:","options":["equal to its nominal return.","negative.","positive because its principal is stable."],"correct":1,"why_vi":"Nominal return đo tăng trưởng số tiền; real return đo tăng trưởng sức mua sau lạm phát. Với lạm phát π, real return = (1+nominal return)/(1+π) − 1; phép trừ chỉ là xấp xỉ. Cash có thể bảo toàn nominal principal nhưng vẫn mất sức mua; real return trái phiếu coupon cố định cũng chịu unexpected inflation.","trap_vi":"So sánh asset returns cùng cơ sở real hoặc nominal; không trộn lẫn."},{"stem_en":"Compared with short-term Treasury bills, long-term fixed-rate government bonds generally have greater exposure to:","options":["issuer-specific equity dividend risk.","commodity inventory risk.","interest rate risk."],"correct":2,"why_vi":"Common stock có dividend không cố định và upside từ tăng giá; bond có contractual payments và priority cao hơn equity khi thanh lý. Long-term government debt vẫn chịu duration và inflation risk; corporate bonds có thêm credit/default và liquidity risks. Large-cap và small-cap có khác biệt về quy mô, liquidity và risk; không được coi small-cap luôn có premium ở mỗi kỳ.","trap_vi":"Government bond không đồng nghĩa risk-free tại mọi investment horizon."},{"stem_en":"A strategy earns small gains frequently but suffers occasional severe losses. This pattern most directly suggests:","options":["positive skewness.","negative skewness.","zero variance."],"correct":1,"why_vi":"Mean và variance không mô tả đầy đủ phân phối. Negative skewness: đuôi trái dài, nguy cơ tổn thất lớn dù nhiều kỳ lời nhỏ; positive skewness có đuôi phải dài. Leptokurtic distributions có kurtosis cao hơn normal (normal kurtosis = 3; excess = 0), thường có tail risk lớn. Normal distribution được xác định bởi mean và variance; thực tế return có thể lệch chuẩn.","trap_vi":"Kurtosis không phải hướng của skew; negative skew không có nghĩa mean âm."},{"stem_en":"A wide bid–ask spread most directly increases an investor's:","options":["contractual coupon rate.","implicit transaction costs.","risk-free interest rate."],"correct":1,"why_vi":"Liquidity là khả năng giao dịch nhanh với chi phí và price impact thấp. Bid–ask spread là chi phí giao dịch ngầm; commissions là chi phí trực tiếp; order lớn có thể gây market impact. Tài sản không thanh khoản thường cần compensation nhưng mức premium không chắc chắn. Net realized return phụ thuộc chi phí, quy mô và turnover.","trap_vi":"Không coi báo giá midpoint là giá chắc chắn có thể mua hoặc bán."},{"stem_en":"For an investor comparing returns in two countries, a sound first step is to:","options":["express returns in a consistent currency and inflation basis.","ignore differences in inflation and exchange rates.","compare only each market's highest annual return."],"correct":0,"why_vi":"Market size, trading frequency, availability of market information và regulatory environment ảnh hưởng khả năng xây dựng và tái cân bằng portfolio. Cross-country data chịu exchange-rate effects, inflation khác nhau và market development; dữ liệu cổ phiếu sống sót có thể thiên lệch. Phân loại tài sản theo nguồn risk, cash flows và liquidity thay vì chỉ theo tên sản phẩm.","trap_vi":"Không so sánh nominal local-currency returns như thể cùng một purchasing power."},{"stem_en":"For a small portfolio seeking broad exposure across many securities, a low-cost diversified index fund may primarily help by:","options":["reducing the cost of obtaining diversification.","guaranteeing a higher market risk premium.","eliminating all systematic risk."],"correct":0,"why_vi":"Theo khung lựa chọn CFAI, nhóm tài sản cần đủ khác biệt về risk–return, mutually exclusive khi phân loại, đủ lớn để đầu tư và khả thi về access/transaction costs. Index funds có thể cho small portfolio exposure rộng với chi phí thấp hơn mua từng security. So sánh diversification benefit với trading và monitoring cost.","trap_vi":"Không đưa tài sản mới chỉ vì tên asset class khác nếu exposures trùng nhau."},{"stem_en":"An asset earns 8.6% nominally while inflation is 3.2%. What is its real return (%)?","options":["5.40%","8.60%","5.23%"],"correct":2,"why_vi":"Real return dùng gross return ratio, không chỉ lấy 8.6−3.2. Thay số: 100 × (1.086/1.032-1) = 5.23%.","trap_vi":"Dùng subtraction approximation hoặc bỏ inflation."},{"stem_en":"An asset has expected return 9.4% and the risk-free rate is 3.1%. What is its expected risk premium in percentage points?","options":["9.40 pp","6.30 pp","12.50 pp"],"correct":1,"why_vi":"Trừ risk-free rate cùng kỳ khỏi expected nominal return. Thay số: 9.4-3.1 = 6.30 pp.","trap_vi":"Nhầm return tổng hoặc cộng risk-free thay vì trừ."},{"stem_en":"A stock is quoted bid $47.80, ask $48.20. An investor buys and immediately sells 300 shares at these quotes. Ignoring commissions and impact, what is the round-trip spread cost in dollars?","options":["120.00 USD","60.00 USD","240.00 USD"],"correct":0,"why_vi":"Mua theo ask và bán theo bid; multiply spread by shares. Thay số: 300 × (48.20-47.80) = 120.00 USD.","trap_vi":"Lấy half-spread hoặc double-count round trip."}],"cards":[{"front_en":"Historical risk and return / Lịch sử lợi suất","back_vi":"Các nhóm tài sản có khác biệt dài hạn về return và volatility. Cổ phiếu là residual claim, nên thường có lợi suất kỳ vọng và biến động lớn hơn trái phiếu. Government bills có kỳ hạn ngắn, rủi ro giá do lãi suất thấp hơn bond dài hạn. Dữ liệu lịch sử là bằng chứng về trade-off chứ không phải cam kết thứ hạng tương lai; so sánh phải thống nhất thời kỳ, tiền tệ và phương pháp tính. | Exam trap: Không suy ra cổ phiếu chắc chắn vượt trái phiếu trong từng năm."},{"front_en":"Nominal versus real returns","back_vi":"Nominal return đo tăng trưởng số tiền; real return đo tăng trưởng sức mua sau lạm phát. Với lạm phát π, real return = (1+nominal return)/(1+π) − 1; phép trừ chỉ là xấp xỉ. Cash có thể bảo toàn nominal principal nhưng vẫn mất sức mua; real return trái phiếu coupon cố định cũng chịu unexpected inflation. | Exam trap: So sánh asset returns cùng cơ sở real hoặc nominal; không trộn lẫn."},{"front_en":"Equity and bond characteristics","back_vi":"Common stock có dividend không cố định và upside từ tăng giá; bond có contractual payments và priority cao hơn equity khi thanh lý. Long-term government debt vẫn chịu duration và inflation risk; corporate bonds có thêm credit/default và liquidity risks. Large-cap và small-cap có khác biệt về quy mô, liquidity và risk; không được coi small-cap luôn có premium ở mỗi kỳ. | Exam trap: Government bond không đồng nghĩa risk-free tại mọi investment horizon."},{"front_en":"Distribution: skewness and tail risk","back_vi":"Mean và variance không mô tả đầy đủ phân phối. Negative skewness: đuôi trái dài, nguy cơ tổn thất lớn dù nhiều kỳ lời nhỏ; positive skewness có đuôi phải dài. Leptokurtic distributions có kurtosis cao hơn normal (normal kurtosis = 3; excess = 0), thường có tail risk lớn. Normal distribution được xác định bởi mean và variance; thực tế return có thể lệch chuẩn. | Exam trap: Kurtosis không phải hướng của skew; negative skew không có nghĩa mean âm."},{"front_en":"Liquidity and trading costs","back_vi":"Liquidity là khả năng giao dịch nhanh với chi phí và price impact thấp. Bid–ask spread là chi phí giao dịch ngầm; commissions là chi phí trực tiếp; order lớn có thể gây market impact. Tài sản không thanh khoản thường cần compensation nhưng mức premium không chắc chắn. Net realized return phụ thuộc chi phí, quy mô và turnover. | Exam trap: Không coi báo giá midpoint là giá chắc chắn có thể mua hoặc bán."},{"front_en":"Other market characteristics","back_vi":"Market size, trading frequency, availability of market information và regulatory environment ảnh hưởng khả năng xây dựng và tái cân bằng portfolio. Cross-country data chịu exchange-rate effects, inflation khác nhau và market development; dữ liệu cổ phiếu sống sót có thể thiên lệch. Phân loại tài sản theo nguồn risk, cash flows và liquidity thay vì chỉ theo tên sản phẩm. | Exam trap: Không so sánh nominal local-currency returns như thể cùng một purchasing power."},{"front_en":"Asset-class inclusion and cost","back_vi":"Theo khung lựa chọn CFAI, nhóm tài sản cần đủ khác biệt về risk–return, mutually exclusive khi phân loại, đủ lớn để đầu tư và khả thi về access/transaction costs. Index funds có thể cho small portfolio exposure rộng với chi phí thấp hơn mua từng security. So sánh diversification benefit với trading và monitoring cost. | Exam trap: Không đưa tài sản mới chỉ vì tên asset class khác nếu exposures trùng nhau."},{"front_en":"Real return — formula and conditions?","back_vi":"(1+Rnom)/(1+π) − 1 · Lợi suất sức mua sau lạm phát. · Rnom, π cùng kỳ; decimal."},{"front_en":"Risk premium — formula and conditions?","back_vi":"E(Rasset) − Rf · Phần bù kỳ vọng so với tài sản phi rủi ro. · So sánh cùng kỳ và basis nominal/real."},{"front_en":"Round-trip quoted spread — formula and conditions?","back_vi":"Ask − Bid · Chi phí spread mỗi đơn vị nếu mua ask bán bid ngay. · Không gồm commission, impact, thuế; bid/ask cùng thời điểm."},{"front_en":"An asset earns 8.6% nominally while inflation is 3.2%. What is its real return (%)?","back_vi":"Real return dùng gross return ratio, không chỉ lấy 8.6−3.2. Thay số: 100 × (1.086/1.032-1) = 5.23%."},{"front_en":"An asset has expected return 9.4% and the risk-free rate is 3.1%. What is its expected risk premium in percentage points?","back_vi":"Trừ risk-free rate cùng kỳ khỏi expected nominal return. Thay số: 9.4-3.1 = 6.30 pp."},{"front_en":"A stock is quoted bid $47.80, ask $48.20. An investor buys and immediately sells 300 shares at these quotes. Ignoring commissions and impact, what is the round-trip spread cost in dollars?","back_vi":"Mua theo ask và bán theo bid; multiply spread by shares. Thay số: 300 × (48.20-47.80) = 120.00 USD."}]},{"id":"CFA26-09-01-LOS02","letter":"b","title_en":"Risk Aversion and Utility","outcome_en":"explain risk aversion and its implications for portfolio choice","overview_vi":"Bài học 1.b: Risk Aversion and Utility. Học định nghĩa, điều kiện, cách áp dụng, ví dụ và English MCQ. Nội dung theo LOS CFAI 2026; ví dụ số do dự án tự viết, không sao chép câu hỏi nguồn.","source":[{"id":"CFA Institute Curriculum 2026 — Portfolio Management Volume 9","pages":"Physical PDF p. 13 (LOS), 22–31 (content)"},{"id":"Kaplan SchweserNotes 2026 — Book 4, Reading 83","pages":"Physical PDF pp. 68–71"},{"id":"SAPP CFA Level I 2026 — Portfolio Management slides","pages":"Physical PDF pp. 8–15"}],"sections":[{"heading":"Risk aversion / Ngại rủi ro","body":"Risk-averse investor thích khoản chắc chắn hơn gamble có cùng expected payoff. Để chấp nhận thêm uncertainty, họ đòi expected return lớn hơn. Risk aversion không có nghĩa từ chối mọi tài sản rủi ro; quyết định phụ thuộc phần bù kỳ vọng và khả năng chấp nhận variance.","trap":"Risk-averse không đồng nghĩa chỉ mua risk-free asset."},{"heading":"Risk neutral and risk loving","body":"Risk-neutral investor đánh giá lựa chọn bằng expected return, không phạt variance trong mô hình đơn giản; risk-seeking investor ưu tiên variance cao hơn khi expected return bằng nhau. Hệ số A của mean–variance utility lần lượt dương, bằng 0 và âm.","trap":"Không nhầm risk tolerance cao với risk-neutral; một người A=1 vẫn risk-averse."},{"heading":"Mean–variance utility","body":"Utility U = E(R) − 0.5Aσ² là thước đo xếp hạng theo expected return và variance. Dùng returns dạng decimal, cùng kỳ; với A>0, variance bị phạt, A lớn thì penalty lớn hơn. U có thể âm, không phải expected cash return hoặc probability.","trap":"Đưa standard deviation bình phương; không trừ trực tiếp Aσ."},{"heading":"Indifference curves","body":"Trên đồ thị E(R) theo σ, cùng U tạo đường E(R)=U+0.5Aσ². Với A>0, curve dốc lên và convex; investor đòi marginal return Aσ để tăng risk. Higher utility nằm phía trên/trái; các đường của cùng người không giao nhau vì mỗi điểm có một utility.","trap":"Indifference curve không phải feasible frontier; nó mô tả sở thích."},{"heading":"Dominance and consistency","body":"Nếu hai tài sản có expected return bằng nhau, người A>0 chọn variance thấp; nếu variance bằng nhau thì chọn E(R) cao. Nếu một danh mục risk và return đều cao hơn, cần tính U hoặc xem indifference curve, không thể kết luận chỉ từ một thuộc tính. Preferences được giả định nhất quán và transitive.","trap":"Không xếp hạng danh mục chỉ theo Sharpe ratio khi câu hỏi cho A và U."}],"formulas":[{"name":"Mean–variance utility","expr":"U=E(R)−Aσ²/2","meaning":"Utility score; A>0 risk averse, A=0 neutral, A<0 seeking.","conditions":"Decimal, cùng horizon, utility approximation."},{"name":"Indifference curve","expr":"E(R)=U+Aσ²/2","meaning":"Expected return cần thiết để giữ U không đổi.","conditions":"A cố định; slope Aσ trong mean–SD space."}],"examples":[{"question_en":"Fund X and Y each have 9% expected return; X has volatility 12% and Y 20%. Investor A is risk-averse while investor B is risk-neutral. How do their rankings differ?","steps_vi":["Cùng expected return, nên A>0 làm utility giảm khi variance tăng.","Risk-neutral B ignores variance in the specified mean–variance utility, so has no preference between equal means."],"answer":"A prefers X; B is indifferent.","check":"Conceptual case; interpretation conditional on stated assumptions."},{"question_en":"A portfolio has expected return 0.11, standard deviation 0.20, and investor A=3. Calculate mean–variance utility as a decimal.","steps_vi":["Variance bằng 0.04; penalty bằng 0.06.","Thay số: .11-3 × .20^2/2.","Kết quả: 0.0500 decimal."],"answer":"0.0500 decimal","check":"Original worked case; Decimal value compared with alternate Fraction expression (square root checked using float)."},{"question_en":"An investor with A=4 requires utility 0.03. What expected return (%) is needed at standard deviation 0.18?","steps_vi":["Giải E(R)=U+Aσ²/2; dùng decimal rồi chuyển sang percent.","Thay số: 100 × (.03+4 × .18^2/2).","Kết quả: 9.48%."],"answer":"9.48%","check":"Original worked case; Decimal value compared with alternate Fraction expression (square root checked using float)."},{"question_en":"For a risk-neutral investor A=0, a portfolio has expected return 6.5% and standard deviation 25%. Calculate utility as a percentage-equivalent score.","steps_vi":["A=0 nên penalty variance bằng zero.","Thay số: 100 × (.065-0 × .25^2/2).","Kết quả: 6.50%."],"answer":"6.50%","check":"Original worked case; Decimal value compared with alternate Fraction expression (square root checked using float)."}],"questions":[{"stem_en":"An investor prefers a certain $100 to a risky payoff with expected value $100. The investor is:","options":["risk averse.","risk neutral.","risk seeking."],"correct":0,"why_vi":"Risk-averse investor thích khoản chắc chắn hơn gamble có cùng expected payoff. Để chấp nhận thêm uncertainty, họ đòi expected return lớn hơn. Risk aversion không có nghĩa từ chối mọi tài sản rủi ro; quyết định phụ thuộc phần bù kỳ vọng và khả năng chấp nhận variance.","trap_vi":"Risk-averse không đồng nghĩa chỉ mua risk-free asset."},{"stem_en":"An investor indifferent between two portfolios with the same expected return but different variances is most consistent with:","options":["strict risk aversion.","risk neutrality.","a preference for lower variance."],"correct":1,"why_vi":"Risk-neutral investor đánh giá lựa chọn bằng expected return, không phạt variance trong mô hình đơn giản; risk-seeking investor ưu tiên variance cao hơn khi expected return bằng nhau. Hệ số A của mean–variance utility lần lượt dương, bằng 0 và âm.","trap_vi":"Không nhầm risk tolerance cao với risk-neutral; một người A=1 vẫn risk-averse."},{"stem_en":"When the risk-aversion coefficient increases, holding expected return and variance fixed, mean–variance utility:","options":["decreases.","increases.","is unchanged for every risky portfolio."],"correct":0,"why_vi":"Utility U = E(R) − 0.5Aσ² là thước đo xếp hạng theo expected return và variance. Dùng returns dạng decimal, cùng kỳ; với A>0, variance bị phạt, A lớn thì penalty lớn hơn. U có thể âm, không phải expected cash return hoặc probability.","trap_vi":"Đưa standard deviation bình phương; không trừ trực tiếp Aσ."},{"stem_en":"For a risk-averse investor, an indifference curve in mean–standard deviation space is generally:","options":["upward sloping and convex.","horizontal at all levels of risk.","downward sloping and concave."],"correct":0,"why_vi":"Trên đồ thị E(R) theo σ, cùng U tạo đường E(R)=U+0.5Aσ². Với A>0, curve dốc lên và convex; investor đòi marginal return Aσ để tăng risk. Higher utility nằm phía trên/trái; các đường của cùng người không giao nhau vì mỗi điểm có một utility.","trap_vi":"Indifference curve không phải feasible frontier; nó mô tả sở thích."},{"stem_en":"Portfolio X and Y have equal volatility, but X has higher expected return. A risk-averse investor generally prefers:","options":["Y.","X.","neither, because their variances are equal."],"correct":1,"why_vi":"Nếu hai tài sản có expected return bằng nhau, người A>0 chọn variance thấp; nếu variance bằng nhau thì chọn E(R) cao. Nếu một danh mục risk và return đều cao hơn, cần tính U hoặc xem indifference curve, không thể kết luận chỉ từ một thuộc tính. Preferences được giả định nhất quán và transitive.","trap_vi":"Không xếp hạng danh mục chỉ theo Sharpe ratio khi câu hỏi cho A và U."},{"stem_en":"A portfolio has expected return 0.11, standard deviation 0.20, and investor A=3. Calculate mean–variance utility as a decimal.","options":["-0.0100 decimal","0.1700 decimal","0.0500 decimal"],"correct":2,"why_vi":"Variance bằng 0.04; penalty bằng 0.06. Thay số: .11-3 × .20^2/2 = 0.0500 decimal.","trap_vi":"Bỏ 1/2 hoặc đổi dấu variance penalty."},{"stem_en":"An investor with A=4 requires utility 0.03. What expected return (%) is needed at standard deviation 0.18?","options":["3.00%","15.96%","9.48%"],"correct":2,"why_vi":"Giải E(R)=U+Aσ²/2; dùng decimal rồi chuyển sang percent. Thay số: 100 × (.03+4 × .18^2/2) = 9.48%.","trap_vi":"Bỏ risk penalty hoặc thiếu 1/2."},{"stem_en":"For a risk-neutral investor A=0, a portfolio has expected return 6.5% and standard deviation 25%. Calculate utility as a percentage-equivalent score.","options":["3.38%","6.50%","-18.50%"],"correct":1,"why_vi":"A=0 nên penalty variance bằng zero. Thay số: 100 × (.065-0 × .25^2/2) = 6.50%.","trap_vi":"Giả định A=1 hoặc trừ volatility trực tiếp."}],"cards":[{"front_en":"Risk aversion / Ngại rủi ro","back_vi":"Risk-averse investor thích khoản chắc chắn hơn gamble có cùng expected payoff. Để chấp nhận thêm uncertainty, họ đòi expected return lớn hơn. Risk aversion không có nghĩa từ chối mọi tài sản rủi ro; quyết định phụ thuộc phần bù kỳ vọng và khả năng chấp nhận variance. | Exam trap: Risk-averse không đồng nghĩa chỉ mua risk-free asset."},{"front_en":"Risk neutral and risk loving","back_vi":"Risk-neutral investor đánh giá lựa chọn bằng expected return, không phạt variance trong mô hình đơn giản; risk-seeking investor ưu tiên variance cao hơn khi expected return bằng nhau. Hệ số A của mean–variance utility lần lượt dương, bằng 0 và âm. | Exam trap: Không nhầm risk tolerance cao với risk-neutral; một người A=1 vẫn risk-averse."},{"front_en":"Mean–variance utility","back_vi":"Utility U = E(R) − 0.5Aσ² là thước đo xếp hạng theo expected return và variance. Dùng returns dạng decimal, cùng kỳ; với A>0, variance bị phạt, A lớn thì penalty lớn hơn. U có thể âm, không phải expected cash return hoặc probability. | Exam trap: Đưa standard deviation bình phương; không trừ trực tiếp Aσ."},{"front_en":"Indifference curves","back_vi":"Trên đồ thị E(R) theo σ, cùng U tạo đường E(R)=U+0.5Aσ². Với A>0, curve dốc lên và convex; investor đòi marginal return Aσ để tăng risk. Higher utility nằm phía trên/trái; các đường của cùng người không giao nhau vì mỗi điểm có một utility. | Exam trap: Indifference curve không phải feasible frontier; nó mô tả sở thích."},{"front_en":"Dominance and consistency","back_vi":"Nếu hai tài sản có expected return bằng nhau, người A>0 chọn variance thấp; nếu variance bằng nhau thì chọn E(R) cao. Nếu một danh mục risk và return đều cao hơn, cần tính U hoặc xem indifference curve, không thể kết luận chỉ từ một thuộc tính. Preferences được giả định nhất quán và transitive. | Exam trap: Không xếp hạng danh mục chỉ theo Sharpe ratio khi câu hỏi cho A và U."},{"front_en":"Mean–variance utility — formula and conditions?","back_vi":"U=E(R)−Aσ²/2 · Utility score; A>0 risk averse, A=0 neutral, A<0 seeking. · Decimal, cùng horizon, utility approximation."},{"front_en":"Indifference curve — formula and conditions?","back_vi":"E(R)=U+Aσ²/2 · Expected return cần thiết để giữ U không đổi. · A cố định; slope Aσ trong mean–SD space."},{"front_en":"A portfolio has expected return 0.11, standard deviation 0.20, and investor A=3. Calculate mean–variance utility as a decimal.","back_vi":"Variance bằng 0.04; penalty bằng 0.06. Thay số: .11-3 × .20^2/2 = 0.0500 decimal."},{"front_en":"An investor with A=4 requires utility 0.03. What expected return (%) is needed at standard deviation 0.18?","back_vi":"Giải E(R)=U+Aσ²/2; dùng decimal rồi chuyển sang percent. Thay số: 100 × (.03+4 × .18^2/2) = 9.48%."},{"front_en":"For a risk-neutral investor A=0, a portfolio has expected return 6.5% and standard deviation 25%. Calculate utility as a percentage-equivalent score.","back_vi":"A=0 nên penalty variance bằng zero. Thay số: 100 × (.065-0 × .25^2/2) = 6.50%."}]},{"id":"CFA26-09-01-LOS03","letter":"c","title_en":"Optimal Complete Portfolio and CAL","outcome_en":"explain optimal portfolio selection given investor utility and the capital allocation line","overview_vi":"Bài học 1.c: Optimal Complete Portfolio and CAL. Học định nghĩa, điều kiện, cách áp dụng, ví dụ và English MCQ. Nội dung theo LOS CFAI 2026; ví dụ số do dự án tự viết, không sao chép câu hỏi nguồn.","source":[{"id":"CFA Institute Curriculum 2026 — Portfolio Management Volume 9","pages":"Physical PDF p. 13 (LOS), 28–31, 50–57 (content)"},{"id":"Kaplan SchweserNotes 2026 — Book 4, Reading 83","pages":"Physical PDF pp. 69–71, 79"},{"id":"SAPP CFA Level I 2026 — Portfolio Management slides","pages":"Physical PDF pp. 29–39"}],"sections":[{"heading":"Capital allocation line / Tập hợp khả thi","body":"CAL kết hợp risk-free asset F với một risky portfolio P: E(Rc)=Rf+y[E(Rp)−Rf], σc=yσp khi y≥0. Đường có intercept Rf và slope reward-to-variability. y=0 là chỉ giữ F; y=1 giữ P; 0<y<1 là lending; y>1 là borrowing nếu được phép.","trap":"CAL của một risky portfolio bất kỳ không nhất thiết là CML."},{"heading":"Utility-maximizing choice","body":"Optimal complete portfolio là điểm trên feasible CAL đạt utility cao nhất; tangency với highest attainable indifference curve khi nghiệm interior. Điểm phía trên CAL hấp dẫn nhưng không khả thi với set đã cho; điểm thấp hơn CAL bị dominated tại cùng σ khi khả thi. Các investor khác A có thể chọn các vị trí khác nhau trên cùng CAL.","trap":"Không chọn điểm có highest expected return nếu không xét risk penalty."},{"heading":"Optimal risky weight","body":"Thay E(Rc) và σc² vào U, tối đa hóa cho y*= [E(Rp)−Rf]/(Aσp²), với A>0, cùng borrowing/lending rate và unconstrained allocation. Đây là hệ quả của utility function CFAI; nếu giới hạn không vay, cắt nghiệm tại y=1; nếu không short và y âm thì giới hạn y=0. Nghiệm cần kiểm tra constraint.","trap":"Không dùng Aσ thay Aσ²; weight > 1 là leverage, không phải lỗi số học."},{"heading":"Separation of choice","body":"Việc xác định best risky portfolio dựa vào risk/return của investment set; sau đó investor chọn tỷ lệ giữa P và F theo A. Với cùng kỳ vọng và cùng risk-free rate, mọi người có thể dùng một tangency fund nhưng differing complete portfolios. Hạn chế vay, thuế và khác biệt kỳ vọng có thể phá kết quả đơn giản.","trap":"Không nhầm optimal risky portfolio với optimal complete portfolio."},{"heading":"Slope and trade-offs","body":"CAL slope = (E(Rp)−Rf)/σp; slope lớn hơn nghĩa expected excess return trên mỗi unit volatility lớn hơn. Với risk aversion dương và positive premium, đường dốc hơn từ cùng Rf tạo opportunities tốt hơn. Slope không dự báo realized return chắc chắn.","trap":"Độ dốc không phải beta hay covariance."}],"formulas":[{"name":"Complete return","expr":"E(Rc)=Rf+y[E(Rp)−Rf]","meaning":"y là fraction invested in risky portfolio.","conditions":"Same lending/borrowing rate."},{"name":"Complete standard deviation","expr":"σc=abs(y)σp","meaning":"Rf constant over horizon.","conditions":"y≥0 trong CAL thông thường."},{"name":"CAL slope","expr":"(E(Rp)−Rf)/σp","meaning":"Reward per unit total volatility.","conditions":"σp>0."},{"name":"Optimal risky allocation","expr":"y*=(E(Rp)−Rf)/(Aσp²)","meaning":"Nghiệm tối đa utility bằng đạo hàm; derived practice.","conditions":"A>0, unconstrained, same rates, consistent units."}],"examples":[{"question_en":"Two investors share the same positive-premium risky fund and risk-free asset. One has A=6 and the other A=2. Explain their complete portfolios under unconstrained equal-rate financing.","steps_vi":["Common opportunity set determines same CAL and same risky portfolio.","Higher A increases risk penalty and reduces optimal risky weight y*."],"answer":"The investor with A=6 has lower risky exposure, not necessarily a different risky fund.","check":"Conceptual case; interpretation conditional on stated assumptions."},{"question_en":"A risky fund has expected return 10%, volatility 20%, and the risk-free rate is 2%. An investor with A=4 can freely borrow or lend at the risk-free rate. Calculate the optimal risky weight (%).","steps_vi":["Maximize utility; derivative E(Rp)−Rf−A y σp²=0.","Thay số: 100 × (.10-.02)/(4 × .20^2).","Kết quả: 50.00%."],"answer":"50.00%","check":"Original worked case; Decimal value compared with alternate Fraction expression (square root checked using float)."},{"question_en":"An investor holds 65% in a risky portfolio returning an expected 12%, volatility 18%, and 35% in bills yielding 3%. What is the complete expected return (%)?","steps_vi":["Weighted return; cùng horizon.","Thay số: 3+.65 × (12-3).","Kết quả: 8.85%."],"answer":"8.85%","check":"Original worked case; Decimal value compared with alternate Fraction expression (square root checked using float)."},{"question_en":"Two feasible CALs begin at Rf=2%. Fund X has expected return 11% and volatility 15%. Calculate the CAL slope.","steps_vi":["Excess return chia total SD, hai đơn vị thống nhất.","Thay số: (.11-.02)/.15.","Kết quả: 0.600 ratio."],"answer":"0.600 ratio","check":"Original worked case; Decimal value compared with alternate Fraction expression (square root checked using float)."},{"question_en":"A risky fund's premium is 6%, volatility 15%, and A=2. With no borrowing or shorting permitted, what percentage of wealth is optimally invested in the fund?","steps_vi":["Unconstrained weight = .06/(2×.15²)=1.3333; constraint y≤1 binds.","Thay số: 100.","Kết quả: 100.00%."],"answer":"100.00%","check":"Original worked case; Decimal value compared with alternate Fraction expression (square root checked using float)."}],"questions":[{"stem_en":"A portfolio invests 40% in a risky fund and 60% in bills. Relative to the risky fund, its volatility is:","options":["40% as large.","60% as large.","unchanged."],"correct":0,"why_vi":"CAL kết hợp risk-free asset F với một risky portfolio P: E(Rc)=Rf+y[E(Rp)−Rf], σc=yσp khi y≥0. Đường có intercept Rf và slope reward-to-variability. y=0 là chỉ giữ F; y=1 giữ P; 0<y<1 là lending; y>1 là borrowing nếu được phép.","trap_vi":"CAL của một risky portfolio bất kỳ không nhất thiết là CML."},{"stem_en":"An interior optimum on a CAL is reached when:","options":["the highest attainable indifference curve is tangent to the CAL.","the lowest utility curve intersects the CAL.","portfolio standard deviation is necessarily zero."],"correct":0,"why_vi":"Optimal complete portfolio là điểm trên feasible CAL đạt utility cao nhất; tangency với highest attainable indifference curve khi nghiệm interior. Điểm phía trên CAL hấp dẫn nhưng không khả thi với set đã cho; điểm thấp hơn CAL bị dominated tại cùng σ khi khả thi. Các investor khác A có thể chọn các vị trí khác nhau trên cùng CAL.","trap_vi":"Không chọn điểm có highest expected return nếu không xét risk penalty."},{"stem_en":"All else equal, a higher risk-aversion coefficient implies that the unconstrained optimal weight in a positive-premium risky asset:","options":["decreases.","increases.","equals one regardless of risk."],"correct":0,"why_vi":"Thay E(Rc) và σc² vào U, tối đa hóa cho y*= [E(Rp)−Rf]/(Aσp²), với A>0, cùng borrowing/lending rate và unconstrained allocation. Đây là hệ quả của utility function CFAI; nếu giới hạn không vay, cắt nghiệm tại y=1; nếu không short và y âm thì giới hạn y=0. Nghiệm cần kiểm tra constraint.","trap_vi":"Không dùng Aσ thay Aσ²; weight > 1 là leverage, không phải lỗi số học."},{"stem_en":"Two investors share the same inputs but differ in risk aversion. Under two-fund separation, they most likely differ in:","options":["their allocation between the risky portfolio and the risk-free asset.","the composition of the common tangency risky portfolio.","the risk-free rate used for identical lending opportunities."],"correct":0,"why_vi":"Việc xác định best risky portfolio dựa vào risk/return của investment set; sau đó investor chọn tỷ lệ giữa P và F theo A. Với cùng kỳ vọng và cùng risk-free rate, mọi người có thể dùng một tangency fund nhưng differing complete portfolios. Hạn chế vay, thuế và khác biệt kỳ vọng có thể phá kết quả đơn giản.","trap_vi":"Không nhầm optimal risky portfolio với optimal complete portfolio."},{"stem_en":"Two CALs have the same intercept. The one with the higher slope offers:","options":["a lower reward-to-risk trade-off.","more expected excess return per unit of standard deviation.","a guaranteed higher realized return."],"correct":1,"why_vi":"CAL slope = (E(Rp)−Rf)/σp; slope lớn hơn nghĩa expected excess return trên mỗi unit volatility lớn hơn. Với risk aversion dương và positive premium, đường dốc hơn từ cùng Rf tạo opportunities tốt hơn. Slope không dự báo realized return chắc chắn.","trap_vi":"Độ dốc không phải beta hay covariance."},{"stem_en":"A risky fund has expected return 10%, volatility 20%, and the risk-free rate is 2%. An investor with A=4 can freely borrow or lend at the risk-free rate. Calculate the optimal risky weight (%).","options":["50.00%","62.50%","10.00%"],"correct":0,"why_vi":"Maximize utility; derivative E(Rp)−Rf−A y σp²=0. Thay số: 100 × (.10-.02)/(4 × .20^2) = 50.00%.","trap_vi":"Dùng full return thay premium hoặc SD thay variance."},{"stem_en":"An investor holds 65% in a risky portfolio returning an expected 12%, volatility 18%, and 35% in bills yielding 3%. What is the complete expected return (%)?","options":["8.85%","7.80%","6.15%"],"correct":0,"why_vi":"Weighted return; cùng horizon. Thay số: 3+.65 × (12-3) = 8.85%.","trap_vi":"Bỏ risk-free income hoặc đảo weights."},{"stem_en":"Two feasible CALs begin at Rf=2%. Fund X has expected return 11% and volatility 15%. Calculate the CAL slope.","options":["0.733 ratio","4.000 ratio","0.600 ratio"],"correct":2,"why_vi":"Excess return chia total SD, hai đơn vị thống nhất. Thay số: (.11-.02)/.15 = 0.600 ratio.","trap_vi":"Dùng full expected return hoặc variance thay SD."},{"stem_en":"A risky fund's premium is 6%, volatility 15%, and A=2. With no borrowing or shorting permitted, what percentage of wealth is optimally invested in the fund?","options":["133.33%","100.00%","0.00%"],"correct":1,"why_vi":"Unconstrained weight = .06/(2×.15²)=1.3333; constraint y≤1 binds. Thay số: 100 = 100.00%.","trap_vi":"Bỏ leverage constraint hoặc cho rằng risk aversion đòi all cash."}],"cards":[{"front_en":"Capital allocation line / Tập hợp khả thi","back_vi":"CAL kết hợp risk-free asset F với một risky portfolio P: E(Rc)=Rf+y[E(Rp)−Rf], σc=yσp khi y≥0. Đường có intercept Rf và slope reward-to-variability. y=0 là chỉ giữ F; y=1 giữ P; 0<y<1 là lending; y>1 là borrowing nếu được phép. | Exam trap: CAL của một risky portfolio bất kỳ không nhất thiết là CML."},{"front_en":"Utility-maximizing choice","back_vi":"Optimal complete portfolio là điểm trên feasible CAL đạt utility cao nhất; tangency với highest attainable indifference curve khi nghiệm interior. Điểm phía trên CAL hấp dẫn nhưng không khả thi với set đã cho; điểm thấp hơn CAL bị dominated tại cùng σ khi khả thi. Các investor khác A có thể chọn các vị trí khác nhau trên cùng CAL. | Exam trap: Không chọn điểm có highest expected return nếu không xét risk penalty."},{"front_en":"Optimal risky weight","back_vi":"Thay E(Rc) và σc² vào U, tối đa hóa cho y*= [E(Rp)−Rf]/(Aσp²), với A>0, cùng borrowing/lending rate và unconstrained allocation. Đây là hệ quả của utility function CFAI; nếu giới hạn không vay, cắt nghiệm tại y=1; nếu không short và y âm thì giới hạn y=0. Nghiệm cần kiểm tra constraint. | Exam trap: Không dùng Aσ thay Aσ²; weight > 1 là leverage, không phải lỗi số học."},{"front_en":"Separation of choice","back_vi":"Việc xác định best risky portfolio dựa vào risk/return của investment set; sau đó investor chọn tỷ lệ giữa P và F theo A. Với cùng kỳ vọng và cùng risk-free rate, mọi người có thể dùng một tangency fund nhưng differing complete portfolios. Hạn chế vay, thuế và khác biệt kỳ vọng có thể phá kết quả đơn giản. | Exam trap: Không nhầm optimal risky portfolio với optimal complete portfolio."},{"front_en":"Slope and trade-offs","back_vi":"CAL slope = (E(Rp)−Rf)/σp; slope lớn hơn nghĩa expected excess return trên mỗi unit volatility lớn hơn. Với risk aversion dương và positive premium, đường dốc hơn từ cùng Rf tạo opportunities tốt hơn. Slope không dự báo realized return chắc chắn. | Exam trap: Độ dốc không phải beta hay covariance."},{"front_en":"Complete return — formula and conditions?","back_vi":"E(Rc)=Rf+y[E(Rp)−Rf] · y là fraction invested in risky portfolio. · Same lending/borrowing rate."},{"front_en":"Complete standard deviation — formula and conditions?","back_vi":"σc=abs(y)σp · Rf constant over horizon. · y≥0 trong CAL thông thường."},{"front_en":"CAL slope — formula and conditions?","back_vi":"(E(Rp)−Rf)/σp · Reward per unit total volatility. · σp>0."},{"front_en":"Optimal risky allocation — formula and conditions?","back_vi":"y*=(E(Rp)−Rf)/(Aσp²) · Nghiệm tối đa utility bằng đạo hàm; derived practice. · A>0, unconstrained, same rates, consistent units."},{"front_en":"A risky fund has expected return 10%, volatility 20%, and the risk-free rate is 2%. An investor with A=4 can freely borrow or lend at the risk-free rate. Calculate the optimal risky weight (%).","back_vi":"Maximize utility; derivative E(Rp)−Rf−A y σp²=0. Thay số: 100 × (.10-.02)/(4 × .20^2) = 50.00%."},{"front_en":"An investor holds 65% in a risky portfolio returning an expected 12%, volatility 18%, and 35% in bills yielding 3%. What is the complete expected return (%)?","back_vi":"Weighted return; cùng horizon. Thay số: 3+.65 × (12-3) = 8.85%."},{"front_en":"Two feasible CALs begin at Rf=2%. Fund X has expected return 11% and volatility 15%. Calculate the CAL slope.","back_vi":"Excess return chia total SD, hai đơn vị thống nhất. Thay số: (.11-.02)/.15 = 0.600 ratio."},{"front_en":"A risky fund's premium is 6%, volatility 15%, and A=2. With no borrowing or shorting permitted, what percentage of wealth is optimally invested in the fund?","back_vi":"Unconstrained weight = .06/(2×.15²)=1.3333; constraint y≤1 binds. Thay số: 100 = 100.00%."}]},{"id":"CFA26-09-01-LOS04","letter":"d","title_en":"Mean, Variance, Covariance and Correlation","outcome_en":"calculate and interpret historical sample mean, variance, covariance and correlation of asset returns","overview_vi":"Bài học 1.d: Mean, Variance, Covariance and Correlation. Học định nghĩa, điều kiện, cách áp dụng, ví dụ và English MCQ. Nội dung theo LOS CFAI 2026; ví dụ số do dự án tự viết, không sao chép câu hỏi nguồn.","source":[{"id":"CFA Institute Curriculum 2026 — Portfolio Management Volume 9","pages":"Physical PDF p. 13 (LOS), 31–40 (content)"},{"id":"Kaplan SchweserNotes 2026 — Book 4, Reading 83","pages":"Physical PDF pp. 72–75"},{"id":"SAPP CFA Level I 2026 — Portfolio Management slides","pages":"Physical PDF pp. 16–20"}],"sections":[{"heading":"Historical mean","body":"Arithmetic sample mean là tổng periodic returns chia số observations n; dùng ước lượng expected single-period return khi sample đại diện. Geometric mean phản ánh growth compounded qua nhiều kỳ và thường nhỏ hơn arithmetic mean nếu returns biến động. Dùng đúng tần suất và đơn vị; không cộng returns để tìm multi-period compounded growth.","trap":"Historical mean là estimate, không phải kỳ vọng chắc chắn."},{"heading":"Sample variance and standard deviation","body":"Sample variance s²=Σ(Rt−R̄)²/(n−1); sample SD là căn bậc hai. n−1 điều chỉnh việc đã ước lượng mean từ mẫu. Population variance dùng n khi biết toàn bộ population. Variance có squared return units, SD có cùng units với return.","trap":"Không dùng n nếu đề yêu cầu sample variance; không ghi variance dưới dạng SD."},{"heading":"Covariance","body":"Sample covariance Cov(X,Y)=Σ(Xt−X̄)(Yt−Ȳ)/(n−1); positive khi deviations cùng dấu thường xuyên; negative khi trái dấu. Phải ghép observations cùng kỳ; covariance có units squared nên magnitude phụ thuộc scale. Cov(X,X)=Var(X).","trap":"Covariance không bị giới hạn trong [−1,+1]."},{"heading":"Correlation","body":"ρxy=Cov(X,Y)/(σxσy), dimensionless, nằm trong [−1,+1]; không xác định nếu một SD bằng 0. Zero correlation biểu thị không có linear relationship, không bảo đảm independence. −1 là perfect negative linear relationship, +1 perfect positive; không đồng nghĩa cùng volatility.","trap":"Correlation không là causal relationship."},{"heading":"Scale and alignment","body":"Nếu dùng returns dưới dạng % points (8 thay 0.08), variance/covariance tăng 10,000 lần nhưng correlation không đổi; SD tăng 100 lần. Ước lượng mẫu phải align dates, frequency và currency; missing observations, stale prices, outliers và changing regimes có thể làm sai estimate.","trap":"Không nhân correlation với variance thay cho SD product."}],"formulas":[{"name":"Arithmetic mean","expr":"R̄=ΣRt/n","meaning":"Average historical single-period returns.","conditions":"Equal weighting of historical observations."},{"name":"Sample variance and SD","expr":"s²=Σ(Rt−R̄)²/(n−1); s=√s²","meaning":"Sample dispersion.","conditions":"n>1; population denominator n only for population."},{"name":"Sample covariance","expr":"sXY=Σ(Xt−X̄)(Yt−Ȳ)/(n−1)","meaning":"Joint co-movement.","conditions":"Aligned data, sample denominator."},{"name":"Correlation","expr":"ρXY=sXY/(sX sY)","meaning":"Normalized linear relationship.","conditions":"Nonzero standard deviations; same data and units."}],"examples":[{"question_en":"Two assets are observed on unmatched trading dates. The analyst calculates covariance by pairing the first available return of each series, irrespective of date. What should be corrected?","steps_vi":["Covariance measures joint deviations in corresponding periods, not unrelated observations.","Align dates, horizon and currency; then use paired sample deviations with n−1 denominator."],"answer":"Recompute from matched observations.","check":"Conceptual case; interpretation conditional on stated assumptions."},{"question_en":"An asset's four annual returns are 2%, 6%, −4%, and 12%. Compute the arithmetic sample mean (%).","steps_vi":["Cộng bốn observations rồi chia 4.","Thay số: (2+6-4+12)/4.","Kết quả: 4.00%."],"answer":"4.00%","check":"Original worked case; Decimal value compared with alternate Fraction expression (square root checked using float)."},{"question_en":"Three periodic returns are 1%, 5%, and 9%. Compute sample variance in squared percentage points.","steps_vi":["Mean 5; sum squared deviations divided by n−1=2.","Thay số: ((1-5)^2+(5-5)^2+(9-5)^2)/2.","Kết quả: 16.00 pp²."],"answer":"16.00 pp²","check":"Original worked case; Decimal value compared with alternate Fraction expression (square root checked using float)."},{"question_en":"Returns for A in three matched periods are 1%, 4%, 7%; returns for B are 9%, 6%, 3%. Compute sample covariance in squared percentage points.","steps_vi":["Means A=4, B=6; paired cross deviations divided by 2.","Thay số: ((-3) × 3+0 × 0+3 × (-3))/2.","Kết quả: -9.00 pp²."],"answer":"-9.00 pp²","check":"Original worked case; Decimal value compared with alternate Fraction expression (square root checked using float)."},{"question_en":"Sample covariance is 0.012, sample SD of A is 0.20, and sample SD of B is 0.15. Find correlation.","steps_vi":["Covariance divided by product of SDs.","Thay số: .012/(.20 × .15).","Kết quả: 0.400 ratio."],"answer":"0.400 ratio","check":"Original worked case; Decimal value compared with alternate Fraction expression (square root checked using float)."},{"question_en":"Four sample observations are −2%, 2%, 6%, 10%. What is the sample standard deviation (%)?","steps_vi":["Mean 4; calculate sample variance then square root.","Thay số: √(((-2-4)^2+(2-4)^2+(6-4)^2+(10-4)^2)/3).","Kết quả: 5.16%."],"answer":"5.16%","check":"Original worked case; Decimal value compared with alternate Fraction expression (square root checked using float)."}],"questions":[{"stem_en":"The arithmetic mean of historical periodic returns is primarily used to estimate:","options":["a single-period expected return.","the exact compound growth rate of a volatile investment.","the maximum possible loss."],"correct":0,"why_vi":"Arithmetic sample mean là tổng periodic returns chia số observations n; dùng ước lượng expected single-period return khi sample đại diện. Geometric mean phản ánh growth compounded qua nhiều kỳ và thường nhỏ hơn arithmetic mean nếu returns biến động. Dùng đúng tần suất và đơn vị; không cộng returns để tìm multi-period compounded growth.","trap_vi":"Historical mean là estimate, không phải kỳ vọng chắc chắn."},{"stem_en":"For a sample of historical returns with an estimated sample mean, the usual variance denominator is:","options":["n + 1.","n².","n − 1."],"correct":2,"why_vi":"Sample variance s²=Σ(Rt−R̄)²/(n−1); sample SD là căn bậc hai. n−1 điều chỉnh việc đã ước lượng mean từ mẫu. Population variance dùng n khi biết toàn bộ population. Variance có squared return units, SD có cùng units với return.","trap_vi":"Không dùng n nếu đề yêu cầu sample variance; không ghi variance dưới dạng SD."},{"stem_en":"Positive covariance between two return series indicates that they tend to:","options":["have exactly equal returns each period.","deviate from their respective means in the same direction.","have zero individual variance."],"correct":1,"why_vi":"Sample covariance Cov(X,Y)=Σ(Xt−X̄)(Yt−Ȳ)/(n−1); positive khi deviations cùng dấu thường xuyên; negative khi trái dấu. Phải ghép observations cùng kỳ; covariance có units squared nên magnitude phụ thuộc scale. Cov(X,X)=Var(X).","trap_vi":"Covariance không bị giới hạn trong [−1,+1]."},{"stem_en":"A sample correlation of zero between two nonconstant return series implies:","options":["statistical independence in every distribution.","that both assets are risk-free.","no measured linear association."],"correct":2,"why_vi":"ρxy=Cov(X,Y)/(σxσy), dimensionless, nằm trong [−1,+1]; không xác định nếu một SD bằng 0. Zero correlation biểu thị không có linear relationship, không bảo đảm independence. −1 là perfect negative linear relationship, +1 perfect positive; không đồng nghĩa cùng volatility.","trap_vi":"Correlation không là causal relationship."},{"stem_en":"If both return series are multiplied by 100, their correlation:","options":["is multiplied by 100.","is multiplied by 10,000.","is unchanged."],"correct":2,"why_vi":"Nếu dùng returns dưới dạng % points (8 thay 0.08), variance/covariance tăng 10,000 lần nhưng correlation không đổi; SD tăng 100 lần. Ước lượng mẫu phải align dates, frequency và currency; missing observations, stale prices, outliers và changing regimes có thể làm sai estimate.","trap_vi":"Không nhân correlation với variance thay cho SD product."},{"stem_en":"An asset's four annual returns are 2%, 6%, −4%, and 12%. Compute the arithmetic sample mean (%).","options":["5.33%","6.00%","4.00%"],"correct":2,"why_vi":"Cộng bốn observations rồi chia 4. Thay số: (2+6-4+12)/4 = 4.00%.","trap_vi":"Nhầm mẫu số sample variance hoặc bỏ dấu âm."},{"stem_en":"Three periodic returns are 1%, 5%, and 9%. Compute sample variance in squared percentage points.","options":["16.00 pp²","10.67 pp²","4.00 pp²"],"correct":0,"why_vi":"Mean 5; sum squared deviations divided by n−1=2. Thay số: ((1-5)^2+(5-5)^2+(9-5)^2)/2 = 16.00 pp².","trap_vi":"Dùng population variance hoặc trả lời SD."},{"stem_en":"Returns for A in three matched periods are 1%, 4%, 7%; returns for B are 9%, 6%, 3%. Compute sample covariance in squared percentage points.","options":["-6.00 pp²","-9.00 pp²","9.00 pp²"],"correct":1,"why_vi":"Means A=4, B=6; paired cross deviations divided by 2. Thay số: ((-3) × 3+0 × 0+3 × (-3))/2 = -9.00 pp².","trap_vi":"Dùng n hoặc bỏ dấu âm."},{"stem_en":"Sample covariance is 0.012, sample SD of A is 0.20, and sample SD of B is 0.15. Find correlation.","options":["0.400 ratio","0.300 ratio","0.012 ratio"],"correct":0,"why_vi":"Covariance divided by product of SDs. Thay số: .012/(.20 × .15) = 0.400 ratio.","trap_vi":"Dùng variance of A hoặc covariance trực tiếp."},{"stem_en":"Four sample observations are −2%, 2%, 6%, 10%. What is the sample standard deviation (%)?","options":["4.47%","26.67%","5.16%"],"correct":2,"why_vi":"Mean 4; calculate sample variance then square root. Thay số: √(((-2-4)^2+(2-4)^2+(6-4)^2+(10-4)^2)/3) = 5.16%.","trap_vi":"Population denominator hoặc trả lời variance."}],"cards":[{"front_en":"Historical mean","back_vi":"Arithmetic sample mean là tổng periodic returns chia số observations n; dùng ước lượng expected single-period return khi sample đại diện. Geometric mean phản ánh growth compounded qua nhiều kỳ và thường nhỏ hơn arithmetic mean nếu returns biến động. Dùng đúng tần suất và đơn vị; không cộng returns để tìm multi-period compounded growth. | Exam trap: Historical mean là estimate, không phải kỳ vọng chắc chắn."},{"front_en":"Sample variance and standard deviation","back_vi":"Sample variance s²=Σ(Rt−R̄)²/(n−1); sample SD là căn bậc hai. n−1 điều chỉnh việc đã ước lượng mean từ mẫu. Population variance dùng n khi biết toàn bộ population. Variance có squared return units, SD có cùng units với return. | Exam trap: Không dùng n nếu đề yêu cầu sample variance; không ghi variance dưới dạng SD."},{"front_en":"Covariance","back_vi":"Sample covariance Cov(X,Y)=Σ(Xt−X̄)(Yt−Ȳ)/(n−1); positive khi deviations cùng dấu thường xuyên; negative khi trái dấu. Phải ghép observations cùng kỳ; covariance có units squared nên magnitude phụ thuộc scale. Cov(X,X)=Var(X). | Exam trap: Covariance không bị giới hạn trong [−1,+1]."},{"front_en":"Correlation","back_vi":"ρxy=Cov(X,Y)/(σxσy), dimensionless, nằm trong [−1,+1]; không xác định nếu một SD bằng 0. Zero correlation biểu thị không có linear relationship, không bảo đảm independence. −1 là perfect negative linear relationship, +1 perfect positive; không đồng nghĩa cùng volatility. | Exam trap: Correlation không là causal relationship."},{"front_en":"Scale and alignment","back_vi":"Nếu dùng returns dưới dạng % points (8 thay 0.08), variance/covariance tăng 10,000 lần nhưng correlation không đổi; SD tăng 100 lần. Ước lượng mẫu phải align dates, frequency và currency; missing observations, stale prices, outliers và changing regimes có thể làm sai estimate. | Exam trap: Không nhân correlation với variance thay cho SD product."},{"front_en":"Arithmetic mean — formula and conditions?","back_vi":"R̄=ΣRt/n · Average historical single-period returns. · Equal weighting of historical observations."},{"front_en":"Sample variance and SD — formula and conditions?","back_vi":"s²=Σ(Rt−R̄)²/(n−1); s=√s² · Sample dispersion. · n>1; population denominator n only for population."},{"front_en":"Sample covariance — formula and conditions?","back_vi":"sXY=Σ(Xt−X̄)(Yt−Ȳ)/(n−1) · Joint co-movement. · Aligned data, sample denominator."},{"front_en":"Correlation — formula and conditions?","back_vi":"ρXY=sXY/(sX sY) · Normalized linear relationship. · Nonzero standard deviations; same data and units."},{"front_en":"An asset's four annual returns are 2%, 6%, −4%, and 12%. Compute the arithmetic sample mean (%).","back_vi":"Cộng bốn observations rồi chia 4. Thay số: (2+6-4+12)/4 = 4.00%."},{"front_en":"Three periodic returns are 1%, 5%, and 9%. Compute sample variance in squared percentage points.","back_vi":"Mean 5; sum squared deviations divided by n−1=2. Thay số: ((1-5)^2+(5-5)^2+(9-5)^2)/2 = 16.00 pp²."},{"front_en":"Returns for A in three matched periods are 1%, 4%, 7%; returns for B are 9%, 6%, 3%. Compute sample covariance in squared percentage points.","back_vi":"Means A=4, B=6; paired cross deviations divided by 2. Thay số: ((-3) × 3+0 × 0+3 × (-3))/2 = -9.00 pp²."},{"front_en":"Sample covariance is 0.012, sample SD of A is 0.20, and sample SD of B is 0.15. Find correlation.","back_vi":"Covariance divided by product of SDs. Thay số: .012/(.20 × .15) = 0.400 ratio."},{"front_en":"Four sample observations are −2%, 2%, 6%, 10%. What is the sample standard deviation (%)?","back_vi":"Mean 4; calculate sample variance then square root. Thay số: √(((-2-4)^2+(2-4)^2+(6-4)^2+(10-4)^2)/3) = 5.16%."}]},{"id":"CFA26-09-01-LOS05","letter":"e","title_en":"Portfolio Standard Deviation","outcome_en":"calculate and interpret portfolio volatility","overview_vi":"Bài học 1.e: Portfolio Standard Deviation. Học định nghĩa, điều kiện, cách áp dụng, ví dụ và English MCQ. Nội dung theo LOS CFAI 2026; ví dụ số do dự án tự viết, không sao chép câu hỏi nguồn.","source":[{"id":"CFA Institute Curriculum 2026 — Portfolio Management Volume 9","pages":"Physical PDF p. 13 (LOS), 31–41 (content)"},{"id":"Kaplan SchweserNotes 2026 — Book 4, Reading 83","pages":"Physical PDF pp. 75–76"},{"id":"SAPP CFA Level I 2026 — Portfolio Management slides","pages":"Physical PDF pp. 21–23"}],"sections":[{"heading":"Expected portfolio return","body":"Với weights tính theo current market values và tổng 1, expected return của portfolio = ΣwiE(Ri). Short positions có weight âm, leverage có thể làm gross exposure >100%. Covariance không tác động trực tiếp mean nếu fixed weights; ảnh hưởng dispersion và optimal weights.","trap":"Không lấy simple average trừ khi equal weights."},{"heading":"Two-asset variance","body":"Variance = w1²σ1²+w2²σ2²+2w1w2Cov12; Cov12=ρ12σ1σ2. Cross term phải có hệ số 2 vì cặp (1,2) và (2,1). Portfolio SD lấy square root sau khi tính variance. Weights và σ dạng decimal khi output decimal.","trap":"Portfolio SD không phải weighted average of individual SDs ngoại trừ special cases."},{"heading":"Many assets and covariance matrix","body":"σp² = ΣiΣj wi wj Covij = w'Σw. Diagonal là individual variances; off-diagonal là covariances. Với n tài sản, có n(n−1)/2 distinct covariance estimates; duplicate symmetric entries không phải independent estimates. Portfolio return linear nhưng risk phụ thuộc tất cả interactions.","trap":"Không bỏ cross terms khi n lớn."},{"heading":"Risk contribution","body":"Tài sản volatility cao có thể giảm portfolio risk nếu covariance với portfolio hiện tại đủ thấp. Marginal effect phụ thuộc exposures và cross terms; một tài sản standalone risk cao không nhất thiết làm danh mục rủi ro hơn. Với short weights, tác động của correlation phải xét dấu w1w2.","trap":"Không so sánh σ của một asset riêng để khẳng định nó làm tăng σp."},{"heading":"Consistency checks","body":"Với long-only weights, perfect positive correlation cho σp=w1σ1+w2σ2; zero correlation vẫn có variance terms; perfect negative correlation cho σp=abs(w1σ1−w2σ2). Variance không âm nếu covariance matrix hợp lệ. Khi hai tài sản có σ như nhau, cùng weight và ρ=1 thì σp=σi.","trap":"Không lấy căn của từng variance rồi cộng khi ρ<1."}],"formulas":[{"name":"Portfolio expected return","expr":"E(Rp)=ΣwiE(Ri)","meaning":"Weight-adjusted return.","conditions":"Net weights sum to one."},{"name":"Two-asset variance","expr":"σp²=w1²σ1²+w2²σ2²+2w1w2ρ12σ1σ2","meaning":"Own variance terms and covariance cross term.","conditions":"Valid covariance, same horizon."},{"name":"Many-asset variance","expr":"σp²=w'Σw; σp=√(w'Σw)","meaning":"Covariance matrix aggregation.","conditions":"Σ positive semidefinite; weights sum to 1."},{"name":"Distinct covariances","expr":"n(n−1)/2","meaning":"Number of unique pairwise covariances.","conditions":"n assets; exclude diagonal."}],"examples":[{"question_en":"An analyst predicts a new portfolio's volatility by weighting each asset's volatility and summing. In what case is this correct for a two-asset long-only portfolio?","steps_vi":["Viết variance including covariance and compare it with square of weighted volatility.","The expressions agree when both positive-weight nonzero-volatility returns are perfectly positively correlated (or degenerate cases)."],"answer":"Perfect positive correlation in the ordinary nondegenerate case.","check":"Conceptual case; interpretation conditional on stated assumptions."},{"question_en":"A long-only portfolio has 45% in equity with expected return 13% and 55% in bonds with expected return 5%. What is its expected return (%)?","steps_vi":["Weighted return using market-value weights.","Thay số: .45 × 13+.55 × 5.","Kết quả: 8.60%."],"answer":"8.60%","check":"Original worked case; Decimal value compared with alternate Fraction expression (square root checked using float)."},{"question_en":"Portfolio weights are 60% and 40%, individual standard deviations are 20% and 10%, and correlation is 0.25. Calculate portfolio SD (%).","steps_vi":["Use full variance with covariance cross term; then square root.","Thay số: √(.6^2 × 20^2+.4^2 × 10^2+2 × .6 × .4 × .25 × 20 × 10).","Kết quả: 13.56%."],"answer":"13.56%","check":"Original worked case; Decimal value compared with alternate Fraction expression (square root checked using float)."},{"question_en":"Three assets have weights 0.5, 0.3, 0.2, SDs 12%, 18%, 10%, and zero pairwise correlations. What is portfolio SD (%)?","steps_vi":["Zero correlations remove cross terms, not own variances.","Thay số: √((.5 × 12)^2+(.3 × 18)^2+(.2 × 10)^2).","Kết quả: 8.32%."],"answer":"8.32%","check":"Original worked case; Decimal value compared with alternate Fraction expression (square root checked using float)."},{"question_en":"For 24 risky assets, how many distinct pairwise covariance terms must be estimated?","steps_vi":["Symmetric covariance matrix: choose unordered pairs excluding diagonal.","Thay số: 24 × 23/2.","Kết quả: 276 count."],"answer":"276 count","check":"Original worked case; Decimal value compared with alternate Fraction expression (square root checked using float)."},{"question_en":"A portfolio has weights 0.5, 0.3, 0.2; variances in pp² of 100, 144, 225; covariances AB=30, AC=−20, BC=40. Compute portfolio variance in pp².","steps_vi":["Add diagonal and twice all distinct covariance terms.","Thay số: .5^2 × 100+.3^2 × 144+.2^2 × 225+2 × (.5 × .3 × 30+.5 × .2 × (-20)+.3 × .2 × 40).","Kết quả: 56.76 pp²."],"answer":"56.76 pp²","check":"Original worked case; Decimal value compared with alternate Fraction expression (square root checked using float)."}],"questions":[{"stem_en":"Which input is needed to calculate a two-asset portfolio's expected return but not its variance?","options":["The correlation of asset returns.","The covariance of asset returns.","The expected returns of the two assets."],"correct":2,"why_vi":"Với weights tính theo current market values và tổng 1, expected return của portfolio = ΣwiE(Ri). Short positions có weight âm, leverage có thể làm gross exposure >100%. Covariance không tác động trực tiếp mean nếu fixed weights; ảnh hưởng dispersion và optimal weights.","trap_vi":"Không lấy simple average trừ khi equal weights."},{"stem_en":"The cross-product term in a two-asset portfolio variance formula is:","options":["2w1w2ρ12σ1σ2.","w1w2ρ12.","2w1w2σ1²σ2²."],"correct":0,"why_vi":"Variance = w1²σ1²+w2²σ2²+2w1w2Cov12; Cov12=ρ12σ1σ2. Cross term phải có hệ số 2 vì cặp (1,2) và (2,1). Portfolio SD lấy square root sau khi tính variance. Weights và σ dạng decimal khi output decimal.","trap_vi":"Portfolio SD không phải weighted average of individual SDs ngoại trừ special cases."},{"stem_en":"For a three-asset portfolio, the number of distinct pairwise covariances is:","options":["three.","six.","nine."],"correct":0,"why_vi":"σp² = ΣiΣj wi wj Covij = w'Σw. Diagonal là individual variances; off-diagonal là covariances. Với n tài sản, có n(n−1)/2 distinct covariance estimates; duplicate symmetric entries không phải independent estimates. Portfolio return linear nhưng risk phụ thuộc tất cả interactions.","trap_vi":"Không bỏ cross terms khi n lớn."},{"stem_en":"A new asset has high standalone volatility but low covariance with an existing portfolio. Its addition:","options":["may reduce portfolio volatility at suitable weights.","must increase portfolio volatility.","has no effect on portfolio variance."],"correct":0,"why_vi":"Tài sản volatility cao có thể giảm portfolio risk nếu covariance với portfolio hiện tại đủ thấp. Marginal effect phụ thuộc exposures và cross terms; một tài sản standalone risk cao không nhất thiết làm danh mục rủi ro hơn. Với short weights, tác động của correlation phải xét dấu w1w2.","trap_vi":"Không so sánh σ của một asset riêng để khẳng định nó làm tăng σp."},{"stem_en":"If two long-only assets have identical volatility and perfect positive correlation, an equally weighted portfolio has volatility:","options":["equal to either asset's volatility.","half of either asset's volatility.","zero."],"correct":0,"why_vi":"Với long-only weights, perfect positive correlation cho σp=w1σ1+w2σ2; zero correlation vẫn có variance terms; perfect negative correlation cho σp=abs(w1σ1−w2σ2). Variance không âm nếu covariance matrix hợp lệ. Khi hai tài sản có σ như nhau, cùng weight và ρ=1 thì σp=σi.","trap_vi":"Không lấy căn của từng variance rồi cộng khi ρ<1."},{"stem_en":"A long-only portfolio has 45% in equity with expected return 13% and 55% in bonds with expected return 5%. What is its expected return (%)?","options":["8.60%","9.00%","9.40%"],"correct":0,"why_vi":"Weighted return using market-value weights. Thay số: .45 × 13+.55 × 5 = 8.60%.","trap_vi":"Dùng equal weights hoặc đảo weights."},{"stem_en":"Portfolio weights are 60% and 40%, individual standard deviations are 20% and 10%, and correlation is 0.25. Calculate portfolio SD (%).","options":["16.00%","13.56%","12.65%"],"correct":1,"why_vi":"Use full variance with covariance cross term; then square root. Thay số: √(.6^2 × 20^2+.4^2 × 10^2+2 × .6 × .4 × .25 × 20 × 10) = 13.56%.","trap_vi":"Weighted SD như ρ=1 hoặc bỏ covariance như ρ=0."},{"stem_en":"Three assets have weights 0.5, 0.3, 0.2, SDs 12%, 18%, 10%, and zero pairwise correlations. What is portfolio SD (%)?","options":["13.40%","69.16%","8.32%"],"correct":2,"why_vi":"Zero correlations remove cross terms, not own variances. Thay số: √((.5 × 12)^2+(.3 × 18)^2+(.2 × 10)^2) = 8.32%.","trap_vi":"Dùng weighted SD hoặc trả lời variance."},{"stem_en":"For 24 risky assets, how many distinct pairwise covariance terms must be estimated?","options":["552 count","276 count","300 count"],"correct":1,"why_vi":"Symmetric covariance matrix: choose unordered pairs excluding diagonal. Thay số: 24 × 23/2 = 276 count.","trap_vi":"Double-count hoặc tính cả diagonal."},{"stem_en":"A portfolio has weights 0.5, 0.3, 0.2; variances in pp² of 100, 144, 225; covariances AB=30, AC=−20, BC=40. Compute portfolio variance in pp².","options":["46.96 pp²","51.86 pp²","56.76 pp²"],"correct":2,"why_vi":"Add diagonal and twice all distinct covariance terms. Thay số: .5^2 × 100+.3^2 × 144+.2^2 × 225+2 × (.5 × .3 × 30+.5 × .2 × (-20)+.3 × .2 × 40) = 56.76 pp².","trap_vi":"Bỏ covariance hoặc thiếu hệ số 2."}],"cards":[{"front_en":"Expected portfolio return","back_vi":"Với weights tính theo current market values và tổng 1, expected return của portfolio = ΣwiE(Ri). Short positions có weight âm, leverage có thể làm gross exposure >100%. Covariance không tác động trực tiếp mean nếu fixed weights; ảnh hưởng dispersion và optimal weights. | Exam trap: Không lấy simple average trừ khi equal weights."},{"front_en":"Two-asset variance","back_vi":"Variance = w1²σ1²+w2²σ2²+2w1w2Cov12; Cov12=ρ12σ1σ2. Cross term phải có hệ số 2 vì cặp (1,2) và (2,1). Portfolio SD lấy square root sau khi tính variance. Weights và σ dạng decimal khi output decimal. | Exam trap: Portfolio SD không phải weighted average of individual SDs ngoại trừ special cases."},{"front_en":"Many assets and covariance matrix","back_vi":"σp² = ΣiΣj wi wj Covij = w'Σw. Diagonal là individual variances; off-diagonal là covariances. Với n tài sản, có n(n−1)/2 distinct covariance estimates; duplicate symmetric entries không phải independent estimates. Portfolio return linear nhưng risk phụ thuộc tất cả interactions. | Exam trap: Không bỏ cross terms khi n lớn."},{"front_en":"Risk contribution","back_vi":"Tài sản volatility cao có thể giảm portfolio risk nếu covariance với portfolio hiện tại đủ thấp. Marginal effect phụ thuộc exposures và cross terms; một tài sản standalone risk cao không nhất thiết làm danh mục rủi ro hơn. Với short weights, tác động của correlation phải xét dấu w1w2. | Exam trap: Không so sánh σ của một asset riêng để khẳng định nó làm tăng σp."},{"front_en":"Consistency checks","back_vi":"Với long-only weights, perfect positive correlation cho σp=w1σ1+w2σ2; zero correlation vẫn có variance terms; perfect negative correlation cho σp=abs(w1σ1−w2σ2). Variance không âm nếu covariance matrix hợp lệ. Khi hai tài sản có σ như nhau, cùng weight và ρ=1 thì σp=σi. | Exam trap: Không lấy căn của từng variance rồi cộng khi ρ<1."},{"front_en":"Portfolio expected return — formula and conditions?","back_vi":"E(Rp)=ΣwiE(Ri) · Weight-adjusted return. · Net weights sum to one."},{"front_en":"Two-asset variance — formula and conditions?","back_vi":"σp²=w1²σ1²+w2²σ2²+2w1w2ρ12σ1σ2 · Own variance terms and covariance cross term. · Valid covariance, same horizon."},{"front_en":"Many-asset variance — formula and conditions?","back_vi":"σp²=w'Σw; σp=√(w'Σw) · Covariance matrix aggregation. · Σ positive semidefinite; weights sum to 1."},{"front_en":"Distinct covariances — formula and conditions?","back_vi":"n(n−1)/2 · Number of unique pairwise covariances. · n assets; exclude diagonal."},{"front_en":"A long-only portfolio has 45% in equity with expected return 13% and 55% in bonds with expected return 5%. What is its expected return (%)?","back_vi":"Weighted return using market-value weights. Thay số: .45 × 13+.55 × 5 = 8.60%."},{"front_en":"Portfolio weights are 60% and 40%, individual standard deviations are 20% and 10%, and correlation is 0.25. Calculate portfolio SD (%).","back_vi":"Use full variance with covariance cross term; then square root. Thay số: √(.6^2 × 20^2+.4^2 × 10^2+2 × .6 × .4 × .25 × 20 × 10) = 13.56%."},{"front_en":"Three assets have weights 0.5, 0.3, 0.2, SDs 12%, 18%, 10%, and zero pairwise correlations. What is portfolio SD (%)?","back_vi":"Zero correlations remove cross terms, not own variances. Thay số: √((.5 × 12)^2+(.3 × 18)^2+(.2 × 10)^2) = 8.32%."},{"front_en":"For 24 risky assets, how many distinct pairwise covariance terms must be estimated?","back_vi":"Symmetric covariance matrix: choose unordered pairs excluding diagonal. Thay số: 24 × 23/2 = 276 count."},{"front_en":"A portfolio has weights 0.5, 0.3, 0.2; variances in pp² of 100, 144, 225; covariances AB=30, AC=−20, BC=40. Compute portfolio variance in pp².","back_vi":"Add diagonal and twice all distinct covariance terms. Thay số: .5^2 × 100+.3^2 × 144+.2^2 × 225+2 × (.5 × .3 × 30+.5 × .2 × (-20)+.3 × .2 × 40) = 56.76 pp²."}]},{"id":"CFA26-09-01-LOS06","letter":"f","title_en":"Diversification and Imperfect Correlation","outcome_en":"describe the effect of imperfect asset correlation on portfolio risk","overview_vi":"Bài học 1.f: Diversification and Imperfect Correlation. Học định nghĩa, điều kiện, cách áp dụng, ví dụ và English MCQ. Nội dung theo LOS CFAI 2026; ví dụ số do dự án tự viết, không sao chép câu hỏi nguồn.","source":[{"id":"CFA Institute Curriculum 2026 — Portfolio Management Volume 9","pages":"Physical PDF p. 13 (LOS), 34–46 (content)"},{"id":"Kaplan SchweserNotes 2026 — Book 4, Reading 83","pages":"Physical PDF pp. 76–78"},{"id":"SAPP CFA Level I 2026 — Portfolio Management slides","pages":"Physical PDF pp. 24–26"}],"sections":[{"heading":"Diversification mechanism","body":"Giảm correlation làm giảm covariance term đối với weights dương, giữ nguyên E(Rp) và standalone volatilities. Investor có thể giảm risk mà không buộc giảm expected return với allocation cố định. Hiệu quả phụ thuộc correlation, weights và độ biến động; ρ=+1 không có benefit so với weighted SD.","trap":"Diversification không đòi correlation âm; chỉ cần thấp hơn +1."},{"heading":"Perfect negative correlation","body":"Khi ρ=−1, portfolio SD là abs(w1σ1−w2σ2). Long-only zero-risk combination tồn tại nếu σ1,σ2>0; w1=σ2/(σ1+σ2). Đây là mathematical hedge of return variation, không tự bảo đảm mọi default/liquidity risk thực tế mất đi. Với ρ>−1 và positive SD không thể tạo zero variance chỉ bằng hai positive weights.","trap":"Không mặc định equal weights tạo zero risk khi volatilities khác nhau."},{"heading":"Large equal-weight portfolios","body":"Với n assets có cùng variance σ² và average pairwise correlation ρ, σp²=σ²[1/n+(n−1)ρ/n]. Khi ρ>0 cố định và n lớn, residual variance tiến về ρσ²; phần idiosyncratic giảm nhưng common risk còn. Trường hợp ρ=0, SD=σ/√n.","trap":"Không ngoại suy fixed negative ρ đến n vô hạn vì covariance matrix phải hợp lệ."},{"heading":"Stress correlations","body":"Correlations được ước lượng từ historical data và có thể đổi theo regime; nhiều assets trở nên đồng biến trong crisis. Diversification across countries, sectors, asset classes hoặc factors giúp giảm concentration nhưng currency exposures, market stress và overlapping economic risks vẫn tồn tại.","trap":"Số lượng holdings không chứng minh risk factors đa dạng."},{"heading":"Diversification comparison","body":"Chọn asset bổ sung cần xem covariance với current portfolio, expected return, liquidity và constraints. Diversification within one asset class giảm security-specific risk; across asset classes mở rộng common factor mix. International diversification phải xét currency và country risk.","trap":"Không thay diversification bằng chỉ mua nhiều cổ phiếu cùng sector."},{"heading":"Marginal Sharpe criterion and insurance","body":"CFAI p46 đưa rule để xem một khoản phân bổ nhỏ vào asset mới cải thiện Sharpe của current portfolio: SRnew > ρnew,p × SRp. Do đó asset có low standalone Sharpe vẫn hữu ích nếu correlation đủ thấp. Put options hoặc insurance có thể có expected return thấp/âm nhưng bảo vệ extreme losses; cost phải được cân nhắc. Rule là marginal risk–return criterion dưới input assumptions, không thay thế constraints.","trap":"Không yêu cầu SRnew lớn hơn SRp nếu correlation <1."}],"formulas":[{"name":"Perfect negative correlation","expr":"σp=abs(w1σ1−w2σ2); w1=σ2/(σ1+σ2) for σp=0","meaning":"Offsetting weighted risks.","conditions":"Two positive-volatility assets, ρ=−1, long-only."},{"name":"Equal-volatility diversified portfolio","expr":"σp²=σ²[1/n+(n−1)ρ/n]","meaning":"Risk floor from common correlation.","conditions":"Equal weights, equal variances, valid common correlation."},{"name":"Variance change from correlation","expr":"Δσp²=2w1w2σ1σ2Δρ","meaning":"Compare correlation scenarios with other inputs fixed.","conditions":"Positive weights for monotonic diversification conclusion."},{"name":"Marginal Sharpe test","expr":"SRnew > ρnew,p × SRp","meaning":"A small positive allocation improves portfolio Sharpe under standard assumptions.","conditions":"Positive SDs, incremental allocation, estimated inputs; not a universal allocation rule."}],"examples":[{"question_en":"A domestic equity investor adds a foreign sector fund. Both funds have similar economic factor exposure, and correlation approaches one during recessions. Does the extra fund automatically remove downside risk?","steps_vi":["Diversification depends on joint exposures, not product names or nationality alone.","Correlation rising in recessions weakens the covariance benefit; check currency, factor and liquidity risks."],"answer":"No. Diversification can be weaker when common factors dominate.","check":"Conceptual case; interpretation conditional on stated assumptions."},{"question_en":"Two assets have volatilities 12% and 20% with correlation −1. What weight (%) in the first asset eliminates return volatility?","steps_vi":["Solve w×12=(1−w)×20.","Thay số: 100 × 20/(12+20).","Kết quả: 62.50%."],"answer":"62.50%","check":"Original worked case; Decimal value compared with alternate Fraction expression (square root checked using float)."},{"question_en":"A portfolio holds 40 equal-weight assets, each with volatility 20% and common pairwise correlation 0.25. Find portfolio volatility (%).","steps_vi":["Equal-risk portfolio: common variance plus shrinking independent component.","Thay số: √(20^2 × (1/40+39 × .25/40)).","Kết quả: 10.37%."],"answer":"10.37%","check":"Original worked case; Decimal value compared with alternate Fraction expression (square root checked using float)."},{"question_en":"A 50/50 portfolio has asset volatilities 18% and 12%. Correlation rises from 0.1 to 0.6. By how many squared percentage points does variance rise?","steps_vi":["Only covariance term changes; compare full variances.","Thay số: 2 × .5 × .5 × 18 × 12 × (.6-.1).","Kết quả: 54.00 pp²."],"answer":"54.00 pp²","check":"Original worked case; Decimal value compared with alternate Fraction expression (square root checked using float)."},{"question_en":"Current portfolio Sharpe is 0.7; a candidate asset has correlation 0.3 with it. Calculate the threshold standalone Sharpe above which a small positive allocation improves Sharpe.","steps_vi":["Apply marginal criterion SRnew > ρnew,p SRp; threshold is 0.21.","Thay số: .7 × .3.","Kết quả: 0.210 ratio."],"answer":"0.210 ratio","check":"Original worked case; Decimal value compared with alternate Fraction expression (square root checked using float)."}],"questions":[{"stem_en":"With positive fixed weights, reducing the correlation from +0.8 to +0.2, all else equal:","options":["reduces expected portfolio return by the same proportion.","reduces portfolio variance.","increases portfolio variance."],"correct":1,"why_vi":"Giảm correlation làm giảm covariance term đối với weights dương, giữ nguyên E(Rp) và standalone volatilities. Investor có thể giảm risk mà không buộc giảm expected return với allocation cố định. Hiệu quả phụ thuộc correlation, weights và độ biến động; ρ=+1 không có benefit so với weighted SD.","trap_vi":"Diversification không đòi correlation âm; chỉ cần thấp hơn +1."},{"stem_en":"Two assets have perfect negative correlation and unequal volatilities. A zero-volatility long-only allocation requires:","options":["equal weights in every case.","weights such that the weighted volatilities are equal.","holding only the more volatile asset."],"correct":1,"why_vi":"Khi ρ=−1, portfolio SD là abs(w1σ1−w2σ2). Long-only zero-risk combination tồn tại nếu σ1,σ2>0; w1=σ2/(σ1+σ2). Đây là mathematical hedge of return variation, không tự bảo đảm mọi default/liquidity risk thực tế mất đi. Với ρ>−1 và positive SD không thể tạo zero variance chỉ bằng hai positive weights.","trap_vi":"Không mặc định equal weights tạo zero risk khi volatilities khác nhau."},{"stem_en":"In a large equal-weight portfolio of identical-volatility assets with common positive correlation, portfolio variance tends toward:","options":["zero regardless of correlation.","the sum of all individual variances.","a positive floor related to the common correlation."],"correct":2,"why_vi":"Với n assets có cùng variance σ² và average pairwise correlation ρ, σp²=σ²[1/n+(n−1)ρ/n]. Khi ρ>0 cố định và n lớn, residual variance tiến về ρσ²; phần idiosyncratic giảm nhưng common risk còn. Trường hợp ρ=0, SD=σ/√n.","trap_vi":"Không ngoại suy fixed negative ρ đến n vô hạn vì covariance matrix phải hợp lệ."},{"stem_en":"During a market crisis, correlations among risky assets increase substantially. The likely effect is:","options":["weaker diversification benefits.","guaranteed lower portfolio volatility.","higher diversification benefits at unchanged weights."],"correct":0,"why_vi":"Correlations được ước lượng từ historical data và có thể đổi theo regime; nhiều assets trở nên đồng biến trong crisis. Diversification across countries, sectors, asset classes hoặc factors giúp giảm concentration nhưng currency exposures, market stress và overlapping economic risks vẫn tồn tại.","trap_vi":"Số lượng holdings không chứng minh risk factors đa dạng."},{"stem_en":"Which addition is most likely to improve diversification, all else equal?","options":["Another asset with identical exposures to current holdings.","An asset with low correlation to the existing portfolio.","A second copy of the current portfolio."],"correct":1,"why_vi":"Chọn asset bổ sung cần xem covariance với current portfolio, expected return, liquidity và constraints. Diversification within one asset class giảm security-specific risk; across asset classes mở rộng common factor mix. International diversification phải xét currency và country risk.","trap_vi":"Không thay diversification bằng chỉ mua nhiều cổ phiếu cùng sector."},{"stem_en":"An existing portfolio has a Sharpe ratio of 0.6. A candidate asset has a Sharpe ratio of 0.35 and correlation of 0.4 with that portfolio. Under the marginal Sharpe criterion, adding a small positive weight is:","options":["not beneficial because 0.35 is less than 0.6.","beneficial because 0.35 exceeds 0.24.","beneficial only if the correlation is negative."],"correct":1,"why_vi":"CFAI p46 đưa rule để xem một khoản phân bổ nhỏ vào asset mới cải thiện Sharpe của current portfolio: SRnew > ρnew,p × SRp. Do đó asset có low standalone Sharpe vẫn hữu ích nếu correlation đủ thấp. Put options hoặc insurance có thể có expected return thấp/âm nhưng bảo vệ extreme losses; cost phải được cân nhắc. Rule là marginal risk–return criterion dưới input assumptions, không thay thế constraints.","trap_vi":"Không yêu cầu SRnew lớn hơn SRp nếu correlation <1."},{"stem_en":"Two assets have volatilities 12% and 20% with correlation −1. What weight (%) in the first asset eliminates return volatility?","options":["37.50%","50.00%","62.50%"],"correct":2,"why_vi":"Solve w×12=(1−w)×20. Thay số: 100 × 20/(12+20) = 62.50%.","trap_vi":"Đảo weight formula hoặc mặc định equal weights."},{"stem_en":"A portfolio holds 40 equal-weight assets, each with volatility 20% and common pairwise correlation 0.25. Find portfolio volatility (%).","options":["10.37%","3.16%","20.00%"],"correct":0,"why_vi":"Equal-risk portfolio: common variance plus shrinking independent component. Thay số: √(20^2 × (1/40+39 × .25/40)) = 10.37%.","trap_vi":"Giả định ρ=0 hoặc ρ=1."},{"stem_en":"A 50/50 portfolio has asset volatilities 18% and 12%. Correlation rises from 0.1 to 0.6. By how many squared percentage points does variance rise?","options":["54.00 pp²","27.00 pp²","64.80 pp²"],"correct":0,"why_vi":"Only covariance term changes; compare full variances. Thay số: 2 × .5 × .5 × 18 × 12 × (.6-.1) = 54.00 pp².","trap_vi":"Thiếu hệ số 2 hoặc lấy cross term mới thay chênh lệch."},{"stem_en":"Current portfolio Sharpe is 0.7; a candidate asset has correlation 0.3 with it. Calculate the threshold standalone Sharpe above which a small positive allocation improves Sharpe.","options":["0.210 ratio","0.700 ratio","2.333 ratio"],"correct":0,"why_vi":"Apply marginal criterion SRnew > ρnew,p SRp; threshold is 0.21. Thay số: .7 × .3 = 0.210 ratio.","trap_vi":"Bỏ correlation hoặc chia thay nhân."}],"cards":[{"front_en":"Diversification mechanism","back_vi":"Giảm correlation làm giảm covariance term đối với weights dương, giữ nguyên E(Rp) và standalone volatilities. Investor có thể giảm risk mà không buộc giảm expected return với allocation cố định. Hiệu quả phụ thuộc correlation, weights và độ biến động; ρ=+1 không có benefit so với weighted SD. | Exam trap: Diversification không đòi correlation âm; chỉ cần thấp hơn +1."},{"front_en":"Perfect negative correlation","back_vi":"Khi ρ=−1, portfolio SD là abs(w1σ1−w2σ2). Long-only zero-risk combination tồn tại nếu σ1,σ2>0; w1=σ2/(σ1+σ2). Đây là mathematical hedge of return variation, không tự bảo đảm mọi default/liquidity risk thực tế mất đi. Với ρ>−1 và positive SD không thể tạo zero variance chỉ bằng hai positive weights. | Exam trap: Không mặc định equal weights tạo zero risk khi volatilities khác nhau."},{"front_en":"Large equal-weight portfolios","back_vi":"Với n assets có cùng variance σ² và average pairwise correlation ρ, σp²=σ²[1/n+(n−1)ρ/n]. Khi ρ>0 cố định và n lớn, residual variance tiến về ρσ²; phần idiosyncratic giảm nhưng common risk còn. Trường hợp ρ=0, SD=σ/√n. | Exam trap: Không ngoại suy fixed negative ρ đến n vô hạn vì covariance matrix phải hợp lệ."},{"front_en":"Stress correlations","back_vi":"Correlations được ước lượng từ historical data và có thể đổi theo regime; nhiều assets trở nên đồng biến trong crisis. Diversification across countries, sectors, asset classes hoặc factors giúp giảm concentration nhưng currency exposures, market stress và overlapping economic risks vẫn tồn tại. | Exam trap: Số lượng holdings không chứng minh risk factors đa dạng."},{"front_en":"Diversification comparison","back_vi":"Chọn asset bổ sung cần xem covariance với current portfolio, expected return, liquidity và constraints. Diversification within one asset class giảm security-specific risk; across asset classes mở rộng common factor mix. International diversification phải xét currency và country risk. | Exam trap: Không thay diversification bằng chỉ mua nhiều cổ phiếu cùng sector."},{"front_en":"Marginal Sharpe criterion and insurance","back_vi":"CFAI p46 đưa rule để xem một khoản phân bổ nhỏ vào asset mới cải thiện Sharpe của current portfolio: SRnew > ρnew,p × SRp. Do đó asset có low standalone Sharpe vẫn hữu ích nếu correlation đủ thấp. Put options hoặc insurance có thể có expected return thấp/âm nhưng bảo vệ extreme losses; cost phải được cân nhắc. Rule là marginal risk–return criterion dưới input assumptions, không thay thế constraints. | Exam trap: Không yêu cầu SRnew lớn hơn SRp nếu correlation <1."},{"front_en":"Perfect negative correlation — formula and conditions?","back_vi":"σp=abs(w1σ1−w2σ2); w1=σ2/(σ1+σ2) for σp=0 · Offsetting weighted risks. · Two positive-volatility assets, ρ=−1, long-only."},{"front_en":"Equal-volatility diversified portfolio — formula and conditions?","back_vi":"σp²=σ²[1/n+(n−1)ρ/n] · Risk floor from common correlation. · Equal weights, equal variances, valid common correlation."},{"front_en":"Variance change from correlation — formula and conditions?","back_vi":"Δσp²=2w1w2σ1σ2Δρ · Compare correlation scenarios with other inputs fixed. · Positive weights for monotonic diversification conclusion."},{"front_en":"Marginal Sharpe test — formula and conditions?","back_vi":"SRnew > ρnew,p × SRp · A small positive allocation improves portfolio Sharpe under standard assumptions. · Positive SDs, incremental allocation, estimated inputs; not a universal allocation rule."},{"front_en":"Two assets have volatilities 12% and 20% with correlation −1. What weight (%) in the first asset eliminates return volatility?","back_vi":"Solve w×12=(1−w)×20. Thay số: 100 × 20/(12+20) = 62.50%."},{"front_en":"A portfolio holds 40 equal-weight assets, each with volatility 20% and common pairwise correlation 0.25. Find portfolio volatility (%).","back_vi":"Equal-risk portfolio: common variance plus shrinking independent component. Thay số: √(20^2 × (1/40+39 × .25/40)) = 10.37%."},{"front_en":"A 50/50 portfolio has asset volatilities 18% and 12%. Correlation rises from 0.1 to 0.6. By how many squared percentage points does variance rise?","back_vi":"Only covariance term changes; compare full variances. Thay số: 2 × .5 × .5 × 18 × 12 × (.6-.1) = 54.00 pp²."},{"front_en":"Current portfolio Sharpe is 0.7; a candidate asset has correlation 0.3 with it. Calculate the threshold standalone Sharpe above which a small positive allocation improves Sharpe.","back_vi":"Apply marginal criterion SRnew > ρnew,p SRp; threshold is 0.21. Thay số: .7 × .3 = 0.210 ratio."}]},{"id":"CFA26-09-01-LOS07","letter":"g","title_en":"Minimum-Variance Frontier, Efficient Frontier and GMVP","outcome_en":"describe and interpret risky asset minimum-variance and efficient frontiers and the global minimum-variance portfolio","overview_vi":"Bài học 1.g: Minimum-Variance Frontier, Efficient Frontier and GMVP. Học định nghĩa, điều kiện, cách áp dụng, ví dụ và English MCQ. Nội dung theo LOS CFAI 2026; ví dụ số do dự án tự viết, không sao chép câu hỏi nguồn.","source":[{"id":"CFA Institute Curriculum 2026 — Portfolio Management Volume 9","pages":"Physical PDF p. 13 (LOS), 46–57 (content)"},{"id":"Kaplan SchweserNotes 2026 — Book 4, Reading 83","pages":"Physical PDF pp. 79–81"},{"id":"SAPP CFA Level I 2026 — Portfolio Management slides","pages":"Physical PDF pp. 27–28, 35–39"}],"sections":[{"heading":"Investment opportunity set","body":"Tập hợp tất cả feasible risk–return combinations từ permissible weights. Với hai risky assets và ρ<1, curve thường cong về trái so với line nối hai standalone assets. Nhiều assets mở rộng opportunity set; short sales cho phép weights âm, thay đổi biên và leverage.","trap":"Feasible không đồng nghĩa efficient."},{"heading":"Minimum-variance frontier","body":"Minimum-variance frontier gồm portfolio variance nhỏ nhất ở mỗi target expected return. Global minimum-variance portfolio (GMVP) là điểm trái nhất của toàn bộ set, có lowest feasible SD. Phần dưới GMVP bị dominated bởi danh mục có cùng volatility nhưng higher expected return (trong standard mean–variance frontier).","trap":"Minimum variance không đồng nghĩa maximum expected return."},{"heading":"Efficient frontier","body":"Efficient frontier của risky assets là upper branch từ GMVP: tại mỗi σ đạt E(R) lớn nhất hoặc tại mỗi E(R) đạt σ nhỏ nhất. Risk-averse investors loại bỏ dominated alternatives. Thêm risk-free asset có thể tạo straight CAL dốc hơn và thay đổi tập efficient complete portfolios.","trap":"Không coi entire minimum-variance frontier là efficient."},{"heading":"Two-asset GMVP","body":"Với tổng weights 1 và unconstrained short sales, w1*=(σ2²−Cov12)/(σ1²+σ2²−2Cov12), w2*=1−w1*. Đây là nghiệm derivative của variance theo w1 (hệ quả công thức CFAI). Nếu long-only, nghiệm ngoài [0,1] bị giới hạn ở endpoint. Nếu denominator zero, hai return series giống nhau về deviations, không có nghiệm interior duy nhất.","trap":"GMVP weight phụ thuộc variance và covariance, không phụ thuộc E(R)."},{"heading":"Tangency and efficient risky allocation","body":"Khi risk-free asset được đưa vào, CAL tangent với risky efficient frontier cho maximum Sharpe ratio nếu giả định borrowing/lending đồng nhất. Risky tangency portfolio không nhất thiết là GMVP; chọn complete portfolio trên CAL theo risk preferences. Investor chỉ có risky assets phải chọn trên risky frontier theo utility.","trap":"GMVP và tangency portfolio là hai mục tiêu tối ưu khác nhau."}],"formulas":[{"name":"GMVP weight","expr":"w1=(σ2²−Cov12)/(σ1²+σ2²−2Cov12)","meaning":"Derived two-asset minimum variance weight.","conditions":"Denominator positive; short sales allowed; clamp for long-only."},{"name":"Efficient frontier criterion","expr":"Minimize w'Σw subject to Σwi=1 and Σwi E(Ri)=target","meaning":"Risk-minimizing portfolio at given return; upper branch efficient.","conditions":"Feasible weights and valid covariance matrix."},{"name":"Tangency criterion","expr":"Maximize (E(Rp)−Rf)/σp","meaning":"Highest feasible CAL slope, not minimum variance alone.","conditions":"Risk-free asset available; σp>0; positive premium."}],"examples":[{"question_en":"A feasible portfolio has expected return 6% and volatility 12%. Another feasible portfolio has expected return 8% and the same volatility. Is the first efficient?","steps_vi":["Giữ risk bằng nhau, so sánh expected return.","Risk-averse investor prefers higher mean at same SD; first portfolio dominated."],"answer":"No, the first is inefficient.","check":"Conceptual case; interpretation conditional on stated assumptions."},{"question_en":"Asset A has variance 144 pp², B variance 64 pp² and covariance 16 pp². Find the unconstrained GMVP weight in A (%).","steps_vi":["Set derivative of variance to zero with wB=1−wA.","Thay số: 100 × (64-16)/(144+64-2 × 16).","Kết quả: 27.27%."],"answer":"27.27%","check":"Original worked case; Decimal value compared with alternate Fraction expression (square root checked using float)."},{"question_en":"Asset A has volatility 10%, B 20%, and correlation zero. What is the GMVP weight in A (%)?","steps_vi":["Inverse variance weighting for uncorrelated assets; weight A higher because lower variance.","Thay số: 100 × 400/(100+400).","Kết quả: 80.00%."],"answer":"80.00%","check":"Original worked case; Decimal value compared with alternate Fraction expression (square root checked using float)."},{"question_en":"Two risky funds have expected returns X=11%, Y=9%, SDs X=20%, Y=10%, and Rf=3%. Calculate fund Y's CAL slope.","steps_vi":["Compare slope Y=.60 with slope X=.40; Y offers higher return per unit SD, though not necessarily global tangency if combinations permitted.","Thay số: (9-3)/10.","Kết quả: 0.600 ratio."],"answer":"0.600 ratio","check":"Original worked case; Decimal value compared with alternate Fraction expression (square root checked using float)."}],"questions":[{"stem_en":"A portfolio lying inside the investment opportunity set rather than on its upper boundary is:","options":["necessarily the global minimum-variance portfolio.","necessarily infeasible.","feasible but not necessarily efficient."],"correct":2,"why_vi":"Tập hợp tất cả feasible risk–return combinations từ permissible weights. Với hai risky assets và ρ<1, curve thường cong về trái so với line nối hai standalone assets. Nhiều assets mở rộng opportunity set; short sales cho phép weights âm, thay đổi biên và leverage.","trap_vi":"Feasible không đồng nghĩa efficient."},{"stem_en":"The global minimum-variance portfolio is the feasible risky portfolio with the lowest:","options":["variance across all attainable expected returns.","expected return.","Sharpe ratio."],"correct":0,"why_vi":"Minimum-variance frontier gồm portfolio variance nhỏ nhất ở mỗi target expected return. Global minimum-variance portfolio (GMVP) là điểm trái nhất của toàn bộ set, có lowest feasible SD. Phần dưới GMVP bị dominated bởi danh mục có cùng volatility nhưng higher expected return (trong standard mean–variance frontier).","trap_vi":"Minimum variance không đồng nghĩa maximum expected return."},{"stem_en":"Which portfolios form the efficient frontier of risky assets?","options":["The upper portion of the minimum-variance frontier beginning at the GMVP.","Every attainable risky portfolio.","The lower branch below the GMVP."],"correct":0,"why_vi":"Efficient frontier của risky assets là upper branch từ GMVP: tại mỗi σ đạt E(R) lớn nhất hoặc tại mỗi E(R) đạt σ nhỏ nhất. Risk-averse investors loại bỏ dominated alternatives. Thêm risk-free asset có thể tạo straight CAL dốc hơn và thay đổi tập efficient complete portfolios.","trap_vi":"Không coi entire minimum-variance frontier là efficient."},{"stem_en":"The unconstrained two-asset GMVP weights depend directly on:","options":["asset variances and covariance.","only expected returns.","only the risk-free rate."],"correct":0,"why_vi":"Với tổng weights 1 và unconstrained short sales, w1*=(σ2²−Cov12)/(σ1²+σ2²−2Cov12), w2*=1−w1*. Đây là nghiệm derivative của variance theo w1 (hệ quả công thức CFAI). Nếu long-only, nghiệm ngoài [0,1] bị giới hạn ở endpoint. Nếu denominator zero, hai return series giống nhau về deviations, không có nghiệm interior duy nhất.","trap_vi":"GMVP weight phụ thuộc variance và covariance, không phụ thuộc E(R)."},{"stem_en":"The risky tangency portfolio for a given risk-free rate maximizes:","options":["expected return without any regard to risk.","the variance of the risky portfolio.","the slope of the CAL."],"correct":2,"why_vi":"Khi risk-free asset được đưa vào, CAL tangent với risky efficient frontier cho maximum Sharpe ratio nếu giả định borrowing/lending đồng nhất. Risky tangency portfolio không nhất thiết là GMVP; chọn complete portfolio trên CAL theo risk preferences. Investor chỉ có risky assets phải chọn trên risky frontier theo utility.","trap_vi":"GMVP và tangency portfolio là hai mục tiêu tối ưu khác nhau."},{"stem_en":"Asset A has variance 144 pp², B variance 64 pp² and covariance 16 pp². Find the unconstrained GMVP weight in A (%).","options":["72.73%","27.27%","30.77%"],"correct":1,"why_vi":"Set derivative of variance to zero with wB=1−wA. Thay số: 100 × (64-16)/(144+64-2 × 16) = 27.27%.","trap_vi":"Đảo weight hoặc bỏ covariance."},{"stem_en":"Asset A has volatility 10%, B 20%, and correlation zero. What is the GMVP weight in A (%)?","options":["80.00%","66.67%","20.00%"],"correct":0,"why_vi":"Inverse variance weighting for uncorrelated assets; weight A higher because lower variance. Thay số: 100 × 400/(100+400) = 80.00%.","trap_vi":"Dùng inverse volatility thay inverse variance hoặc đảo weight."},{"stem_en":"Two risky funds have expected returns X=11%, Y=9%, SDs X=20%, Y=10%, and Rf=3%. Calculate fund Y's CAL slope.","options":["0.900 ratio","0.400 ratio","0.600 ratio"],"correct":2,"why_vi":"Compare slope Y=.60 with slope X=.40; Y offers higher return per unit SD, though not necessarily global tangency if combinations permitted. Thay số: (9-3)/10 = 0.600 ratio.","trap_vi":"Bỏ Rf hoặc tính slope X thay Y."}],"cards":[{"front_en":"Investment opportunity set","back_vi":"Tập hợp tất cả feasible risk–return combinations từ permissible weights. Với hai risky assets và ρ<1, curve thường cong về trái so với line nối hai standalone assets. Nhiều assets mở rộng opportunity set; short sales cho phép weights âm, thay đổi biên và leverage. | Exam trap: Feasible không đồng nghĩa efficient."},{"front_en":"Minimum-variance frontier","back_vi":"Minimum-variance frontier gồm portfolio variance nhỏ nhất ở mỗi target expected return. Global minimum-variance portfolio (GMVP) là điểm trái nhất của toàn bộ set, có lowest feasible SD. Phần dưới GMVP bị dominated bởi danh mục có cùng volatility nhưng higher expected return (trong standard mean–variance frontier). | Exam trap: Minimum variance không đồng nghĩa maximum expected return."},{"front_en":"Efficient frontier","back_vi":"Efficient frontier của risky assets là upper branch từ GMVP: tại mỗi σ đạt E(R) lớn nhất hoặc tại mỗi E(R) đạt σ nhỏ nhất. Risk-averse investors loại bỏ dominated alternatives. Thêm risk-free asset có thể tạo straight CAL dốc hơn và thay đổi tập efficient complete portfolios. | Exam trap: Không coi entire minimum-variance frontier là efficient."},{"front_en":"Two-asset GMVP","back_vi":"Với tổng weights 1 và unconstrained short sales, w1*=(σ2²−Cov12)/(σ1²+σ2²−2Cov12), w2*=1−w1*. Đây là nghiệm derivative của variance theo w1 (hệ quả công thức CFAI). Nếu long-only, nghiệm ngoài [0,1] bị giới hạn ở endpoint. Nếu denominator zero, hai return series giống nhau về deviations, không có nghiệm interior duy nhất. | Exam trap: GMVP weight phụ thuộc variance và covariance, không phụ thuộc E(R)."},{"front_en":"Tangency and efficient risky allocation","back_vi":"Khi risk-free asset được đưa vào, CAL tangent với risky efficient frontier cho maximum Sharpe ratio nếu giả định borrowing/lending đồng nhất. Risky tangency portfolio không nhất thiết là GMVP; chọn complete portfolio trên CAL theo risk preferences. Investor chỉ có risky assets phải chọn trên risky frontier theo utility. | Exam trap: GMVP và tangency portfolio là hai mục tiêu tối ưu khác nhau."},{"front_en":"GMVP weight — formula and conditions?","back_vi":"w1=(σ2²−Cov12)/(σ1²+σ2²−2Cov12) · Derived two-asset minimum variance weight. · Denominator positive; short sales allowed; clamp for long-only."},{"front_en":"Efficient frontier criterion — formula and conditions?","back_vi":"Minimize w'Σw subject to Σwi=1 and Σwi E(Ri)=target · Risk-minimizing portfolio at given return; upper branch efficient. · Feasible weights and valid covariance matrix."},{"front_en":"Tangency criterion — formula and conditions?","back_vi":"Maximize (E(Rp)−Rf)/σp · Highest feasible CAL slope, not minimum variance alone. · Risk-free asset available; σp>0; positive premium."},{"front_en":"Asset A has variance 144 pp², B variance 64 pp² and covariance 16 pp². Find the unconstrained GMVP weight in A (%).","back_vi":"Set derivative of variance to zero with wB=1−wA. Thay số: 100 × (64-16)/(144+64-2 × 16) = 27.27%."},{"front_en":"Asset A has volatility 10%, B 20%, and correlation zero. What is the GMVP weight in A (%)?","back_vi":"Inverse variance weighting for uncorrelated assets; weight A higher because lower variance. Thay số: 100 × 400/(100+400) = 80.00%."},{"front_en":"Two risky funds have expected returns X=11%, Y=9%, SDs X=20%, Y=10%, and Rf=3%. Calculate fund Y's CAL slope.","back_vi":"Compare slope Y=.60 with slope X=.40; Y offers higher return per unit SD, though not necessarily global tangency if combinations permitted. Thay số: (9-3)/10 = 0.600 ratio."}]}]},{"module_id":"CFA26-09-02","subject":"Portfolio Management","module_title":"Portfolio Risk and Return: Part II","level":"CFA Level I 2026","status":"Source-mapped detailed academic draft; not independently certified","language":"Vietnamese explanations, English financial terms and exam questions","source_policy":"Original explanations and questions; source-mapped to CFAI 2026 Volume 9, Kaplan Book 4 and SAPP PM slides; selected QBank patterns reviewed without copying stems","disclaimer_vi":"Bản học chi tiết dạng draft tự biên soạn. Dữ liệu lịch sử không đảm bảo lợi suất tương lai. Công thức dùng cùng kỳ, cùng đơn vị và điều kiện ghi rõ. Chưa thẩm định học thuật độc lập từng dòng và mọi câu hỏi.","los":[{"id":"CFA26-09-02-LOS01","letter":"a","title_en":"Risk-Free Asset and Risky Portfolio","outcome_en":"describe the implications of mixing a risk-free asset with a risky portfolio","overview_vi":"Bài học 2.a: Risk-Free Asset and Risky Portfolio. Học định nghĩa, điều kiện, cách áp dụng, ví dụ và English MCQ. Nội dung theo LOS CFAI 2026; ví dụ số do dự án tự viết, không sao chép câu hỏi nguồn.","source":[{"id":"CFA Institute Curriculum 2026 — Portfolio Management Volume 9","pages":"Physical PDF p. 71 (LOS), 72–76, 81–84 (content)"},{"id":"Kaplan SchweserNotes 2026 — Book 4, Reading 84","pages":"Physical PDF pp. 85–88"},{"id":"SAPP CFA Level I 2026 — Portfolio Management slides","pages":"Physical PDF pp. 52, 55–56"}],"sections":[{"heading":"Risk-free plus risky portfolio","body":"Risk-free asset trong capital market theory có return biết trước trong đúng horizon nên σ=0 và covariance với mọi risky asset bằng 0. Khi kết hợp với risky portfolio, E(Rc)=Rf+y[E(Rp)−Rf], variance=y²σp² và SD=abs(y)σp. Giữ nhiều risk-free asset làm giảm exposure tuyến tính với y≥0.","trap":"Risk-free theo nominal horizon không đồng nghĩa real purchasing power luôn không rủi ro."},{"heading":"Lending and borrowing","body":"Nếu positive risky premium, phân bổ 0<y<1 là lend tại Rf; y=1 chỉ risky fund; y>1 borrow (risk-free weight âm) để mua risky fund vượt equity vốn có. Leverage khuếch đại cả gains và losses; expected return tăng theo premium nhưng không guaranteed realized gains.","trap":"Weight 140% risky nghĩa borrow 40% of equity, không borrow 140%."},{"heading":"Different borrowing and lending rates","body":"Nếu borrowing rate Rb cao hơn lending rate Rf, leveraged segment có E(Rc)=Rb+y[E(Rp)−Rb] (y>1), kém dốc hơn lending segment với cùng P. Tại y=1 hai đoạn gặp E(Rp); global optimal borrowing risky portfolio có thể khác lending risky portfolio. Borrowing costs ảnh hưởng tangency choice và utility.","trap":"Không dùng Rf để tính chi phí vay nếu Rb khác Rf."},{"heading":"Utility choice and leverage constraints","body":"Investor lựa chọn complete portfolio dựa vào risk aversion và opportunity set; higher A thường giữ nhiều risk-free asset hơn. Margin constraints, lending/borrowing spread, restricted short sales có thể giới hạn feasible set. Một leveraged investment không tạo diversification benefit tự động; nó tăng total market exposure.","trap":"Leverage không làm Sharpe tăng trong frictionless equal-rate CAL khi scale exposure."}],"formulas":[{"name":"Risk-free allocation","expr":"E(Rc)=Rf+y(E(Rp)−Rf); σc=abs(y)σp","meaning":"Mix risky fund and risk-free asset.","conditions":"Common risk-free rate; deterministic Rf."},{"name":"Leveraged return at borrowing rate","expr":"E(Rc)=y E(Rp)−(y−1)Rb","meaning":"Net expected return after financing.","conditions":"y>1, borrowing rate Rb known."}],"examples":[{"question_en":"An investor wants twice the exposure to a risky portfolio using a loan at a known rate. Is the expected excess return twice as large as before if borrowing costs exceed the risk-free lending rate?","steps_vi":["Volatility doubles because risky weight doubles.","Expected return is 2E(Rp)−Rb, so excess over lending Rf does not equal 2[E(Rp)−Rf] when Rb>Rf."],"answer":"No; higher borrowing cost lowers the leveraged excess return relative to equal-rate CAL.","check":"Conceptual case; interpretation conditional on stated assumptions."},{"question_en":"A risky portfolio has expected return 9%, volatility 16%, Rf=3%. A complete portfolio invests 150% of investor equity in the risky portfolio, borrowing the remainder at Rf. Find expected return (%).","steps_vi":["Risk-free weight −0.5; financing cost deducted.","Thay số: 1.5 × 9-.5 × 3.","Kết quả: 12.00%."],"answer":"12.00%","check":"Original worked case; Decimal value compared with alternate Fraction expression (square root checked using float)."},{"question_en":"An investor buys 130% of equity in a risky fund with expected return 11%, financing at a borrowing rate of 5% (lending rate 2%). Find complete expected return (%).","steps_vi":["Use borrowing rate on negative cash, not lending rate.","Thay số: 1.3 × 11-.3 × 5.","Kết quả: 12.80%."],"answer":"12.80%","check":"Original worked case; Decimal value compared with alternate Fraction expression (square root checked using float)."},{"question_en":"A portfolio allocates 120% of equity to a fund with standard deviation 22%, borrowing at a constant rate. Compute complete volatility (%).","steps_vi":["Risk-free financing has no variance in this simplified model.","Thay số: 1.2 × 22.","Kết quả: 26.40%."],"answer":"26.40%","check":"Original worked case; Decimal value compared with alternate Fraction expression (square root checked using float)."}],"questions":[{"stem_en":"When 30% of a complete portfolio is invested in a risky portfolio and the rest in a risk-free asset, complete-portfolio standard deviation equals:","options":["0.30 times the risky portfolio's standard deviation.","0.70 times the risky portfolio's standard deviation.","the risky portfolio's standard deviation divided by 0.30."],"correct":0,"why_vi":"Risk-free asset trong capital market theory có return biết trước trong đúng horizon nên σ=0 và covariance với mọi risky asset bằng 0. Khi kết hợp với risky portfolio, E(Rc)=Rf+y[E(Rp)−Rf], variance=y²σp² và SD=abs(y)σp. Giữ nhiều risk-free asset làm giảm exposure tuyến tính với y≥0.","trap_vi":"Risk-free theo nominal horizon không đồng nghĩa real purchasing power luôn không rủi ro."},{"stem_en":"A complete portfolio with a risky-asset weight of 1.25 is financed by:","options":["borrowing 25% of investor equity.","lending 25% of investor equity.","borrowing 125% of investor equity."],"correct":0,"why_vi":"Nếu positive risky premium, phân bổ 0<y<1 là lend tại Rf; y=1 chỉ risky fund; y>1 borrow (risk-free weight âm) để mua risky fund vượt equity vốn có. Leverage khuếch đại cả gains và losses; expected return tăng theo premium nhưng không guaranteed realized gains.","trap_vi":"Weight 140% risky nghĩa borrow 40% of equity, không borrow 140%."},{"stem_en":"With the same risky fund and a borrowing rate above the lending rate, the leveraged segment of the CAL has:","options":["the same slope regardless of borrowing costs.","a higher slope because financing is more expensive.","a lower slope than the lending segment."],"correct":2,"why_vi":"Nếu borrowing rate Rb cao hơn lending rate Rf, leveraged segment có E(Rc)=Rb+y[E(Rp)−Rb] (y>1), kém dốc hơn lending segment với cùng P. Tại y=1 hai đoạn gặp E(Rp); global optimal borrowing risky portfolio có thể khác lending risky portfolio. Borrowing costs ảnh hưởng tangency choice và utility.","trap_vi":"Không dùng Rf để tính chi phí vay nếu Rb khác Rf."},{"stem_en":"For a positive-premium risky fund, leverage at the same risk-free borrowing rate changes expected excess return and volatility by:","options":["opposite proportional changes.","the same positive scaling factor.","reducing volatility to zero."],"correct":1,"why_vi":"Investor lựa chọn complete portfolio dựa vào risk aversion và opportunity set; higher A thường giữ nhiều risk-free asset hơn. Margin constraints, lending/borrowing spread, restricted short sales có thể giới hạn feasible set. Một leveraged investment không tạo diversification benefit tự động; nó tăng total market exposure.","trap_vi":"Leverage không làm Sharpe tăng trong frictionless equal-rate CAL khi scale exposure."},{"stem_en":"A risky portfolio has expected return 9%, volatility 16%, Rf=3%. A complete portfolio invests 150% of investor equity in the risky portfolio, borrowing the remainder at Rf. Find expected return (%).","options":["12.00%","13.50%","15.00%"],"correct":0,"why_vi":"Risk-free weight −0.5; financing cost deducted. Thay số: 1.5 × 9-.5 × 3 = 12.00%.","trap_vi":"Bỏ interest expense hoặc thêm thay trừ financing."},{"stem_en":"An investor buys 130% of equity in a risky fund with expected return 11%, financing at a borrowing rate of 5% (lending rate 2%). Find complete expected return (%).","options":["12.80%","13.70%","14.30%"],"correct":0,"why_vi":"Use borrowing rate on negative cash, not lending rate. Thay số: 1.3 × 11-.3 × 5 = 12.80%.","trap_vi":"Dùng lending rate hoặc bỏ financing."},{"stem_en":"A portfolio allocates 120% of equity to a fund with standard deviation 22%, borrowing at a constant rate. Compute complete volatility (%).","options":["22.00%","26.40%","4.40%"],"correct":1,"why_vi":"Risk-free financing has no variance in this simplified model. Thay số: 1.2 × 22 = 26.40%.","trap_vi":"Bỏ leverage hoặc dùng incremental exposure thay total exposure."}],"cards":[{"front_en":"Risk-free plus risky portfolio","back_vi":"Risk-free asset trong capital market theory có return biết trước trong đúng horizon nên σ=0 và covariance với mọi risky asset bằng 0. Khi kết hợp với risky portfolio, E(Rc)=Rf+y[E(Rp)−Rf], variance=y²σp² và SD=abs(y)σp. Giữ nhiều risk-free asset làm giảm exposure tuyến tính với y≥0. | Exam trap: Risk-free theo nominal horizon không đồng nghĩa real purchasing power luôn không rủi ro."},{"front_en":"Lending and borrowing","back_vi":"Nếu positive risky premium, phân bổ 0<y<1 là lend tại Rf; y=1 chỉ risky fund; y>1 borrow (risk-free weight âm) để mua risky fund vượt equity vốn có. Leverage khuếch đại cả gains và losses; expected return tăng theo premium nhưng không guaranteed realized gains. | Exam trap: Weight 140% risky nghĩa borrow 40% of equity, không borrow 140%."},{"front_en":"Different borrowing and lending rates","back_vi":"Nếu borrowing rate Rb cao hơn lending rate Rf, leveraged segment có E(Rc)=Rb+y[E(Rp)−Rb] (y>1), kém dốc hơn lending segment với cùng P. Tại y=1 hai đoạn gặp E(Rp); global optimal borrowing risky portfolio có thể khác lending risky portfolio. Borrowing costs ảnh hưởng tangency choice và utility. | Exam trap: Không dùng Rf để tính chi phí vay nếu Rb khác Rf."},{"front_en":"Utility choice and leverage constraints","back_vi":"Investor lựa chọn complete portfolio dựa vào risk aversion và opportunity set; higher A thường giữ nhiều risk-free asset hơn. Margin constraints, lending/borrowing spread, restricted short sales có thể giới hạn feasible set. Một leveraged investment không tạo diversification benefit tự động; nó tăng total market exposure. | Exam trap: Leverage không làm Sharpe tăng trong frictionless equal-rate CAL khi scale exposure."},{"front_en":"Risk-free allocation — formula and conditions?","back_vi":"E(Rc)=Rf+y(E(Rp)−Rf); σc=abs(y)σp · Mix risky fund and risk-free asset. · Common risk-free rate; deterministic Rf."},{"front_en":"Leveraged return at borrowing rate — formula and conditions?","back_vi":"E(Rc)=y E(Rp)−(y−1)Rb · Net expected return after financing. · y>1, borrowing rate Rb known."},{"front_en":"A risky portfolio has expected return 9%, volatility 16%, Rf=3%. A complete portfolio invests 150% of investor equity in the risky portfolio, borrowing the remainder at Rf. Find expected return (%).","back_vi":"Risk-free weight −0.5; financing cost deducted. Thay số: 1.5 × 9-.5 × 3 = 12.00%."},{"front_en":"An investor buys 130% of equity in a risky fund with expected return 11%, financing at a borrowing rate of 5% (lending rate 2%). Find complete expected return (%).","back_vi":"Use borrowing rate on negative cash, not lending rate. Thay số: 1.3 × 11-.3 × 5 = 12.80%."},{"front_en":"A portfolio allocates 120% of equity to a fund with standard deviation 22%, borrowing at a constant rate. Compute complete volatility (%).","back_vi":"Risk-free financing has no variance in this simplified model. Thay số: 1.2 × 22 = 26.40%."}]},{"id":"CFA26-09-02-LOS02","letter":"b","title_en":"CAL and Capital Market Line","outcome_en":"explain the capital allocation and capital market lines","overview_vi":"Bài học 2.b: CAL and Capital Market Line. Học định nghĩa, điều kiện, cách áp dụng, ví dụ và English MCQ. Nội dung theo LOS CFAI 2026; ví dụ số do dự án tự viết, không sao chép câu hỏi nguồn.","source":[{"id":"CFA Institute Curriculum 2026 — Portfolio Management Volume 9","pages":"Physical PDF p. 71 (LOS), 76–84 (content)"},{"id":"Kaplan SchweserNotes 2026 — Book 4, Reading 84","pages":"Physical PDF pp. 86–88"},{"id":"SAPP CFA Level I 2026 — Portfolio Management slides","pages":"Physical PDF pp. 53–56"}],"sections":[{"heading":"CAL and CML","body":"CAL mô tả kết hợp risk-free asset với bất kỳ risky portfolio P. CML là CAL đặc biệt khi P là market portfolio M trong equilibrium CAPM. Trục ngang của cả hai là total standard deviation; intercept Rf, CML slope market Sharpe ratio. CML biểu diễn efficient complete portfolios, không định giá tất cả individual securities.","trap":"Không dùng beta làm trục ngang của CML."},{"heading":"Market portfolio and passive investing","body":"Theoretical market portfolio bao gồm tất cả risky assets, value-weighted theo market capitalization. Market proxy như broad equity index chỉ là approximation, không chứa mọi risky assets. Passive strategy cố gắng replicate market/index exposures; active strategy seeks excess risk-adjusted return bằng dự báo, selection, timing hoặc tilts.","trap":"Không đồng nhất một domestic equity index với toàn bộ theoretical market portfolio."},{"heading":"CML slope and portfolios","body":"CML: E(Rp)=Rf+[(E(Rm)−Rf)/σm]σp đối với efficient combinations của market portfolio và risk-free asset, y≥0 với equal financing rate. Mỗi điểm trên CML có cùng slope (Sharpe); left of M là lending, right là leverage. Điểm nằm dưới line kém hiệu quả trong model.","trap":"Không dùng CML để đòi expected return cho một individual stock dựa trên total SD."},{"heading":"CML versus SML","body":"CML liên hệ E(R) với σ của efficient portfolios; SML liên hệ E(R) với beta của mọi assets/portfolios khi CAPM equilibrium đúng. SML slope market risk premium, CML slope market risk premium/σm. Individual stock có unsystematic risk có thể nằm dưới CML mà vẫn nằm trên SML.","trap":"Một security dưới CML không tự động overpriced; cần so với SML."},{"heading":"Optimal market portfolio and assumptions","body":"Nếu mọi investors có homogeneous expectations, single-period horizon, frictionless markets và cùng risk-free rate, tangency portfolio của họ trùng nhau. Aggregate demand risky assets phải khớp market supply, nên common tangency portfolio là market portfolio. Active views hoặc differing constraints làm benchmark theoretical khó quan sát.","trap":"CML là equilibrium result, không phải mọi market index tự động efficient."}],"formulas":[{"name":"Capital market line","expr":"E(Rp)=Rf+[(E(Rm)−Rf)/σm]σp","meaning":"Expected return of efficient market/risk-free mixtures.","conditions":"Common Rf; nonnegative market allocation."},{"name":"Market allocation","expr":"y=σp/σm; βp=y","meaning":"Portfolio along CML; target SD sets market exposure.","conditions":"y≥0, risk-free beta zero."}],"examples":[{"question_en":"An analyst compares a correctly priced individual stock's expected return with the CML at the stock's volatility. It falls below the CML. Has the analyst established overvaluation?","steps_vi":["CML applies to efficient risk-free/market mixtures and uses total SD.","Individual stock may include idiosyncratic variance. The correct CAPM pricing benchmark is SML at the stock's beta."],"answer":"No; compare expected return with CAPM/SML instead.","check":"Conceptual case; interpretation conditional on stated assumptions."},{"question_en":"Market expected return is 10%, risk-free rate 2.5%, market volatility 15%. Find the CML slope.","steps_vi":["Market premium per unit market SD.","Thay số: (10-2.5)/15.","Kết quả: 0.500 ratio."],"answer":"0.500 ratio","check":"Original worked case; Decimal value compared with alternate Fraction expression (square root checked using float)."},{"question_en":"Rf=3%, E(Rm)=12%, and σm=18%. An efficient complete portfolio targets volatility 12%. What is its expected return (%)?","steps_vi":["CML: market weight 12/18=2/3, rest bills.","Thay số: 3+(12-3) × 12/18.","Kết quả: 9.00%."],"answer":"9.00%","check":"Original worked case; Decimal value compared with alternate Fraction expression (square root checked using float)."},{"question_en":"Market volatility is 16%. An efficient CML portfolio targets volatility 24%. What is the percentage of equity allocated to the market?","steps_vi":["Scale market volatility by exposure; remaining weight −50% is borrowing.","Thay số: 100 × 24/16.","Kết quả: 150.00%."],"answer":"150.00%","check":"Original worked case; Decimal value compared with alternate Fraction expression (square root checked using float)."}],"questions":[{"stem_en":"Which statement most accurately distinguishes the CML from a general CAL?","options":["The CML uses beta instead of standard deviation on the horizontal axis.","The CML uses the market portfolio as its risky portfolio.","A CAL can only be drawn for the market portfolio."],"correct":1,"why_vi":"CAL mô tả kết hợp risk-free asset với bất kỳ risky portfolio P. CML là CAL đặc biệt khi P là market portfolio M trong equilibrium CAPM. Trục ngang của cả hai là total standard deviation; intercept Rf, CML slope market Sharpe ratio. CML biểu diễn efficient complete portfolios, không định giá tất cả individual securities.","trap_vi":"Không dùng beta làm trục ngang của CML."},{"stem_en":"Under the idealized CAPM, the market portfolio is:","options":["a value-weighted portfolio of all risky assets.","an equally weighted portfolio of only domestic large-cap stocks.","a portfolio of only short-term Treasury bills."],"correct":0,"why_vi":"Theoretical market portfolio bao gồm tất cả risky assets, value-weighted theo market capitalization. Market proxy như broad equity index chỉ là approximation, không chứa mọi risky assets. Passive strategy cố gắng replicate market/index exposures; active strategy seeks excess risk-adjusted return bằng dự báo, selection, timing hoặc tilts.","trap_vi":"Không đồng nhất một domestic equity index với toàn bộ theoretical market portfolio."},{"stem_en":"A portfolio lies on the CML to the right of the market portfolio. It most likely represents:","options":["a combination of bills and less than 100% market exposure.","a leveraged investment in the market portfolio.","a portfolio whose market risk is fully eliminated."],"correct":1,"why_vi":"CML: E(Rp)=Rf+[(E(Rm)−Rf)/σm]σp đối với efficient combinations của market portfolio và risk-free asset, y≥0 với equal financing rate. Mỗi điểm trên CML có cùng slope (Sharpe); left of M là lending, right là leverage. Điểm nằm dưới line kém hiệu quả trong model.","trap_vi":"Không dùng CML để đòi expected return cho một individual stock dựa trên total SD."},{"stem_en":"An individual stock correctly priced by the CAPM but carrying substantial company-specific risk may lie:","options":["above both lines necessarily.","on the SML and below the CML.","on the CML only and never on the SML."],"correct":1,"why_vi":"CML liên hệ E(R) với σ của efficient portfolios; SML liên hệ E(R) với beta của mọi assets/portfolios khi CAPM equilibrium đúng. SML slope market risk premium, CML slope market risk premium/σm. Individual stock có unsystematic risk có thể nằm dưới CML mà vẫn nằm trên SML.","trap_vi":"Một security dưới CML không tự động overpriced; cần so với SML."},{"stem_en":"Under homogeneous expectations and frictionless equal-rate borrowing and lending, investors differ primarily in:","options":["the identity of the common optimal risky portfolio.","their allocation between the market portfolio and the risk-free asset.","the covariance matrix used by each investor."],"correct":1,"why_vi":"Nếu mọi investors có homogeneous expectations, single-period horizon, frictionless markets và cùng risk-free rate, tangency portfolio của họ trùng nhau. Aggregate demand risky assets phải khớp market supply, nên common tangency portfolio là market portfolio. Active views hoặc differing constraints làm benchmark theoretical khó quan sát.","trap_vi":"CML là equilibrium result, không phải mọi market index tự động efficient."},{"stem_en":"Market expected return is 10%, risk-free rate 2.5%, market volatility 15%. Find the CML slope.","options":["0.667 ratio","0.500 ratio","0.033 ratio"],"correct":1,"why_vi":"Market premium per unit market SD. Thay số: (10-2.5)/15 = 0.500 ratio.","trap_vi":"Bỏ Rf hoặc variance thay SD."},{"stem_en":"Rf=3%, E(Rm)=12%, and σm=18%. An efficient complete portfolio targets volatility 12%. What is its expected return (%)?","options":["8.00%","11.00%","9.00%"],"correct":2,"why_vi":"CML: market weight 12/18=2/3, rest bills. Thay số: 3+(12-3) × 12/18 = 9.00%.","trap_vi":"Bỏ return on risk-free hoặc dùng full market return trong excess term."},{"stem_en":"Market volatility is 16%. An efficient CML portfolio targets volatility 24%. What is the percentage of equity allocated to the market?","options":["66.67%","150.00%","50.00%"],"correct":1,"why_vi":"Scale market volatility by exposure; remaining weight −50% is borrowing. Thay số: 100 × 24/16 = 150.00%.","trap_vi":"Đảo tỷ lệ hoặc chỉ báo borrowed weight."}],"cards":[{"front_en":"CAL and CML","back_vi":"CAL mô tả kết hợp risk-free asset với bất kỳ risky portfolio P. CML là CAL đặc biệt khi P là market portfolio M trong equilibrium CAPM. Trục ngang của cả hai là total standard deviation; intercept Rf, CML slope market Sharpe ratio. CML biểu diễn efficient complete portfolios, không định giá tất cả individual securities. | Exam trap: Không dùng beta làm trục ngang của CML."},{"front_en":"Market portfolio and passive investing","back_vi":"Theoretical market portfolio bao gồm tất cả risky assets, value-weighted theo market capitalization. Market proxy như broad equity index chỉ là approximation, không chứa mọi risky assets. Passive strategy cố gắng replicate market/index exposures; active strategy seeks excess risk-adjusted return bằng dự báo, selection, timing hoặc tilts. | Exam trap: Không đồng nhất một domestic equity index với toàn bộ theoretical market portfolio."},{"front_en":"CML slope and portfolios","back_vi":"CML: E(Rp)=Rf+[(E(Rm)−Rf)/σm]σp đối với efficient combinations của market portfolio và risk-free asset, y≥0 với equal financing rate. Mỗi điểm trên CML có cùng slope (Sharpe); left of M là lending, right là leverage. Điểm nằm dưới line kém hiệu quả trong model. | Exam trap: Không dùng CML để đòi expected return cho một individual stock dựa trên total SD."},{"front_en":"CML versus SML","back_vi":"CML liên hệ E(R) với σ của efficient portfolios; SML liên hệ E(R) với beta của mọi assets/portfolios khi CAPM equilibrium đúng. SML slope market risk premium, CML slope market risk premium/σm. Individual stock có unsystematic risk có thể nằm dưới CML mà vẫn nằm trên SML. | Exam trap: Một security dưới CML không tự động overpriced; cần so với SML."},{"front_en":"Optimal market portfolio and assumptions","back_vi":"Nếu mọi investors có homogeneous expectations, single-period horizon, frictionless markets và cùng risk-free rate, tangency portfolio của họ trùng nhau. Aggregate demand risky assets phải khớp market supply, nên common tangency portfolio là market portfolio. Active views hoặc differing constraints làm benchmark theoretical khó quan sát. | Exam trap: CML là equilibrium result, không phải mọi market index tự động efficient."},{"front_en":"Capital market line — formula and conditions?","back_vi":"E(Rp)=Rf+[(E(Rm)−Rf)/σm]σp · Expected return of efficient market/risk-free mixtures. · Common Rf; nonnegative market allocation."},{"front_en":"Market allocation — formula and conditions?","back_vi":"y=σp/σm; βp=y · Portfolio along CML; target SD sets market exposure. · y≥0, risk-free beta zero."},{"front_en":"Market expected return is 10%, risk-free rate 2.5%, market volatility 15%. Find the CML slope.","back_vi":"Market premium per unit market SD. Thay số: (10-2.5)/15 = 0.500 ratio."},{"front_en":"Rf=3%, E(Rm)=12%, and σm=18%. An efficient complete portfolio targets volatility 12%. What is its expected return (%)?","back_vi":"CML: market weight 12/18=2/3, rest bills. Thay số: 3+(12-3) × 12/18 = 9.00%."},{"front_en":"Market volatility is 16%. An efficient CML portfolio targets volatility 24%. What is the percentage of equity allocated to the market?","back_vi":"Scale market volatility by exposure; remaining weight −50% is borrowing. Thay số: 100 × 24/16 = 150.00%."}]},{"id":"CFA26-09-02-LOS03","letter":"c","title_en":"Systematic and Nonsystematic Risk","outcome_en":"explain market and diversifiable risk and why diversifiable risk earns no additional expected return","overview_vi":"Bài học 2.c: Systematic and Nonsystematic Risk. Học định nghĩa, điều kiện, cách áp dụng, ví dụ và English MCQ. Nội dung theo LOS CFAI 2026; ví dụ số do dự án tự viết, không sao chép câu hỏi nguồn.","source":[{"id":"CFA Institute Curriculum 2026 — Portfolio Management Volume 9","pages":"Physical PDF p. 71 (LOS), 85–90 (content)"},{"id":"Kaplan SchweserNotes 2026 — Book 4, Reading 84","pages":"Physical PDF pp. 88–90"},{"id":"SAPP CFA Level I 2026 — Portfolio Management slides","pages":"Physical PDF pp. 57–58"}],"sections":[{"heading":"Systematic risk","body":"Systematic (market, nondiversifiable) risk đến từ common economic shocks tác động nhiều assets: rates, inflation, growth, aggregate risk appetite. Diversification securities không triệt tiêu common exposure; theo CAPM, expected risk premium chỉ liên quan systematic risk measured by beta.","trap":"Systematic không phải tất cả volatility của stock."},{"heading":"Nonsystematic risk","body":"Nonsystematic/idiosyncratic/diversifiable risk liên quan sự kiện của một company/industry riêng: product recall, lawsuit, plant accident. Khi exposures đủ diversified và residual risks không tương quan mạnh, positive và negative surprises offset. Investor không được bù thêm expected premium chỉ để tự chọn chịu idiosyncratic risk có thể loại bỏ.","trap":"Một industry shock có thể common trong ngành nhưng diversifiable trong broader portfolio."},{"heading":"Risk decomposition","body":"Trong single-index model với residual uncorrelated with market, Var(Ri)=βi²σm²+σei². First term systematic variance; residual term nonsystematic variance. SD không cộng tuyến tính; total SD=√(sum of variances). Higher beta không chắc chắn higher total variance nếu residual khác.","trap":"Không lấy βσm + σe làm total SD."},{"heading":"Diversification and pricing","body":"Khi số securities tăng, idiosyncratic variance có thể giảm nhanh ban đầu rồi chậm dần; systematic risk remains. Market portfolio fully diversified trong CAPM chỉ còn market risk. Đòi premium cho company-specific risk sẽ không bền trong competitive equilibrium vì diversified investors không phải chịu risk đó.","trap":"Không suy ra tất cả diversified portfolios đều có beta=1."}],"formulas":[{"name":"Total variance decomposition","expr":"σi²=βi²σm²+σe²","meaning":"Systematic and nonsystematic variance.","conditions":"Single-index model, residual uncorrelated with market."},{"name":"Systematic variance share","expr":"R²=βi²σm²/σi²","meaning":"Fraction of variance explained by market regression.","conditions":"σi²>0, one-factor regression with intercept."}],"examples":[{"question_en":"A fund owns 100 airline stocks but no other exposures. A fuel-price shock affects all airline positions. Explain why holding many stocks may not remove the risk.","steps_vi":["Specific firm surprises may offset, but fuel price exposure is shared across the sector.","Broader diversification can diversify sector risk to an extent; aggregate macro components may remain systematic."],"answer":"Common exposure matters more than the count of holdings.","check":"Conceptual case; interpretation conditional on stated assumptions."},{"question_en":"An asset has beta 1.2, market volatility 15%, residual volatility 10%. Calculate total volatility (%).","steps_vi":["Systematic SD is 18%, but add variances, not SDs.","Thay số: √(1.2^2 × 15^2+10^2).","Kết quả: 20.59%."],"answer":"20.59%","check":"Original worked case; Decimal value compared with alternate Fraction expression (square root checked using float)."},{"question_en":"A stock's total variance is 0.0625, its beta is 0.8, and market variance is 0.04. Find nonsystematic variance (decimal squared).","steps_vi":["Subtract systematic variance β²σm² from total variance.","Thay số: .0625-.8^2 × .04.","Kết quả: 0.0369 decimal²."],"answer":"0.0369 decimal²","check":"Original worked case; Decimal value compared with alternate Fraction expression (square root checked using float)."},{"question_en":"A stock has systematic variance 0.016 and residual variance 0.024. What percentage of its total variance is explained by the market model?","steps_vi":["R² = systematic variance / total variance, under uncorrelated residual assumption.","Thay số: 100 × .016/(.016+.024).","Kết quả: 40.00%."],"answer":"40.00%","check":"Original worked case; Decimal value compared with alternate Fraction expression (square root checked using float)."}],"questions":[{"stem_en":"A broad recession that simultaneously affects most companies is an example of:","options":["purely company-specific risk.","risk that disappears when one more stock is added.","systematic risk."],"correct":2,"why_vi":"Systematic (market, nondiversifiable) risk đến từ common economic shocks tác động nhiều assets: rates, inflation, growth, aggregate risk appetite. Diversification securities không triệt tiêu common exposure; theo CAPM, expected risk premium chỉ liên quan systematic risk measured by beta.","trap_vi":"Systematic không phải tất cả volatility của stock."},{"stem_en":"Under the CAPM, investors should not expect extra return solely for bearing:","options":["positive market beta.","diversifiable company-specific risk.","systematic risk exposure."],"correct":1,"why_vi":"Nonsystematic/idiosyncratic/diversifiable risk liên quan sự kiện của một company/industry riêng: product recall, lawsuit, plant accident. Khi exposures đủ diversified và residual risks không tương quan mạnh, positive và negative surprises offset. Investor không được bù thêm expected premium chỉ để tự chọn chịu idiosyncratic risk có thể loại bỏ.","trap_vi":"Một industry shock có thể common trong ngành nhưng diversifiable trong broader portfolio."},{"stem_en":"In a single-index model with uncorrelated residuals and market returns, total variance equals:","options":["systematic standard deviation plus residual standard deviation.","only beta squared, regardless of market volatility.","systematic variance plus residual variance."],"correct":2,"why_vi":"Trong single-index model với residual uncorrelated with market, Var(Ri)=βi²σm²+σei². First term systematic variance; residual term nonsystematic variance. SD không cộng tuyến tính; total SD=√(sum of variances). Higher beta không chắc chắn higher total variance nếu residual khác.","trap_vi":"Không lấy βσm + σe làm total SD."},{"stem_en":"An investor holds a well-diversified low-beta portfolio. Relative to a concentrated portfolio with the same beta, its most likely difference is:","options":["a higher required CAPM return solely because it is diversified.","zero market risk by definition.","lower nonsystematic risk."],"correct":2,"why_vi":"Khi số securities tăng, idiosyncratic variance có thể giảm nhanh ban đầu rồi chậm dần; systematic risk remains. Market portfolio fully diversified trong CAPM chỉ còn market risk. Đòi premium cho company-specific risk sẽ không bền trong competitive equilibrium vì diversified investors không phải chịu risk đó.","trap_vi":"Không suy ra tất cả diversified portfolios đều có beta=1."},{"stem_en":"An asset has beta 1.2, market volatility 15%, residual volatility 10%. Calculate total volatility (%).","options":["28.00%","18.00%","20.59%"],"correct":2,"why_vi":"Systematic SD is 18%, but add variances, not SDs. Thay số: √(1.2^2 × 15^2+10^2) = 20.59%.","trap_vi":"Cộng SDs hoặc chỉ systematic SD."},{"stem_en":"A stock's total variance is 0.0625, its beta is 0.8, and market variance is 0.04. Find nonsystematic variance (decimal squared).","options":["0.0305 decimal²","0.0225 decimal²","0.0369 decimal²"],"correct":2,"why_vi":"Subtract systematic variance β²σm² from total variance. Thay số: .0625-.8^2 × .04 = 0.0369 decimal².","trap_vi":"Không bình phương beta hoặc bỏ beta."},{"stem_en":"A stock has systematic variance 0.016 and residual variance 0.024. What percentage of its total variance is explained by the market model?","options":["40.00%","60.00%","66.67%"],"correct":0,"why_vi":"R² = systematic variance / total variance, under uncorrelated residual assumption. Thay số: 100 × .016/(.016+.024) = 40.00%.","trap_vi":"Lấy residual share hoặc chia cho residual variance."}],"cards":[{"front_en":"Systematic risk","back_vi":"Systematic (market, nondiversifiable) risk đến từ common economic shocks tác động nhiều assets: rates, inflation, growth, aggregate risk appetite. Diversification securities không triệt tiêu common exposure; theo CAPM, expected risk premium chỉ liên quan systematic risk measured by beta. | Exam trap: Systematic không phải tất cả volatility của stock."},{"front_en":"Nonsystematic risk","back_vi":"Nonsystematic/idiosyncratic/diversifiable risk liên quan sự kiện của một company/industry riêng: product recall, lawsuit, plant accident. Khi exposures đủ diversified và residual risks không tương quan mạnh, positive và negative surprises offset. Investor không được bù thêm expected premium chỉ để tự chọn chịu idiosyncratic risk có thể loại bỏ. | Exam trap: Một industry shock có thể common trong ngành nhưng diversifiable trong broader portfolio."},{"front_en":"Risk decomposition","back_vi":"Trong single-index model với residual uncorrelated with market, Var(Ri)=βi²σm²+σei². First term systematic variance; residual term nonsystematic variance. SD không cộng tuyến tính; total SD=√(sum of variances). Higher beta không chắc chắn higher total variance nếu residual khác. | Exam trap: Không lấy βσm + σe làm total SD."},{"front_en":"Diversification and pricing","back_vi":"Khi số securities tăng, idiosyncratic variance có thể giảm nhanh ban đầu rồi chậm dần; systematic risk remains. Market portfolio fully diversified trong CAPM chỉ còn market risk. Đòi premium cho company-specific risk sẽ không bền trong competitive equilibrium vì diversified investors không phải chịu risk đó. | Exam trap: Không suy ra tất cả diversified portfolios đều có beta=1."},{"front_en":"Total variance decomposition — formula and conditions?","back_vi":"σi²=βi²σm²+σe² · Systematic and nonsystematic variance. · Single-index model, residual uncorrelated with market."},{"front_en":"Systematic variance share — formula and conditions?","back_vi":"R²=βi²σm²/σi² · Fraction of variance explained by market regression. · σi²>0, one-factor regression with intercept."},{"front_en":"An asset has beta 1.2, market volatility 15%, residual volatility 10%. Calculate total volatility (%).","back_vi":"Systematic SD is 18%, but add variances, not SDs. Thay số: √(1.2^2 × 15^2+10^2) = 20.59%."},{"front_en":"A stock's total variance is 0.0625, its beta is 0.8, and market variance is 0.04. Find nonsystematic variance (decimal squared).","back_vi":"Subtract systematic variance β²σm² from total variance. Thay số: .0625-.8^2 × .04 = 0.0369 decimal²."},{"front_en":"A stock has systematic variance 0.016 and residual variance 0.024. What percentage of its total variance is explained by the market model?","back_vi":"R² = systematic variance / total variance, under uncorrelated residual assumption. Thay số: 100 × .016/(.016+.024) = 40.00%."}]},{"id":"CFA26-09-02-LOS04","letter":"d","title_en":"Return-Generating Models and Market Model","outcome_en":"explain return generating models, the market model, and their uses","overview_vi":"Bài học 2.d: Return-Generating Models and Market Model. Học định nghĩa, điều kiện, cách áp dụng, ví dụ và English MCQ. Nội dung theo LOS CFAI 2026; ví dụ số do dự án tự viết, không sao chép câu hỏi nguồn.","source":[{"id":"CFA Institute Curriculum 2026 — Portfolio Management Volume 9","pages":"Physical PDF p. 71 (LOS), 87–90, 103–104 (content)"},{"id":"Kaplan SchweserNotes 2026 — Book 4, Reading 84","pages":"Physical PDF pp. 90–91"},{"id":"SAPP CFA Level I 2026 — Portfolio Management slides","pages":"Physical PDF pp. 59–60"}],"sections":[{"heading":"Return-generating models","body":"Mô hình kỳ vọng return kết nối asset returns với risk factors: E(Ri)−Rf=Σβij E(Fj) khi Fj là factor premiums, trong khung không có riêng alpha theo giả định. Factor loading đo sensitivity, factor premium đo expected compensation; không nhầm loading với realized return. Model inputs và estimates có uncertainty.","trap":"Không coi factor model là dự báo chính xác từng period."},{"heading":"Macroeconomic, fundamental, statistical factors","body":"Macroeconomic models dùng shocks/exposures đối với inflation, interest rates, growth. Fundamental models dùng characteristics như size, book-to-market hoặc earnings-related factors. Statistical models extract patterns từ returns/covariance, có thể không có clear economic interpretation và dễ data mining. Mục tiêu là giải thích risk/return và giảm dimensionality.","trap":"Một statistically significant factor không chắc có causal economic relation."},{"heading":"Single-index and market model","body":"Single-index framework dùng market as common factor; realized market model R_i=α_i+β_i R_m+e_i, trong đó intercept từ regression, slope beta và residual idiosyncratic. E(e)=0, Cov(e,Rm)=0 là giả định/OLS property. Market model forecasts conditional realized returns và estimates beta; không áp đặt CAPM equilibrium intercept.","trap":"Market model intercept trên raw returns khác Jensen alpha trên excess returns."},{"heading":"Fama–French and Carhart","body":"CFAI giới thiệu market, size (SMB), value (HML) và momentum (UMD) trong three-/four-factor extensions. SMB biểu thị return small minus big; HML high book-to-market minus low; UMD winners minus losers. Các factor loadings mô tả systematic exposures; empirical model fit không chứng minh equilibrium và không đảm bảo future premiums.","trap":"Size/value factor không đồng nghĩa company-specific residual."},{"heading":"Practical portfolio uses","body":"Factor models giúp estimate expected returns, decompose covariance/risk, identify shared exposures và evaluate portfolio managers relative to factor benchmarks. Với n securities, full covariance estimation đòi n(n−1)/2 correlations; factor structure có thể giảm parameters. Model error, unstable loadings, omitted factors và estimation error là limitations.","trap":"Fewer parameters không đảm bảo better forecasts."}],"formulas":[{"name":"Multifactor expected excess return","expr":"E(Ri)−Rf=Σβij E(Fj)","meaning":"Weighted expected factor premiums.","conditions":"Factors and loadings specified; model without separate alpha."},{"name":"Market model","expr":"Ri=αi+βi Rm+ei","meaning":"Conditional return and residual.","conditions":"Raw returns specification; e uncorrelated with Rm."},{"name":"Market model residual","expr":"ei=Ri−(αi+βi Rm)","meaning":"Observed return less fitted return.","conditions":"Use same horizon and return basis."},{"name":"CAPM-consistent raw intercept","expr":"αi=Rf(1−βi)","meaning":"Intercept consistent with CAPM when Rf constant.","conditions":"CAPM equilibrium restriction, not imposed on all regressions."}],"examples":[{"question_en":"An analyst fits a return regression using interest-rate surprises, inflation surprises and a broad market factor. The fitted coefficients change in a crisis. What does this imply?","steps_vi":["Factors are macroeconomic/market inputs with estimated loadings.","Parameter instability makes out-of-sample forecasts uncertain; reassess factor selection and estimation window."],"answer":"A useful factor model is not necessarily stable across regimes.","check":"Conceptual case; interpretation conditional on stated assumptions."},{"question_en":"A two-factor model has market premium 5%, factor-2 premium 2%, beta loadings 1.1 and −0.4, and Rf=3%. Calculate expected asset return (%).","steps_vi":["Add risk-free rate to weighted factor premiums.","Thay số: 3+1.1 × 5-.4 × 2.","Kết quả: 7.70%."],"answer":"7.70%","check":"Original worked case; Decimal value compared with alternate Fraction expression (square root checked using float)."},{"question_en":"A market model has intercept 0.3%, beta 1.4 and realized market return −2%. Calculate the fitted stock return (%).","steps_vi":["Raw-return regression: α+βRm, with expected residual zero.","Thay số: .3+1.4 × (-2).","Kết quả: -2.50%."],"answer":"-2.50%","check":"Original worked case; Decimal value compared with alternate Fraction expression (square root checked using float)."},{"question_en":"A stock returns 5.1%. Its market model has alpha 0.4%, beta 0.9, and market return 3%. What is the stock-specific residual in percentage points?","steps_vi":["Realized return less regression fitted return.","Thay số: 5.1-(.4+.9 × 3).","Kết quả: 2.00 pp."],"answer":"2.00 pp","check":"Original worked case; Decimal value compared with alternate Fraction expression (square root checked using float)."},{"question_en":"Assuming CAPM and constant Rf=4%, a stock has beta 0.7. What is its CAPM-consistent intercept in a raw-return market model (%)?","steps_vi":["Rearrange CAPM into α+βRm: raw intercept Rf(1−β).","Thay số: 4 × (1-.7).","Kết quả: 1.20%."],"answer":"1.20%","check":"Original worked case; Decimal value compared with alternate Fraction expression (square root checked using float)."}],"questions":[{"stem_en":"In a multifactor return-generating model, a factor loading measures:","options":["the guaranteed dollar gain from the factor.","the market's risk-free return.","the security's sensitivity to a specified factor."],"correct":2,"why_vi":"Mô hình kỳ vọng return kết nối asset returns với risk factors: E(Ri)−Rf=Σβij E(Fj) khi Fj là factor premiums, trong khung không có riêng alpha theo giả định. Factor loading đo sensitivity, factor premium đo expected compensation; không nhầm loading với realized return. Model inputs và estimates có uncertainty.","trap_vi":"Không coi factor model là dự báo chính xác từng period."},{"stem_en":"A model that extracts latent return factors without assigning them economic labels is most consistent with:","options":["a purely macroeconomic model.","a fixed contractual coupon model.","a statistical factor model."],"correct":2,"why_vi":"Macroeconomic models dùng shocks/exposures đối với inflation, interest rates, growth. Fundamental models dùng characteristics như size, book-to-market hoặc earnings-related factors. Statistical models extract patterns từ returns/covariance, có thể không có clear economic interpretation và dễ data mining. Mục tiêu là giải thích risk/return và giảm dimensionality.","trap_vi":"Một statistically significant factor không chắc có causal economic relation."},{"stem_en":"In the market model R_i = α_i + β_i R_m + e_i, the slope coefficient is:","options":["the residual.","beta.","the risk-free rate."],"correct":1,"why_vi":"Single-index framework dùng market as common factor; realized market model R_i=α_i+β_i R_m+e_i, trong đó intercept từ regression, slope beta và residual idiosyncratic. E(e)=0, Cov(e,Rm)=0 là giả định/OLS property. Market model forecasts conditional realized returns và estimates beta; không áp đặt CAPM equilibrium intercept.","trap_vi":"Market model intercept trên raw returns khác Jensen alpha trên excess returns."},{"stem_en":"The Carhart four-factor model extends a market, size and value model by adding:","options":["the risk-free rate as a company-specific residual.","only a bond's contractual maturity.","momentum."],"correct":2,"why_vi":"CFAI giới thiệu market, size (SMB), value (HML) và momentum (UMD) trong three-/four-factor extensions. SMB biểu thị return small minus big; HML high book-to-market minus low; UMD winners minus losers. Các factor loadings mô tả systematic exposures; empirical model fit không chứng minh equilibrium và không đảm bảo future premiums.","trap_vi":"Size/value factor không đồng nghĩa company-specific residual."},{"stem_en":"A key practical benefit of factor models for very large portfolios is that they can:","options":["reduce the number of separately estimated risk relationships.","eliminate all estimation error.","guarantee zero idiosyncratic risk in each security."],"correct":0,"why_vi":"Factor models giúp estimate expected returns, decompose covariance/risk, identify shared exposures và evaluate portfolio managers relative to factor benchmarks. Với n securities, full covariance estimation đòi n(n−1)/2 correlations; factor structure có thể giảm parameters. Model error, unstable loadings, omitted factors và estimation error là limitations.","trap_vi":"Fewer parameters không đảm bảo better forecasts."},{"stem_en":"A two-factor model has market premium 5%, factor-2 premium 2%, beta loadings 1.1 and −0.4, and Rf=3%. Calculate expected asset return (%).","options":["9.30%","4.70%","7.70%"],"correct":2,"why_vi":"Add risk-free rate to weighted factor premiums. Thay số: 3+1.1 × 5-.4 × 2 = 7.70%.","trap_vi":"Đảo dấu loading hoặc bỏ Rf."},{"stem_en":"A market model has intercept 0.3%, beta 1.4 and realized market return −2%. Calculate the fitted stock return (%).","options":["-2.50%","-1.70%","3.10%"],"correct":0,"why_vi":"Raw-return regression: α+βRm, with expected residual zero. Thay số: .3+1.4 × (-2) = -2.50%.","trap_vi":"Bỏ beta hoặc bỏ dấu âm market return."},{"stem_en":"A stock returns 5.1%. Its market model has alpha 0.4%, beta 0.9, and market return 3%. What is the stock-specific residual in percentage points?","options":["2.00 pp","2.40 pp","3.10 pp"],"correct":0,"why_vi":"Realized return less regression fitted return. Thay số: 5.1-(.4+.9 × 3) = 2.00 pp.","trap_vi":"Bỏ intercept hoặc nhầm fitted return với residual."},{"stem_en":"Assuming CAPM and constant Rf=4%, a stock has beta 0.7. What is its CAPM-consistent intercept in a raw-return market model (%)?","options":["2.80%","4.00%","1.20%"],"correct":2,"why_vi":"Rearrange CAPM into α+βRm: raw intercept Rf(1−β). Thay số: 4 × (1-.7) = 1.20%.","trap_vi":"Dùng Rf×beta hoặc Rf nguyên."}],"cards":[{"front_en":"Return-generating models","back_vi":"Mô hình kỳ vọng return kết nối asset returns với risk factors: E(Ri)−Rf=Σβij E(Fj) khi Fj là factor premiums, trong khung không có riêng alpha theo giả định. Factor loading đo sensitivity, factor premium đo expected compensation; không nhầm loading với realized return. Model inputs và estimates có uncertainty. | Exam trap: Không coi factor model là dự báo chính xác từng period."},{"front_en":"Macroeconomic, fundamental, statistical factors","back_vi":"Macroeconomic models dùng shocks/exposures đối với inflation, interest rates, growth. Fundamental models dùng characteristics như size, book-to-market hoặc earnings-related factors. Statistical models extract patterns từ returns/covariance, có thể không có clear economic interpretation và dễ data mining. Mục tiêu là giải thích risk/return và giảm dimensionality. | Exam trap: Một statistically significant factor không chắc có causal economic relation."},{"front_en":"Single-index and market model","back_vi":"Single-index framework dùng market as common factor; realized market model R_i=α_i+β_i R_m+e_i, trong đó intercept từ regression, slope beta và residual idiosyncratic. E(e)=0, Cov(e,Rm)=0 là giả định/OLS property. Market model forecasts conditional realized returns và estimates beta; không áp đặt CAPM equilibrium intercept. | Exam trap: Market model intercept trên raw returns khác Jensen alpha trên excess returns."},{"front_en":"Fama–French and Carhart","back_vi":"CFAI giới thiệu market, size (SMB), value (HML) và momentum (UMD) trong three-/four-factor extensions. SMB biểu thị return small minus big; HML high book-to-market minus low; UMD winners minus losers. Các factor loadings mô tả systematic exposures; empirical model fit không chứng minh equilibrium và không đảm bảo future premiums. | Exam trap: Size/value factor không đồng nghĩa company-specific residual."},{"front_en":"Practical portfolio uses","back_vi":"Factor models giúp estimate expected returns, decompose covariance/risk, identify shared exposures và evaluate portfolio managers relative to factor benchmarks. Với n securities, full covariance estimation đòi n(n−1)/2 correlations; factor structure có thể giảm parameters. Model error, unstable loadings, omitted factors và estimation error là limitations. | Exam trap: Fewer parameters không đảm bảo better forecasts."},{"front_en":"Multifactor expected excess return — formula and conditions?","back_vi":"E(Ri)−Rf=Σβij E(Fj) · Weighted expected factor premiums. · Factors and loadings specified; model without separate alpha."},{"front_en":"Market model — formula and conditions?","back_vi":"Ri=αi+βi Rm+ei · Conditional return and residual. · Raw returns specification; e uncorrelated with Rm."},{"front_en":"Market model residual — formula and conditions?","back_vi":"ei=Ri−(αi+βi Rm) · Observed return less fitted return. · Use same horizon and return basis."},{"front_en":"CAPM-consistent raw intercept — formula and conditions?","back_vi":"αi=Rf(1−βi) · Intercept consistent with CAPM when Rf constant. · CAPM equilibrium restriction, not imposed on all regressions."},{"front_en":"A two-factor model has market premium 5%, factor-2 premium 2%, beta loadings 1.1 and −0.4, and Rf=3%. Calculate expected asset return (%).","back_vi":"Add risk-free rate to weighted factor premiums. Thay số: 3+1.1 × 5-.4 × 2 = 7.70%."},{"front_en":"A market model has intercept 0.3%, beta 1.4 and realized market return −2%. Calculate the fitted stock return (%).","back_vi":"Raw-return regression: α+βRm, with expected residual zero. Thay số: .3+1.4 × (-2) = -2.50%."},{"front_en":"A stock returns 5.1%. Its market model has alpha 0.4%, beta 0.9, and market return 3%. What is the stock-specific residual in percentage points?","back_vi":"Realized return less regression fitted return. Thay số: 5.1-(.4+.9 × 3) = 2.00 pp."},{"front_en":"Assuming CAPM and constant Rf=4%, a stock has beta 0.7. What is its CAPM-consistent intercept in a raw-return market model (%)?","back_vi":"Rearrange CAPM into α+βRm: raw intercept Rf(1−β). Thay số: 4 × (1-.7) = 1.20%."}]},{"id":"CFA26-09-02-LOS05","letter":"e","title_en":"Calculation and Interpretation of Beta","outcome_en":"calculate and interpret beta","overview_vi":"Bài học 2.e: Calculation and Interpretation of Beta. Học định nghĩa, điều kiện, cách áp dụng, ví dụ và English MCQ. Nội dung theo LOS CFAI 2026; ví dụ số do dự án tự viết, không sao chép câu hỏi nguồn.","source":[{"id":"CFA Institute Curriculum 2026 — Portfolio Management Volume 9","pages":"Physical PDF p. 71 (LOS), 90–94 (content)"},{"id":"Kaplan SchweserNotes 2026 — Book 4, Reading 84","pages":"Physical PDF pp. 91–93"},{"id":"SAPP CFA Level I 2026 — Portfolio Management slides","pages":"Physical PDF pp. 61–63"}],"sections":[{"heading":"Beta definition","body":"βi=Cov(Ri,Rm)/Var(Rm)=ρim σi/σm. Beta dimensionless; measure systematic sensitivity, không đo total risk. Beta positive nghĩa cùng hướng market on average; negative beta nghĩa opposite; beta 0 nghĩa zero linear market exposure, vẫn có residual risk.","trap":"Beta không phải correlation; có thể lớn hơn 1 hoặc nhỏ hơn −1."},{"heading":"Beta from regression","body":"Estimate beta là slope OLS regression của asset returns trên market returns, cần consistent sampling periods và market proxy. Using excess returns cũng cho same slope nếu Rf constant. Beta estimates phụ thuộc sample window, changes in leverage/business, stale trading và benchmark choice; historical beta không bất biến.","trap":"Intercept và slope không thể đổi chỗ."},{"heading":"Portfolio beta","body":"βp=Σwiβi (weights theo portfolio market value, total net weights=1). Risk-free asset beta 0, market portfolio beta 1; short weight âm có thể giảm hoặc tăng beta depending on exposure. Không cần correlation matrix để tính βp nếu individual betas consistent benchmark.","trap":"Portfolio beta không phải weighted average of individual SDs."},{"heading":"Beta versus total variance","body":"Covariance-based beta phản ánh only systematic contribution. Single-index systematic variance=β²σm², systematic SD=abs(β)σm. R² = systematic variance / total variance under standard market regression. Stock beta 0 có thể có high residual variance; negative beta giảm portfolio market exposure nhưng không riskless.","trap":"Không dùng beta âm làm systematic SD âm."}],"formulas":[{"name":"Beta from covariance","expr":"βi=Cov(Ri,Rm)/σm²","meaning":"Market regression slope.","conditions":"σm²>0."},{"name":"Beta from correlation","expr":"βi=ρim σi/σm","meaning":"Convert correlation and volatilities to sensitivity.","conditions":"Matching time horizon and same market benchmark."},{"name":"Portfolio beta","expr":"βp=Σwi βi","meaning":"Weighted market exposure.","conditions":"Net weights sum to one; consistent beta benchmark."}],"examples":[{"question_en":"A stock has a beta near zero and unusually large residual volatility. A manager calls it a risk-free asset. Is this justified?","steps_vi":["Beta measures market sensitivity, not total variance.","Residual risk can be large even if Cov(stock, market)≈0."],"answer":"No, near-zero beta does not imply zero total risk.","check":"Conceptual case; interpretation conditional on stated assumptions."},{"question_en":"Covariance between a security and the market is 0.032, market variance is 0.025. Calculate beta.","steps_vi":["Divide market covariance by market variance.","Thay số: .032/.025.","Kết quả: 1.280 ratio."],"answer":"1.280 ratio","check":"Original worked case; Decimal value compared with alternate Fraction expression (square root checked using float)."},{"question_en":"A stock has volatility 28%, market volatility 20%, and correlation 0.65. Find beta.","steps_vi":["Use correlation times relative SD or covariance divided by market variance.","Thay số: .65 × 28/20.","Kết quả: 0.910 ratio."],"answer":"0.910 ratio","check":"Original worked case; Decimal value compared with alternate Fraction expression (square root checked using float)."},{"question_en":"A portfolio holds 50% in beta 1.4 stock, 30% in beta 0.6 stock, and 20% in bills. Find portfolio beta.","steps_vi":["Market-value weighted beta, cash beta zero.","Thay số: .5 × 1.4+.3 × .6+.2 × 0.","Kết quả: 0.880 ratio."],"answer":"0.880 ratio","check":"Original worked case; Decimal value compared with alternate Fraction expression (square root checked using float)."},{"question_en":"A security has negative market correlation −0.25 and volatility 24%, while the market has volatility 12%. Find beta.","steps_vi":["Negative covariance implies negative beta; absolute volatility remains positive.","Thay số: -.25 × 24/12.","Kết quả: -0.500 ratio."],"answer":"-0.500 ratio","check":"Original worked case; Decimal value compared with alternate Fraction expression (square root checked using float)."}],"questions":[{"stem_en":"A stock with beta greater than one has:","options":["a correlation with the market greater than one.","necessarily lower total volatility than the market.","greater systematic sensitivity than the market."],"correct":2,"why_vi":"βi=Cov(Ri,Rm)/Var(Rm)=ρim σi/σm. Beta dimensionless; measure systematic sensitivity, không đo total risk. Beta positive nghĩa cùng hướng market on average; negative beta nghĩa opposite; beta 0 nghĩa zero linear market exposure, vẫn có residual risk.","trap_vi":"Beta không phải correlation; có thể lớn hơn 1 hoặc nhỏ hơn −1."},{"stem_en":"A regression of a stock's returns on market returns produces a slope of 1.3. The estimated beta is:","options":["the regression intercept.","1.3.","the residual standard deviation."],"correct":1,"why_vi":"Estimate beta là slope OLS regression của asset returns trên market returns, cần consistent sampling periods và market proxy. Using excess returns cũng cho same slope nếu Rf constant. Beta estimates phụ thuộc sample window, changes in leverage/business, stale trading và benchmark choice; historical beta không bất biến.","trap_vi":"Intercept và slope không thể đổi chỗ."},{"stem_en":"A complete portfolio allocates 60% to the market and 40% to a risk-free asset. Its beta is:","options":["1.00.","0.60.","0.40."],"correct":1,"why_vi":"βp=Σwiβi (weights theo portfolio market value, total net weights=1). Risk-free asset beta 0, market portfolio beta 1; short weight âm có thể giảm hoặc tăng beta depending on exposure. Không cần correlation matrix để tính βp nếu individual betas consistent benchmark.","trap_vi":"Portfolio beta không phải weighted average of individual SDs."},{"stem_en":"A negative-beta asset has:","options":["negative linear exposure to market movements, but potentially positive total volatility.","negative total standard deviation.","no possible company-specific risk."],"correct":0,"why_vi":"Covariance-based beta phản ánh only systematic contribution. Single-index systematic variance=β²σm², systematic SD=abs(β)σm. R² = systematic variance / total variance under standard market regression. Stock beta 0 có thể có high residual variance; negative beta giảm portfolio market exposure nhưng không riskless.","trap_vi":"Không dùng beta âm làm systematic SD âm."},{"stem_en":"Covariance between a security and the market is 0.032, market variance is 0.025. Calculate beta.","options":["0.781 ratio","1.280 ratio","0.202 ratio"],"correct":1,"why_vi":"Divide market covariance by market variance. Thay số: .032/.025 = 1.280 ratio.","trap_vi":"Đảo tỷ lệ hoặc chia market SD thay variance."},{"stem_en":"A stock has volatility 28%, market volatility 20%, and correlation 0.65. Find beta.","options":["0.650 ratio","0.464 ratio","0.910 ratio"],"correct":2,"why_vi":"Use correlation times relative SD or covariance divided by market variance. Thay số: .65 × 28/20 = 0.910 ratio.","trap_vi":"Nhầm correlation với beta hoặc đảo SD ratio."},{"stem_en":"A portfolio holds 50% in beta 1.4 stock, 30% in beta 0.6 stock, and 20% in bills. Find portfolio beta.","options":["1.000 ratio","1.100 ratio","0.880 ratio"],"correct":2,"why_vi":"Market-value weighted beta, cash beta zero. Thay số: .5 × 1.4+.3 × .6+.2 × 0 = 0.880 ratio.","trap_vi":"Equal-weight hoặc normalize risky holdings mà bỏ cash."},{"stem_en":"A security has negative market correlation −0.25 and volatility 24%, while the market has volatility 12%. Find beta.","options":["0.500 ratio","-0.500 ratio","-0.250 ratio"],"correct":1,"why_vi":"Negative covariance implies negative beta; absolute volatility remains positive. Thay số: -.25 × 24/12 = -0.500 ratio.","trap_vi":"Bỏ dấu âm hoặc nhầm beta với correlation."}],"cards":[{"front_en":"Beta definition","back_vi":"βi=Cov(Ri,Rm)/Var(Rm)=ρim σi/σm. Beta dimensionless; measure systematic sensitivity, không đo total risk. Beta positive nghĩa cùng hướng market on average; negative beta nghĩa opposite; beta 0 nghĩa zero linear market exposure, vẫn có residual risk. | Exam trap: Beta không phải correlation; có thể lớn hơn 1 hoặc nhỏ hơn −1."},{"front_en":"Beta from regression","back_vi":"Estimate beta là slope OLS regression của asset returns trên market returns, cần consistent sampling periods và market proxy. Using excess returns cũng cho same slope nếu Rf constant. Beta estimates phụ thuộc sample window, changes in leverage/business, stale trading và benchmark choice; historical beta không bất biến. | Exam trap: Intercept và slope không thể đổi chỗ."},{"front_en":"Portfolio beta","back_vi":"βp=Σwiβi (weights theo portfolio market value, total net weights=1). Risk-free asset beta 0, market portfolio beta 1; short weight âm có thể giảm hoặc tăng beta depending on exposure. Không cần correlation matrix để tính βp nếu individual betas consistent benchmark. | Exam trap: Portfolio beta không phải weighted average of individual SDs."},{"front_en":"Beta versus total variance","back_vi":"Covariance-based beta phản ánh only systematic contribution. Single-index systematic variance=β²σm², systematic SD=abs(β)σm. R² = systematic variance / total variance under standard market regression. Stock beta 0 có thể có high residual variance; negative beta giảm portfolio market exposure nhưng không riskless. | Exam trap: Không dùng beta âm làm systematic SD âm."},{"front_en":"Beta from covariance — formula and conditions?","back_vi":"βi=Cov(Ri,Rm)/σm² · Market regression slope. · σm²>0."},{"front_en":"Beta from correlation — formula and conditions?","back_vi":"βi=ρim σi/σm · Convert correlation and volatilities to sensitivity. · Matching time horizon and same market benchmark."},{"front_en":"Portfolio beta — formula and conditions?","back_vi":"βp=Σwi βi · Weighted market exposure. · Net weights sum to one; consistent beta benchmark."},{"front_en":"Covariance between a security and the market is 0.032, market variance is 0.025. Calculate beta.","back_vi":"Divide market covariance by market variance. Thay số: .032/.025 = 1.280 ratio."},{"front_en":"A stock has volatility 28%, market volatility 20%, and correlation 0.65. Find beta.","back_vi":"Use correlation times relative SD or covariance divided by market variance. Thay số: .65 × 28/20 = 0.910 ratio."},{"front_en":"A portfolio holds 50% in beta 1.4 stock, 30% in beta 0.6 stock, and 20% in bills. Find portfolio beta.","back_vi":"Market-value weighted beta, cash beta zero. Thay số: .5 × 1.4+.3 × .6+.2 × 0 = 0.880 ratio."},{"front_en":"A security has negative market correlation −0.25 and volatility 24%, while the market has volatility 12%. Find beta.","back_vi":"Negative covariance implies negative beta; absolute volatility remains positive. Thay số: -.25 × 24/12 = -0.500 ratio."}]},{"id":"CFA26-09-02-LOS06","letter":"f","title_en":"CAPM Assumptions and Security Market Line","outcome_en":"explain the CAPM, its assumptions and the security market line","overview_vi":"Bài học 2.f: CAPM Assumptions and Security Market Line. Học định nghĩa, điều kiện, cách áp dụng, ví dụ và English MCQ. Nội dung theo LOS CFAI 2026; ví dụ số do dự án tự viết, không sao chép câu hỏi nguồn.","source":[{"id":"CFA Institute Curriculum 2026 — Portfolio Management Volume 9","pages":"Physical PDF p. 71 (LOS), 94–99, 101–104 (content)"},{"id":"Kaplan SchweserNotes 2026 — Book 4, Reading 84","pages":"Physical PDF pp. 94–97"},{"id":"SAPP CFA Level I 2026 — Portfolio Management slides","pages":"Physical PDF pp. 64–65"}],"sections":[{"heading":"CAPM equilibrium","body":"CAPM E(Ri)=Rf+βi[E(Rm)−Rf] áp dụng expected equilibrium returns. Market risk premium E(Rm)−Rf là compensation for one unit beta. Beta i tương ứng systematic risk. Nếu beta zero, CAPM expected return=Rf, dù total SD có thể >0. Beta negative có thể imply expected return below Rf khi premium dương.","trap":"Expected return không phải guarantee realized return."},{"heading":"CAPM assumptions","body":"Khung lý thuyết giả định investors rational, risk-averse mean–variance optimizers, homogeneous expectations, same single-period horizon; assets tradable/divisible; không taxes/transaction costs, investors price takers; unlimited borrowing/lending at common Rf và short sales feasible theo mô hình. Competitive equilibrium dẫn đến market portfolio. Frictions và heterogeneous beliefs làm hạn chế ứng dụng.","trap":"Không nhầm CAPM giả định tất cả investors có cùng risk aversion."},{"heading":"SML geometry","body":"Security Market Line plots E(R) against beta, intercept Rf at beta 0, slope market risk premium. Market M lies at beta=1 and E(Rm). All correctly priced individual assets/portfolios lie on SML regardless of residual risk, unlike CML which plots SD for efficient portfolios.","trap":"SML slope is market risk premium, not Sharpe ratio."},{"heading":"Changes in SML","body":"Giữ market premium fixed, higher Rf shifts SML upward in parallel; higher premium with fixed Rf steepens it. Không tự động suy ra parallel shift nếu E(Rm) fixed thay vì premium fixed. Risk aversion aggregate có thể ảnh hưởng market premium, nhưng đây là comparative statics với giả định nêu rõ.","trap":"Cần đọc đề giữ market return hay market premium không đổi."},{"heading":"Limitations and extensions","body":"Market portfolio theoretical không quan sát đầy đủ; beta có thể unstable, assumptions unrealistic, model chỉ one risk factor. Empirical tests gặp joint hypothesis issue giữa model và market proxy. APT, multifactor models (size, value, momentum) là extensions; chúng có assumptions và estimation risk riêng. CAPM vẫn hữu ích làm benchmark, cost of equity và expected return model.","trap":"Model limitations không làm CAPM trở thành identity cho realized returns."}],"formulas":[{"name":"CAPM/SML","expr":"E(Ri)=Rf+βi[E(Rm)−Rf]","meaning":"Equilibrium expected return with market risk premium.","conditions":"Standard CAPM assumptions; beta systematic risk."},{"name":"SML slope","expr":"E(Rm)−Rf","meaning":"Expected compensation per unit beta.","conditions":"Compare changes while holding other input fixed."}],"examples":[{"question_en":"Two assets have equal beta but different firm-specific volatility. Under CAPM equilibrium, which has the higher expected return?","steps_vi":["SML links expected returns to beta only, with common Rf and market premium.","Differences in diversifiable residual variance do not enter required expected return."],"answer":"Their CAPM expected returns are equal.","check":"Conceptual case; interpretation conditional on stated assumptions."},{"question_en":"If Rf=3% and the expected market return increases from 8% to 11%, how many percentage points does the SML slope increase?","steps_vi":["Rf held fixed; slope is market premium, not market SD.","Thay số: (11-3)-(8-3).","Kết quả: 3.00 pp."],"answer":"3.00 pp","check":"Original worked case; Decimal value compared with alternate Fraction expression (square root checked using float)."},{"question_en":"The market premium is 6% and Rf=2%. A beta-0.5 stock is correctly priced. Find its expected return (%).","steps_vi":["SML at beta 0.5; intercept Rf.","Thay số: 2+.5 × 6.","Kết quả: 5.00%."],"answer":"5.00%","check":"Original worked case; Decimal value compared with alternate Fraction expression (square root checked using float)."}],"questions":[{"stem_en":"Under the CAPM, expected return on an asset with beta zero is:","options":["the risk-free rate.","zero in all circumstances.","the expected market return."],"correct":0,"why_vi":"CAPM E(Ri)=Rf+βi[E(Rm)−Rf] áp dụng expected equilibrium returns. Market risk premium E(Rm)−Rf là compensation for one unit beta. Beta i tương ứng systematic risk. Nếu beta zero, CAPM expected return=Rf, dù total SD có thể >0. Beta negative có thể imply expected return below Rf khi premium dương.","trap_vi":"Expected return không phải guarantee realized return."},{"stem_en":"Which assumption is consistent with the standard CAPM?","options":["All investors have identical risk-aversion coefficients.","Risky securities have zero transaction-independent variance.","Investors have homogeneous expectations about asset returns and risks."],"correct":2,"why_vi":"Khung lý thuyết giả định investors rational, risk-averse mean–variance optimizers, homogeneous expectations, same single-period horizon; assets tradable/divisible; không taxes/transaction costs, investors price takers; unlimited borrowing/lending at common Rf và short sales feasible theo mô hình. Competitive equilibrium dẫn đến market portfolio. Frictions và heterogeneous beliefs làm hạn chế ứng dụng.","trap_vi":"Không nhầm CAPM giả định tất cả investors có cùng risk aversion."},{"stem_en":"The slope of the security market line is:","options":["the expected market risk premium.","the market standard deviation.","the market Sharpe ratio."],"correct":0,"why_vi":"Security Market Line plots E(R) against beta, intercept Rf at beta 0, slope market risk premium. Market M lies at beta=1 and E(Rm). All correctly priced individual assets/portfolios lie on SML regardless of residual risk, unlike CML which plots SD for efficient portfolios.","trap_vi":"SML slope is market risk premium, not Sharpe ratio."},{"stem_en":"Holding the risk-free rate fixed, an increase in the expected market risk premium causes the SML to:","options":["become flatter.","become steeper.","shift downward in parallel."],"correct":1,"why_vi":"Giữ market premium fixed, higher Rf shifts SML upward in parallel; higher premium with fixed Rf steepens it. Không tự động suy ra parallel shift nếu E(Rm) fixed thay vì premium fixed. Risk aversion aggregate có thể ảnh hưởng market premium, nhưng đây là comparative statics với giả định nêu rõ.","trap_vi":"Cần đọc đề giữ market return hay market premium không đổi."},{"stem_en":"A major empirical limitation of CAPM testing is that:","options":["beta is always identical for every asset.","the true market portfolio is difficult to observe.","the risk-free rate is defined as market volatility."],"correct":1,"why_vi":"Market portfolio theoretical không quan sát đầy đủ; beta có thể unstable, assumptions unrealistic, model chỉ one risk factor. Empirical tests gặp joint hypothesis issue giữa model và market proxy. APT, multifactor models (size, value, momentum) là extensions; chúng có assumptions và estimation risk riêng. CAPM vẫn hữu ích làm benchmark, cost of equity và expected return model.","trap_vi":"Model limitations không làm CAPM trở thành identity cho realized returns."},{"stem_en":"If Rf=3% and the expected market return increases from 8% to 11%, how many percentage points does the SML slope increase?","options":["3.00 pp","8.00 pp","5.00 pp"],"correct":0,"why_vi":"Rf held fixed; slope is market premium, not market SD. Thay số: (11-3)-(8-3) = 3.00 pp.","trap_vi":"Dùng slope mới hoặc cũ thay đổi slope."},{"stem_en":"The market premium is 6% and Rf=2%. A beta-0.5 stock is correctly priced. Find its expected return (%).","options":["3.00%","4.00%","5.00%"],"correct":2,"why_vi":"SML at beta 0.5; intercept Rf. Thay số: 2+.5 × 6 = 5.00%.","trap_vi":"Bỏ Rf hoặc trừ Rf lần nữa khỏi premium."}],"cards":[{"front_en":"CAPM equilibrium","back_vi":"CAPM E(Ri)=Rf+βi[E(Rm)−Rf] áp dụng expected equilibrium returns. Market risk premium E(Rm)−Rf là compensation for one unit beta. Beta i tương ứng systematic risk. Nếu beta zero, CAPM expected return=Rf, dù total SD có thể >0. Beta negative có thể imply expected return below Rf khi premium dương. | Exam trap: Expected return không phải guarantee realized return."},{"front_en":"CAPM assumptions","back_vi":"Khung lý thuyết giả định investors rational, risk-averse mean–variance optimizers, homogeneous expectations, same single-period horizon; assets tradable/divisible; không taxes/transaction costs, investors price takers; unlimited borrowing/lending at common Rf và short sales feasible theo mô hình. Competitive equilibrium dẫn đến market portfolio. Frictions và heterogeneous beliefs làm hạn chế ứng dụng. | Exam trap: Không nhầm CAPM giả định tất cả investors có cùng risk aversion."},{"front_en":"SML geometry","back_vi":"Security Market Line plots E(R) against beta, intercept Rf at beta 0, slope market risk premium. Market M lies at beta=1 and E(Rm). All correctly priced individual assets/portfolios lie on SML regardless of residual risk, unlike CML which plots SD for efficient portfolios. | Exam trap: SML slope is market risk premium, not Sharpe ratio."},{"front_en":"Changes in SML","back_vi":"Giữ market premium fixed, higher Rf shifts SML upward in parallel; higher premium with fixed Rf steepens it. Không tự động suy ra parallel shift nếu E(Rm) fixed thay vì premium fixed. Risk aversion aggregate có thể ảnh hưởng market premium, nhưng đây là comparative statics với giả định nêu rõ. | Exam trap: Cần đọc đề giữ market return hay market premium không đổi."},{"front_en":"Limitations and extensions","back_vi":"Market portfolio theoretical không quan sát đầy đủ; beta có thể unstable, assumptions unrealistic, model chỉ one risk factor. Empirical tests gặp joint hypothesis issue giữa model và market proxy. APT, multifactor models (size, value, momentum) là extensions; chúng có assumptions và estimation risk riêng. CAPM vẫn hữu ích làm benchmark, cost of equity và expected return model. | Exam trap: Model limitations không làm CAPM trở thành identity cho realized returns."},{"front_en":"CAPM/SML — formula and conditions?","back_vi":"E(Ri)=Rf+βi[E(Rm)−Rf] · Equilibrium expected return with market risk premium. · Standard CAPM assumptions; beta systematic risk."},{"front_en":"SML slope — formula and conditions?","back_vi":"E(Rm)−Rf · Expected compensation per unit beta. · Compare changes while holding other input fixed."},{"front_en":"If Rf=3% and the expected market return increases from 8% to 11%, how many percentage points does the SML slope increase?","back_vi":"Rf held fixed; slope is market premium, not market SD. Thay số: (11-3)-(8-3) = 3.00 pp."},{"front_en":"The market premium is 6% and Rf=2%. A beta-0.5 stock is correctly priced. Find its expected return (%).","back_vi":"SML at beta 0.5; intercept Rf. Thay số: 2+.5 × 6 = 5.00%."}]},{"id":"CFA26-09-02-LOS07","letter":"g","title_en":"Expected Return Using CAPM","outcome_en":"calculate and interpret expected asset returns using CAPM","overview_vi":"Bài học 2.g: Expected Return Using CAPM. Học định nghĩa, điều kiện, cách áp dụng, ví dụ và English MCQ. Nội dung theo LOS CFAI 2026; ví dụ số do dự án tự viết, không sao chép câu hỏi nguồn.","source":[{"id":"CFA Institute Curriculum 2026 — Portfolio Management Volume 9","pages":"Physical PDF p. 71 (LOS), 94–101 (content)"},{"id":"Kaplan SchweserNotes 2026 — Book 4, Reading 84","pages":"Physical PDF pp. 94–97"},{"id":"SAPP CFA Level I 2026 — Portfolio Management slides","pages":"Physical PDF pp. 66–67"}],"sections":[{"heading":"Required return computation","body":"Tính market risk premium = E(Rm)−Rf; multiply beta; add Rf. Inputs phải đồng tiền, nominal/real basis và horizon consistent. Nếu đề cho market premium rồi, không trừ Rf lần nữa. Expected return model là required risk-adjusted benchmark, không phải forecast return chắc chắn.","trap":"Không nhân beta với full market return rồi cộng Rf."},{"heading":"Interpretation across betas","body":"Với positive market premium, asset beta>1 có expected return > market; 0<beta<1 nằm giữa Rf và market; beta=1 same expected return; beta<0 lower than Rf. Khi market premium khác dấu, conclusions thay đổi. Beta measures exposure to market, không phải total volatility ranking.","trap":"Negative beta không imply negative expected return bắt buộc."},{"heading":"Portfolio required return","body":"CAPM linear in beta, nên E(Rp)=ΣwiE(Ri) nếu each asset follows CAPM và net weights sum to 1. Hoặc tính portfolio beta rồi thay vào equation. Khi includes bills, beta bill=0. Portfolio return actual có thể deviate do realized market moves và residual risks.","trap":"Không average betas không trọng số khi portfolio weights khác nhau."},{"heading":"Solving implied inputs","body":"Có thể đảo CAPM để suy beta=(E(Ri)−Rf)/MRP khi MRP≠0, hoặc implied MRP=(E(Ri)−Rf)/β nếu β≠0. Nếu estimated expected return do analyst forecast khác required return, không dùng nó làm beta implied equilibrium một cách vô điều kiện.","trap":"Không chia cho market return thay market risk premium."}],"formulas":[{"name":"CAPM return","expr":"E(Ri)=Rf+βi×MRP","meaning":"Expected risk-adjusted return.","conditions":"MRP=E(Rm)−Rf; if given directly don't subtract again."},{"name":"Implied beta","expr":"βi=[E(Ri)−Rf]/MRP","meaning":"Infer equilibrium beta if CAPM holds.","conditions":"MRP≠0; expected equilibrium return."},{"name":"Implied market risk premium","expr":"MRP=[E(Ri)−Rf]/βi","meaning":"Invert CAPM for MRP.","conditions":"βi≠0."}],"examples":[{"question_en":"A security has beta 1.4 and forecast return below the CAPM required return. Does CAPM guarantee that the security will lose money?","steps_vi":["Required return is an equilibrium benchmark for risk, not a realized return guarantee.","Below-benchmark forecast suggests possible overvaluation, but absolute forecast may still be positive."],"answer":"No. Distinguish expected abnormal return from actual investment loss.","check":"Conceptual case; interpretation conditional on stated assumptions."},{"question_en":"Rf=2.8%, expected market return 9.2%, beta=1.25. Find the CAPM expected return (%).","steps_vi":["Market premium first, multiply beta, then add Rf.","Thay số: 2.8+1.25 × (9.2-2.8).","Kết quả: 10.80%."],"answer":"10.80%","check":"Original worked case; Decimal value compared with alternate Fraction expression (square root checked using float)."},{"question_en":"Rf=3%, market premium 7%, beta=−0.4. Find expected return (%).","steps_vi":["Negative beta reduces required return below Rf; not necessarily negative.","Thay số: 3-.4 × 7.","Kết quả: 0.20%."],"answer":"0.20%","check":"Original worked case; Decimal value compared with alternate Fraction expression (square root checked using float)."},{"question_en":"CAPM required return=10.4%, Rf=2.4%, market premium=5%. Find implied beta.","steps_vi":["Invert CAPM using premium, not market return.","Thay số: (10.4-2.4)/5.","Kết quả: 1.600 ratio."],"answer":"1.600 ratio","check":"Original worked case; Decimal value compared with alternate Fraction expression (square root checked using float)."},{"question_en":"A correctly priced stock has expected return 11%, beta=1.4 and risk-free rate 4%. Find implied market risk premium (%).","steps_vi":["Assume CAPM equilibrium and beta nonzero.","Thay số: (11-4)/1.4.","Kết quả: 5.00%."],"answer":"5.00%","check":"Original worked case; Decimal value compared with alternate Fraction expression (square root checked using float)."},{"question_en":"A portfolio has 70% in beta 1.2 stock and 30% in beta 0.5 stock. Given Rf=3% and market premium 6%, find required return (%).","steps_vi":["Calculate weighted beta then CAPM, or weighted required returns.","Thay số: 3+(.7 × 1.2+.3 × .5) × 6.","Kết quả: 8.94%."],"answer":"8.94%","check":"Original worked case; Decimal value compared with alternate Fraction expression (square root checked using float)."}],"questions":[{"stem_en":"Given Rf = 3%, E(Rm) = 9%, and beta = 1.5, CAPM expected return is:","options":["12%.","16.5%.","9%."],"correct":0,"why_vi":"Tính market risk premium = E(Rm)−Rf; multiply beta; add Rf. Inputs phải đồng tiền, nominal/real basis và horizon consistent. Nếu đề cho market premium rồi, không trừ Rf lần nữa. Expected return model là required risk-adjusted benchmark, không phải forecast return chắc chắn.","trap_vi":"Không nhân beta với full market return rồi cộng Rf."},{"stem_en":"With a positive market risk premium, a negative-beta asset has a CAPM expected return:","options":["above the market return in all cases.","below the risk-free rate.","equal to the market return."],"correct":1,"why_vi":"Với positive market premium, asset beta>1 có expected return > market; 0<beta<1 nằm giữa Rf và market; beta=1 same expected return; beta<0 lower than Rf. Khi market premium khác dấu, conclusions thay đổi. Beta measures exposure to market, không phải total volatility ranking.","trap_vi":"Negative beta không imply negative expected return bắt buộc."},{"stem_en":"If all assets satisfy CAPM, the required return of a portfolio can be calculated using:","options":["the portfolio's weighted-average beta.","the maximum beta among its holdings.","the portfolio's total standard deviation in the SML formula."],"correct":0,"why_vi":"CAPM linear in beta, nên E(Rp)=ΣwiE(Ri) nếu each asset follows CAPM và net weights sum to 1. Hoặc tính portfolio beta rồi thay vào equation. Khi includes bills, beta bill=0. Portfolio return actual có thể deviate do realized market moves và residual risks.","trap_vi":"Không average betas không trọng số khi portfolio weights khác nhau."},{"stem_en":"An asset's CAPM required return is 9%, the risk-free rate is 3%, and the market premium is 5%. Its implied beta is:","options":["1.80.","1.20.","0.60."],"correct":1,"why_vi":"Có thể đảo CAPM để suy beta=(E(Ri)−Rf)/MRP khi MRP≠0, hoặc implied MRP=(E(Ri)−Rf)/β nếu β≠0. Nếu estimated expected return do analyst forecast khác required return, không dùng nó làm beta implied equilibrium một cách vô điều kiện.","trap_vi":"Không chia cho market return thay market risk premium."},{"stem_en":"Rf=2.8%, expected market return 9.2%, beta=1.25. Find the CAPM expected return (%).","options":["14.30%","10.80%","8.00%"],"correct":1,"why_vi":"Market premium first, multiply beta, then add Rf. Thay số: 2.8+1.25 × (9.2-2.8) = 10.80%.","trap_vi":"Dùng market return thay premium hoặc bỏ Rf."},{"stem_en":"Rf=3%, market premium 7%, beta=−0.4. Find expected return (%).","options":["5.80%","-2.80%","0.20%"],"correct":2,"why_vi":"Negative beta reduces required return below Rf; not necessarily negative. Thay số: 3-.4 × 7 = 0.20%.","trap_vi":"Bỏ dấu âm beta hoặc bỏ Rf."},{"stem_en":"CAPM required return=10.4%, Rf=2.4%, market premium=5%. Find implied beta.","options":["2.080 ratio","1.600 ratio","1.081 ratio"],"correct":1,"why_vi":"Invert CAPM using premium, not market return. Thay số: (10.4-2.4)/5 = 1.600 ratio.","trap_vi":"Dùng total asset return hoặc market return thay premium."},{"stem_en":"A correctly priced stock has expected return 11%, beta=1.4 and risk-free rate 4%. Find implied market risk premium (%).","options":["5.00%","7.86%","9.80%"],"correct":0,"why_vi":"Assume CAPM equilibrium and beta nonzero. Thay số: (11-4)/1.4 = 5.00%.","trap_vi":"Bỏ Rf hoặc nhân thay chia beta."},{"stem_en":"A portfolio has 70% in beta 1.2 stock and 30% in beta 0.5 stock. Given Rf=3% and market premium 6%, find required return (%).","options":["8.10%","8.94%","5.94%"],"correct":1,"why_vi":"Calculate weighted beta then CAPM, or weighted required returns. Thay số: 3+(.7 × 1.2+.3 × .5) × 6 = 8.94%.","trap_vi":"Equal-weight hoặc bỏ Rf."}],"cards":[{"front_en":"Required return computation","back_vi":"Tính market risk premium = E(Rm)−Rf; multiply beta; add Rf. Inputs phải đồng tiền, nominal/real basis và horizon consistent. Nếu đề cho market premium rồi, không trừ Rf lần nữa. Expected return model là required risk-adjusted benchmark, không phải forecast return chắc chắn. | Exam trap: Không nhân beta với full market return rồi cộng Rf."},{"front_en":"Interpretation across betas","back_vi":"Với positive market premium, asset beta>1 có expected return > market; 0<beta<1 nằm giữa Rf và market; beta=1 same expected return; beta<0 lower than Rf. Khi market premium khác dấu, conclusions thay đổi. Beta measures exposure to market, không phải total volatility ranking. | Exam trap: Negative beta không imply negative expected return bắt buộc."},{"front_en":"Portfolio required return","back_vi":"CAPM linear in beta, nên E(Rp)=ΣwiE(Ri) nếu each asset follows CAPM và net weights sum to 1. Hoặc tính portfolio beta rồi thay vào equation. Khi includes bills, beta bill=0. Portfolio return actual có thể deviate do realized market moves và residual risks. | Exam trap: Không average betas không trọng số khi portfolio weights khác nhau."},{"front_en":"Solving implied inputs","back_vi":"Có thể đảo CAPM để suy beta=(E(Ri)−Rf)/MRP khi MRP≠0, hoặc implied MRP=(E(Ri)−Rf)/β nếu β≠0. Nếu estimated expected return do analyst forecast khác required return, không dùng nó làm beta implied equilibrium một cách vô điều kiện. | Exam trap: Không chia cho market return thay market risk premium."},{"front_en":"CAPM return — formula and conditions?","back_vi":"E(Ri)=Rf+βi×MRP · Expected risk-adjusted return. · MRP=E(Rm)−Rf; if given directly don't subtract again."},{"front_en":"Implied beta — formula and conditions?","back_vi":"βi=[E(Ri)−Rf]/MRP · Infer equilibrium beta if CAPM holds. · MRP≠0; expected equilibrium return."},{"front_en":"Implied market risk premium — formula and conditions?","back_vi":"MRP=[E(Ri)−Rf]/βi · Invert CAPM for MRP. · βi≠0."},{"front_en":"Rf=2.8%, expected market return 9.2%, beta=1.25. Find the CAPM expected return (%).","back_vi":"Market premium first, multiply beta, then add Rf. Thay số: 2.8+1.25 × (9.2-2.8) = 10.80%."},{"front_en":"Rf=3%, market premium 7%, beta=−0.4. Find expected return (%).","back_vi":"Negative beta reduces required return below Rf; not necessarily negative. Thay số: 3-.4 × 7 = 0.20%."},{"front_en":"CAPM required return=10.4%, Rf=2.4%, market premium=5%. Find implied beta.","back_vi":"Invert CAPM using premium, not market return. Thay số: (10.4-2.4)/5 = 1.600 ratio."},{"front_en":"A correctly priced stock has expected return 11%, beta=1.4 and risk-free rate 4%. Find implied market risk premium (%).","back_vi":"Assume CAPM equilibrium and beta nonzero. Thay số: (11-4)/1.4 = 5.00%."},{"front_en":"A portfolio has 70% in beta 1.2 stock and 30% in beta 0.5 stock. Given Rf=3% and market premium 6%, find required return (%).","back_vi":"Calculate weighted beta then CAPM, or weighted required returns. Thay số: 3+(.7 × 1.2+.3 × .5) × 6 = 8.94%."}]},{"id":"CFA26-09-02-LOS08","letter":"h","title_en":"Applications of CAPM and SML","outcome_en":"describe and demonstrate uses of CAPM and the SML","overview_vi":"Bài học 2.h: Applications of CAPM and SML. Học định nghĩa, điều kiện, cách áp dụng, ví dụ và English MCQ. Nội dung theo LOS CFAI 2026; ví dụ số do dự án tự viết, không sao chép câu hỏi nguồn.","source":[{"id":"CFA Institute Curriculum 2026 — Portfolio Management Volume 9","pages":"Physical PDF p. 71 (LOS), 99–104, 111–116 (content)"},{"id":"Kaplan SchweserNotes 2026 — Book 4, Reading 84","pages":"Physical PDF pp. 98–99"},{"id":"SAPP CFA Level I 2026 — Portfolio Management slides","pages":"Physical PDF pp. 68–70"}],"sections":[{"heading":"Security selection and mispricing","body":"Compare analyst's expected return với CAPM required return at beta. Nếu expected>required, plot above SML, positive expected alpha, potentially undervalued (giữ cash-flow forecasts fixed). Expected<required: below SML, potentially overvalued. Giá tăng làm expected return giảm nếu future cash flows fixed, hướng về equilibrium.","trap":"Không gọi above SML là overpriced; không dựa riêng realized one-period return để xác nhận mispricing."},{"heading":"Cost of equity and project risk","body":"CAPM required return dùng làm cost of equity khi discount expected equity cash flows; project evaluation dùng risk of project cash flows/exposure, không máy móc beta toàn công ty nếu project khác risk. Matching currency, horizon, nominal basis và capital structure quan trọng. Project hurdle rate cho total cash flows thường cần WACC, không tự đồng nhất cost of equity.","trap":"Không dùng CAPM cost of equity làm universal discount rate cho debt cash flows."},{"heading":"Security characteristic line (SCL)","body":"SCL là empirical regression của realized excess security return trên realized excess market return. Slope beta, intercept Jensen alpha trong specification excess-return regression. SML là cross-sectional theoretical relation of expected return to beta; SCL là time-series relation of realized excess returns. Raw return intercept α_market model không nhất thiết Jensen alpha.","trap":"Không nhầm SCL trục x market excess return với SML trục x beta."},{"heading":"Portfolio construction and active views","body":"CAPM provides benchmark for expected return and risk exposures. Manager may overweight assets with positive estimated alpha, underweight negative alpha, while monitoring beta, residual risk, covariance, costs and constraints. If no superior information, low-cost broad market exposure fits passive approach. Positive forecast alpha không guarantee realized alpha; model/estimation errors can reverse ranking.","trap":"Không chọn security chỉ dựa highest standalone expected return mà bỏ risk."},{"heading":"Performance attribution vs appraisal","body":"Measurement trả lời realized portfolio return; attribution giải thích nguồn return (allocation, selection, factors); appraisal đánh giá skill vs luck sau điều chỉnh risk. CAPM alpha hỗ trợ appraisal nhưng model misspecification, benchmark choice, sample length và costs affect interpretation.","trap":"Positive alpha trong một kỳ không chứng minh skill."},{"heading":"Active portfolio information ratio","body":"Trong phần portfolio construction của CFAI PDF p115, alpha trên nonsystematic risk (αi/σei) đo abnormal return per unit residual risk thêm vào well-diversified base. Trong mô hình active selection đơn giản, relative weights của nonmarket securities proportional αi/σei²; cân nhắc diversification, estimation và constraints. Không đồng nhất residual-risk ratio này với mọi definition tracking-error information ratio ngoài ngữ cảnh.","trap":"Không chia alpha cho beta khi đang hỏi ratio dùng nonsystematic risk."},{"heading":"Forecast holding-period return","body":"Khi analyst cho current price P0, expected end price P1 và dividend D1, forecast HPR=(P1−P0+D1)/P0. So với CAPM required return cùng horizon để tìm expected alpha. Two stocks with different price levels cần normalize gains by initial price. Đây là ứng dụng SML thường gặp trong QBank Reading 84, không phải một model khác.","trap":"Không bỏ dividend hoặc dùng end price làm denominator."}],"formulas":[{"name":"Expected alpha","expr":"αexpected=E(Ri)forecast−[Rf+βi MRP]","meaning":"Positive alpha above SML; potential undervaluation conditional on forecast.","conditions":"Forecast basis and CAPM inputs consistent."},{"name":"Security characteristic line","expr":"Ri−Rf=αi+βi(Rm−Rf)+ei","meaning":"Empirical excess-return regression.","conditions":"OLS residual, time-series; not SML."},{"name":"Project present value","expr":"NPV=Σt CFt/(1+k)^t−initial outlay","meaning":"CAPM can inform k for comparable risky equity cash flows.","conditions":"Cash flow and rate consistent; not universal WACC."},{"name":"Active-selection ratio","expr":"αi/σei; relative active weights ∝ αi/σei²","meaning":"Simplified CFAI residual-risk framework.","conditions":"Requires residual risk >0, model assumptions and constraints; not universal allocation rule."},{"name":"Forecast holding-period return","expr":"(P1−P0+D1)/P0","meaning":"Expected price change plus dividend income divided by initial price.","conditions":"One-period forecast, cash dividend and prices same currency; compare with CAPM benchmark."}],"examples":[{"question_en":"A manager has identified a positive expected alpha relative to a domestic index but the asset is a foreign bond. Does positive alpha prove that its price is wrong?","steps_vi":["Benchmark may omit foreign fixed-income exposures and currency risk.","CFAI notes an asset can improve risk-return versus an incomplete market proxy without being inherently mispriced; review benchmark and covariance."],"answer":"No; positive estimated alpha is conditional evidence, not proof.","check":"Conceptual case; interpretation conditional on stated assumptions."},{"question_en":"A stock has analyst forecast return 12.5%, beta 1.1, Rf=3%, and market premium 7%. Find its expected alpha in percentage points.","steps_vi":["Above SML by positive expected alpha; potential undervaluation conditional on inputs.","Thay số: 12.5-(3+1.1 × 7).","Kết quả: 1.80 pp."],"answer":"1.80 pp","check":"Original worked case; Decimal value compared with alternate Fraction expression (square root checked using float)."},{"question_en":"A one-year equity-financed project costs $100 and has expected terminal cash flow $119. The project beta is 1.2, Rf=3%, MRP=5%. Find NPV in dollars.","steps_vi":["Use CAPM project required return 9%; discount matching expected equity cash flow.","Thay số: 119/(1+(3+1.2 × 5)/100)-100.","Kết quả: 9.17 USD."],"answer":"9.17 USD","check":"Original worked case; Decimal value compared with alternate Fraction expression (square root checked using float)."},{"question_en":"A stock has estimated alpha 2.1% and residual volatility 14%. Calculate the alpha-to-residual-risk ratio in the simplified active-selection framework.","steps_vi":["Use nonsystematic volatility, not beta or total SD.","Thay số: 2.1/14.","Kết quả: 0.150 ratio."],"answer":"0.150 ratio","check":"Original worked case; Decimal value compared with alternate Fraction expression (square root checked using float)."},{"question_en":"A stock costs $50, is expected to sell for $54 in one year and pay a $1.50 dividend. Its beta is 1.2, Rf=3%, MRP=5%. Compute forecast alpha in percentage points.","steps_vi":["Forecast HPR=11%; required return 9%; positive alpha implies potential undervaluation conditional on estimates.","Thay số: 100 × (54-50+1.5)/50-(3+1.2 × 5).","Kết quả: 2.00 pp."],"answer":"2.00 pp","check":"Original worked case; Decimal value compared with alternate Fraction expression (square root checked using float)."}],"questions":[{"stem_en":"An analyst estimates a stock's expected return above its CAPM required return. Under the analyst's assumptions the stock appears:","options":["overvalued.","undervalued.","correctly priced regardless of the gap."],"correct":1,"why_vi":"Compare analyst's expected return với CAPM required return at beta. Nếu expected>required, plot above SML, positive expected alpha, potentially undervalued (giữ cash-flow forecasts fixed). Expected<required: below SML, potentially overvalued. Giá tăng làm expected return giảm nếu future cash flows fixed, hướng về equilibrium.","trap_vi":"Không gọi above SML là overpriced; không dựa riêng realized one-period return để xác nhận mispricing."},{"stem_en":"For a project with materially different systematic risk from the firm's existing business, a suitable CAPM input is:","options":["the firm's current beta regardless of project risk.","zero beta because projects are not traded directly.","a beta reflecting the project's systematic risk."],"correct":2,"why_vi":"CAPM required return dùng làm cost of equity khi discount expected equity cash flows; project evaluation dùng risk of project cash flows/exposure, không máy móc beta toàn công ty nếu project khác risk. Matching currency, horizon, nominal basis và capital structure quan trọng. Project hurdle rate cho total cash flows thường cần WACC, không tự đồng nhất cost of equity.","trap_vi":"Không dùng CAPM cost of equity làm universal discount rate cho debt cash flows."},{"stem_en":"In a security characteristic line estimated using excess returns, the intercept is most directly interpreted as:","options":["market beta.","estimated Jensen's alpha.","market standard deviation."],"correct":1,"why_vi":"SCL là empirical regression của realized excess security return trên realized excess market return. Slope beta, intercept Jensen alpha trong specification excess-return regression. SML là cross-sectional theoretical relation of expected return to beta; SCL là time-series relation of realized excess returns. Raw return intercept α_market model không nhất thiết Jensen alpha.","trap_vi":"Không nhầm SCL trục x market excess return với SML trục x beta."},{"stem_en":"A manager identifying positive estimated alpha should still consider:","options":["only the stock's nominal price.","no risk constraints because estimated alpha is positive.","portfolio covariance, implementation costs, and estimation uncertainty."],"correct":2,"why_vi":"CAPM provides benchmark for expected return and risk exposures. Manager may overweight assets with positive estimated alpha, underweight negative alpha, while monitoring beta, residual risk, covariance, costs and constraints. If no superior information, low-cost broad market exposure fits passive approach. Positive forecast alpha không guarantee realized alpha; model/estimation errors can reverse ranking.","trap_vi":"Không chọn security chỉ dựa highest standalone expected return mà bỏ risk."},{"stem_en":"Determining whether a manager's observed performance reflects skill rather than luck is primarily:","options":["return measurement alone.","the definition of the risk-free rate.","performance appraisal."],"correct":2,"why_vi":"Measurement trả lời realized portfolio return; attribution giải thích nguồn return (allocation, selection, factors); appraisal đánh giá skill vs luck sau điều chỉnh risk. CAPM alpha hỗ trợ appraisal nhưng model misspecification, benchmark choice, sample length và costs affect interpretation.","trap_vi":"Positive alpha trong một kỳ không chứng minh skill."},{"stem_en":"In the simplified CFAI active-security selection framework, holding expected alpha fixed, a security becomes more attractive when its:","options":["nonsystematic risk increases.","estimated residual variance becomes irrelevant.","nonsystematic risk decreases."],"correct":2,"why_vi":"Trong phần portfolio construction của CFAI PDF p115, alpha trên nonsystematic risk (αi/σei) đo abnormal return per unit residual risk thêm vào well-diversified base. Trong mô hình active selection đơn giản, relative weights của nonmarket securities proportional αi/σei²; cân nhắc diversification, estimation và constraints. Không đồng nhất residual-risk ratio này với mọi definition tracking-error information ratio ngoài ngữ cảnh.","trap_vi":"Không chia alpha cho beta khi đang hỏi ratio dùng nonsystematic risk."},{"stem_en":"A stock expected to appreciate by 5% and pay a dividend yield of 2% has forecast one-period holding return closest to:","options":["5%.","2%.","7%."],"correct":2,"why_vi":"Khi analyst cho current price P0, expected end price P1 và dividend D1, forecast HPR=(P1−P0+D1)/P0. So với CAPM required return cùng horizon để tìm expected alpha. Two stocks with different price levels cần normalize gains by initial price. Đây là ứng dụng SML thường gặp trong QBank Reading 84, không phải một model khác.","trap_vi":"Không bỏ dividend hoặc dùng end price làm denominator."},{"stem_en":"A stock has analyst forecast return 12.5%, beta 1.1, Rf=3%, and market premium 7%. Find its expected alpha in percentage points.","options":["1.80 pp","5.50 pp","2.50 pp"],"correct":0,"why_vi":"Above SML by positive expected alpha; potential undervaluation conditional on inputs. Thay số: 12.5-(3+1.1 × 7) = 1.80 pp.","trap_vi":"Trừ premium trực tiếp hoặc dùng market return thay beta-adjusted benchmark."},{"stem_en":"A one-year equity-financed project costs $100 and has expected terminal cash flow $119. The project beta is 1.2, Rf=3%, MRP=5%. Find NPV in dollars.","options":["9.17 USD","19.00 USD","13.33 USD"],"correct":0,"why_vi":"Use CAPM project required return 9%; discount matching expected equity cash flow. Thay số: 119/(1+(3+1.2 × 5)/100)-100 = 9.17 USD.","trap_vi":"Bỏ discount hoặc dùng market premium làm discount rate."},{"stem_en":"A stock has estimated alpha 2.1% and residual volatility 14%. Calculate the alpha-to-residual-risk ratio in the simplified active-selection framework.","options":["0.011 ratio","0.150 ratio","6.667 ratio"],"correct":1,"why_vi":"Use nonsystematic volatility, not beta or total SD. Thay số: 2.1/14 = 0.150 ratio.","trap_vi":"Chia residual variance hoặc đảo ratio."},{"stem_en":"A stock costs $50, is expected to sell for $54 in one year and pay a $1.50 dividend. Its beta is 1.2, Rf=3%, MRP=5%. Compute forecast alpha in percentage points.","options":["-1.00 pp","3.00 pp","2.00 pp"],"correct":2,"why_vi":"Forecast HPR=11%; required return 9%; positive alpha implies potential undervaluation conditional on estimates. Thay số: 100 × (54-50+1.5)/50-(3+1.2 × 5) = 2.00 pp.","trap_vi":"Bỏ dividend hoặc bỏ beta adjustment."}],"cards":[{"front_en":"Security selection and mispricing","back_vi":"Compare analyst's expected return với CAPM required return at beta. Nếu expected>required, plot above SML, positive expected alpha, potentially undervalued (giữ cash-flow forecasts fixed). Expected<required: below SML, potentially overvalued. Giá tăng làm expected return giảm nếu future cash flows fixed, hướng về equilibrium. | Exam trap: Không gọi above SML là overpriced; không dựa riêng realized one-period return để xác nhận mispricing."},{"front_en":"Cost of equity and project risk","back_vi":"CAPM required return dùng làm cost of equity khi discount expected equity cash flows; project evaluation dùng risk of project cash flows/exposure, không máy móc beta toàn công ty nếu project khác risk. Matching currency, horizon, nominal basis và capital structure quan trọng. Project hurdle rate cho total cash flows thường cần WACC, không tự đồng nhất cost of equity. | Exam trap: Không dùng CAPM cost of equity làm universal discount rate cho debt cash flows."},{"front_en":"Security characteristic line (SCL)","back_vi":"SCL là empirical regression của realized excess security return trên realized excess market return. Slope beta, intercept Jensen alpha trong specification excess-return regression. SML là cross-sectional theoretical relation of expected return to beta; SCL là time-series relation of realized excess returns. Raw return intercept α_market model không nhất thiết Jensen alpha. | Exam trap: Không nhầm SCL trục x market excess return với SML trục x beta."},{"front_en":"Portfolio construction and active views","back_vi":"CAPM provides benchmark for expected return and risk exposures. Manager may overweight assets with positive estimated alpha, underweight negative alpha, while monitoring beta, residual risk, covariance, costs and constraints. If no superior information, low-cost broad market exposure fits passive approach. Positive forecast alpha không guarantee realized alpha; model/estimation errors can reverse ranking. | Exam trap: Không chọn security chỉ dựa highest standalone expected return mà bỏ risk."},{"front_en":"Performance attribution vs appraisal","back_vi":"Measurement trả lời realized portfolio return; attribution giải thích nguồn return (allocation, selection, factors); appraisal đánh giá skill vs luck sau điều chỉnh risk. CAPM alpha hỗ trợ appraisal nhưng model misspecification, benchmark choice, sample length và costs affect interpretation. | Exam trap: Positive alpha trong một kỳ không chứng minh skill."},{"front_en":"Active portfolio information ratio","back_vi":"Trong phần portfolio construction của CFAI PDF p115, alpha trên nonsystematic risk (αi/σei) đo abnormal return per unit residual risk thêm vào well-diversified base. Trong mô hình active selection đơn giản, relative weights của nonmarket securities proportional αi/σei²; cân nhắc diversification, estimation và constraints. Không đồng nhất residual-risk ratio này với mọi definition tracking-error information ratio ngoài ngữ cảnh. | Exam trap: Không chia alpha cho beta khi đang hỏi ratio dùng nonsystematic risk."},{"front_en":"Forecast holding-period return","back_vi":"Khi analyst cho current price P0, expected end price P1 và dividend D1, forecast HPR=(P1−P0+D1)/P0. So với CAPM required return cùng horizon để tìm expected alpha. Two stocks with different price levels cần normalize gains by initial price. Đây là ứng dụng SML thường gặp trong QBank Reading 84, không phải một model khác. | Exam trap: Không bỏ dividend hoặc dùng end price làm denominator."},{"front_en":"Expected alpha — formula and conditions?","back_vi":"αexpected=E(Ri)forecast−[Rf+βi MRP] · Positive alpha above SML; potential undervaluation conditional on forecast. · Forecast basis and CAPM inputs consistent."},{"front_en":"Security characteristic line — formula and conditions?","back_vi":"Ri−Rf=αi+βi(Rm−Rf)+ei · Empirical excess-return regression. · OLS residual, time-series; not SML."},{"front_en":"Project present value — formula and conditions?","back_vi":"NPV=Σt CFt/(1+k)^t−initial outlay · CAPM can inform k for comparable risky equity cash flows. · Cash flow and rate consistent; not universal WACC."},{"front_en":"Active-selection ratio — formula and conditions?","back_vi":"αi/σei; relative active weights ∝ αi/σei² · Simplified CFAI residual-risk framework. · Requires residual risk >0, model assumptions and constraints; not universal allocation rule."},{"front_en":"Forecast holding-period return — formula and conditions?","back_vi":"(P1−P0+D1)/P0 · Expected price change plus dividend income divided by initial price. · One-period forecast, cash dividend and prices same currency; compare with CAPM benchmark."},{"front_en":"A stock has analyst forecast return 12.5%, beta 1.1, Rf=3%, and market premium 7%. Find its expected alpha in percentage points.","back_vi":"Above SML by positive expected alpha; potential undervaluation conditional on inputs. Thay số: 12.5-(3+1.1 × 7) = 1.80 pp."},{"front_en":"A one-year equity-financed project costs $100 and has expected terminal cash flow $119. The project beta is 1.2, Rf=3%, MRP=5%. Find NPV in dollars.","back_vi":"Use CAPM project required return 9%; discount matching expected equity cash flow. Thay số: 119/(1+(3+1.2 × 5)/100)-100 = 9.17 USD."},{"front_en":"A stock has estimated alpha 2.1% and residual volatility 14%. Calculate the alpha-to-residual-risk ratio in the simplified active-selection framework.","back_vi":"Use nonsystematic volatility, not beta or total SD. Thay số: 2.1/14 = 0.150 ratio."},{"front_en":"A stock costs $50, is expected to sell for $54 in one year and pay a $1.50 dividend. Its beta is 1.2, Rf=3%, MRP=5%. Compute forecast alpha in percentage points.","back_vi":"Forecast HPR=11%; required return 9%; positive alpha implies potential undervaluation conditional on estimates. Thay số: 100 × (54-50+1.5)/50-(3+1.2 × 5) = 2.00 pp."}]},{"id":"CFA26-09-02-LOS09","letter":"i","title_en":"Sharpe, Treynor, M² and Jensen Alpha","outcome_en":"calculate and interpret Sharpe, Treynor, M-squared and Jensen’s alpha","overview_vi":"Bài học 2.i: Sharpe, Treynor, M² and Jensen Alpha. Học định nghĩa, điều kiện, cách áp dụng, ví dụ và English MCQ. Nội dung theo LOS CFAI 2026; ví dụ số do dự án tự viết, không sao chép câu hỏi nguồn.","source":[{"id":"CFA Institute Curriculum 2026 — Portfolio Management Volume 9","pages":"Physical PDF p. 71 (LOS), 104–110 (content)"},{"id":"Kaplan SchweserNotes 2026 — Book 4, Reading 84","pages":"Physical PDF pp. 100–102"},{"id":"SAPP CFA Level I 2026 — Portfolio Management slides","pages":"Physical PDF pp. 71–72"}],"sections":[{"heading":"Sharpe ratio","body":"Sharpe=(Rp−Rf)/σp (ex post average period returns và SD, hoặc ex ante expectations). Measures excess return per total risk, phù hợp khi portfolio là toàn bộ risky wealth hoặc chưa diversified. Dùng same horizon và same Rf. Với negative premium, simple rankings can be misleading (more risk can make negative ratio less negative).","trap":"Không dùng beta ở mẫu Sharpe."},{"heading":"Treynor ratio","body":"Treynor=(Rp−Rf)/βp, measures excess return per unit systematic risk. Hữu ích khi portfolio là component trong well-diversified overall wealth. Beta phải nonzero; standard ranking meaningful nhất khi beta và premium dương. Treynor units are return per unit beta, khác Sharpe dimensionless.","trap":"Không xếp hạng beta âm hoặc bằng 0 theo ratio đơn giản."},{"heading":"M-squared and M-squared alpha","body":"Theo CFAI Volume 9 PDF p107, M²=Rf+Sharpe_p×σm = risk-adjusted portfolio return at market volatility. M² alpha=M²−Rm là excess over benchmark market return. M² có return units; M² và Sharpe rank identically for same Rf,σm. Construction scales risky portfolio to σm via lending/borrowing assuming same Rf.","trap":"Một số tài liệu gọi M² là chênh lệch; trong bộ này M² và M² alpha được tách rõ đúng CFAI."},{"heading":"Jensen's alpha","body":"Jensen alpha = Rp−[Rf+βp(Rm−Rf)] cho ex post averages; ex ante alpha là expected return minus CAPM benchmark. Positive alpha means above required return given beta; negative below. Units return percentage points. Khi market model/benchmark sai, alpha có thể phản ánh omitted risk, không tự động skill.","trap":"Không lấy actual return trừ market return nếu beta khác 1."},{"heading":"Ranking divergence","body":"Sharpe/M² use total volatility; Treynor/Jensen use market beta. Concentrated manager có high residual risk có thể high Treynor nhưng low Sharpe. Với cùng market benchmark, positive premium/beta và equal risk assumptions, rankings tùy measure; Jensen alpha là absolute excess vs benchmark, Treynor ratio normalized by beta, nên không luôn đồng thứ hạng.","trap":"Không khẳng định Sharpe, Treynor, Jensen luôn cùng rank."},{"heading":"Benchmark consistency and interpretation","body":"Performance estimates dùng period-matched average returns, volatility, beta and Rf. Risk-free lending assumption ảnh hưởng M² construction; fees/gross-net consistency và realistic benchmark important. Appraisal is retrospective; realized positive alpha có thể do chance, time-varying beta hoặc model error. So sánh risk-adjusted returns với phù hợp investment mandate.","trap":"Không annualize numerator và giữ denominator monthly mà không chuyển đổi."}],"formulas":[{"name":"Sharpe ratio","expr":"(Rp−Rf)/σp","meaning":"Excess return per total standard deviation.","conditions":"Same period; σp>0; positive premium for straightforward rankings."},{"name":"Treynor ratio","expr":"(Rp−Rf)/βp","meaning":"Excess return per beta unit.","conditions":"βp>0 and positive premium for straightforward rankings."},{"name":"M²","expr":"Rf+Sharpe_p×σm","meaning":"Market-volatility-adjusted return, per CFAI convention.","conditions":"Scale fund using risk-free lending/borrowing assumption."},{"name":"M² alpha","expr":"M²−Rm","meaning":"Risk-adjusted return difference against market.","conditions":"Same market, same period."},{"name":"Jensen alpha","expr":"Rp−[Rf+βp(Rm−Rf)]","meaning":"Actual return above CAPM expected benchmark.","conditions":"Ex post period-consistent data, or ex ante expected inputs clearly stated."}],"examples":[{"question_en":"An endowment must choose one undiversified manager to manage all assets. A manager with high Treynor ratio has substantial residual volatility. Which measure should receive particular attention?","steps_vi":["The total portfolio matters, not just a small component of diversified wealth.","Sharpe and M² incorporate total volatility; Treynor and Jensen focus on systematic beta."],"answer":"Use total-risk appraisal measures (Sharpe/M²), alongside appropriate benchmark and constraints.","check":"Conceptual case; interpretation conditional on stated assumptions."},{"question_en":"A fund earns average return 11%, risk-free rate 3%, portfolio SD 16%. Calculate Sharpe ratio.","steps_vi":["Excess return per total SD.","Thay số: (11-3)/16.","Kết quả: 0.500 ratio."],"answer":"0.500 ratio","check":"Original worked case; Decimal value compared with alternate Fraction expression (square root checked using float)."},{"question_en":"A diversified fund earns average return 12%, risk-free rate 4%, beta 1.25. Compute Treynor ratio expressed as percentage points per unit beta.","steps_vi":["Use beta in denominator, not total SD.","Thay số: (12-4)/1.25.","Kết quả: 6.40 pp/beta."],"answer":"6.40 pp/beta","check":"Original worked case; Decimal value compared with alternate Fraction expression (square root checked using float)."},{"question_en":"Portfolio return 13%, Rf=3%, σp=20%, σm=15%. Calculate M-squared risk-adjusted return (%), not M-squared alpha.","steps_vi":["Scale portfolio to 75% of its volatility with remaining 25% in bills.","Thay số: 3+(13-3)/20 × 15.","Kết quả: 10.50%."],"answer":"10.50%","check":"Original worked case; Decimal value compared with alternate Fraction expression (square root checked using float)."},{"question_en":"A portfolio has Sharpe 0.6, Rf=2%, market volatility 18% and market return 11%. What is M-squared alpha in percentage points?","steps_vi":["Compute M²=12.8%; subtract market return to find M² alpha.","Thay số: 2+.6 × 18-11.","Kết quả: 1.80 pp."],"answer":"1.80 pp","check":"Original worked case; Decimal value compared with alternate Fraction expression (square root checked using float)."},{"question_en":"A portfolio earns 13.2%, beta=1.3, market average return=10%, risk-free rate=2%. Find Jensen's alpha in percentage points.","steps_vi":["Subtract beta-adjusted benchmark, not market return alone.","Thay số: 13.2-(2+1.3 × (10-2)).","Kết quả: 0.80 pp."],"answer":"0.80 pp","check":"Original worked case; Decimal value compared with alternate Fraction expression (square root checked using float)."},{"question_en":"Manager A has average return 10%, volatility 14%, and Rf=3%. Manager B has average return 13%, volatility 25%, same Rf. By how much does A's Sharpe exceed B's?","steps_vi":["Compute both risk-adjusted ratios; A has lower nominal return but greater Sharpe.","Thay số: (10-3)/14-(13-3)/25.","Kết quả: 0.100 ratio."],"answer":"0.100 ratio","check":"Original worked case; Decimal value compared with alternate Fraction expression (square root checked using float)."}],"questions":[{"stem_en":"Which appraisal measure uses total portfolio standard deviation in its denominator?","options":["Treynor ratio.","Sharpe ratio.","Jensen's alpha."],"correct":1,"why_vi":"Sharpe=(Rp−Rf)/σp (ex post average period returns và SD, hoặc ex ante expectations). Measures excess return per total risk, phù hợp khi portfolio là toàn bộ risky wealth hoặc chưa diversified. Dùng same horizon và same Rf. Với negative premium, simple rankings can be misleading (more risk can make negative ratio less negative).","trap_vi":"Không dùng beta ở mẫu Sharpe."},{"stem_en":"The Treynor ratio is generally most appropriate for evaluating:","options":["an isolated portfolio whose total risk is the only relevant risk measure.","a well-diversified portfolio as part of an investor's overall diversified holdings.","the coupon payments of an individual bond without any risk estimate."],"correct":1,"why_vi":"Treynor=(Rp−Rf)/βp, measures excess return per unit systematic risk. Hữu ích khi portfolio là component trong well-diversified overall wealth. Beta phải nonzero; standard ranking meaningful nhất khi beta và premium dương. Treynor units are return per unit beta, khác Sharpe dimensionless.","trap_vi":"Không xếp hạng beta âm hoặc bằng 0 theo ratio đơn giản."},{"stem_en":"Under the CFAI convention where M-squared is the risk-adjusted return, M-squared alpha equals:","options":["M-squared minus portfolio volatility.","M-squared minus the market return.","the portfolio beta divided by market volatility."],"correct":1,"why_vi":"Theo CFAI Volume 9 PDF p107, M²=Rf+Sharpe_p×σm = risk-adjusted portfolio return at market volatility. M² alpha=M²−Rm là excess over benchmark market return. M² có return units; M² và Sharpe rank identically for same Rf,σm. Construction scales risky portfolio to σm via lending/borrowing assuming same Rf.","trap_vi":"Một số tài liệu gọi M² là chênh lệch; trong bộ này M² và M² alpha được tách rõ đúng CFAI."},{"stem_en":"A portfolio returns 10%, its CAPM benchmark return is 8%, and the market returns 12%. Jensen's alpha is:","options":["−2%.","+2%.","+10%."],"correct":1,"why_vi":"Jensen alpha = Rp−[Rf+βp(Rm−Rf)] cho ex post averages; ex ante alpha là expected return minus CAPM benchmark. Positive alpha means above required return given beta; negative below. Units return percentage points. Khi market model/benchmark sai, alpha có thể phản ánh omitted risk, không tự động skill.","trap_vi":"Không lấy actual return trừ market return nếu beta khác 1."},{"stem_en":"Two managers have identical beta and excess return but different residual risk. The manager with lower total volatility has:","options":["a higher Sharpe ratio, with the same Treynor ratio.","a higher Treynor ratio and the same Sharpe ratio.","a lower Sharpe ratio because residual risk is smaller."],"correct":0,"why_vi":"Sharpe/M² use total volatility; Treynor/Jensen use market beta. Concentrated manager có high residual risk có thể high Treynor nhưng low Sharpe. Với cùng market benchmark, positive premium/beta và equal risk assumptions, rankings tùy measure; Jensen alpha là absolute excess vs benchmark, Treynor ratio normalized by beta, nên không luôn đồng thứ hạng.","trap_vi":"Không khẳng định Sharpe, Treynor, Jensen luôn cùng rank."},{"stem_en":"For valid comparisons of risk-adjusted performance across funds, an analyst should use:","options":["annual returns divided by unadjusted daily risk regardless of measure.","consistent return frequency, risk-free rate, and benchmark definitions.","different risk-free rates solely to improve each fund's ranking."],"correct":1,"why_vi":"Performance estimates dùng period-matched average returns, volatility, beta and Rf. Risk-free lending assumption ảnh hưởng M² construction; fees/gross-net consistency và realistic benchmark important. Appraisal is retrospective; realized positive alpha có thể do chance, time-varying beta hoặc model error. So sánh risk-adjusted returns với phù hợp investment mandate.","trap_vi":"Không annualize numerator và giữ denominator monthly mà không chuyển đổi."},{"stem_en":"A fund earns average return 11%, risk-free rate 3%, portfolio SD 16%. Calculate Sharpe ratio.","options":["0.688 ratio","0.031 ratio","0.500 ratio"],"correct":2,"why_vi":"Excess return per total SD. Thay số: (11-3)/16 = 0.500 ratio.","trap_vi":"Bỏ Rf hoặc variance thay SD."},{"stem_en":"A diversified fund earns average return 12%, risk-free rate 4%, beta 1.25. Compute Treynor ratio expressed as percentage points per unit beta.","options":["9.60 pp/beta","10.00 pp/beta","6.40 pp/beta"],"correct":2,"why_vi":"Use beta in denominator, not total SD. Thay số: (12-4)/1.25 = 6.40 pp/beta.","trap_vi":"Bỏ Rf hoặc nhân beta."},{"stem_en":"Portfolio return 13%, Rf=3%, σp=20%, σm=15%. Calculate M-squared risk-adjusted return (%), not M-squared alpha.","options":["7.50%","10.50%","10.00%"],"correct":1,"why_vi":"Scale portfolio to 75% of its volatility with remaining 25% in bills. Thay số: 3+(13-3)/20 × 15 = 10.50%.","trap_vi":"Bỏ Rf trong M² hoặc trả lời excess return."},{"stem_en":"A portfolio has Sharpe 0.6, Rf=2%, market volatility 18% and market return 11%. What is M-squared alpha in percentage points?","options":["12.80 pp","-0.20 pp","1.80 pp"],"correct":2,"why_vi":"Compute M²=12.8%; subtract market return to find M² alpha. Thay số: 2+.6 × 18-11 = 1.80 pp.","trap_vi":"Trả lời M² thay alpha hoặc bỏ Rf khi tính adjusted return."},{"stem_en":"A portfolio earns 13.2%, beta=1.3, market average return=10%, risk-free rate=2%. Find Jensen's alpha in percentage points.","options":["3.20 pp","2.80 pp","0.80 pp"],"correct":2,"why_vi":"Subtract beta-adjusted benchmark, not market return alone. Thay số: 13.2-(2+1.3 × (10-2)) = 0.80 pp.","trap_vi":"Dùng market return hoặc bỏ Rf trong benchmark."},{"stem_en":"Manager A has average return 10%, volatility 14%, and Rf=3%. Manager B has average return 13%, volatility 25%, same Rf. By how much does A's Sharpe exceed B's?","options":["0.194 ratio","-0.100 ratio","0.100 ratio"],"correct":2,"why_vi":"Compute both risk-adjusted ratios; A has lower nominal return but greater Sharpe. Thay số: (10-3)/14-(13-3)/25 = 0.100 ratio.","trap_vi":"Dùng gross returns hoặc đảo comparison."}],"cards":[{"front_en":"Sharpe ratio","back_vi":"Sharpe=(Rp−Rf)/σp (ex post average period returns và SD, hoặc ex ante expectations). Measures excess return per total risk, phù hợp khi portfolio là toàn bộ risky wealth hoặc chưa diversified. Dùng same horizon và same Rf. Với negative premium, simple rankings can be misleading (more risk can make negative ratio less negative). | Exam trap: Không dùng beta ở mẫu Sharpe."},{"front_en":"Treynor ratio","back_vi":"Treynor=(Rp−Rf)/βp, measures excess return per unit systematic risk. Hữu ích khi portfolio là component trong well-diversified overall wealth. Beta phải nonzero; standard ranking meaningful nhất khi beta và premium dương. Treynor units are return per unit beta, khác Sharpe dimensionless. | Exam trap: Không xếp hạng beta âm hoặc bằng 0 theo ratio đơn giản."},{"front_en":"M-squared and M-squared alpha","back_vi":"Theo CFAI Volume 9 PDF p107, M²=Rf+Sharpe_p×σm = risk-adjusted portfolio return at market volatility. M² alpha=M²−Rm là excess over benchmark market return. M² có return units; M² và Sharpe rank identically for same Rf,σm. Construction scales risky portfolio to σm via lending/borrowing assuming same Rf. | Exam trap: Một số tài liệu gọi M² là chênh lệch; trong bộ này M² và M² alpha được tách rõ đúng CFAI."},{"front_en":"Jensen's alpha","back_vi":"Jensen alpha = Rp−[Rf+βp(Rm−Rf)] cho ex post averages; ex ante alpha là expected return minus CAPM benchmark. Positive alpha means above required return given beta; negative below. Units return percentage points. Khi market model/benchmark sai, alpha có thể phản ánh omitted risk, không tự động skill. | Exam trap: Không lấy actual return trừ market return nếu beta khác 1."},{"front_en":"Ranking divergence","back_vi":"Sharpe/M² use total volatility; Treynor/Jensen use market beta. Concentrated manager có high residual risk có thể high Treynor nhưng low Sharpe. Với cùng market benchmark, positive premium/beta và equal risk assumptions, rankings tùy measure; Jensen alpha là absolute excess vs benchmark, Treynor ratio normalized by beta, nên không luôn đồng thứ hạng. | Exam trap: Không khẳng định Sharpe, Treynor, Jensen luôn cùng rank."},{"front_en":"Benchmark consistency and interpretation","back_vi":"Performance estimates dùng period-matched average returns, volatility, beta and Rf. Risk-free lending assumption ảnh hưởng M² construction; fees/gross-net consistency và realistic benchmark important. Appraisal is retrospective; realized positive alpha có thể do chance, time-varying beta hoặc model error. So sánh risk-adjusted returns với phù hợp investment mandate. | Exam trap: Không annualize numerator và giữ denominator monthly mà không chuyển đổi."},{"front_en":"Sharpe ratio — formula and conditions?","back_vi":"(Rp−Rf)/σp · Excess return per total standard deviation. · Same period; σp>0; positive premium for straightforward rankings."},{"front_en":"Treynor ratio — formula and conditions?","back_vi":"(Rp−Rf)/βp · Excess return per beta unit. · βp>0 and positive premium for straightforward rankings."},{"front_en":"M² — formula and conditions?","back_vi":"Rf+Sharpe_p×σm · Market-volatility-adjusted return, per CFAI convention. · Scale fund using risk-free lending/borrowing assumption."},{"front_en":"M² alpha — formula and conditions?","back_vi":"M²−Rm · Risk-adjusted return difference against market. · Same market, same period."},{"front_en":"Jensen alpha — formula and conditions?","back_vi":"Rp−[Rf+βp(Rm−Rf)] · Actual return above CAPM expected benchmark. · Ex post period-consistent data, or ex ante expected inputs clearly stated."},{"front_en":"A fund earns average return 11%, risk-free rate 3%, portfolio SD 16%. Calculate Sharpe ratio.","back_vi":"Excess return per total SD. Thay số: (11-3)/16 = 0.500 ratio."},{"front_en":"A diversified fund earns average return 12%, risk-free rate 4%, beta 1.25. Compute Treynor ratio expressed as percentage points per unit beta.","back_vi":"Use beta in denominator, not total SD. Thay số: (12-4)/1.25 = 6.40 pp/beta."},{"front_en":"Portfolio return 13%, Rf=3%, σp=20%, σm=15%. Calculate M-squared risk-adjusted return (%), not M-squared alpha.","back_vi":"Scale portfolio to 75% of its volatility with remaining 25% in bills. Thay số: 3+(13-3)/20 × 15 = 10.50%."},{"front_en":"A portfolio has Sharpe 0.6, Rf=2%, market volatility 18% and market return 11%. What is M-squared alpha in percentage points?","back_vi":"Compute M²=12.8%; subtract market return to find M² alpha. Thay số: 2+.6 × 18-11 = 1.80 pp."},{"front_en":"A portfolio earns 13.2%, beta=1.3, market average return=10%, risk-free rate=2%. Find Jensen's alpha in percentage points.","back_vi":"Subtract beta-adjusted benchmark, not market return alone. Thay số: 13.2-(2+1.3 × (10-2)) = 0.80 pp."},{"front_en":"Manager A has average return 10%, volatility 14%, and Rf=3%. Manager B has average return 13%, volatility 25%, same Rf. By how much does A's Sharpe exceed B's?","back_vi":"Compute both risk-adjusted ratios; A has lower nominal return but greater Sharpe. Thay số: (10-3)/14-(13-3)/25 = 0.100 ratio."}]}]},{"module_id":"CFA26-09-03","subject":"Portfolio Management","module_title":"Portfolio Management: An Overview","level":"CFA Level I 2026","status":"Source-mapped detailed academic draft; not independently certified","language":"Vietnamese explanations, English financial terms and English exam questions","source_policy":"Original explanations and questions; source-mapped to CFAI 2026 Volume 9, Kaplan Book 4 and SAPP PM slides. Selected existing v57 legacy lesson concepts reviewed; QBank readings 85–86 sampled for question coverage; no publisher questions copied.","disclaimer_vi":"Bản học chi tiết dạng draft. Các bài số mở rộng để luyện tập là ví dụ tự biên soạn và có giả định riêng; không biến LOS describe/explain thành yêu cầu tính toán chính thức. Chưa thẩm định học thuật độc lập toàn bộ nội dung.","los":[{"id":"CFA26-09-03-LOS01","letter":"a","title_en":"Portfolio Approach to Investing","outcome_en":"describe the portfolio approach to investing","overview_vi":"Bài học 3.a: Portfolio Approach to Investing. Học bản chất khái niệm, điều kiện áp dụng, so sánh và giải quyết tình huống. Công thức ghi supplement là bài luyện thêm; câu hỏi tiếng Anh do dự án tự biên soạn.","source":[{"id":"CFA Institute Curriculum 2026 — Portfolio Management Volume 9","pages":"Physical PDF p. 131 (LOS), 132–141 (content)"},{"id":"Kaplan SchweserNotes 2026 — Book 4, Reading 85","pages":"Physical PDF pp. 107–108"},{"id":"SAPP CFA Level I 2026 — Portfolio Management slides","pages":"Physical PDF pp. 86–94"}],"sections":[{"heading":"Portfolio perspective","body":"Đánh giá một khoản đầu tư bằng đóng góp của nó vào expected return và rủi ro toàn danh mục, không chỉ bằng độ biến động riêng. Một tài sản có volatility lớn vẫn có thể hữu ích nếu covariance với tài sản hiện có đủ thấp. Điều này giải thích vì sao hai nhà đầu tư có thể đánh giá cùng một chứng khoán khác nhau.","trap":"Không xếp hạng chứng khoán chỉ theo stand-alone volatility."},{"heading":"Diversification mechanism","body":"Khi các nguồn lợi nhuận không cùng biến động hoàn toàn, tổn thất của một vị thế có thể được bù một phần bởi vị thế khác. Danh mục giảm rủi ro riêng lẻ mà không nhất thiết hy sinh expected return; covariance và weights quyết định mức giảm.","trap":"Nhiều cổ phiếu cùng ngành không bảo đảm đa dạng hóa hiệu quả."},{"heading":"Risk-return trade-off","body":"Đa dạng hóa mở rộng các lựa chọn risk–return: có thể đạt cùng expected return với rủi ro thấp hơn hoặc lợi nhuận kỳ vọng cao hơn với cùng rủi ro. Không phải mọi danh mục đều nằm trên efficient frontier.","trap":"Lợi nhuận kỳ vọng không phải lợi nhuận chắc chắn."},{"heading":"Downside protection","body":"Đa dạng hóa làm giảm phụ thuộc vào một nguồn lỗ nhưng không bảo đảm tránh drawdown. Trong khủng hoảng, correlations có thể tăng và nhiều nhóm tài sản đồng thời giảm giá. Phải xét thanh khoản và nguồn risk chung.","trap":"Correlation ước tính lịch sử không cố định trong stress."},{"heading":"Modern portfolio theory","body":"Markowitz sử dụng expected returns, variance và covariance để phân tích tập danh mục; CAPM phát triển tư duy rằng rủi ro được định giá của một chứng khoán trong danh mục đa dạng hóa là systematic risk. LM1–LM2 đã xây nền công thức, LM3 áp dụng tư duy quản lý.","trap":"Không nhầm variance riêng của chứng khoán với beta trong CAPM."},{"heading":"Concentration","body":"Một danh mục nắm nhiều mã nhưng cùng phụ thuộc lãi suất, hàng hóa hoặc một thị trường có thể vẫn tập trung rủi ro. Cần xem exposures và correlation, không chỉ đếm số lượng vị thế.","trap":"Thêm một quỹ có cùng holdings có thể không tạo nguồn đa dạng hóa mới."}],"formulas":[{"name":"Expected portfolio return","expr":"E(Rp) = Σ wi E(Ri)","meaning":"Lợi nhuận kỳ vọng là bình quân gia quyền theo tỷ trọng.","conditions":"Cùng currency, horizon; weights xác định, tổng bằng 1."},{"name":"Two-asset variance","expr":"σp² = wA²σA² + wB²σB² + 2wAwBρABσAσB","meaning":"Covariance quyết định phần rủi ro chung.","conditions":"Dùng decimal hoặc cùng đơn vị; long-only trong ví dụ."},{"name":"Diversification diagnostic (supplement)","expr":"DR = (Σ wi σi) / σp","meaning":"So sánh weighted stand-alone volatility với portfolio volatility.","conditions":"Bổ trợ LM1, long-only, σp > 0; không phải LOS formula bắt buộc."}],"examples":[{"question_en":"A concentrated bank-stock portfolio considers a volatile government bond fund whose returns have low correlation with bank shares. Should the bond fund be rejected solely on its volatility?","steps_vi":["Xem đóng góp của fund vào expected return và total portfolio variance, không chỉ volatility riêng.","Covariance thấp có thể giảm risk nhưng cần kiểm tra weights, rate risk, liquidity và objectives."],"answer":"Do not reject solely on stand-alone volatility; evaluate the combined portfolio.","check":"Original conceptual case; conclusions conditional on the stated facts."},{"question_en":"A portfolio invests 60% in assets expected to earn 9% and 40% in assets expected to earn 4%. Its expected return is closest to:","steps_vi":["Tính weighted expected return, dùng tỷ trọng đầu kỳ.","Thay số: 0.6 × 9+0.4 × 4.","Kết quả: 7.00%."],"answer":"7.00%","check":"Original supplemental practice; Decimal compared with an alternate expression using Fraction (square root uses float in the second method)."},{"question_en":"Two assets each have volatility of 12%, correlation zero and equal positive weights. Portfolio volatility is closest to:","steps_vi":["Variance gồm hai hạng weighted variance, covariance bằng 0, lấy căn.","Thay số: √(0.5^2 × 12^2+0.5^2 × 12^2).","Kết quả: 8.49%."],"answer":"8.49%","check":"Original supplemental practice; Decimal compared with an alternate expression using Fraction (square root uses float in the second method)."},{"question_en":"An equally weighted two-asset portfolio has volatilities of 18% and 10% and correlation −1. Portfolio volatility is closest to:","steps_vi":["Correlation −1 làm volatility bằng trị tuyệt đối chênh weighted exposures.","Thay số: √(0.25 × 18^2+0.25 × 10^2-2 × 0.5 × 0.5 × 18 × 10).","Kết quả: 4.00%."],"answer":"4.00%","check":"Original supplemental practice; Decimal compared with an alternate expression using Fraction (square root uses float in the second method)."}],"questions":[{"stem_en":"Which factor is most relevant when evaluating a new asset from the portfolio perspective?","options":["Its contribution to total portfolio risk and return","Its stand-alone volatility alone","Its historical return ranking alone"],"correct":0,"why_vi":"Đánh giá một khoản đầu tư bằng đóng góp của nó vào expected return và rủi ro toàn danh mục, không chỉ bằng độ biến động riêng. Một tài sản có volatility lớn vẫn có thể hữu ích nếu covariance với tài sản hiện có đủ thấp. Điều này giải thích vì sao hai nhà đầu tư có thể đánh giá cùng một chứng khoán khác nhau.","trap_vi":"Không xếp hạng chứng khoán chỉ theo stand-alone volatility."},{"stem_en":"Which combination is most likely to reduce portfolio risk, all else equal?","options":["Assets with identical return movements","Assets with lower pairwise return correlations","Assets with higher concentration in a single issuer"],"correct":1,"why_vi":"Khi các nguồn lợi nhuận không cùng biến động hoàn toàn, tổn thất của một vị thế có thể được bù một phần bởi vị thế khác. Danh mục giảm rủi ro riêng lẻ mà không nhất thiết hy sinh expected return; covariance và weights quyết định mức giảm.","trap_vi":"Nhiều cổ phiếu cùng ngành không bảo đảm đa dạng hóa hiệu quả."},{"stem_en":"A diversified portfolio can improve the risk-return trade-off primarily by:","options":["guaranteeing the highest realized return.","reducing risk for a given expected return.","eliminating every source of uncertainty."],"correct":1,"why_vi":"Đa dạng hóa mở rộng các lựa chọn risk–return: có thể đạt cùng expected return với rủi ro thấp hơn hoặc lợi nhuận kỳ vọng cao hơn với cùng rủi ro. Không phải mọi danh mục đều nằm trên efficient frontier.","trap_vi":"Lợi nhuận kỳ vọng không phải lợi nhuận chắc chắn."},{"stem_en":"Diversification is least reliable as protection against losses when:","options":["returns are weakly correlated in normal markets.","common risk factors dominate in severe market stress.","issuer-specific risks are independent."],"correct":1,"why_vi":"Đa dạng hóa làm giảm phụ thuộc vào một nguồn lỗ nhưng không bảo đảm tránh drawdown. Trong khủng hoảng, correlations có thể tăng và nhiều nhóm tài sản đồng thời giảm giá. Phải xét thanh khoản và nguồn risk chung.","trap_vi":"Correlation ước tính lịch sử không cố định trong stress."},{"stem_en":"In the CAPM, the risk rewarded with higher expected return is primarily:","options":["diversifiable issuer-specific risk.","the number of holdings.","systematic risk."],"correct":2,"why_vi":"Markowitz sử dụng expected returns, variance và covariance để phân tích tập danh mục; CAPM phát triển tư duy rằng rủi ro được định giá của một chứng khoán trong danh mục đa dạng hóa là systematic risk. LM1–LM2 đã xây nền công thức, LM3 áp dụng tư duy quản lý.","trap_vi":"Không nhầm variance riêng của chứng khoán với beta trong CAPM."},{"stem_en":"A portfolio holding 40 stocks from the same narrow industry most likely remains exposed to:","options":["zero systematic risk.","concentrated common industry risk.","a guaranteed lower loss than a broad-market fund."],"correct":1,"why_vi":"Một danh mục nắm nhiều mã nhưng cùng phụ thuộc lãi suất, hàng hóa hoặc một thị trường có thể vẫn tập trung rủi ro. Cần xem exposures và correlation, không chỉ đếm số lượng vị thế.","trap_vi":"Thêm một quỹ có cùng holdings có thể không tạo nguồn đa dạng hóa mới."},{"stem_en":"A portfolio invests 60% in assets expected to earn 9% and 40% in assets expected to earn 4%. Its expected return is closest to:","options":["7.00%","6.50%","6.00%"],"correct":0,"why_vi":"Tính weighted expected return, dùng tỷ trọng đầu kỳ. Thay số: 0.6 × 9+0.4 × 4 = 7.00%.","trap_vi":"Không lấy simple average hoặc đảo weights."},{"stem_en":"Two assets each have volatility of 12%, correlation zero and equal positive weights. Portfolio volatility is closest to:","options":["12.00%","8.49%","6.00%"],"correct":1,"why_vi":"Variance gồm hai hạng weighted variance, covariance bằng 0, lấy căn. Thay số: √(0.5^2 × 12^2+0.5^2 × 12^2) = 8.49%.","trap_vi":"Không lấy weighted volatility hoặc chỉ tính một tài sản."},{"stem_en":"An equally weighted two-asset portfolio has volatilities of 18% and 10% and correlation −1. Portfolio volatility is closest to:","options":["4.00%","14.00%","10.30%"],"correct":0,"why_vi":"Correlation −1 làm volatility bằng trị tuyệt đối chênh weighted exposures. Thay số: √(0.25 × 18^2+0.25 × 10^2-2 × 0.5 × 0.5 × 18 × 10) = 4.00%.","trap_vi":"Correlation −1 không luôn làm volatility bằng 0 nếu weighted exposures khác nhau."}],"cards":[{"front_en":"Portfolio perspective","back_vi":"Đánh giá một khoản đầu tư bằng đóng góp của nó vào expected return và rủi ro toàn danh mục, không chỉ bằng độ biến động riêng. Một tài sản có volatility lớn vẫn có thể hữu ích nếu covariance với tài sản hiện có đủ thấp. Điều này giải thích vì sao hai nhà đầu tư có thể đánh giá cùng một chứng khoán khác nhau. | Exam trap: Không xếp hạng chứng khoán chỉ theo stand-alone volatility."},{"front_en":"Diversification mechanism","back_vi":"Khi các nguồn lợi nhuận không cùng biến động hoàn toàn, tổn thất của một vị thế có thể được bù một phần bởi vị thế khác. Danh mục giảm rủi ro riêng lẻ mà không nhất thiết hy sinh expected return; covariance và weights quyết định mức giảm. | Exam trap: Nhiều cổ phiếu cùng ngành không bảo đảm đa dạng hóa hiệu quả."},{"front_en":"Risk-return trade-off","back_vi":"Đa dạng hóa mở rộng các lựa chọn risk–return: có thể đạt cùng expected return với rủi ro thấp hơn hoặc lợi nhuận kỳ vọng cao hơn với cùng rủi ro. Không phải mọi danh mục đều nằm trên efficient frontier. | Exam trap: Lợi nhuận kỳ vọng không phải lợi nhuận chắc chắn."},{"front_en":"Downside protection","back_vi":"Đa dạng hóa làm giảm phụ thuộc vào một nguồn lỗ nhưng không bảo đảm tránh drawdown. Trong khủng hoảng, correlations có thể tăng và nhiều nhóm tài sản đồng thời giảm giá. Phải xét thanh khoản và nguồn risk chung. | Exam trap: Correlation ước tính lịch sử không cố định trong stress."},{"front_en":"Modern portfolio theory","back_vi":"Markowitz sử dụng expected returns, variance và covariance để phân tích tập danh mục; CAPM phát triển tư duy rằng rủi ro được định giá của một chứng khoán trong danh mục đa dạng hóa là systematic risk. LM1–LM2 đã xây nền công thức, LM3 áp dụng tư duy quản lý. | Exam trap: Không nhầm variance riêng của chứng khoán với beta trong CAPM."},{"front_en":"Concentration","back_vi":"Một danh mục nắm nhiều mã nhưng cùng phụ thuộc lãi suất, hàng hóa hoặc một thị trường có thể vẫn tập trung rủi ro. Cần xem exposures và correlation, không chỉ đếm số lượng vị thế. | Exam trap: Thêm một quỹ có cùng holdings có thể không tạo nguồn đa dạng hóa mới."},{"front_en":"Expected portfolio return — formula or framework?","back_vi":"E(Rp) = Σ wi E(Ri) · Lợi nhuận kỳ vọng là bình quân gia quyền theo tỷ trọng. · Cùng currency, horizon; weights xác định, tổng bằng 1."},{"front_en":"Two-asset variance — formula or framework?","back_vi":"σp² = wA²σA² + wB²σB² + 2wAwBρABσAσB · Covariance quyết định phần rủi ro chung. · Dùng decimal hoặc cùng đơn vị; long-only trong ví dụ."},{"front_en":"Diversification diagnostic (supplement) — formula or framework?","back_vi":"DR = (Σ wi σi) / σp · So sánh weighted stand-alone volatility với portfolio volatility. · Bổ trợ LM1, long-only, σp > 0; không phải LOS formula bắt buộc."},{"front_en":"A portfolio invests 60% in assets expected to earn 9% and 40% in assets expected to earn 4%. Its expected return is closest to:","back_vi":"Tính weighted expected return, dùng tỷ trọng đầu kỳ. Thay số: 0.6 × 9+0.4 × 4 = 7.00%. | Không lấy simple average hoặc đảo weights."},{"front_en":"Two assets each have volatility of 12%, correlation zero and equal positive weights. Portfolio volatility is closest to:","back_vi":"Variance gồm hai hạng weighted variance, covariance bằng 0, lấy căn. Thay số: √(0.5^2 × 12^2+0.5^2 × 12^2) = 8.49%. | Không lấy weighted volatility hoặc chỉ tính một tài sản."},{"front_en":"An equally weighted two-asset portfolio has volatilities of 18% and 10% and correlation −1. Portfolio volatility is closest to:","back_vi":"Correlation −1 làm volatility bằng trị tuyệt đối chênh weighted exposures. Thay số: √(0.25 × 18^2+0.25 × 10^2-2 × 0.5 × 0.5 × 18 × 10) = 4.00%. | Correlation −1 không luôn làm volatility bằng 0 nếu weighted exposures khác nhau."}]},{"id":"CFA26-09-03-LOS02","letter":"b","title_en":"Steps in the Portfolio Management Process","outcome_en":"describe the steps in the portfolio management process","overview_vi":"Bài học 3.b: Steps in the Portfolio Management Process. Học bản chất khái niệm, điều kiện áp dụng, so sánh và giải quyết tình huống. Công thức ghi supplement là bài luyện thêm; câu hỏi tiếng Anh do dự án tự biên soạn.","source":[{"id":"CFA Institute Curriculum 2026 — Portfolio Management Volume 9","pages":"Physical PDF p. 131 (LOS), 141–145 (content)"},{"id":"Kaplan SchweserNotes 2026 — Book 4, Reading 85","pages":"Physical PDF pp. 108–109"},{"id":"SAPP CFA Level I 2026 — Portfolio Management slides","pages":"Physical PDF pp. 95–98"}],"sections":[{"heading":"Planning step","body":"Trước khi lựa chọn tài sản, người quản lý tìm hiểu client objectives và constraints rồi lập IPS. Benchmark phù hợp có thể được xác định từ bước này để đánh giá trong feedback. IPS được rà soát định kỳ và khi hoàn cảnh quan trọng thay đổi.","trap":"Không bắt đầu bằng việc tìm mã cổ phiếu hấp dẫn."},{"heading":"Execution step","body":"Execution gồm asset allocation, security analysis và portfolio construction. Dự báo kinh tế và thị trường vốn hỗ trợ quyết định tỷ trọng; đánh giá chứng khoán giúp lựa chọn vị thế trong từng lớp tài sản; toàn bộ phải phù hợp IPS.","trap":"Execution không phải chỉ là giao dịch khớp lệnh."},{"heading":"Top-down analysis","body":"Top-down bắt đầu từ điều kiện kinh tế vĩ mô, xu hướng thị trường, khu vực và ngành trước khi xét công ty. Ví dụ, nhận định lạm phát tăng có thể tác động đồng thời đến trái phiếu dài hạn và ngành nhạy lãi suất.","trap":"Không đồng nghĩa bắt buộc với passive investing."},{"heading":"Bottom-up analysis","body":"Bottom-up xuất phát từ chất lượng quản trị, lợi thế cạnh tranh, dòng tiền và định giá công ty; có thể phối hợp top-down. Security analysis chuyển dự báo dòng tiền và risk thành ước tính giá trị và quyết định đầu tư.","trap":"Bottom-up không loại bỏ hoàn toàn yếu tố kinh tế."},{"heading":"Feedback step","body":"Theo dõi thay đổi thị trường, portfolio exposures, nhu cầu khách hàng và hiệu quả. Rebalancing xử lý tỷ trọng trôi khỏi policy; performance measurement/reporting phản hồi kết quả. Nếu IPS không còn phản ánh hoàn cảnh thì quay lại planning.","trap":"Không điều chỉnh IPS chỉ vì kết quả ngắn hạn kém."},{"heading":"Performance evaluation","body":"Measurement xác định kết quả, so sánh benchmark và đánh giá mức đáp ứng mục tiêu. Phân tích nguồn return có thể hỗ trợ phân biệt allocation và selection; các quyết định cần được xét cùng risk, phí và horizon.","trap":"Một kỳ vượt benchmark không chứng minh kỹ năng bền vững."}],"formulas":[{"name":"Portfolio management process","expr":"Planning → Execution → Feedback → Planning","meaning":"Planning: needs + IPS; execution: allocation + analysis + construction; feedback: monitoring + rebalancing + measurement/reporting.","conditions":"Framework, không phải công thức tính."},{"name":"Benchmark-relative return (supplement)","expr":"Active return = Rp − Rb","meaning":"Chênh lệch kết quả portfolio và benchmark.","conditions":"Cùng kỳ, currency, treatment of fees; không phải attribution đầy đủ."}],"examples":[{"question_en":"A new client has not disclosed expected withdrawals. The manager has already identified an undervalued stock. What is the appropriate next step?","steps_vi":["Planning chưa hoàn tất vì liquidity needs chưa rõ; chưa thể xác định phù hợp.","Thu thập objectives/constraints, lập IPS rồi mới chuyển execution và security selection."],"answer":"Complete planning before executing the security selection.","check":"Original conceptual case; conclusions conditional on the stated facts."},{"question_en":"A portfolio returns 7.8% net of fees and its comparable benchmark returns 6.1%. Active return is closest to:","steps_vi":["Lấy portfolio return trừ benchmark, cùng kỳ và fee convention.","Thay số: 7.8-6.1.","Kết quả: 1.70 percentage points."],"answer":"1.70 percentage points","check":"Original supplemental practice; Decimal compared with an alternate expression using Fraction (square root uses float in the second method)."}],"questions":[{"stem_en":"The first step in managing a new client's portfolio is to:","options":["understand the client's needs and prepare an IPS.","select the best performing securities.","measure the manager's historical alpha."],"correct":0,"why_vi":"Trước khi lựa chọn tài sản, người quản lý tìm hiểu client objectives và constraints rồi lập IPS. Benchmark phù hợp có thể được xác định từ bước này để đánh giá trong feedback. IPS được rà soát định kỳ và khi hoàn cảnh quan trọng thay đổi.","trap_vi":"Không bắt đầu bằng việc tìm mã cổ phiếu hấp dẫn."},{"stem_en":"Which activity belongs to the execution stage?","options":["Obtaining the client's initial objectives","Determining asset-class weights and selecting securities","Reviewing realized performance against the benchmark"],"correct":1,"why_vi":"Execution gồm asset allocation, security analysis và portfolio construction. Dự báo kinh tế và thị trường vốn hỗ trợ quyết định tỷ trọng; đánh giá chứng khoán giúp lựa chọn vị thế trong từng lớp tài sản; toàn bộ phải phù hợp IPS.","trap_vi":"Execution không phải chỉ là giao dịch khớp lệnh."},{"stem_en":"A manager first forecasts economic growth, then selects industries and companies. This is primarily:","options":["bottom-up analysis.","top-down analysis.","performance measurement."],"correct":1,"why_vi":"Top-down bắt đầu từ điều kiện kinh tế vĩ mô, xu hướng thị trường, khu vực và ngành trước khi xét công ty. Ví dụ, nhận định lạm phát tăng có thể tác động đồng thời đến trái phiếu dài hạn và ngành nhạy lãi suất.","trap_vi":"Không đồng nghĩa bắt buộc với passive investing."},{"stem_en":"An analyst starts with a firm's management quality and expected cash flows. This is most consistent with:","options":["strategic asset allocation only.","portfolio rebalancing.","bottom-up analysis."],"correct":2,"why_vi":"Bottom-up xuất phát từ chất lượng quản trị, lợi thế cạnh tranh, dòng tiền và định giá công ty; có thể phối hợp top-down. Security analysis chuyển dự báo dòng tiền và risk thành ước tính giá trị và quyết định đầu tư.","trap_vi":"Bottom-up không loại bỏ hoàn toàn yếu tố kinh tế."},{"stem_en":"A portfolio manager compares actual weights with policy limits after market movements. This is part of:","options":["feedback.","initial planning only.","security valuation only."],"correct":0,"why_vi":"Theo dõi thay đổi thị trường, portfolio exposures, nhu cầu khách hàng và hiệu quả. Rebalancing xử lý tỷ trọng trôi khỏi policy; performance measurement/reporting phản hồi kết quả. Nếu IPS không còn phản ánh hoàn cảnh thì quay lại planning.","trap_vi":"Không điều chỉnh IPS chỉ vì kết quả ngắn hạn kém."},{"stem_en":"Which action best completes the feedback stage?","options":["Report performance relative to the agreed objectives and benchmark","Choose a benchmark retrospectively to maximize apparent skill","Ignore deviations if the portfolio made a profit"],"correct":0,"why_vi":"Measurement xác định kết quả, so sánh benchmark và đánh giá mức đáp ứng mục tiêu. Phân tích nguồn return có thể hỗ trợ phân biệt allocation và selection; các quyết định cần được xét cùng risk, phí và horizon.","trap_vi":"Một kỳ vượt benchmark không chứng minh kỹ năng bền vững."},{"stem_en":"A portfolio returns 7.8% net of fees and its comparable benchmark returns 6.1%. Active return is closest to:","options":["1.70 percentage points","7.80 percentage points","13.90 percentage points"],"correct":0,"why_vi":"Lấy portfolio return trừ benchmark, cùng kỳ và fee convention. Thay số: 7.8-6.1 = 1.70 percentage points.","trap_vi":"Không nhầm absolute return với active return."}],"cards":[{"front_en":"Planning step","back_vi":"Trước khi lựa chọn tài sản, người quản lý tìm hiểu client objectives và constraints rồi lập IPS. Benchmark phù hợp có thể được xác định từ bước này để đánh giá trong feedback. IPS được rà soát định kỳ và khi hoàn cảnh quan trọng thay đổi. | Exam trap: Không bắt đầu bằng việc tìm mã cổ phiếu hấp dẫn."},{"front_en":"Execution step","back_vi":"Execution gồm asset allocation, security analysis và portfolio construction. Dự báo kinh tế và thị trường vốn hỗ trợ quyết định tỷ trọng; đánh giá chứng khoán giúp lựa chọn vị thế trong từng lớp tài sản; toàn bộ phải phù hợp IPS. | Exam trap: Execution không phải chỉ là giao dịch khớp lệnh."},{"front_en":"Top-down analysis","back_vi":"Top-down bắt đầu từ điều kiện kinh tế vĩ mô, xu hướng thị trường, khu vực và ngành trước khi xét công ty. Ví dụ, nhận định lạm phát tăng có thể tác động đồng thời đến trái phiếu dài hạn và ngành nhạy lãi suất. | Exam trap: Không đồng nghĩa bắt buộc với passive investing."},{"front_en":"Bottom-up analysis","back_vi":"Bottom-up xuất phát từ chất lượng quản trị, lợi thế cạnh tranh, dòng tiền và định giá công ty; có thể phối hợp top-down. Security analysis chuyển dự báo dòng tiền và risk thành ước tính giá trị và quyết định đầu tư. | Exam trap: Bottom-up không loại bỏ hoàn toàn yếu tố kinh tế."},{"front_en":"Feedback step","back_vi":"Theo dõi thay đổi thị trường, portfolio exposures, nhu cầu khách hàng và hiệu quả. Rebalancing xử lý tỷ trọng trôi khỏi policy; performance measurement/reporting phản hồi kết quả. Nếu IPS không còn phản ánh hoàn cảnh thì quay lại planning. | Exam trap: Không điều chỉnh IPS chỉ vì kết quả ngắn hạn kém."},{"front_en":"Performance evaluation","back_vi":"Measurement xác định kết quả, so sánh benchmark và đánh giá mức đáp ứng mục tiêu. Phân tích nguồn return có thể hỗ trợ phân biệt allocation và selection; các quyết định cần được xét cùng risk, phí và horizon. | Exam trap: Một kỳ vượt benchmark không chứng minh kỹ năng bền vững."},{"front_en":"Portfolio management process — formula or framework?","back_vi":"Planning → Execution → Feedback → Planning · Planning: needs + IPS; execution: allocation + analysis + construction; feedback: monitoring + rebalancing + measurement/reporting. · Framework, không phải công thức tính."},{"front_en":"Benchmark-relative return (supplement) — formula or framework?","back_vi":"Active return = Rp − Rb · Chênh lệch kết quả portfolio và benchmark. · Cùng kỳ, currency, treatment of fees; không phải attribution đầy đủ."},{"front_en":"A portfolio returns 7.8% net of fees and its comparable benchmark returns 6.1%. Active return is closest to:","back_vi":"Lấy portfolio return trừ benchmark, cùng kỳ và fee convention. Thay số: 7.8-6.1 = 1.70 percentage points. | Không nhầm absolute return với active return."}]},{"id":"CFA26-09-03-LOS03","letter":"c","title_en":"Types of Investors and Their Needs","outcome_en":"describe types of investors and distinctive characteristics and needs of each","overview_vi":"Bài học 3.c: Types of Investors and Their Needs. Học bản chất khái niệm, điều kiện áp dụng, so sánh và giải quyết tình huống. Công thức ghi supplement là bài luyện thêm; câu hỏi tiếng Anh do dự án tự biên soạn.","source":[{"id":"CFA Institute Curriculum 2026 — Portfolio Management Volume 9","pages":"Physical PDF p. 131 (LOS), 145–151 (content)"},{"id":"Kaplan SchweserNotes 2026 — Book 4, Reading 85","pages":"Physical PDF pp. 109–110"},{"id":"SAPP CFA Level I 2026 — Portfolio Management slides","pages":"Physical PDF pp. 99–106"}],"sections":[{"heading":"Individual investors","body":"Cá nhân có horizon, mục tiêu, thuế, thu nhập và willingness khác nhau. Tài sản tài chính cần gắn với nghĩa vụ như học phí, nhà ở hoặc nghỉ hưu. Không suy mức chấp nhận risk chỉ từ tuổi hoặc tài sản ròng.","trap":"Không áp một asset mix cho mọi cá nhân."},{"heading":"Defined benefit pension funds","body":"DB pension plan có nghĩa vụ chi trả benefit đã xác định. Horizon thường dài và khả năng chịu risk có thể cao, nhưng kế hoạch trưởng thành với nhiều người nghỉ hưu cần dòng tiền và thanh khoản nhiều hơn kế hoạch trẻ. Funding status và sponsor strength rất quan trọng.","trap":"Không mặc định mọi DB fund đều có risk tolerance cao."},{"heading":"Endowments and foundations","body":"Endowments hỗ trợ trường học, bệnh viện hoặc tổ chức lâu dài; foundations tài trợ mục tiêu xã hội. Horizon thường rất dài, spending commitments định kỳ, nên có thể dùng một phần illiquid assets nếu duy trì đủ liquidity và sức mua.","trap":"Perpetual horizon không có nghĩa không phải chi tiền."},{"heading":"Banks","body":"Ngân hàng phải đáp ứng rút tiền gửi, nghĩa vụ và chi phí vận hành, tuân thủ quy định vốn/thanh khoản. Do đó thường ưu tiên liquidity và kiểm soát risk; asset–liability matching cần xem maturity và rate sensitivity.","trap":"Không lấy SAA của endowment áp thẳng cho bank."},{"heading":"Insurance companies","body":"Life insurer có nghĩa vụ dài hạn tương đối dự đoán được, còn property and casualty insurer có claim khó đoán về thời gian và quy mô. Cả hai cần tài sản đáp ứng claims, chất lượng tín dụng và yêu cầu vốn; P&C thường cần liquidity cao hơn.","trap":"Không đánh đồng mọi loại bảo hiểm."},{"heading":"Sovereign wealth funds","body":"SWF do nhà nước sở hữu, có nguồn tài sản như thu từ tài nguyên, ngoại hối hoặc thặng dư. Mục đích có thể ổn định ngân sách, tiết kiệm liên thế hệ, dự trữ hoặc phát triển. Horizon và risk tolerance phụ thuộc nhiệm vụ.","trap":"Không suy rằng mọi SWF đều đầu tư dài hạn với risk cao."},{"heading":"Investment needs comparison","body":"Bảng so sánh trong Curriculum sử dụng horizon, risk tolerance, income needs và liquidity needs. Đây là xu hướng điển hình, không phải điều kiện cứng. Khi phân tích một case phải ưu tiên liabilities, cash outflows và quy định đã nêu.","trap":"Không chọn theo tên định chế nếu case đưa dữ kiện khác."}],"formulas":[{"name":"Institutional needs matrix","expr":"Horizon × risk tolerance × income needs × liquidity needs","meaning":"So sánh từng client dựa nghĩa vụ và nhiệm vụ, không dựa tên tổ chức đơn thuần.","conditions":"Framework định tính; các đặc điểm điển hình không cứng nhắc."},{"name":"Spending amount (supplement)","expr":"Cash spending = specified base × spending rate","meaning":"Ước tính nhu cầu tiền để tài trợ chi tiêu.","conditions":"Dùng chính xác base trong policy; nhiều endowment dùng moving average."}],"examples":[{"question_en":"An endowment funds annual scholarships; a property insurer must pay unpredictable claims. Compare the investment implications.","steps_vi":["Endowment có spending thường kỳ và horizon dài, có thể dành phần phù hợp cho illiquid assets nếu cash reserve đủ.","Insurer cần liquidity để xử lý claims khó đoán và tuân thủ capital rules; không sao chép allocation endowment."],"answer":"Different liabilities and liquidity needs imply different portfolios.","check":"Original conceptual case; conclusions conditional on the stated facts."},{"question_en":"An endowment's spending policy specifies 4% of a USD 75 million valuation base. Its annual spending amount is closest to:","steps_vi":["Dùng base và spending rate đã nêu.","Thay số: 75 × 0.04.","Kết quả: 3.00 USD million."],"answer":"3.00 USD million","check":"Original supplemental practice; Decimal compared with an alternate expression using Fraction (square root uses float in the second method)."},{"question_en":"An insurer expects claims of USD 12 million next quarter and reliable matching inflows of USD 5 million. The remaining cash requirement is closest to:","steps_vi":["Net cash gap bằng claims trừ matching inflows, chưa gồm safety buffer.","Thay số: 12-5.","Kết quả: 7.00 USD million."],"answer":"7.00 USD million","check":"Original supplemental practice; Decimal compared with an alternate expression using Fraction (square root uses float in the second method)."}],"questions":[{"stem_en":"Which investor type has needs that generally vary most with personal circumstances?","options":["Defined benefit pension plans as a group","Bank treasury portfolios as a group","Individual investors"],"correct":2,"why_vi":"Cá nhân có horizon, mục tiêu, thuế, thu nhập và willingness khác nhau. Tài sản tài chính cần gắn với nghĩa vụ như học phí, nhà ở hoặc nghỉ hưu. Không suy mức chấp nhận risk chỉ từ tuổi hoặc tài sản ròng.","trap_vi":"Không áp một asset mix cho mọi cá nhân."},{"stem_en":"Compared with a growing DB plan, a mature DB plan with many retirees generally has:","options":["no future liabilities.","no need for liquid assets.","greater current benefit payment needs."],"correct":2,"why_vi":"DB pension plan có nghĩa vụ chi trả benefit đã xác định. Horizon thường dài và khả năng chịu risk có thể cao, nhưng kế hoạch trưởng thành với nhiều người nghỉ hưu cần dòng tiền và thanh khoản nhiều hơn kế hoạch trẻ. Funding status và sponsor strength rất quan trọng.","trap_vi":"Không mặc định mọi DB fund đều có risk tolerance cao."},{"stem_en":"A university endowment that funds annual operating expenses should most directly consider:","options":["its spending policy and long-term purchasing power.","only the next day's NAV.","eliminating all long-term assets."],"correct":0,"why_vi":"Endowments hỗ trợ trường học, bệnh viện hoặc tổ chức lâu dài; foundations tài trợ mục tiêu xã hội. Horizon thường rất dài, spending commitments định kỳ, nên có thể dùng một phần illiquid assets nếu duy trì đủ liquidity và sức mua.","trap_vi":"Perpetual horizon không có nghĩa không phải chi tiền."},{"stem_en":"A bank's investment portfolio generally places high emphasis on:","options":["liquidity to meet withdrawals and regulatory constraints.","perpetual illiquidity.","maximizing private equity exposure regardless of liabilities."],"correct":0,"why_vi":"Ngân hàng phải đáp ứng rút tiền gửi, nghĩa vụ và chi phí vận hành, tuân thủ quy định vốn/thanh khoản. Do đó thường ưu tiên liquidity và kiểm soát risk; asset–liability matching cần xem maturity và rate sensitivity.","trap_vi":"Không lấy SAA của endowment áp thẳng cho bank."},{"stem_en":"Relative to a life insurer with predictable long-term liabilities, a property and casualty insurer generally faces:","options":["greater uncertainty about the timing of claims.","no need to hold liquid assets.","a guaranteed perpetual investment horizon."],"correct":0,"why_vi":"Life insurer có nghĩa vụ dài hạn tương đối dự đoán được, còn property and casualty insurer có claim khó đoán về thời gian và quy mô. Cả hai cần tài sản đáp ứng claims, chất lượng tín dụng và yêu cầu vốn; P&C thường cần liquidity cao hơn.","trap_vi":"Không đánh đồng mọi loại bảo hiểm."},{"stem_en":"Which factor best determines a sovereign wealth fund's liquidity needs?","options":["Its specific mandate and expected withdrawals","Government ownership by itself","The fund's historical return alone"],"correct":0,"why_vi":"SWF do nhà nước sở hữu, có nguồn tài sản như thu từ tài nguyên, ngoại hối hoặc thặng dư. Mục đích có thể ổn định ngân sách, tiết kiệm liên thế hệ, dự trữ hoặc phát triển. Horizon và risk tolerance phụ thuộc nhiệm vụ.","trap_vi":"Không suy rằng mọi SWF đều đầu tư dài hạn với risk cao."},{"stem_en":"Which information is most useful for comparing two institutional investors' portfolio needs?","options":["Liability timing, spending requirements, risk tolerance and horizon","Their legal names alone","The number of investment managers alone"],"correct":0,"why_vi":"Bảng so sánh trong Curriculum sử dụng horizon, risk tolerance, income needs và liquidity needs. Đây là xu hướng điển hình, không phải điều kiện cứng. Khi phân tích một case phải ưu tiên liabilities, cash outflows và quy định đã nêu.","trap_vi":"Không chọn theo tên định chế nếu case đưa dữ kiện khác."},{"stem_en":"An endowment's spending policy specifies 4% of a USD 75 million valuation base. Its annual spending amount is closest to:","options":["4.50 USD million","3.00 USD million","30.00 USD million"],"correct":1,"why_vi":"Dùng base và spending rate đã nêu. Thay số: 75 × 0.04 = 3.00 USD million.","trap_vi":"Không tự đổi base hoặc sai đơn vị phần trăm."},{"stem_en":"An insurer expects claims of USD 12 million next quarter and reliable matching inflows of USD 5 million. The remaining cash requirement is closest to:","options":["17.00 USD million","5.00 USD million","7.00 USD million"],"correct":2,"why_vi":"Net cash gap bằng claims trừ matching inflows, chưa gồm safety buffer. Thay số: 12-5 = 7.00 USD million.","trap_vi":"Không cộng inflows vào cash gap."}],"cards":[{"front_en":"Individual investors","back_vi":"Cá nhân có horizon, mục tiêu, thuế, thu nhập và willingness khác nhau. Tài sản tài chính cần gắn với nghĩa vụ như học phí, nhà ở hoặc nghỉ hưu. Không suy mức chấp nhận risk chỉ từ tuổi hoặc tài sản ròng. | Exam trap: Không áp một asset mix cho mọi cá nhân."},{"front_en":"Defined benefit pension funds","back_vi":"DB pension plan có nghĩa vụ chi trả benefit đã xác định. Horizon thường dài và khả năng chịu risk có thể cao, nhưng kế hoạch trưởng thành với nhiều người nghỉ hưu cần dòng tiền và thanh khoản nhiều hơn kế hoạch trẻ. Funding status và sponsor strength rất quan trọng. | Exam trap: Không mặc định mọi DB fund đều có risk tolerance cao."},{"front_en":"Endowments and foundations","back_vi":"Endowments hỗ trợ trường học, bệnh viện hoặc tổ chức lâu dài; foundations tài trợ mục tiêu xã hội. Horizon thường rất dài, spending commitments định kỳ, nên có thể dùng một phần illiquid assets nếu duy trì đủ liquidity và sức mua. | Exam trap: Perpetual horizon không có nghĩa không phải chi tiền."},{"front_en":"Banks","back_vi":"Ngân hàng phải đáp ứng rút tiền gửi, nghĩa vụ và chi phí vận hành, tuân thủ quy định vốn/thanh khoản. Do đó thường ưu tiên liquidity và kiểm soát risk; asset–liability matching cần xem maturity và rate sensitivity. | Exam trap: Không lấy SAA của endowment áp thẳng cho bank."},{"front_en":"Insurance companies","back_vi":"Life insurer có nghĩa vụ dài hạn tương đối dự đoán được, còn property and casualty insurer có claim khó đoán về thời gian và quy mô. Cả hai cần tài sản đáp ứng claims, chất lượng tín dụng và yêu cầu vốn; P&C thường cần liquidity cao hơn. | Exam trap: Không đánh đồng mọi loại bảo hiểm."},{"front_en":"Sovereign wealth funds","back_vi":"SWF do nhà nước sở hữu, có nguồn tài sản như thu từ tài nguyên, ngoại hối hoặc thặng dư. Mục đích có thể ổn định ngân sách, tiết kiệm liên thế hệ, dự trữ hoặc phát triển. Horizon và risk tolerance phụ thuộc nhiệm vụ. | Exam trap: Không suy rằng mọi SWF đều đầu tư dài hạn với risk cao."},{"front_en":"Investment needs comparison","back_vi":"Bảng so sánh trong Curriculum sử dụng horizon, risk tolerance, income needs và liquidity needs. Đây là xu hướng điển hình, không phải điều kiện cứng. Khi phân tích một case phải ưu tiên liabilities, cash outflows và quy định đã nêu. | Exam trap: Không chọn theo tên định chế nếu case đưa dữ kiện khác."},{"front_en":"Institutional needs matrix — formula or framework?","back_vi":"Horizon × risk tolerance × income needs × liquidity needs · So sánh từng client dựa nghĩa vụ và nhiệm vụ, không dựa tên tổ chức đơn thuần. · Framework định tính; các đặc điểm điển hình không cứng nhắc."},{"front_en":"Spending amount (supplement) — formula or framework?","back_vi":"Cash spending = specified base × spending rate · Ước tính nhu cầu tiền để tài trợ chi tiêu. · Dùng chính xác base trong policy; nhiều endowment dùng moving average."},{"front_en":"An endowment's spending policy specifies 4% of a USD 75 million valuation base. Its annual spending amount is closest to:","back_vi":"Dùng base và spending rate đã nêu. Thay số: 75 × 0.04 = 3.00 USD million. | Không tự đổi base hoặc sai đơn vị phần trăm."},{"front_en":"An insurer expects claims of USD 12 million next quarter and reliable matching inflows of USD 5 million. The remaining cash requirement is closest to:","back_vi":"Net cash gap bằng claims trừ matching inflows, chưa gồm safety buffer. Thay số: 12-5 = 7.00 USD million. | Không cộng inflows vào cash gap."}]},{"id":"CFA26-09-03-LOS04","letter":"d","title_en":"Defined Contribution and Defined Benefit Plans","outcome_en":"describe defined contribution and defined benefit pension plans","overview_vi":"Bài học 3.d: Defined Contribution and Defined Benefit Plans. Học bản chất khái niệm, điều kiện áp dụng, so sánh và giải quyết tình huống. Công thức ghi supplement là bài luyện thêm; câu hỏi tiếng Anh do dự án tự biên soạn.","source":[{"id":"CFA Institute Curriculum 2026 — Portfolio Management Volume 9","pages":"Physical PDF p. 131 (LOS), 146–148,150–151 (content)"},{"id":"Kaplan SchweserNotes 2026 — Book 4, Reading 85","pages":"Physical PDF pp. 110–111"},{"id":"SAPP CFA Level I 2026 — Portfolio Management slides","pages":"Physical PDF pp. 99–106"}],"sections":[{"heading":"Defined contribution","body":"DC quy định mức đóng góp của employer/employee; số dư cuối kỳ phụ thuộc contributions, investment performance và fees. Người lao động thường chịu investment risk và phải quản lý tài sản để tài trợ retirement income.","trap":"Contribution xác định không đồng nghĩa retirement benefit xác định."},{"heading":"Defined benefit","body":"DB xác định benefit theo công thức, thường liên quan salary và years of service. Mức đóng góp phải đủ đáp ứng giá trị hiện tại nghĩa vụ; sponsor chịu investment/funding risk chủ yếu, có thể phát sinh nghĩa vụ tài trợ bổ sung.","trap":"DB không cố định contribution giống DC."},{"heading":"Funding status","body":"So sánh giá trị tài sản plan với present value của obligations; funded ratio thấp hơn 100% là thiếu tài trợ theo phép đo đang sử dụng. Discount rates, longevity, salary growth và market returns làm biến động funding. Đây là bài tập hỗ trợ, không đồng nhất mọi chuẩn kế toán.","trap":"Không so market assets với tổng benefit danh nghĩa chưa chiết khấu."},{"heading":"Benefit formula","body":"Một mô hình đơn giản DB tính pension hàng năm bằng accrual rate nhân years of service và pensionable salary. Thực tế phụ thuộc điều khoản plan, salary averaging, caps, vesting và inflation adjustments.","trap":"Không tự suy benefit bằng toàn bộ final salary."},{"heading":"Asset-liability matching","body":"DB có thể dùng bonds để giảm sensitivity mismatch giữa assets và liabilities, kết hợp growth assets để đáp ứng mục tiêu funding. DC thường có menu đầu tư hoặc lifecycle fund, nhưng target date không bảo đảm giá trị khi nghỉ hưu.","trap":"Không nhầm target-date fund với pension guarantee."},{"heading":"Pension maturity","body":"Kế hoạch DB non trẻ có nhiều người đang đóng góp và ít benefit payments; kế hoạch mature cần chi trả nhiều hơn. Độ trưởng thành ảnh hưởng liquidity và allocation, ngay cả khi cả hai đều có nghĩa vụ dài hạn.","trap":"Không đồng nhất pension horizon với liquidity need."}],"formulas":[{"name":"DC accumulation (supplement)","expr":"Ending balance = opening balance × (1+r) + end-period contribution","meaning":"Minh họa balance phụ thuộc return và contributions.","conditions":"Contribution cuối kỳ, return đã net fees nếu đề cho; không có withdrawals."},{"name":"DB funding ratio (supplement)","expr":"Funded ratio = assets / PV of benefit obligations","meaning":"Đánh giá mức tài trợ theo cùng measurement basis.","conditions":"Cùng thời điểm, PV dương, không tự suy chuẩn pháp lý/kế toán."},{"name":"DB annual pension (supplement)","expr":"Benefit = accrual rate × service years × pensionable salary","meaning":"Ví dụ benefit xác định theo salary/service.","conditions":"Chỉ khi plan quy định formula đơn giản này."}],"examples":[{"question_en":"A sponsor offers employees an account funded with 6% of salary; the employee selects investments. Another plan promises a pension based on years worked and salary. Identify the risk allocation.","steps_vi":["Plan 1 xác định contribution và outcome phụ thuộc performance, nên là DC; participant chịu investment risk chủ yếu.","Plan 2 định nghĩa benefit, là DB; sponsor chịu risk tài trợ và đầu tư chủ yếu."],"answer":"Plan 1: DC; plan 2: DB.","check":"Original conceptual case; conclusions conditional on the stated facts."},{"question_en":"A DC account begins the year at USD 80,000, earns 7% net of fees and receives a USD 4,000 contribution at year-end. The ending account value is closest to:","steps_vi":["Contribution cuối kỳ không hưởng full-year return.","Thay số: 80000 × 1.07+4000.","Kết quả: 89,600.00 USD."],"answer":"89,600.00 USD","check":"Original supplemental practice; Decimal compared with an alternate expression using Fraction (square root uses float in the second method)."},{"question_en":"A DB plan has assets of USD 126 million and benefit obligations with a present value of USD 140 million. Its funded ratio is closest to:","steps_vi":["Chia assets cho PV obligations tại cùng ngày.","Thay số: 126/140 × 100.","Kết quả: 90.00%."],"answer":"90.00%","check":"Original supplemental practice; Decimal compared with an alternate expression using Fraction (square root uses float in the second method)."},{"question_en":"A simplified DB plan provides an annual pension equal to 1.6% of pensionable salary per service year. Salary is USD 60,000 and service is 25 years. Annual benefit is closest to:","steps_vi":["Accrual rate nhân salary và service years, theo plan giả định.","Thay số: 0.016 × 60000 × 25.","Kết quả: 24,000.00 USD."],"answer":"24,000.00 USD","check":"Original supplemental practice; Decimal compared with an alternate expression using Fraction (square root uses float in the second method)."}],"questions":[{"stem_en":"In a typical defined contribution plan, investment risk is borne primarily by:","options":["the employer guaranteeing a fixed pension benefit.","the manager of the fund, regardless of the plan terms.","the plan participant."],"correct":2,"why_vi":"DC quy định mức đóng góp của employer/employee; số dư cuối kỳ phụ thuộc contributions, investment performance và fees. Người lao động thường chịu investment risk và phải quản lý tài sản để tài trợ retirement income.","trap_vi":"Contribution xác định không đồng nghĩa retirement benefit xác định."},{"stem_en":"In a traditional defined benefit plan, the sponsor generally bears:","options":["the risk that assets are insufficient to meet promised benefits.","no financial risk after initial contributions.","only the employee's personal asset allocation decision."],"correct":0,"why_vi":"DB xác định benefit theo công thức, thường liên quan salary và years of service. Mức đóng góp phải đủ đáp ứng giá trị hiện tại nghĩa vụ; sponsor chịu investment/funding risk chủ yếu, có thể phát sinh nghĩa vụ tài trợ bổ sung.","trap_vi":"DB không cố định contribution giống DC."},{"stem_en":"A DB plan has assets below the present value of its obligations. It is most accurately described as:","options":["overfunded.","underfunded on that measurement basis.","a defined contribution plan."],"correct":1,"why_vi":"So sánh giá trị tài sản plan với present value của obligations; funded ratio thấp hơn 100% là thiếu tài trợ theo phép đo đang sử dụng. Discount rates, longevity, salary growth và market returns làm biến động funding. Đây là bài tập hỗ trợ, không đồng nhất mọi chuẩn kế toán.","trap_vi":"Không so market assets với tổng benefit danh nghĩa chưa chiết khấu."},{"stem_en":"A pension that pays a specified percentage of pensionable salary per year of service is most consistent with:","options":["a pure defined contribution plan.","a defined benefit plan.","a closed-end equity fund."],"correct":1,"why_vi":"Một mô hình đơn giản DB tính pension hàng năm bằng accrual rate nhân years of service và pensionable salary. Thực tế phụ thuộc điều khoản plan, salary averaging, caps, vesting và inflation adjustments.","trap_vi":"Không tự suy benefit bằng toàn bộ final salary."},{"stem_en":"A DB plan matches bond duration to the duration of its obligations primarily to manage:","options":["asset-liability interest rate risk.","the employee's contribution rate only.","the number of outstanding ETF shares."],"correct":0,"why_vi":"DB có thể dùng bonds để giảm sensitivity mismatch giữa assets và liabilities, kết hợp growth assets để đáp ứng mục tiêu funding. DC thường có menu đầu tư hoặc lifecycle fund, nhưng target date không bảo đảm giá trị khi nghỉ hưu.","trap_vi":"Không nhầm target-date fund với pension guarantee."},{"stem_en":"A shift toward a larger retired membership is most likely to increase a pension plan's:","options":["ability to ignore liquidity.","guaranteed return on equities.","near-term cash payment requirements."],"correct":2,"why_vi":"Kế hoạch DB non trẻ có nhiều người đang đóng góp và ít benefit payments; kế hoạch mature cần chi trả nhiều hơn. Độ trưởng thành ảnh hưởng liquidity và allocation, ngay cả khi cả hai đều có nghĩa vụ dài hạn.","trap_vi":"Không đồng nhất pension horizon với liquidity need."},{"stem_en":"A DC account begins the year at USD 80,000, earns 7% net of fees and receives a USD 4,000 contribution at year-end. The ending account value is closest to:","options":["89,600.00 USD","89,880.00 USD","85,600.00 USD"],"correct":0,"why_vi":"Contribution cuối kỳ không hưởng full-year return. Thay số: 80000 × 1.07+4000 = 89,600.00 USD.","trap_vi":"Không tính lãi cho end-year contribution hoặc bỏ contribution."},{"stem_en":"A DB plan has assets of USD 126 million and benefit obligations with a present value of USD 140 million. Its funded ratio is closest to:","options":["111.11%","90.00%","10.00%"],"correct":1,"why_vi":"Chia assets cho PV obligations tại cùng ngày. Thay số: 126/140 × 100 = 90.00%.","trap_vi":"Không đảo tỷ số hoặc dùng shortfall rate."},{"stem_en":"A simplified DB plan provides an annual pension equal to 1.6% of pensionable salary per service year. Salary is USD 60,000 and service is 25 years. Annual benefit is closest to:","options":["960.00 USD","24,000.00 USD","15,000.00 USD"],"correct":1,"why_vi":"Accrual rate nhân salary và service years, theo plan giả định. Thay số: 0.016 × 60000 × 25 = 24,000.00 USD.","trap_vi":"Không bỏ years hoặc dùng số năm như percentage benefit."}],"cards":[{"front_en":"Defined contribution","back_vi":"DC quy định mức đóng góp của employer/employee; số dư cuối kỳ phụ thuộc contributions, investment performance và fees. Người lao động thường chịu investment risk và phải quản lý tài sản để tài trợ retirement income. | Exam trap: Contribution xác định không đồng nghĩa retirement benefit xác định."},{"front_en":"Defined benefit","back_vi":"DB xác định benefit theo công thức, thường liên quan salary và years of service. Mức đóng góp phải đủ đáp ứng giá trị hiện tại nghĩa vụ; sponsor chịu investment/funding risk chủ yếu, có thể phát sinh nghĩa vụ tài trợ bổ sung. | Exam trap: DB không cố định contribution giống DC."},{"front_en":"Funding status","back_vi":"So sánh giá trị tài sản plan với present value của obligations; funded ratio thấp hơn 100% là thiếu tài trợ theo phép đo đang sử dụng. Discount rates, longevity, salary growth và market returns làm biến động funding. Đây là bài tập hỗ trợ, không đồng nhất mọi chuẩn kế toán. | Exam trap: Không so market assets với tổng benefit danh nghĩa chưa chiết khấu."},{"front_en":"Benefit formula","back_vi":"Một mô hình đơn giản DB tính pension hàng năm bằng accrual rate nhân years of service và pensionable salary. Thực tế phụ thuộc điều khoản plan, salary averaging, caps, vesting và inflation adjustments. | Exam trap: Không tự suy benefit bằng toàn bộ final salary."},{"front_en":"Asset-liability matching","back_vi":"DB có thể dùng bonds để giảm sensitivity mismatch giữa assets và liabilities, kết hợp growth assets để đáp ứng mục tiêu funding. DC thường có menu đầu tư hoặc lifecycle fund, nhưng target date không bảo đảm giá trị khi nghỉ hưu. | Exam trap: Không nhầm target-date fund với pension guarantee."},{"front_en":"Pension maturity","back_vi":"Kế hoạch DB non trẻ có nhiều người đang đóng góp và ít benefit payments; kế hoạch mature cần chi trả nhiều hơn. Độ trưởng thành ảnh hưởng liquidity và allocation, ngay cả khi cả hai đều có nghĩa vụ dài hạn. | Exam trap: Không đồng nhất pension horizon với liquidity need."},{"front_en":"DC accumulation (supplement) — formula or framework?","back_vi":"Ending balance = opening balance × (1+r) + end-period contribution · Minh họa balance phụ thuộc return và contributions. · Contribution cuối kỳ, return đã net fees nếu đề cho; không có withdrawals."},{"front_en":"DB funding ratio (supplement) — formula or framework?","back_vi":"Funded ratio = assets / PV of benefit obligations · Đánh giá mức tài trợ theo cùng measurement basis. · Cùng thời điểm, PV dương, không tự suy chuẩn pháp lý/kế toán."},{"front_en":"DB annual pension (supplement) — formula or framework?","back_vi":"Benefit = accrual rate × service years × pensionable salary · Ví dụ benefit xác định theo salary/service. · Chỉ khi plan quy định formula đơn giản này."},{"front_en":"A DC account begins the year at USD 80,000, earns 7% net of fees and receives a USD 4,000 contribution at year-end. The ending account value is closest to:","back_vi":"Contribution cuối kỳ không hưởng full-year return. Thay số: 80000 × 1.07+4000 = 89,600.00 USD. | Không tính lãi cho end-year contribution hoặc bỏ contribution."},{"front_en":"A DB plan has assets of USD 126 million and benefit obligations with a present value of USD 140 million. Its funded ratio is closest to:","back_vi":"Chia assets cho PV obligations tại cùng ngày. Thay số: 126/140 × 100 = 90.00%. | Không đảo tỷ số hoặc dùng shortfall rate."},{"front_en":"A simplified DB plan provides an annual pension equal to 1.6% of pensionable salary per service year. Salary is USD 60,000 and service is 25 years. Annual benefit is closest to:","back_vi":"Accrual rate nhân salary và service years, theo plan giả định. Thay số: 0.016 × 60000 × 25 = 24,000.00 USD. | Không bỏ years hoặc dùng số năm như percentage benefit."}]},{"id":"CFA26-09-03-LOS05","letter":"e","title_en":"Asset Management Industry","outcome_en":"describe aspects of the asset management industry","overview_vi":"Bài học 3.e: Asset Management Industry. Học bản chất khái niệm, điều kiện áp dụng, so sánh và giải quyết tình huống. Công thức ghi supplement là bài luyện thêm; câu hỏi tiếng Anh do dự án tự biên soạn.","source":[{"id":"CFA Institute Curriculum 2026 — Portfolio Management Volume 9","pages":"Physical PDF p. 131 (LOS), 151–155 (content)"},{"id":"Kaplan SchweserNotes 2026 — Book 4, Reading 85","pages":"Physical PDF pp. 111–112"},{"id":"SAPP CFA Level I 2026 — Portfolio Management slides","pages":"Physical PDF pp. 117–122"}],"sections":[{"heading":"Buy-side versus sell-side","body":"Asset manager là buy-side, sử dụng vốn của khách hàng/quỹ để đầu tư. Sell-side gồm môi giới, dealer và investment bank cung cấp execution, research, liquidity và issuance services. Có thể có quan hệ mua dịch vụ và xung đột lợi ích.","trap":"Không nhầm research do broker cung cấp với quyền quản lý tiền khách hàng."},{"heading":"Active and passive","body":"Active management cố vượt benchmark bằng security selection, allocation hoặc timing; passive cố tái tạo exposure của index. Active thường có research và turnover costs cao hơn; passive vẫn chịu fees, tracking risk và market risk.","trap":"Passive không có nghĩa không có rủi ro."},{"heading":"Traditional versus alternative managers","body":"Traditional managers thường quản lý public stocks và bonds, trong khi alternative managers tập trung hedge funds, private equity, real assets hoặc chiến lược khác. Ranh giới có thể mờ; fee models và liquidity khác theo strategy/vehicle.","trap":"Không kết luận tất cả alternative funds có cùng phí hoặc leverage."},{"heading":"Fee revenue","body":"Asset-based management fee tính trên AUM theo hợp đồng, còn performance fee phụ thuộc kết quả theo điều khoản. AUM tăng do inflows hoặc investment gains có thể làm management revenue tăng; performance revenue biến động hơn.","trap":"Không nhầm doanh thu manager với return khách hàng."},{"heading":"Growth of passive investment","body":"Index funds và exchange-traded products giúp nhà đầu tư tiếp cận exposure đa dạng với chi phí thường thấp. Scale và competition gây áp lực phí; cần đánh giá tracking, trading costs và suitability, không chỉ headline fee.","trap":"Không coi ETF là đồng nghĩa với passive fund."},{"heading":"Big data","body":"Alternative data như social media, satellite imagery và sensor/geolocation có thể hỗ trợ ước tính hoạt động kinh doanh. Chất lượng, tính hợp pháp, bias và khả năng phân tích dữ liệu ảnh hưởng giá trị; dữ liệu nhiều không tự động sinh alpha.","trap":"Không đánh đồng tín hiệu dữ liệu với kết quả chắc chắn."},{"heading":"Robo-advisers","body":"Digital advice dùng questionnaires và algorithms để hỗ trợ allocation, rebalancing và có thể tax-loss harvesting. Dịch vụ thường có chi phí thấp và dễ tiếp cận, nhưng cần kiểm tra chất lượng assumptions và trường hợp nhu cầu phức tạp.","trap":"Không coi tự động hóa là thay thế toàn bộ suitability review."}],"formulas":[{"name":"Management fee (supplement)","expr":"Fee = annual fee rate × fee-bearing AUM","meaning":"Doanh thu fee của manager theo tài sản tính phí.","conditions":"Annual period; base và fee convention đã cho, không bao gồm performance fee."},{"name":"Manager comparison","expr":"Active: seek excess return; passive: track benchmark; traditional/alternative: strategy and investment universe","meaning":"Phân loại theo mục tiêu và assets; hai chiều phân loại không đồng nhất.","conditions":"Framework; so sánh net return, risk và implementation costs."}],"examples":[{"question_en":"An adviser compares an active fund with a low-cost index fund in the same market. What should the adviser evaluate?","steps_vi":["Xác định benchmark, exposures và objective active/passive trước; return gross không phải kết quả client.","So net fees, tracking risk, turnover, liquidity và evidence of skill trong cùng horizon, không kết luận active luôn kém hoặc luôn tốt."],"answer":"Compare suitability and risk-adjusted net performance on a consistent basis.","check":"Original conceptual case; conclusions conditional on the stated facts."},{"question_en":"A manager charges a 0.65% annual fee on a constant fee-bearing AUM of USD 240 million. Annual management fee is closest to:","steps_vi":["Fee rate 65 bps = 0.0065, nhân AUM.","Thay số: 240 × 0.0065.","Kết quả: 1.56 USD million."],"answer":"1.56 USD million","check":"Original supplemental practice; Decimal compared with an alternate expression using Fraction (square root uses float in the second method)."},{"question_en":"An active fund earns 8.2% before a 0.9 percentage point expense charge, and an index fund earns 7.8% before a 0.2 percentage point expense charge. Under this additive convention, the active fund's net excess return over the index fund is closest to:","steps_vi":["So net returns sau fee theo convention đề cho.","Thay số: (8.2-0.9)-(7.8-0.2).","Kết quả: -0.30 percentage points."],"answer":"-0.30 percentage points","check":"Original supplemental practice; Decimal compared with an alternate expression using Fraction (square root uses float in the second method)."}],"questions":[{"stem_en":"An asset manager purchasing securities for client portfolios is primarily part of the:","options":["buy side.","sell side.","securities issuer's treasury function."],"correct":0,"why_vi":"Asset manager là buy-side, sử dụng vốn của khách hàng/quỹ để đầu tư. Sell-side gồm môi giới, dealer và investment bank cung cấp execution, research, liquidity và issuance services. Có thể có quan hệ mua dịch vụ và xung đột lợi ích.","trap_vi":"Không nhầm research do broker cung cấp với quyền quản lý tiền khách hàng."},{"stem_en":"A passive equity manager is most likely to seek to:","options":["closely track a specified index, subject to fees and implementation frictions.","guarantee a positive absolute return.","maximize discretionary deviations from the benchmark."],"correct":0,"why_vi":"Active management cố vượt benchmark bằng security selection, allocation hoặc timing; passive cố tái tạo exposure của index. Active thường có research và turnover costs cao hơn; passive vẫn chịu fees, tracking risk và market risk.","trap_vi":"Passive không có nghĩa không có rủi ro."},{"stem_en":"Which distinction is most consistent with the asset management industry?","options":["Alternative managers often use less traditional asset classes or strategies","Every traditional fund is passive","Every alternative fund holds only cash"],"correct":0,"why_vi":"Traditional managers thường quản lý public stocks và bonds, trong khi alternative managers tập trung hedge funds, private equity, real assets hoặc chiến lược khác. Ranh giới có thể mờ; fee models và liquidity khác theo strategy/vehicle.","trap_vi":"Không kết luận tất cả alternative funds có cùng phí hoặc leverage."},{"stem_en":"A fee based on assets under management most directly changes with:","options":["only the number of securities.","the fee-bearing asset base.","only realized capital gains."],"correct":1,"why_vi":"Asset-based management fee tính trên AUM theo hợp đồng, còn performance fee phụ thuộc kết quả theo điều khoản. AUM tăng do inflows hoặc investment gains có thể làm management revenue tăng; performance revenue biến động hơn.","trap_vi":"Không nhầm doanh thu manager với return khách hàng."},{"stem_en":"Which development most directly contributes to pressure on active management fees?","options":["A requirement that all active managers earn positive alpha","Expansion of lower-cost index investment products","Elimination of index benchmarks"],"correct":1,"why_vi":"Index funds và exchange-traded products giúp nhà đầu tư tiếp cận exposure đa dạng với chi phí thường thấp. Scale và competition gây áp lực phí; cần đánh giá tracking, trading costs và suitability, không chỉ headline fee.","trap_vi":"Không coi ETF là đồng nghĩa với passive fund."},{"stem_en":"Which is an example of alternative data in an investment process?","options":["Satellite observations used to estimate retail activity","The face value printed on a bond certificate","A fixed contractual coupon alone"],"correct":0,"why_vi":"Alternative data như social media, satellite imagery và sensor/geolocation có thể hỗ trợ ước tính hoạt động kinh doanh. Chất lượng, tính hợp pháp, bias và khả năng phân tích dữ liệu ảnh hưởng giá trị; dữ liệu nhiều không tự động sinh alpha.","trap_vi":"Không đánh đồng tín hiệu dữ liệu với kết quả chắc chắn."},{"stem_en":"A robo-adviser most commonly provides:","options":["algorithm-based portfolio recommendations and implementation.","guaranteed avoidance of investment losses.","a defined benefit pension guarantee."],"correct":0,"why_vi":"Digital advice dùng questionnaires và algorithms để hỗ trợ allocation, rebalancing và có thể tax-loss harvesting. Dịch vụ thường có chi phí thấp và dễ tiếp cận, nhưng cần kiểm tra chất lượng assumptions và trường hợp nhu cầu phức tạp.","trap_vi":"Không coi tự động hóa là thay thế toàn bộ suitability review."},{"stem_en":"A manager charges a 0.65% annual fee on a constant fee-bearing AUM of USD 240 million. Annual management fee is closest to:","options":["15.60 USD million","0.16 USD million","1.56 USD million"],"correct":2,"why_vi":"Fee rate 65 bps = 0.0065, nhân AUM. Thay số: 240 × 0.0065 = 1.56 USD million.","trap_vi":"Phân biệt bps, percent và decimal."},{"stem_en":"An active fund earns 8.2% before a 0.9 percentage point expense charge, and an index fund earns 7.8% before a 0.2 percentage point expense charge. Under this additive convention, the active fund's net excess return over the index fund is closest to:","options":["0.40 percentage points","-0.50 percentage points","-0.30 percentage points"],"correct":2,"why_vi":"So net returns sau fee theo convention đề cho. Thay số: (8.2-0.9)-(7.8-0.2) = -0.30 percentage points.","trap_vi":"Không so gross active với net benchmark hoặc bỏ fee của index fund."}],"cards":[{"front_en":"Buy-side versus sell-side","back_vi":"Asset manager là buy-side, sử dụng vốn của khách hàng/quỹ để đầu tư. Sell-side gồm môi giới, dealer và investment bank cung cấp execution, research, liquidity và issuance services. Có thể có quan hệ mua dịch vụ và xung đột lợi ích. | Exam trap: Không nhầm research do broker cung cấp với quyền quản lý tiền khách hàng."},{"front_en":"Active and passive","back_vi":"Active management cố vượt benchmark bằng security selection, allocation hoặc timing; passive cố tái tạo exposure của index. Active thường có research và turnover costs cao hơn; passive vẫn chịu fees, tracking risk và market risk. | Exam trap: Passive không có nghĩa không có rủi ro."},{"front_en":"Traditional versus alternative managers","back_vi":"Traditional managers thường quản lý public stocks và bonds, trong khi alternative managers tập trung hedge funds, private equity, real assets hoặc chiến lược khác. Ranh giới có thể mờ; fee models và liquidity khác theo strategy/vehicle. | Exam trap: Không kết luận tất cả alternative funds có cùng phí hoặc leverage."},{"front_en":"Fee revenue","back_vi":"Asset-based management fee tính trên AUM theo hợp đồng, còn performance fee phụ thuộc kết quả theo điều khoản. AUM tăng do inflows hoặc investment gains có thể làm management revenue tăng; performance revenue biến động hơn. | Exam trap: Không nhầm doanh thu manager với return khách hàng."},{"front_en":"Growth of passive investment","back_vi":"Index funds và exchange-traded products giúp nhà đầu tư tiếp cận exposure đa dạng với chi phí thường thấp. Scale và competition gây áp lực phí; cần đánh giá tracking, trading costs và suitability, không chỉ headline fee. | Exam trap: Không coi ETF là đồng nghĩa với passive fund."},{"front_en":"Big data","back_vi":"Alternative data như social media, satellite imagery và sensor/geolocation có thể hỗ trợ ước tính hoạt động kinh doanh. Chất lượng, tính hợp pháp, bias và khả năng phân tích dữ liệu ảnh hưởng giá trị; dữ liệu nhiều không tự động sinh alpha. | Exam trap: Không đánh đồng tín hiệu dữ liệu với kết quả chắc chắn."},{"front_en":"Robo-advisers","back_vi":"Digital advice dùng questionnaires và algorithms để hỗ trợ allocation, rebalancing và có thể tax-loss harvesting. Dịch vụ thường có chi phí thấp và dễ tiếp cận, nhưng cần kiểm tra chất lượng assumptions và trường hợp nhu cầu phức tạp. | Exam trap: Không coi tự động hóa là thay thế toàn bộ suitability review."},{"front_en":"Management fee (supplement) — formula or framework?","back_vi":"Fee = annual fee rate × fee-bearing AUM · Doanh thu fee của manager theo tài sản tính phí. · Annual period; base và fee convention đã cho, không bao gồm performance fee."},{"front_en":"Manager comparison — formula or framework?","back_vi":"Active: seek excess return; passive: track benchmark; traditional/alternative: strategy and investment universe · Phân loại theo mục tiêu và assets; hai chiều phân loại không đồng nhất. · Framework; so sánh net return, risk và implementation costs."},{"front_en":"A manager charges a 0.65% annual fee on a constant fee-bearing AUM of USD 240 million. Annual management fee is closest to:","back_vi":"Fee rate 65 bps = 0.0065, nhân AUM. Thay số: 240 × 0.0065 = 1.56 USD million. | Phân biệt bps, percent và decimal."},{"front_en":"An active fund earns 8.2% before a 0.9 percentage point expense charge, and an index fund earns 7.8% before a 0.2 percentage point expense charge. Under this additive convention, the active fund's net excess return over the index fund is closest to:","back_vi":"So net returns sau fee theo convention đề cho. Thay số: (8.2-0.9)-(7.8-0.2) = -0.30 percentage points. | Không so gross active với net benchmark hoặc bỏ fee của index fund."}]},{"id":"CFA26-09-03-LOS06","letter":"f","title_en":"Mutual Funds and Other Investment Vehicles","outcome_en":"describe mutual funds and compare them with other pooled investment products","overview_vi":"Bài học 3.f: Mutual Funds and Other Investment Vehicles. Học bản chất khái niệm, điều kiện áp dụng, so sánh và giải quyết tình huống. Công thức ghi supplement là bài luyện thêm; câu hỏi tiếng Anh do dự án tự biên soạn.","source":[{"id":"CFA Institute Curriculum 2026 — Portfolio Management Volume 9","pages":"Physical PDF p. 131 (LOS), 155–162 (content)"},{"id":"Kaplan SchweserNotes 2026 — Book 4, Reading 85","pages":"Physical PDF pp. 112–114"},{"id":"SAPP CFA Level I 2026 — Portfolio Management slides","pages":"Physical PDF pp. 107–116"}],"sections":[{"heading":"Mutual fund structure","body":"Mutual fund gộp vốn nhiều người; mỗi unit có quyền hưởng theo tỷ lệ vào income và net assets. NAV mỗi unit bằng assets trừ liabilities chia units outstanding. Open-end fund thường định giá cuối ngày và phát hành/thu hồi units theo NAV tương ứng.","trap":"NAV tổng khác NAV mỗi share."},{"heading":"Open-end and closed-end","body":"Open-end fund tạo và redeem shares theo yêu cầu tại NAV áp dụng; closed-end fund thường phát hành số shares tương đối cố định và giao dịch trên thị trường thứ cấp, market price có thể lệch NAV.","trap":"Closed-end discount không phải tự động mất giá underlying portfolio."},{"heading":"Load and no-load funds","body":"Load là sales charge khi mua hoặc bán units theo điều khoản; no-load không có sales load nhưng vẫn có management fee và expenses. Phí ảnh hưởng số vốn đầu tư và net return.","trap":"No-load không có nghĩa zero expenses."},{"heading":"Money market funds","body":"Đầu tư short-term money market instruments như T-bills, CD và commercial paper; mục tiêu liquidity, preservation và return gần money market rates. Có CNAV hoặc VNAV theo cấu trúc, không phải bảo hiểm tiền gửi ngân hàng.","trap":"Không coi CNAV là bảo đảm chính phủ."},{"heading":"Bond and stock funds","body":"Bond funds phân theo government, corporate, high yield, global, inflation protected hoặc tax-free; equity funds active hoặc index. Bond fund chịu rate/credit risk; active equity thường có research costs và turnover cao hơn index fund, tax impact tùy luật.","trap":"Không nhầm tax-free bond fund với miễn thuế cho mọi investor."},{"heading":"Balanced and target date","body":"Balanced/hybrid fund kết hợp stocks và bonds; lifecycle/target-date fund thay đổi asset mix theo thời điểm mục tiêu, thường giảm equity exposure khi gần nghỉ hưu. Glide path và mức risk cuối kỳ phụ thuộc thiết kế.","trap":"Target date không bảo đảm số tiền đủ để nghỉ hưu."},{"heading":"Separately managed accounts","body":"SMA giữ portfolio riêng cho từng client và có thể tùy biến tax, restrictions và holdings. Khác pooled fund nơi investor có pro-rata units. Chi phí và minimum account có thể lớn hơn tùy manager.","trap":"Không coi SMA là pooled investment product."},{"heading":"Exchange-traded funds","body":"ETF units giao dịch intraday qua exchange, market price có thể lệch NAV. Creation/redemption của authorized participants hỗ trợ giảm chênh lệch. Investor chịu bid–ask spread, brokerage nếu có, expense và tracking risk; có cả active ETFs.","trap":"ETF giao dịch trong ngày không đồng nghĩa có NAV cố định."},{"heading":"Hedge and private equity funds","body":"Hedge funds thường private, có thể short/leverage và charge performance fee; withdrawal restrictions khác nhau. PE/VC thường limited partnership, đầu tư dài hạn, tham gia cải thiện doanh nghiệp và exit qua sale/IPO; management fees và carried interest là cấu trúc phổ biến.","trap":"Không mặc định hedge fund luôn ít risk hoặc PE luôn thanh khoản."}],"formulas":[{"name":"NAV per share","expr":"NAV = (market value of assets − liabilities) / shares outstanding","meaning":"Net assets phân bổ cho từng share.","conditions":"Cùng valuation date, liabilities chưa trừ, shares > 0."},{"name":"Closed-end premium/discount (supplement)","expr":"Premium (signed) = market price / NAV − 1","meaning":"Dương là premium; âm là discount.","conditions":"NAV > 0; cùng thời điểm; discount dương về độ lớn nếu đề hỏi magnitude."},{"name":"Front-end load (supplement)","expr":"Net invested = initial cash × (1 − load rate)","meaning":"Khoản vốn còn lại sau phí mua.","conditions":"Chỉ khi load tính theo cash offering amount; không tự suy convention khác."},{"name":"Fund vehicle comparison","expr":"Open-end: NAV subscriptions/redemptions; closed-end/ETF: secondary market; SMA: individually managed","meaning":"Phân biệt quyền sở hữu, cơ chế định giá, liquidity và fees.","conditions":"Framework; ETF primary market có creation/redemption đặc thù; active ETF tồn tại."}],"examples":[{"question_en":"A client wants to trade an equity fund during the trading day and another client wants direct redemption at end-of-day NAV. Which structures are appropriate?","steps_vi":["ETF phù hợp nhu cầu intraday secondary-market execution, nhưng có spread và premium/discount.","Conventional open-end mutual fund thường được mua/redeem theo applicable end-of-day NAV."],"answer":"ETF for intraday trading; open-end mutual fund for NAV-based dealing.","check":"Original conceptual case; conclusions conditional on the stated facts."},{"question_en":"A fund holds USD 98 million of assets and USD 3 million of liabilities. There are 5 million shares outstanding. NAV per share is closest to:","steps_vi":["Net assets chia shares outstanding.","Thay số: (98-3)/5.","Kết quả: 19.00 USD."],"answer":"19.00 USD","check":"Original supplemental practice; Decimal compared with an alternate expression using Fraction (square root uses float in the second method)."},{"question_en":"A closed-end fund has NAV of USD 25 per share and trades at USD 23. Its discount to NAV, stated as a positive magnitude, is closest to:","steps_vi":["Discount magnitude = (NAV − market price)/NAV.","Thay số: (25-23)/25 × 100.","Kết quả: 8.00%."],"answer":"8.00%","check":"Original supplemental practice; Decimal compared with an alternate expression using Fraction (square root uses float in the second method)."},{"question_en":"An investor contributes USD 20,000 to a fund charging a front-end load of 2.5% of the offering amount. The amount initially invested is closest to:","steps_vi":["Trừ sales load tính trên initial offering amount.","Thay số: 20000 × (1-0.025).","Kết quả: 19,500.00 USD."],"answer":"19,500.00 USD","check":"Original supplemental practice; Decimal compared with an alternate expression using Fraction (square root uses float in the second method)."},{"question_en":"An ETF has NAV of USD 40 and a market price of USD 40.60. The premium to NAV is closest to:","steps_vi":["Chênh lệch market price chia NAV.","Thay số: (40.6/40-1) × 100.","Kết quả: 1.50%."],"answer":"1.50%","check":"Original supplemental practice; Decimal compared with an alternate expression using Fraction (square root uses float in the second method)."}],"questions":[{"stem_en":"A mutual fund investor generally owns:","options":["a direct individual title to every underlying security.","a fixed guaranteed coupon from the fund manager.","a proportionate interest in a pooled portfolio."],"correct":2,"why_vi":"Mutual fund gộp vốn nhiều người; mỗi unit có quyền hưởng theo tỷ lệ vào income và net assets. NAV mỗi unit bằng assets trừ liabilities chia units outstanding. Open-end fund thường định giá cuối ngày và phát hành/thu hồi units theo NAV tương ứng.","trap_vi":"NAV tổng khác NAV mỗi share."},{"stem_en":"Which vehicle is most likely to trade persistently at a discount to NAV in the secondary market?","options":["An open-end fund redeemed at NAV","A conventional closed-end fund","A bank deposit held at par"],"correct":1,"why_vi":"Open-end fund tạo và redeem shares theo yêu cầu tại NAV áp dụng; closed-end fund thường phát hành số shares tương đối cố định và giao dịch trên thị trường thứ cấp, market price có thể lệch NAV.","trap_vi":"Closed-end discount không phải tự động mất giá underlying portfolio."},{"stem_en":"A no-load mutual fund most likely:","options":["has no operating expenses of any kind.","guarantees redemption above NAV.","has no sales load but may charge ongoing expenses."],"correct":2,"why_vi":"Load là sales charge khi mua hoặc bán units theo điều khoản; no-load không có sales load nhưng vẫn có management fee và expenses. Phí ảnh hưởng số vốn đầu tư và net return.","trap_vi":"No-load không có nghĩa zero expenses."},{"stem_en":"Compared with a typical long-term bond fund, a money market fund generally holds:","options":["longer-duration bonds.","primarily private equity stakes.","shorter-maturity instruments."],"correct":2,"why_vi":"Đầu tư short-term money market instruments như T-bills, CD và commercial paper; mục tiêu liquidity, preservation và return gần money market rates. Có CNAV hoặc VNAV theo cấu trúc, không phải bảo hiểm tiền gửi ngân hàng.","trap_vi":"Không coi CNAV là bảo đảm chính phủ."},{"stem_en":"A fund investing principally in below-investment-grade corporate bonds is a:","options":["money market fund.","broad equity index fund.","high-yield bond fund."],"correct":2,"why_vi":"Bond funds phân theo government, corporate, high yield, global, inflation protected hoặc tax-free; equity funds active hoặc index. Bond fund chịu rate/credit risk; active equity thường có research costs và turnover cao hơn index fund, tax impact tùy luật.","trap_vi":"Không nhầm tax-free bond fund với miễn thuế cho mọi investor."},{"stem_en":"Which fund is specifically designed to change asset allocation as a retirement date approaches?","options":["Constant-maturity bond fund","Target-date fund","Single-industry equity fund"],"correct":1,"why_vi":"Balanced/hybrid fund kết hợp stocks và bonds; lifecycle/target-date fund thay đổi asset mix theo thời điểm mục tiêu, thường giảm equity exposure khi gần nghỉ hưu. Glide path và mức risk cuối kỳ phụ thuộc thiết kế.","trap_vi":"Target date không bảo đảm số tiền đủ để nghỉ hưu."},{"stem_en":"Which investment arrangement most directly allows a client to own an individually tailored securities portfolio?","options":["Open-end mutual fund","Separately managed account","Closed-end pooled fund"],"correct":1,"why_vi":"SMA giữ portfolio riêng cho từng client và có thể tùy biến tax, restrictions và holdings. Khác pooled fund nơi investor có pro-rata units. Chi phí và minimum account có thể lớn hơn tùy manager.","trap_vi":"Không coi SMA là pooled investment product."},{"stem_en":"Compared with a conventional open-end mutual fund, an ETF generally offers:","options":["redemption by every retail investor directly at end-of-day NAV only.","intraday secondary-market trading.","guaranteed zero trading costs."],"correct":1,"why_vi":"ETF units giao dịch intraday qua exchange, market price có thể lệch NAV. Creation/redemption của authorized participants hỗ trợ giảm chênh lệch. Investor chịu bid–ask spread, brokerage nếu có, expense và tracking risk; có cả active ETFs.","trap_vi":"ETF giao dịch trong ngày không đồng nghĩa có NAV cố định."},{"stem_en":"Which vehicle most commonly has a multi-year commitment and exits portfolio companies through sales or IPOs?","options":["Money market mutual fund","Broad-market ETF","Private equity fund"],"correct":2,"why_vi":"Hedge funds thường private, có thể short/leverage và charge performance fee; withdrawal restrictions khác nhau. PE/VC thường limited partnership, đầu tư dài hạn, tham gia cải thiện doanh nghiệp và exit qua sale/IPO; management fees và carried interest là cấu trúc phổ biến.","trap_vi":"Không mặc định hedge fund luôn ít risk hoặc PE luôn thanh khoản."},{"stem_en":"A fund holds USD 98 million of assets and USD 3 million of liabilities. There are 5 million shares outstanding. NAV per share is closest to:","options":["19.60 USD","20.20 USD","19.00 USD"],"correct":2,"why_vi":"Net assets chia shares outstanding. Thay số: (98-3)/5 = 19.00 USD.","trap_vi":"Trừ liabilities trước khi chia."},{"stem_en":"A closed-end fund has NAV of USD 25 per share and trades at USD 23. Its discount to NAV, stated as a positive magnitude, is closest to:","options":["8.70%","8.00%","-8.00%"],"correct":1,"why_vi":"Discount magnitude = (NAV − market price)/NAV. Thay số: (25-23)/25 × 100 = 8.00%.","trap_vi":"Mẫu số NAV và đề hỏi độ lớn dương."},{"stem_en":"An investor contributes USD 20,000 to a fund charging a front-end load of 2.5% of the offering amount. The amount initially invested is closest to:","options":["19,500.00 USD","20,512.82 USD","500.00 USD"],"correct":0,"why_vi":"Trừ sales load tính trên initial offering amount. Thay số: 20000 × (1-0.025) = 19,500.00 USD.","trap_vi":"Phân biệt net invested và load amount."},{"stem_en":"An ETF has NAV of USD 40 and a market price of USD 40.60. The premium to NAV is closest to:","options":["1.50%","1.48%","-1.50%"],"correct":0,"why_vi":"Chênh lệch market price chia NAV. Thay số: (40.6/40-1) × 100 = 1.50%.","trap_vi":"Không chia market price hoặc đảo dấu."}],"cards":[{"front_en":"Mutual fund structure","back_vi":"Mutual fund gộp vốn nhiều người; mỗi unit có quyền hưởng theo tỷ lệ vào income và net assets. NAV mỗi unit bằng assets trừ liabilities chia units outstanding. Open-end fund thường định giá cuối ngày và phát hành/thu hồi units theo NAV tương ứng. | Exam trap: NAV tổng khác NAV mỗi share."},{"front_en":"Open-end and closed-end","back_vi":"Open-end fund tạo và redeem shares theo yêu cầu tại NAV áp dụng; closed-end fund thường phát hành số shares tương đối cố định và giao dịch trên thị trường thứ cấp, market price có thể lệch NAV. | Exam trap: Closed-end discount không phải tự động mất giá underlying portfolio."},{"front_en":"Load and no-load funds","back_vi":"Load là sales charge khi mua hoặc bán units theo điều khoản; no-load không có sales load nhưng vẫn có management fee và expenses. Phí ảnh hưởng số vốn đầu tư và net return. | Exam trap: No-load không có nghĩa zero expenses."},{"front_en":"Money market funds","back_vi":"Đầu tư short-term money market instruments như T-bills, CD và commercial paper; mục tiêu liquidity, preservation và return gần money market rates. Có CNAV hoặc VNAV theo cấu trúc, không phải bảo hiểm tiền gửi ngân hàng. | Exam trap: Không coi CNAV là bảo đảm chính phủ."},{"front_en":"Bond and stock funds","back_vi":"Bond funds phân theo government, corporate, high yield, global, inflation protected hoặc tax-free; equity funds active hoặc index. Bond fund chịu rate/credit risk; active equity thường có research costs và turnover cao hơn index fund, tax impact tùy luật. | Exam trap: Không nhầm tax-free bond fund với miễn thuế cho mọi investor."},{"front_en":"Balanced and target date","back_vi":"Balanced/hybrid fund kết hợp stocks và bonds; lifecycle/target-date fund thay đổi asset mix theo thời điểm mục tiêu, thường giảm equity exposure khi gần nghỉ hưu. Glide path và mức risk cuối kỳ phụ thuộc thiết kế. | Exam trap: Target date không bảo đảm số tiền đủ để nghỉ hưu."},{"front_en":"Separately managed accounts","back_vi":"SMA giữ portfolio riêng cho từng client và có thể tùy biến tax, restrictions và holdings. Khác pooled fund nơi investor có pro-rata units. Chi phí và minimum account có thể lớn hơn tùy manager. | Exam trap: Không coi SMA là pooled investment product."},{"front_en":"Exchange-traded funds","back_vi":"ETF units giao dịch intraday qua exchange, market price có thể lệch NAV. Creation/redemption của authorized participants hỗ trợ giảm chênh lệch. Investor chịu bid–ask spread, brokerage nếu có, expense và tracking risk; có cả active ETFs. | Exam trap: ETF giao dịch trong ngày không đồng nghĩa có NAV cố định."},{"front_en":"Hedge and private equity funds","back_vi":"Hedge funds thường private, có thể short/leverage và charge performance fee; withdrawal restrictions khác nhau. PE/VC thường limited partnership, đầu tư dài hạn, tham gia cải thiện doanh nghiệp và exit qua sale/IPO; management fees và carried interest là cấu trúc phổ biến. | Exam trap: Không mặc định hedge fund luôn ít risk hoặc PE luôn thanh khoản."},{"front_en":"NAV per share — formula or framework?","back_vi":"NAV = (market value of assets − liabilities) / shares outstanding · Net assets phân bổ cho từng share. · Cùng valuation date, liabilities chưa trừ, shares > 0."},{"front_en":"Closed-end premium/discount (supplement) — formula or framework?","back_vi":"Premium (signed) = market price / NAV − 1 · Dương là premium; âm là discount. · NAV > 0; cùng thời điểm; discount dương về độ lớn nếu đề hỏi magnitude."},{"front_en":"Front-end load (supplement) — formula or framework?","back_vi":"Net invested = initial cash × (1 − load rate) · Khoản vốn còn lại sau phí mua. · Chỉ khi load tính theo cash offering amount; không tự suy convention khác."},{"front_en":"Fund vehicle comparison — formula or framework?","back_vi":"Open-end: NAV subscriptions/redemptions; closed-end/ETF: secondary market; SMA: individually managed · Phân biệt quyền sở hữu, cơ chế định giá, liquidity và fees. · Framework; ETF primary market có creation/redemption đặc thù; active ETF tồn tại."},{"front_en":"A fund holds USD 98 million of assets and USD 3 million of liabilities. There are 5 million shares outstanding. NAV per share is closest to:","back_vi":"Net assets chia shares outstanding. Thay số: (98-3)/5 = 19.00 USD. | Trừ liabilities trước khi chia."},{"front_en":"A closed-end fund has NAV of USD 25 per share and trades at USD 23. Its discount to NAV, stated as a positive magnitude, is closest to:","back_vi":"Discount magnitude = (NAV − market price)/NAV. Thay số: (25-23)/25 × 100 = 8.00%. | Mẫu số NAV và đề hỏi độ lớn dương."},{"front_en":"An investor contributes USD 20,000 to a fund charging a front-end load of 2.5% of the offering amount. The amount initially invested is closest to:","back_vi":"Trừ sales load tính trên initial offering amount. Thay số: 20000 × (1-0.025) = 19,500.00 USD. | Phân biệt net invested và load amount."},{"front_en":"An ETF has NAV of USD 40 and a market price of USD 40.60. The premium to NAV is closest to:","back_vi":"Chênh lệch market price chia NAV. Thay số: (40.6/40-1) × 100 = 1.50%. | Không chia market price hoặc đảo dấu."}]}]},{"module_id":"CFA26-09-04","subject":"Portfolio Management","module_title":"Basics of Portfolio Planning and Construction","level":"CFA Level I 2026","status":"Source-mapped detailed academic draft; not independently certified","language":"Vietnamese explanations, English financial terms and English exam questions","source_policy":"Original explanations and questions; source-mapped to CFAI 2026 Volume 9, Kaplan Book 4 and SAPP PM slides. Selected existing v57 legacy lesson concepts reviewed; QBank readings 85–86 sampled for question coverage; no publisher questions copied.","disclaimer_vi":"Bản học chi tiết dạng draft. Các bài số mở rộng để luyện tập là ví dụ tự biên soạn và có giả định riêng; không biến LOS describe/explain thành yêu cầu tính toán chính thức. Chưa thẩm định học thuật độc lập toàn bộ nội dung.","los":[{"id":"CFA26-09-04-LOS01","letter":"a","title_en":"Reasons for a Written IPS","outcome_en":"describe the reasons for a written investment policy statement (IPS)","overview_vi":"Bài học 4.a: Reasons for a Written IPS. Học bản chất khái niệm, điều kiện áp dụng, so sánh và giải quyết tình huống. Công thức ghi supplement là bài luyện thêm; câu hỏi tiếng Anh do dự án tự biên soạn.","source":[{"id":"CFA Institute Curriculum 2026 — Portfolio Management Volume 9","pages":"Physical PDF p. 169 (LOS), 170–172 (content)"},{"id":"Kaplan SchweserNotes 2026 — Book 4, Reading 86","pages":"Physical PDF pp. 118"},{"id":"SAPP CFA Level I 2026 — Portfolio Management slides","pages":"Physical PDF pp. 135–136"}],"sections":[{"heading":"Purpose of a written IPS","body":"IPS là văn bản ghi rõ goals, objectives, constraints và phạm vi quản lý tiền. Giúp manager thiết kế portfolio phù hợp thay vì chọn đầu tư dựa trên suy đoán; client hiểu điều gì có thể kỳ vọng và điều gì không.","trap":"IPS không bảo đảm đạt target return."},{"heading":"Discipline and continuity","body":"IPS tạo chuẩn chung để xử lý biến động, thay manager hoặc nhân sự committee; quyết định được đối chiếu mục tiêu dài hạn. Khi hoàn cảnh thay đổi phải cập nhật tài liệu theo quy trình.","trap":"Không giữ IPS bất biến khi liabilities thay đổi thực chất."},{"heading":"Suitability and communication","body":"Trước khi đầu tư, manager và client thống nhất mục tiêu, ràng buộc, khả năng chịu risk và cách đo kết quả. Mâu thuẫn như muốn return rất cao nhưng không chịu lỗ phải được giải quyết hoặc điều chỉnh mục tiêu.","trap":"Không chọn tài sản trước rồi viết IPS để hợp thức hóa."},{"heading":"Accountability","body":"Benchmark, reporting và review được thống nhất trước giúp đánh giá manager và portfolio. IPS làm rõ trách nhiệm giữa client, advisor, custodian hoặc committee. Không dùng kết quả đã xảy ra để lựa benchmark có lợi.","trap":"Không đánh giá manager bằng benchmark không phù hợp mandate."},{"heading":"Review triggers","body":"IPS cần định kỳ review và cập nhật khi mục tiêu, thuế, hoàn cảnh, liquidity hoặc legal constraints thay đổi đáng kể. Market forecast có thể thay đổi SAA mà không nhất thiết thay client objectives. Tần suất cụ thể theo chính sách.","trap":"Một phiên thị trường xấu không tự động là thay đổi mục tiêu."}],"formulas":[{"name":"IPS purpose and review","expr":"Needs → written policy → implementation → review","meaning":"Mục tiêu và constraints làm chuẩn đánh giá, kỷ luật, communication.","conditions":"Framework; update khi hoàn cảnh thay đổi thực chất."}],"examples":[{"question_en":"A family changes its portfolio manager but its objectives and obligations remain unchanged. How should the written IPS be used?","steps_vi":["IPS giữ mục tiêu/ràng buộc và responsibility framework, giúp continuity.","New manager review facts and suitability, không tự chọn policy mới chỉ vì thay manager."],"answer":"Use the IPS as a shared, reviewable mandate.","check":"Original conceptual case; conclusions conditional on the stated facts."}],"questions":[{"stem_en":"A written IPS is most useful because it:","options":["guarantees achievement of the return objective.","removes all market risk.","documents the client's objectives and constraints for investment decisions."],"correct":2,"why_vi":"IPS là văn bản ghi rõ goals, objectives, constraints và phạm vi quản lý tiền. Giúp manager thiết kế portfolio phù hợp thay vì chọn đầu tư dựa trên suy đoán; client hiểu điều gì có thể kỳ vọng và điều gì không.","trap_vi":"IPS không bảo đảm đạt target return."},{"stem_en":"An investment committee changes personnel. A written IPS most directly provides:","options":["a guarantee of better market performance.","automatic permission to change constraints.","continuity of investment policy."],"correct":2,"why_vi":"IPS tạo chuẩn chung để xử lý biến động, thay manager hoặc nhân sự committee; quyết định được đối chiếu mục tiêu dài hạn. Khi hoàn cảnh thay đổi phải cập nhật tài liệu theo quy trình.","trap_vi":"Không giữ IPS bất biến khi liabilities thay đổi thực chất."},{"stem_en":"A client requires capital preservation but requests a highly leveraged strategy. The manager should first:","options":["implement leverage without discussion.","clarify and reconcile the conflicting objectives and constraints.","remove the risk objective from the IPS."],"correct":1,"why_vi":"Trước khi đầu tư, manager và client thống nhất mục tiêu, ràng buộc, khả năng chịu risk và cách đo kết quả. Mâu thuẫn như muốn return rất cao nhưng không chịu lỗ phải được giải quyết hoặc điều chỉnh mục tiêu.","trap_vi":"Không chọn tài sản trước rồi viết IPS để hợp thức hóa."},{"stem_en":"A benchmark specified before investing primarily supports:","options":["retrospective selection of the most favorable comparison.","a guaranteed positive active return.","consistent performance evaluation and accountability."],"correct":2,"why_vi":"Benchmark, reporting và review được thống nhất trước giúp đánh giá manager và portfolio. IPS làm rõ trách nhiệm giữa client, advisor, custodian hoặc committee. Không dùng kết quả đã xảy ra để lựa benchmark có lợi.","trap_vi":"Không đánh giá manager bằng benchmark không phù hợp mandate."},{"stem_en":"Which event most clearly warrants reassessing an individual's IPS?","options":["A single day of index underperformance with no client changes","A routine change in an ETF's market price","A material unexpected near-term spending obligation"],"correct":2,"why_vi":"IPS cần định kỳ review và cập nhật khi mục tiêu, thuế, hoàn cảnh, liquidity hoặc legal constraints thay đổi đáng kể. Market forecast có thể thay đổi SAA mà không nhất thiết thay client objectives. Tần suất cụ thể theo chính sách.","trap_vi":"Một phiên thị trường xấu không tự động là thay đổi mục tiêu."}],"cards":[{"front_en":"Purpose of a written IPS","back_vi":"IPS là văn bản ghi rõ goals, objectives, constraints và phạm vi quản lý tiền. Giúp manager thiết kế portfolio phù hợp thay vì chọn đầu tư dựa trên suy đoán; client hiểu điều gì có thể kỳ vọng và điều gì không. | Exam trap: IPS không bảo đảm đạt target return."},{"front_en":"Discipline and continuity","back_vi":"IPS tạo chuẩn chung để xử lý biến động, thay manager hoặc nhân sự committee; quyết định được đối chiếu mục tiêu dài hạn. Khi hoàn cảnh thay đổi phải cập nhật tài liệu theo quy trình. | Exam trap: Không giữ IPS bất biến khi liabilities thay đổi thực chất."},{"front_en":"Suitability and communication","back_vi":"Trước khi đầu tư, manager và client thống nhất mục tiêu, ràng buộc, khả năng chịu risk và cách đo kết quả. Mâu thuẫn như muốn return rất cao nhưng không chịu lỗ phải được giải quyết hoặc điều chỉnh mục tiêu. | Exam trap: Không chọn tài sản trước rồi viết IPS để hợp thức hóa."},{"front_en":"Accountability","back_vi":"Benchmark, reporting và review được thống nhất trước giúp đánh giá manager và portfolio. IPS làm rõ trách nhiệm giữa client, advisor, custodian hoặc committee. Không dùng kết quả đã xảy ra để lựa benchmark có lợi. | Exam trap: Không đánh giá manager bằng benchmark không phù hợp mandate."},{"front_en":"Review triggers","back_vi":"IPS cần định kỳ review và cập nhật khi mục tiêu, thuế, hoàn cảnh, liquidity hoặc legal constraints thay đổi đáng kể. Market forecast có thể thay đổi SAA mà không nhất thiết thay client objectives. Tần suất cụ thể theo chính sách. | Exam trap: Một phiên thị trường xấu không tự động là thay đổi mục tiêu."},{"front_en":"IPS purpose and review — formula or framework?","back_vi":"Needs → written policy → implementation → review · Mục tiêu và constraints làm chuẩn đánh giá, kỷ luật, communication. · Framework; update khi hoàn cảnh thay đổi thực chất."}]},{"id":"CFA26-09-04-LOS02","letter":"b","title_en":"Major Components of an IPS","outcome_en":"describe the major components of an IPS","overview_vi":"Bài học 4.b: Major Components of an IPS. Học bản chất khái niệm, điều kiện áp dụng, so sánh và giải quyết tình huống. Công thức ghi supplement là bài luyện thêm; câu hỏi tiếng Anh do dự án tự biên soạn.","source":[{"id":"CFA Institute Curriculum 2026 — Portfolio Management Volume 9","pages":"Physical PDF p. 169 (LOS), 171–172,180–185 (content)"},{"id":"Kaplan SchweserNotes 2026 — Book 4, Reading 86","pages":"Physical PDF pp. 118–119"},{"id":"SAPP CFA Level I 2026 — Portfolio Management slides","pages":"Physical PDF pp. 137–138"}],"sections":[{"heading":"Introduction and purpose","body":"IPS mô tả client, mục đích danh mục và lý do tồn tại của văn bản. Ví dụ quỹ tài trợ trường học để duy trì real purchasing power và chi tiêu thường xuyên. Phần mở đầu khác objective định lượng.","trap":"Không nhầm mô tả mục đích với target weights."},{"heading":"Duties and responsibilities","body":"Ghi rõ vai trò của client, trustees, investment manager, custodian và advisors; ai quyết định strategic allocation, ai triển khai và ai giám sát. Delegation phải rõ để tránh lẫn trách nhiệm.","trap":"Không coi mọi quyết định do broker chịu trách nhiệm."},{"heading":"Procedures and review","body":"Procedures nêu cách duy trì IPS, điều kiện sửa đổi; evaluation and review nêu báo cáo, benchmark, frequency và cách nhận feedback. Việc ghi rõ cơ chế cập nhật hỗ trợ accountability.","trap":"Không nhầm quy trình review với risk objective."},{"heading":"Investment objectives","body":"Hai nhóm mục tiêu là risk và return: absolute hoặc relative, horizon, units, gross/net, nominal/real theo nhu cầu. Mục tiêu phải nhất quán và có thể kiểm tra; risk tolerance phản ánh willingness và capacity.","trap":"Không coi return objective là forecast thị trường chắc chắn."},{"heading":"Investment constraints","body":"Các hạn chế liquidity, time horizon, tax, legal/regulatory và unique circumstances ảnh hưởng lựa chọn tài sản. Chúng khác mục tiêu, vì giới hạn tập feasible portfolios chứ không chỉ xác định lợi nhuận mong muốn.","trap":"Không gộp tax constraints thành expected return duy nhất."},{"heading":"Guidelines and appendices","body":"Investment guidelines chỉ cách thực hiện, permitted assets, leverage restrictions và limits; phụ lục thường có SAA/policy weights và rebalancing policy. Curriculum tách SAA như kết quả kết hợp IPS với market expectations; thực tế có thể đưa vào phụ lục IPS.","trap":"Không yêu cầu IPS phải liệt kê mọi mã chứng khoán."}],"formulas":[{"name":"IPS structure","expr":"Client + purpose + duties + procedures + objectives + constraints + guidelines + evaluation/review + appendices","meaning":"Phân biệt vai trò từng nhóm mục trong IPS.","conditions":"Framework; format có thể thay đổi; SAA có thể là phụ lục."}],"examples":[{"question_en":"An IPS lists the trustees' authority, a 3% tracking risk limit, and an annual review schedule. Classify each item.","steps_vi":["Authority thuộc duties and responsibilities; tracking risk limit là risk objective.","Annual review schedule thuộc procedures/evaluation and review; cả ba mục khác nhau."],"answer":"Responsibilities; investment objectives; review procedures.","check":"Original conceptual case; conclusions conditional on the stated facts."}],"questions":[{"stem_en":"Which IPS component identifies the client and why the portfolio is managed?","options":["The list of executed trades","The latest performance attribution report","Introduction and statement of purpose"],"correct":2,"why_vi":"IPS mô tả client, mục đích danh mục và lý do tồn tại của văn bản. Ví dụ quỹ tài trợ trường học để duy trì real purchasing power và chi tiêu thường xuyên. Phần mở đầu khác objective định lượng.","trap_vi":"Không nhầm mô tả mục đích với target weights."},{"stem_en":"Which IPS section identifies who may approve changes to investment policy?","options":["Historical returns appendix","Statement of duties and responsibilities","Security valuation worksheet"],"correct":1,"why_vi":"Ghi rõ vai trò của client, trustees, investment manager, custodian và advisors; ai quyết định strategic allocation, ai triển khai và ai giám sát. Delegation phải rõ để tránh lẫn trách nhiệm.","trap_vi":"Không coi mọi quyết định do broker chịu trách nhiệm."},{"stem_en":"An IPS provision requiring an annual policy review belongs most directly to:","options":["a target annual return.","an asset's expected cash flow.","procedures for keeping the IPS current."],"correct":2,"why_vi":"Procedures nêu cách duy trì IPS, điều kiện sửa đổi; evaluation and review nêu báo cáo, benchmark, frequency và cách nhận feedback. Việc ghi rõ cơ chế cập nhật hỗ trợ accountability.","trap_vi":"Không nhầm quy trình review với risk objective."},{"stem_en":"A maximum acceptable annual tracking error belongs to the IPS section on:","options":["investment objectives.","client introduction.","custodian contact details."],"correct":0,"why_vi":"Hai nhóm mục tiêu là risk và return: absolute hoặc relative, horizon, units, gross/net, nominal/real theo nhu cầu. Mục tiêu phải nhất quán và có thể kiểm tra; risk tolerance phản ánh willingness và capacity.","trap_vi":"Không coi return objective là forecast thị trường chắc chắn."},{"stem_en":"A prohibition on holding a specific industry because of the client's stated values is primarily an:","options":["asset-class return forecast.","investment constraint.","performance measurement formula."],"correct":1,"why_vi":"Các hạn chế liquidity, time horizon, tax, legal/regulatory và unique circumstances ảnh hưởng lựa chọn tài sản. Chúng khác mục tiêu, vì giới hạn tập feasible portfolios chứ không chỉ xác định lợi nhuận mong muốn.","trap_vi":"Không gộp tax constraints thành expected return duy nhất."},{"stem_en":"A rule requiring action if an equity weight exceeds its allowed band is most directly a:","options":["definition of the client's identity.","forecast of equity returns.","rebalancing policy."],"correct":2,"why_vi":"Investment guidelines chỉ cách thực hiện, permitted assets, leverage restrictions và limits; phụ lục thường có SAA/policy weights và rebalancing policy. Curriculum tách SAA như kết quả kết hợp IPS với market expectations; thực tế có thể đưa vào phụ lục IPS.","trap_vi":"Không yêu cầu IPS phải liệt kê mọi mã chứng khoán."}],"cards":[{"front_en":"Introduction and purpose","back_vi":"IPS mô tả client, mục đích danh mục và lý do tồn tại của văn bản. Ví dụ quỹ tài trợ trường học để duy trì real purchasing power và chi tiêu thường xuyên. Phần mở đầu khác objective định lượng. | Exam trap: Không nhầm mô tả mục đích với target weights."},{"front_en":"Duties and responsibilities","back_vi":"Ghi rõ vai trò của client, trustees, investment manager, custodian và advisors; ai quyết định strategic allocation, ai triển khai và ai giám sát. Delegation phải rõ để tránh lẫn trách nhiệm. | Exam trap: Không coi mọi quyết định do broker chịu trách nhiệm."},{"front_en":"Procedures and review","back_vi":"Procedures nêu cách duy trì IPS, điều kiện sửa đổi; evaluation and review nêu báo cáo, benchmark, frequency và cách nhận feedback. Việc ghi rõ cơ chế cập nhật hỗ trợ accountability. | Exam trap: Không nhầm quy trình review với risk objective."},{"front_en":"Investment objectives","back_vi":"Hai nhóm mục tiêu là risk và return: absolute hoặc relative, horizon, units, gross/net, nominal/real theo nhu cầu. Mục tiêu phải nhất quán và có thể kiểm tra; risk tolerance phản ánh willingness và capacity. | Exam trap: Không coi return objective là forecast thị trường chắc chắn."},{"front_en":"Investment constraints","back_vi":"Các hạn chế liquidity, time horizon, tax, legal/regulatory và unique circumstances ảnh hưởng lựa chọn tài sản. Chúng khác mục tiêu, vì giới hạn tập feasible portfolios chứ không chỉ xác định lợi nhuận mong muốn. | Exam trap: Không gộp tax constraints thành expected return duy nhất."},{"front_en":"Guidelines and appendices","back_vi":"Investment guidelines chỉ cách thực hiện, permitted assets, leverage restrictions và limits; phụ lục thường có SAA/policy weights và rebalancing policy. Curriculum tách SAA như kết quả kết hợp IPS với market expectations; thực tế có thể đưa vào phụ lục IPS. | Exam trap: Không yêu cầu IPS phải liệt kê mọi mã chứng khoán."},{"front_en":"IPS structure — formula or framework?","back_vi":"Client + purpose + duties + procedures + objectives + constraints + guidelines + evaluation/review + appendices · Phân biệt vai trò từng nhóm mục trong IPS. · Framework; format có thể thay đổi; SAA có thể là phụ lục."}]},{"id":"CFA26-09-04-LOS03","letter":"c","title_en":"Risk and Return Objectives","outcome_en":"describe risk and return objectives and how they may be developed for a client","overview_vi":"Bài học 4.c: Risk and Return Objectives. Học bản chất khái niệm, điều kiện áp dụng, so sánh và giải quyết tình huống. Công thức ghi supplement là bài luyện thêm; câu hỏi tiếng Anh do dự án tự biên soạn.","source":[{"id":"CFA Institute Curriculum 2026 — Portfolio Management Volume 9","pages":"Physical PDF p. 169 (LOS), 172–180 (content)"},{"id":"Kaplan SchweserNotes 2026 — Book 4, Reading 86","pages":"Physical PDF pp. 119–120"},{"id":"SAPP CFA Level I 2026 — Portfolio Management slides","pages":"Physical PDF pp. 139–140"}],"sections":[{"heading":"Absolute risk objectives","body":"Risk objective tuyệt đối không dựa benchmark, ví dụ xác suất danh mục không giảm quá mức nhất định trong 12 tháng. Volatility hoặc VaR là thước đo có thể dùng, cần chỉ rõ horizon và confidence. Mục tiêu xác suất không phải bảo đảm.","trap":"Không nhầm giới hạn VaR với maximum possible loss."},{"heading":"Relative risk objectives","body":"Relative risk xác định theo benchmark phù hợp; tracking risk/error là standard deviation của active returns. Mục tiêu có thể là xác suất return nằm trong band quanh benchmark, không nói portfolio chắc chắn không lỗ.","trap":"Tracking error thấp vẫn có thể đi cùng absolute volatility cao."},{"heading":"Liability-driven objectives","body":"Khi liabilities có size/timing/certainty tương đối xác định, LDI đặt mục tiêu giảm xác suất không đáp ứng obligations. Return có thể so discount rate dùng định giá liability trong thời gian nhiều năm, risk xét cả assets và liabilities.","trap":"Không tối đa hóa return độc lập với nghĩa vụ."},{"heading":"Absolute and relative return","body":"Absolute return có thể nominal hoặc inflation-adjusted real; relative return đặt so benchmark như index hoặc reference rate. Cần làm rõ gross/net fees và tax, period đo lường. Benchmark phải phù hợp exposure.","trap":"Không nhầm real return với nominal minus inflation chính xác trong mọi trường hợp."},{"heading":"Required return from goals","body":"Required return xuất phát mục tiêu tài chính, số vốn, horizon và cash flows; desired return là mức mong muốn. Với không có thêm contribution/rút tiền, cần tăng vốn theo mục tiêu danh nghĩa cuối kỳ. Phải trừ phần vốn dành dự phòng khỏi investable assets nếu được nêu.","trap":"Không dùng tổng wealth bao gồm emergency reserve để tính growth rate."},{"heading":"Real versus nominal","body":"Lạm phát làm giảm purchasing power; nominal target cuối kỳ = real target hôm nay nhân hệ số lạm phát tích lũy. Real return chính xác từ tỷ lệ gross returns, không chỉ lấy chênh lệch khi cần tính chính xác.","trap":"Không trừ lạm phát lần nữa khi target đã là nominal."},{"heading":"Feasibility and trade-offs","body":"Return objective phải thực tế so capital market expectations và risk tolerance. Nếu required return không khả thi, thảo luận tăng saving, kéo dài horizon, giảm spending hoặc sửa goal; không tự tăng risk vượt capacity.","trap":"Required return cao không tự tạo ability chịu risk cao."}],"formulas":[{"name":"Absolute vs relative risk","expr":"Absolute: σ, VaR; relative: tracking risk = σ(Rp − Rb); liability-driven: shortfall versus obligations","meaning":"Chọn risk measure phù hợp mục tiêu.","conditions":"Cùng horizon; VaR cần confidence, không phải maximum loss."},{"name":"Nominal target wealth","expr":"FVnominal = target in today's money × (1+π)^T","meaning":"Chuyển purchasing-power goal sang nominal amount tại horizon.","conditions":"Inflation constant trong ví dụ; nếu thay đổi dùng tích hệ số từng kỳ."},{"name":"Required annual return","expr":"r = (FV / PV)^(1/T) − 1","meaning":"Annual compound return cần đạt target khi không có cash flows trung gian.","conditions":"PV là investable wealth; FV nominal hoặc real nhất quán; T>0."},{"name":"Exact real return","expr":"rreal = (1+rnominal)/(1+π) − 1","meaning":"Loại tác động inflation khỏi nominal return.","conditions":"Cùng kỳ; π > −100%; không dùng xấp xỉ nếu yêu cầu chính xác."},{"name":"Active return target","expr":"Required return = benchmark return + target excess return","meaning":"Chuyển mục tiêu benchmark-relative thành return threshold khi benchmark biết.","conditions":"Cùng kỳ, convention additive; benchmark tương lai chưa chắc chắn."}],"examples":[{"question_en":"A client wants no more than a 4% annual loss with 95% probability and a return 1% above a named index. Classify the objectives.","steps_vi":["Loss threshold với probability/horizon, không benchmark: absolute risk objective; không phải guaranteed cap.","Index +1% là relative return objective, benchmark phải phù hợp."],"answer":"Absolute risk objective and relative return objective.","check":"Original conceptual case; conclusions conditional on the stated facts."},{"question_en":"A client wants USD 500,000 in today's purchasing power in three years. Annual inflation is expected to be 4%. The nominal target is closest to:","steps_vi":["Compound inflation 3 kỳ.","Thay số: 500000 × 1.04^3.","Kết quả: 562,432.00 USD."],"answer":"562,432.00 USD","check":"Original supplemental practice; Decimal compared with an alternate expression using Fraction (square root uses float in the second method)."},{"question_en":"A client has USD 250,000 available for a goal and needs USD 302,500 in two years, with no additional cash flows. The annual required return is closest to:","steps_vi":["Lấy căn bậc 2 của FV/PV rồi trừ 1.","Thay số: (√(302500/250000)-1) × 100.","Kết quả: 10.00%."],"answer":"10.00%","check":"Original supplemental practice; Decimal compared with an alternate expression using Fraction (square root uses float in the second method)."},{"question_en":"A portfolio earns a nominal 8% while inflation is 3%. Its exact real return is closest to:","steps_vi":["Fisher gross-factor relation.","Thay số: (1.08/1.03-1) × 100.","Kết quả: 4.85%."],"answer":"4.85%","check":"Original supplemental practice; Decimal compared with an alternate expression using Fraction (square root uses float in the second method)."},{"question_en":"A client has USD 600,000 total savings, including a USD 100,000 emergency reserve excluded from investing. A one-year investment goal is USD 540,000 with no cash flows. The required return is closest to:","steps_vi":["Chỉ tính investable wealth 500,000.","Thay số: (540000/(600000-100000)-1) × 100.","Kết quả: 8.00%."],"answer":"8.00%","check":"Original supplemental practice; Decimal compared with an alternate expression using Fraction (square root uses float in the second method)."},{"question_en":"An IPS sets a 0.8 percentage point annual excess return objective over a benchmark that returns 5.4%. The portfolio's corresponding return target is closest to:","steps_vi":["Relative return target cộng benchmark return.","Thay số: 5.4+0.8.","Kết quả: 6.20%."],"answer":"6.20%","check":"Original supplemental practice; Decimal compared with an alternate expression using Fraction (square root uses float in the second method)."}],"questions":[{"stem_en":"Which is an absolute risk objective?","options":["Annual tracking error below 2% relative to an index","Returns within 3% of a policy benchmark","A 95% probability of losing no more than 5% over one year"],"correct":2,"why_vi":"Risk objective tuyệt đối không dựa benchmark, ví dụ xác suất danh mục không giảm quá mức nhất định trong 12 tháng. Volatility hoặc VaR là thước đo có thể dùng, cần chỉ rõ horizon và confidence. Mục tiêu xác suất không phải bảo đảm.","trap_vi":"Không nhầm giới hạn VaR với maximum possible loss."},{"stem_en":"The standard deviation of portfolio returns minus benchmark returns is:","options":["tracking error.","absolute expected return.","the funded ratio."],"correct":0,"why_vi":"Relative risk xác định theo benchmark phù hợp; tracking risk/error là standard deviation của active returns. Mục tiêu có thể là xác suất return nằm trong band quanh benchmark, không nói portfolio chắc chắn không lỗ.","trap_vi":"Tracking error thấp vẫn có thể đi cùng absolute volatility cao."},{"stem_en":"For a DB pension fund, a liability-driven risk objective is most likely to focus on:","options":["the number of equities in an index.","the standalone return of the best-performing asset.","the probability of failing to meet promised benefit payments."],"correct":2,"why_vi":"Khi liabilities có size/timing/certainty tương đối xác định, LDI đặt mục tiêu giảm xác suất không đáp ứng obligations. Return có thể so discount rate dùng định giá liability trong thời gian nhiều năm, risk xét cả assets và liabilities.","trap_vi":"Không tối đa hóa return độc lập với nghĩa vụ."},{"stem_en":"Which is a relative return objective?","options":["Earn 5% nominal return per year","Maintain a specified absolute portfolio value","Outperform the policy benchmark by 1% annually"],"correct":2,"why_vi":"Absolute return có thể nominal hoặc inflation-adjusted real; relative return đặt so benchmark như index hoặc reference rate. Cần làm rõ gross/net fees và tax, period đo lường. Benchmark phải phù hợp exposure.","trap_vi":"Không nhầm real return với nominal minus inflation chính xác trong mọi trường hợp."},{"stem_en":"A client has a future wealth target and no intervening cash flows. Required annual return is determined most directly by:","options":["the client's preferred stock market index alone.","the manager's previous annual bonus.","the target wealth, investable initial wealth and horizon."],"correct":2,"why_vi":"Required return xuất phát mục tiêu tài chính, số vốn, horizon và cash flows; desired return là mức mong muốn. Với không có thêm contribution/rút tiền, cần tăng vốn theo mục tiêu danh nghĩa cuối kỳ. Phải trừ phần vốn dành dự phòng khỏi investable assets nếu được nêu.","trap_vi":"Không dùng tổng wealth bao gồm emergency reserve để tính growth rate."},{"stem_en":"If a future target is expressed in today's purchasing power, the nominal target is obtained by:","options":["compounding the real target at the expected inflation rate.","subtracting cumulative inflation from the real target.","ignoring inflation because the horizon is long."],"correct":0,"why_vi":"Lạm phát làm giảm purchasing power; nominal target cuối kỳ = real target hôm nay nhân hệ số lạm phát tích lũy. Real return chính xác từ tỷ lệ gross returns, không chỉ lấy chênh lệch khi cần tính chính xác.","trap_vi":"Không trừ lạm phát lần nữa khi target đã là nominal."},{"stem_en":"When a client's required return is inconsistent with acceptable risk, the manager should most appropriately:","options":["discuss changes to the goal, contributions or horizon.","increase risk without the client's informed agreement.","promise the required return."],"correct":0,"why_vi":"Return objective phải thực tế so capital market expectations và risk tolerance. Nếu required return không khả thi, thảo luận tăng saving, kéo dài horizon, giảm spending hoặc sửa goal; không tự tăng risk vượt capacity.","trap_vi":"Required return cao không tự tạo ability chịu risk cao."},{"stem_en":"A client wants USD 500,000 in today's purchasing power in three years. Annual inflation is expected to be 4%. The nominal target is closest to:","options":["560,000.00 USD","562,432.00 USD","444,498.18 USD"],"correct":1,"why_vi":"Compound inflation 3 kỳ. Thay số: 500000 × 1.04^3 = 562,432.00 USD.","trap_vi":"Không dùng simple inflation hoặc discount mục tiêu."},{"stem_en":"A client has USD 250,000 available for a goal and needs USD 302,500 in two years, with no additional cash flows. The annual required return is closest to:","options":["21.00%","10.50%","10.00%"],"correct":2,"why_vi":"Lấy căn bậc 2 của FV/PV rồi trừ 1. Thay số: (√(302500/250000)-1) × 100 = 10.00%.","trap_vi":"Không dùng cumulative return hoặc chia đều cho hai năm."},{"stem_en":"A portfolio earns a nominal 8% while inflation is 3%. Its exact real return is closest to:","options":["4.85%","5.00%","2.67%"],"correct":0,"why_vi":"Fisher gross-factor relation. Thay số: (1.08/1.03-1) × 100 = 4.85%.","trap_vi":"Nominal minus inflation chỉ xấp xỉ."},{"stem_en":"A client has USD 600,000 total savings, including a USD 100,000 emergency reserve excluded from investing. A one-year investment goal is USD 540,000 with no cash flows. The required return is closest to:","options":["-10.00%","8.00%","108.00%"],"correct":1,"why_vi":"Chỉ tính investable wealth 500,000. Thay số: (540000/(600000-100000)-1) × 100 = 8.00%.","trap_vi":"Không dùng emergency reserve hoặc quên trừ 1."},{"stem_en":"An IPS sets a 0.8 percentage point annual excess return objective over a benchmark that returns 5.4%. The portfolio's corresponding return target is closest to:","options":["5.44%","4.60%","6.20%"],"correct":2,"why_vi":"Relative return target cộng benchmark return. Thay số: 5.4+0.8 = 6.20%.","trap_vi":"Percentage points không phải multiplicative percent."}],"cards":[{"front_en":"Absolute risk objectives","back_vi":"Risk objective tuyệt đối không dựa benchmark, ví dụ xác suất danh mục không giảm quá mức nhất định trong 12 tháng. Volatility hoặc VaR là thước đo có thể dùng, cần chỉ rõ horizon và confidence. Mục tiêu xác suất không phải bảo đảm. | Exam trap: Không nhầm giới hạn VaR với maximum possible loss."},{"front_en":"Relative risk objectives","back_vi":"Relative risk xác định theo benchmark phù hợp; tracking risk/error là standard deviation của active returns. Mục tiêu có thể là xác suất return nằm trong band quanh benchmark, không nói portfolio chắc chắn không lỗ. | Exam trap: Tracking error thấp vẫn có thể đi cùng absolute volatility cao."},{"front_en":"Liability-driven objectives","back_vi":"Khi liabilities có size/timing/certainty tương đối xác định, LDI đặt mục tiêu giảm xác suất không đáp ứng obligations. Return có thể so discount rate dùng định giá liability trong thời gian nhiều năm, risk xét cả assets và liabilities. | Exam trap: Không tối đa hóa return độc lập với nghĩa vụ."},{"front_en":"Absolute and relative return","back_vi":"Absolute return có thể nominal hoặc inflation-adjusted real; relative return đặt so benchmark như index hoặc reference rate. Cần làm rõ gross/net fees và tax, period đo lường. Benchmark phải phù hợp exposure. | Exam trap: Không nhầm real return với nominal minus inflation chính xác trong mọi trường hợp."},{"front_en":"Required return from goals","back_vi":"Required return xuất phát mục tiêu tài chính, số vốn, horizon và cash flows; desired return là mức mong muốn. Với không có thêm contribution/rút tiền, cần tăng vốn theo mục tiêu danh nghĩa cuối kỳ. Phải trừ phần vốn dành dự phòng khỏi investable assets nếu được nêu. | Exam trap: Không dùng tổng wealth bao gồm emergency reserve để tính growth rate."},{"front_en":"Real versus nominal","back_vi":"Lạm phát làm giảm purchasing power; nominal target cuối kỳ = real target hôm nay nhân hệ số lạm phát tích lũy. Real return chính xác từ tỷ lệ gross returns, không chỉ lấy chênh lệch khi cần tính chính xác. | Exam trap: Không trừ lạm phát lần nữa khi target đã là nominal."},{"front_en":"Feasibility and trade-offs","back_vi":"Return objective phải thực tế so capital market expectations và risk tolerance. Nếu required return không khả thi, thảo luận tăng saving, kéo dài horizon, giảm spending hoặc sửa goal; không tự tăng risk vượt capacity. | Exam trap: Required return cao không tự tạo ability chịu risk cao."},{"front_en":"Absolute vs relative risk — formula or framework?","back_vi":"Absolute: σ, VaR; relative: tracking risk = σ(Rp − Rb); liability-driven: shortfall versus obligations · Chọn risk measure phù hợp mục tiêu. · Cùng horizon; VaR cần confidence, không phải maximum loss."},{"front_en":"Nominal target wealth — formula or framework?","back_vi":"FVnominal = target in today's money × (1+π)^T · Chuyển purchasing-power goal sang nominal amount tại horizon. · Inflation constant trong ví dụ; nếu thay đổi dùng tích hệ số từng kỳ."},{"front_en":"Required annual return — formula or framework?","back_vi":"r = (FV / PV)^(1/T) − 1 · Annual compound return cần đạt target khi không có cash flows trung gian. · PV là investable wealth; FV nominal hoặc real nhất quán; T>0."},{"front_en":"Exact real return — formula or framework?","back_vi":"rreal = (1+rnominal)/(1+π) − 1 · Loại tác động inflation khỏi nominal return. · Cùng kỳ; π > −100%; không dùng xấp xỉ nếu yêu cầu chính xác."},{"front_en":"Active return target — formula or framework?","back_vi":"Required return = benchmark return + target excess return · Chuyển mục tiêu benchmark-relative thành return threshold khi benchmark biết. · Cùng kỳ, convention additive; benchmark tương lai chưa chắc chắn."},{"front_en":"A client wants USD 500,000 in today's purchasing power in three years. Annual inflation is expected to be 4%. The nominal target is closest to:","back_vi":"Compound inflation 3 kỳ. Thay số: 500000 × 1.04^3 = 562,432.00 USD. | Không dùng simple inflation hoặc discount mục tiêu."},{"front_en":"A client has USD 250,000 available for a goal and needs USD 302,500 in two years, with no additional cash flows. The annual required return is closest to:","back_vi":"Lấy căn bậc 2 của FV/PV rồi trừ 1. Thay số: (√(302500/250000)-1) × 100 = 10.00%. | Không dùng cumulative return hoặc chia đều cho hai năm."},{"front_en":"A portfolio earns a nominal 8% while inflation is 3%. Its exact real return is closest to:","back_vi":"Fisher gross-factor relation. Thay số: (1.08/1.03-1) × 100 = 4.85%. | Nominal minus inflation chỉ xấp xỉ."},{"front_en":"A client has USD 600,000 total savings, including a USD 100,000 emergency reserve excluded from investing. A one-year investment goal is USD 540,000 with no cash flows. The required return is closest to:","back_vi":"Chỉ tính investable wealth 500,000. Thay số: (540000/(600000-100000)-1) × 100 = 8.00%. | Không dùng emergency reserve hoặc quên trừ 1."},{"front_en":"An IPS sets a 0.8 percentage point annual excess return objective over a benchmark that returns 5.4%. The portfolio's corresponding return target is closest to:","back_vi":"Relative return target cộng benchmark return. Thay số: 5.4+0.8 = 6.20%. | Percentage points không phải multiplicative percent."}]},{"id":"CFA26-09-04-LOS04","letter":"d","title_en":"Willingness and Ability to Take Risk","outcome_en":"explain the difference between the willingness and the ability (capacity) to take risk in analyzing an investor’s financial risk tolerance","overview_vi":"Bài học 4.d: Willingness and Ability to Take Risk. Học bản chất khái niệm, điều kiện áp dụng, so sánh và giải quyết tình huống. Công thức ghi supplement là bài luyện thêm; câu hỏi tiếng Anh do dự án tự biên soạn.","source":[{"id":"CFA Institute Curriculum 2026 — Portfolio Management Volume 9","pages":"Physical PDF p. 169 (LOS), 174–178 (content)"},{"id":"Kaplan SchweserNotes 2026 — Book 4, Reading 86","pages":"Physical PDF pp. 119–120"},{"id":"SAPP CFA Level I 2026 — Portfolio Management slides","pages":"Physical PDF pp. 141–142"}],"sections":[{"heading":"Ability or capacity","body":"Capacity là khả năng tài chính chịu tổn thất: wealth, liabilities, income stability, horizon, liquidity và khả năng bù lỗ. Tiền cần trong vài tháng không có cùng capacity như vốn dài hạn, dù tổng tài sản lớn.","trap":"Không suy ability chỉ từ willingness."},{"heading":"Willingness","body":"Willingness là thái độ và mức thoải mái tâm lý khi chịu rủi ro. Questionnaires, interviews và scenarios giúp đánh giá; phản ứng thực tế khi drawdown có thể khác câu trả lời lý thuyết. Cần thảo luận và giáo dục.","trap":"Không coi willingness là tài sản tài chính."},{"heading":"Both high or both low","body":"Nếu ability và willingness đều cao, risk tolerance có thể cao; nếu cả hai thấp, risk tolerance thấp. Đây là khung định tính, cần xem mục tiêu và constraints cụ thể; không tự động gán một tỷ lệ equity.","trap":"Không chọn high risk chỉ vì một tiêu chí cao."},{"heading":"Ability low willingness high","body":"Khi client muốn mạo hiểm nhưng tài chính không chịu nổi, manager giải thích và lấy capacity làm giới hạn trên. Ví dụ unstable income và upcoming tuition khiến risk thực tế thấp dù thích đầu cơ.","trap":"Không lấy trung bình để vượt ability."},{"heading":"Ability high willingness low","body":"Khi client có khả năng tài chính nhưng lo lắng, advisor giải thích risk/return và đánh giá willingness thực sự. Có thể điều chỉnh nhận thức thông qua education; không áp portfolio quá rủi ro khi client chưa đồng ý.","trap":"Capacity cao không tự động xóa willingness thấp."},{"heading":"Document and revisit","body":"Tổng hợp risk tolerance vào IPS, có thể khác nhau cho các mục tiêu/horizon. Khi income, wealth, liability hoặc attitudes thay đổi, cần review. Không dùng điểm survey một cách máy móc mà bỏ qua financial facts.","trap":"Không coi risk tolerance cố định vĩnh viễn."}],"formulas":[{"name":"Risk tolerance framework","expr":"Ability high/low × willingness high/low → informed risk tolerance","meaning":"Ability từ tài chính, willingness từ thái độ. Nếu mâu thuẫn, tư vấn và giới hạn risk phù hợp.","conditions":"Framework; không lấy trung bình số học, không vượt capacity."}],"examples":[{"question_en":"A business owner has unstable income and a large payment due next year but enjoys speculative investments. Assess risk tolerance.","steps_vi":["Willingness cao nhưng ability thấp vì income uncertainty và near-term liability.","Tư vấn rủi ro, bảo vệ cash obligation và không tăng risk vượt capacity; ghi vào IPS."],"answer":"Financial capacity should constrain the risk taken.","check":"Original conceptual case; conclusions conditional on the stated facts."}],"questions":[{"stem_en":"Which factor most directly reduces financial ability to bear risk?","options":["A substantial unavoidable near-term cash obligation","Enjoyment of speculative trading","A preference for volatile stocks"],"correct":0,"why_vi":"Capacity là khả năng tài chính chịu tổn thất: wealth, liabilities, income stability, horizon, liquidity và khả năng bù lỗ. Tiền cần trong vài tháng không có cùng capacity như vốn dài hạn, dù tổng tài sản lớn.","trap_vi":"Không suy ability chỉ từ willingness."},{"stem_en":"A client with ample savings becomes extremely anxious about temporary losses. This primarily indicates low:","options":["ability to take risk based solely on wealth.","expected inflation.","willingness to take risk."],"correct":2,"why_vi":"Willingness là thái độ và mức thoải mái tâm lý khi chịu rủi ro. Questionnaires, interviews và scenarios giúp đánh giá; phản ứng thực tế khi drawdown có thể khác câu trả lời lý thuyết. Cần thảo luận và giáo dục.","trap_vi":"Không coi willingness là tài sản tài chính."},{"stem_en":"A client has stable income, no major near-term liabilities and is comfortable with investment losses. All else equal, risk tolerance is most likely:","options":["necessarily zero.","unrelated to both ability and willingness.","relatively high."],"correct":2,"why_vi":"Nếu ability và willingness đều cao, risk tolerance có thể cao; nếu cả hai thấp, risk tolerance thấp. Đây là khung định tính, cần xem mục tiêu và constraints cụ thể; không tự động gán một tỷ lệ equity.","trap_vi":"Không chọn high risk chỉ vì một tiêu chí cao."},{"stem_en":"A risk-seeking client must fund a large payment next year and has limited reserves. The adviser should give greatest weight to:","options":["the client's high willingness alone.","the manager's personal risk preference.","the client's low ability to take risk."],"correct":2,"why_vi":"Khi client muốn mạo hiểm nhưng tài chính không chịu nổi, manager giải thích và lấy capacity làm giới hạn trên. Ví dụ unstable income và upcoming tuition khiến risk thực tế thấp dù thích đầu cơ.","trap_vi":"Không lấy trung bình để vượt ability."},{"stem_en":"A financially secure client has a low willingness to accept losses. The adviser should most appropriately:","options":["discuss risk and respect the client's informed tolerance.","assume high risk tolerance without discussion.","ignore the psychological preference."],"correct":0,"why_vi":"Khi client có khả năng tài chính nhưng lo lắng, advisor giải thích risk/return và đánh giá willingness thực sự. Có thể điều chỉnh nhận thức thông qua education; không áp portfolio quá rủi ro khi client chưa đồng ý.","trap_vi":"Capacity cao không tự động xóa willingness thấp."},{"stem_en":"Which practice is most appropriate after a client suffers a permanent income reduction?","options":["Reassess ability to bear risk and update the IPS if material","Increase the risk budget automatically","Retain the prior risk profile without inquiry"],"correct":0,"why_vi":"Tổng hợp risk tolerance vào IPS, có thể khác nhau cho các mục tiêu/horizon. Khi income, wealth, liability hoặc attitudes thay đổi, cần review. Không dùng điểm survey một cách máy móc mà bỏ qua financial facts.","trap_vi":"Không coi risk tolerance cố định vĩnh viễn."}],"cards":[{"front_en":"Ability or capacity","back_vi":"Capacity là khả năng tài chính chịu tổn thất: wealth, liabilities, income stability, horizon, liquidity và khả năng bù lỗ. Tiền cần trong vài tháng không có cùng capacity như vốn dài hạn, dù tổng tài sản lớn. | Exam trap: Không suy ability chỉ từ willingness."},{"front_en":"Willingness","back_vi":"Willingness là thái độ và mức thoải mái tâm lý khi chịu rủi ro. Questionnaires, interviews và scenarios giúp đánh giá; phản ứng thực tế khi drawdown có thể khác câu trả lời lý thuyết. Cần thảo luận và giáo dục. | Exam trap: Không coi willingness là tài sản tài chính."},{"front_en":"Both high or both low","back_vi":"Nếu ability và willingness đều cao, risk tolerance có thể cao; nếu cả hai thấp, risk tolerance thấp. Đây là khung định tính, cần xem mục tiêu và constraints cụ thể; không tự động gán một tỷ lệ equity. | Exam trap: Không chọn high risk chỉ vì một tiêu chí cao."},{"front_en":"Ability low willingness high","back_vi":"Khi client muốn mạo hiểm nhưng tài chính không chịu nổi, manager giải thích và lấy capacity làm giới hạn trên. Ví dụ unstable income và upcoming tuition khiến risk thực tế thấp dù thích đầu cơ. | Exam trap: Không lấy trung bình để vượt ability."},{"front_en":"Ability high willingness low","back_vi":"Khi client có khả năng tài chính nhưng lo lắng, advisor giải thích risk/return và đánh giá willingness thực sự. Có thể điều chỉnh nhận thức thông qua education; không áp portfolio quá rủi ro khi client chưa đồng ý. | Exam trap: Capacity cao không tự động xóa willingness thấp."},{"front_en":"Document and revisit","back_vi":"Tổng hợp risk tolerance vào IPS, có thể khác nhau cho các mục tiêu/horizon. Khi income, wealth, liability hoặc attitudes thay đổi, cần review. Không dùng điểm survey một cách máy móc mà bỏ qua financial facts. | Exam trap: Không coi risk tolerance cố định vĩnh viễn."},{"front_en":"Risk tolerance framework — formula or framework?","back_vi":"Ability high/low × willingness high/low → informed risk tolerance · Ability từ tài chính, willingness từ thái độ. Nếu mâu thuẫn, tư vấn và giới hạn risk phù hợp. · Framework; không lấy trung bình số học, không vượt capacity."}]},{"id":"CFA26-09-04-LOS05","letter":"e","title_en":"Investment Constraints","outcome_en":"describe the investment constraints of liquidity, time horizon, tax concerns, legal and regulatory factors, and unique circumstances and their implications for the choice of portfolio assets","overview_vi":"Bài học 4.e: Investment Constraints. Học bản chất khái niệm, điều kiện áp dụng, so sánh và giải quyết tình huống. Công thức ghi supplement là bài luyện thêm; câu hỏi tiếng Anh do dự án tự biên soạn.","source":[{"id":"CFA Institute Curriculum 2026 — Portfolio Management Volume 9","pages":"Physical PDF p. 169 (LOS), 180–188 (content)"},{"id":"Kaplan SchweserNotes 2026 — Book 4, Reading 86","pages":"Physical PDF pp. 120–121"},{"id":"SAPP CFA Level I 2026 — Portfolio Management slides","pages":"Physical PDF pp. 143–149"}],"sections":[{"heading":"Liquidity constraint","body":"Xác định số tiền và thời điểm cần rút (tuition, healthcare, spending, claims). Phần tài sản đáp ứng obligation nên dễ chuyển thành tiền và ít risk tại lúc cần, có thể dùng securities đáo hạn phù hợp.","trap":"Liquidity cao không đồng nghĩa market value chắc chắn tại mọi thời điểm."},{"heading":"Time horizon","body":"Horizon là thời gian đầu tư trước khi cần sử dụng tài sản, có thể nhiều giai đoạn như tích lũy, nghỉ hưu và chuyển giao. Horizon dài có thể chịu volatility tạm thời tốt hơn, nhưng phải xét nghĩa vụ ngắn hạn bên trong.","trap":"Không xem horizon dài là quyền bỏ qua liquidity."},{"heading":"Tax concerns","body":"Tax status ảnh hưởng after-tax return, turnover, realized gains, income và account structure. Tax-deferred/exempt accounts có khác biệt; xác định quy định cụ thể trước khi so investment alternatives.","trap":"Không giả định cùng tax rate cho mọi loại income."},{"heading":"Legal and regulatory","body":"Restrictions có thể xuất phát từ luật đầu tư pension, insurance, trust documents hoặc hợp đồng; giới hạn asset classes, concentration, leverage hoặc fiduciary duties. Manager phải biết áp dụng đúng jurisdiction và loại client.","trap":"Không vi phạm luật vì expected return cao."},{"heading":"Unique circumstances","body":"Client có thể có employer stock, family business, donor requirements, religious/ethical preferences hoặc restrictions riêng. Tài sản bên ngoài danh mục và nguồn thu cùng exposure cần được xét để giảm concentration.","trap":"Không coi unique constraint là optional nếu đã được thỏa thuận."},{"heading":"Interactions and information gathering","body":"Constraints tương tác với nhau: cash need ảnh hưởng capacity, tax và legal giới hạn cách rebalance, unique preferences thu hẹp universe. Thu thập dữ liệu bằng trao đổi client, tài liệu tài sản và liabilities; cập nhật khi thay đổi.","trap":"Không tự điền giả định thiếu dữ kiện vào IPS."}],"formulas":[{"name":"Constraint checklist","expr":"Liquidity; time horizon; tax; legal/regulatory; unique circumstances","meaning":"Đánh giá tác động của từng constraint tới feasible assets.","conditions":"Framework; xác minh theo client/jurisdiction."},{"name":"Liquidity reserve (supplement)","expr":"Reserve needed = known near-term payments − reliable matching inflows","meaning":"Xác định cash gap để tài trợ nghĩa vụ.","conditions":"Chỉ các dòng tiền tin cậy cùng thời điểm; buffer khác có thể cần thêm."},{"name":"After-tax income return (supplement)","expr":"r_after = r_before × (1 − tax rate)","meaning":"Minh họa income chịu thuế trực tiếp.","conditions":"Một kỳ, return hoàn toàn income chịu một mức thuế; không áp cho mixed gains/deferral."}],"examples":[{"question_en":"An employee holds substantial employer shares, faces a tuition bill in nine months and invests through a taxable account. Identify constraints.","steps_vi":["Tuition tạo liquidity/short horizon; taxable account tạo tax considerations.","Existing employer exposure là unique circumstance/concentration; cân nhắc income cũng phụ thuộc employer."],"answer":"Liquidity, horizon, tax and unique circumstances all matter.","check":"Original conceptual case; conclusions conditional on the stated facts."},{"question_en":"A client needs USD 65,000 in four months and has a reliable matching cash inflow of USD 18,000. The minimum remaining funding gap before any extra buffer is closest to:","steps_vi":["Lấy payment trừ inflow chắc chắn cùng thời điểm.","Thay số: 65000-18000.","Kết quả: 47,000.00 USD."],"answer":"47,000.00 USD","check":"Original supplemental practice; Decimal compared with an alternate expression using Fraction (square root uses float in the second method)."},{"question_en":"An investment pays a 6.5% income yield, fully taxable at a 24% rate, with no capital gain or other costs. After-tax return is closest to:","steps_vi":["Income yield trừ income tax, theo giả định một kỳ.","Thay số: 6.5 × (1-0.24).","Kết quả: 4.94%."],"answer":"4.94%","check":"Original supplemental practice; Decimal compared with an alternate expression using Fraction (square root uses float in the second method)."}],"questions":[{"stem_en":"A known tuition payment due in six months most directly creates a:","options":["long-term return guarantee.","liquidity constraint.","security selection benchmark."],"correct":1,"why_vi":"Xác định số tiền và thời điểm cần rút (tuition, healthcare, spending, claims). Phần tài sản đáp ứng obligation nên dễ chuyển thành tiền và ít risk tại lúc cần, có thể dùng securities đáo hạn phù hợp.","trap_vi":"Liquidity cao không đồng nghĩa market value chắc chắn tại mọi thời điểm."},{"stem_en":"An investor plans to retire in 20 years but needs a house deposit next year. The IPS should recognize:","options":["only the retirement date.","multiple relevant investment horizons.","no liquidity needs before retirement."],"correct":1,"why_vi":"Horizon là thời gian đầu tư trước khi cần sử dụng tài sản, có thể nhiều giai đoạn như tích lũy, nghỉ hưu và chuyển giao. Horizon dài có thể chịu volatility tạm thời tốt hơn, nhưng phải xét nghĩa vụ ngắn hạn bên trong.","trap_vi":"Không xem horizon dài là quyền bỏ qua liquidity."},{"stem_en":"For a taxable client, portfolio construction should primarily evaluate investments on an:","options":["assumed tax-free basis regardless of account.","identical gross return basis only.","appropriate after-tax basis."],"correct":2,"why_vi":"Tax status ảnh hưởng after-tax return, turnover, realized gains, income và account structure. Tax-deferred/exempt accounts có khác biệt; xác định quy định cụ thể trước khi so investment alternatives.","trap_vi":"Không giả định cùng tax rate cho mọi loại income."},{"stem_en":"A statutory ceiling on pension investments in a particular asset class is a:","options":["legal and regulatory constraint.","return objective.","historical volatility estimate."],"correct":0,"why_vi":"Restrictions có thể xuất phát từ luật đầu tư pension, insurance, trust documents hoặc hợp đồng; giới hạn asset classes, concentration, leverage hoặc fiduciary duties. Manager phải biết áp dụng đúng jurisdiction và loại client.","trap_vi":"Không vi phạm luật vì expected return cao."},{"stem_en":"An employee whose job and wealth depend heavily on one company should most directly consider:","options":["increasing the same stock solely for familiarity.","concentration arising from existing company exposure.","ignoring all assets outside the managed account."],"correct":1,"why_vi":"Client có thể có employer stock, family business, donor requirements, religious/ethical preferences hoặc restrictions riêng. Tài sản bên ngoài danh mục và nguồn thu cùng exposure cần được xét để giảm concentration.","trap_vi":"Không coi unique constraint là optional nếu đã được thỏa thuận."},{"stem_en":"Which is the most appropriate approach to a client's incompletely documented liquidity and tax situation?","options":["Assume no constraints unless losses occur","Use the same policy as another client of similar age","Obtain the necessary information before finalizing portfolio constraints"],"correct":2,"why_vi":"Constraints tương tác với nhau: cash need ảnh hưởng capacity, tax và legal giới hạn cách rebalance, unique preferences thu hẹp universe. Thu thập dữ liệu bằng trao đổi client, tài liệu tài sản và liabilities; cập nhật khi thay đổi.","trap_vi":"Không tự điền giả định thiếu dữ kiện vào IPS."},{"stem_en":"A client needs USD 65,000 in four months and has a reliable matching cash inflow of USD 18,000. The minimum remaining funding gap before any extra buffer is closest to:","options":["83,000.00 USD","18,000.00 USD","47,000.00 USD"],"correct":2,"why_vi":"Lấy payment trừ inflow chắc chắn cùng thời điểm. Thay số: 65000-18000 = 47,000.00 USD.","trap_vi":"Không tính inflow thành nghĩa vụ."},{"stem_en":"An investment pays a 6.5% income yield, fully taxable at a 24% rate, with no capital gain or other costs. After-tax return is closest to:","options":["1.56%","4.94%","6.50%"],"correct":1,"why_vi":"Income yield trừ income tax, theo giả định một kỳ. Thay số: 6.5 × (1-0.24) = 4.94%.","trap_vi":"Không lấy tax amount làm after-tax yield."}],"cards":[{"front_en":"Liquidity constraint","back_vi":"Xác định số tiền và thời điểm cần rút (tuition, healthcare, spending, claims). Phần tài sản đáp ứng obligation nên dễ chuyển thành tiền và ít risk tại lúc cần, có thể dùng securities đáo hạn phù hợp. | Exam trap: Liquidity cao không đồng nghĩa market value chắc chắn tại mọi thời điểm."},{"front_en":"Time horizon","back_vi":"Horizon là thời gian đầu tư trước khi cần sử dụng tài sản, có thể nhiều giai đoạn như tích lũy, nghỉ hưu và chuyển giao. Horizon dài có thể chịu volatility tạm thời tốt hơn, nhưng phải xét nghĩa vụ ngắn hạn bên trong. | Exam trap: Không xem horizon dài là quyền bỏ qua liquidity."},{"front_en":"Tax concerns","back_vi":"Tax status ảnh hưởng after-tax return, turnover, realized gains, income và account structure. Tax-deferred/exempt accounts có khác biệt; xác định quy định cụ thể trước khi so investment alternatives. | Exam trap: Không giả định cùng tax rate cho mọi loại income."},{"front_en":"Legal and regulatory","back_vi":"Restrictions có thể xuất phát từ luật đầu tư pension, insurance, trust documents hoặc hợp đồng; giới hạn asset classes, concentration, leverage hoặc fiduciary duties. Manager phải biết áp dụng đúng jurisdiction và loại client. | Exam trap: Không vi phạm luật vì expected return cao."},{"front_en":"Unique circumstances","back_vi":"Client có thể có employer stock, family business, donor requirements, religious/ethical preferences hoặc restrictions riêng. Tài sản bên ngoài danh mục và nguồn thu cùng exposure cần được xét để giảm concentration. | Exam trap: Không coi unique constraint là optional nếu đã được thỏa thuận."},{"front_en":"Interactions and information gathering","back_vi":"Constraints tương tác với nhau: cash need ảnh hưởng capacity, tax và legal giới hạn cách rebalance, unique preferences thu hẹp universe. Thu thập dữ liệu bằng trao đổi client, tài liệu tài sản và liabilities; cập nhật khi thay đổi. | Exam trap: Không tự điền giả định thiếu dữ kiện vào IPS."},{"front_en":"Constraint checklist — formula or framework?","back_vi":"Liquidity; time horizon; tax; legal/regulatory; unique circumstances · Đánh giá tác động của từng constraint tới feasible assets. · Framework; xác minh theo client/jurisdiction."},{"front_en":"Liquidity reserve (supplement) — formula or framework?","back_vi":"Reserve needed = known near-term payments − reliable matching inflows · Xác định cash gap để tài trợ nghĩa vụ. · Chỉ các dòng tiền tin cậy cùng thời điểm; buffer khác có thể cần thêm."},{"front_en":"After-tax income return (supplement) — formula or framework?","back_vi":"r_after = r_before × (1 − tax rate) · Minh họa income chịu thuế trực tiếp. · Một kỳ, return hoàn toàn income chịu một mức thuế; không áp cho mixed gains/deferral."},{"front_en":"A client needs USD 65,000 in four months and has a reliable matching cash inflow of USD 18,000. The minimum remaining funding gap before any extra buffer is closest to:","back_vi":"Lấy payment trừ inflow chắc chắn cùng thời điểm. Thay số: 65000-18000 = 47,000.00 USD. | Không tính inflow thành nghĩa vụ."},{"front_en":"An investment pays a 6.5% income yield, fully taxable at a 24% rate, with no capital gain or other costs. After-tax return is closest to:","back_vi":"Income yield trừ income tax, theo giả định một kỳ. Thay số: 6.5 × (1-0.24) = 4.94%. | Không lấy tax amount làm after-tax yield."}]},{"id":"CFA26-09-04-LOS06","letter":"f","title_en":"Specification of Asset Classes","outcome_en":"explain the specification of asset classes in relation to asset allocation","overview_vi":"Bài học 4.f: Specification of Asset Classes. Học bản chất khái niệm, điều kiện áp dụng, so sánh và giải quyết tình huống. Công thức ghi supplement là bài luyện thêm; câu hỏi tiếng Anh do dự án tự biên soạn.","source":[{"id":"CFA Institute Curriculum 2026 — Portfolio Management Volume 9","pages":"Physical PDF p. 169 (LOS), 189–192 (content)"},{"id":"Kaplan SchweserNotes 2026 — Book 4, Reading 86","pages":"Physical PDF pp. 121–123"},{"id":"SAPP CFA Level I 2026 — Portfolio Management slides","pages":"Physical PDF pp. 150–152"}],"sections":[{"heading":"Asset class definition","body":"Asset class là nhóm tài sản có risk–return characteristics tương đối đồng nhất, không phải tên một wrapper. Phân nhóm cổ phiếu/bond theo region, size, credit, currency hoặc duration giúp kiểm soát exposure cụ thể.","trap":"ETF là investment vehicle, có thể nắm nhiều lớp tài sản."},{"heading":"Homogeneity within class","body":"Các assets cùng class nên có risk/return drivers tương tự và tương quan nội nhóm tương đối cao. Nếu nhóm quá rộng, một manager có thể thay đổi allocation giữa các exposures mà policy không kiểm soát được.","trap":"Không yêu cầu correlation phải chính xác bằng 1."},{"heading":"Diversification across classes","body":"Giữa các asset classes, correlations nên thấp hơn tương quan trong class để tạo diversification. Không có yêu cầu mọi cross-class correlation phải âm. Capital market expectations cần ước tính cả covariance và volatility.","trap":"Không chọn nhóm chỉ vì stand-alone expected return cao."},{"heading":"Mutually exclusive categories","body":"Các nhóm phải tránh overlapping để mỗi exposure chỉ được tính một lần; cùng lúc phải bao quát đủ relevant investable universe. Multi-asset vehicle có thể cần look-through hoặc phân loại nhất quán.","trap":"Không cộng toàn bộ balanced fund vào cả stocks và bonds."},{"heading":"Granularity and delegation","body":"Chia fixed income thành sovereign, IG corporate, high yield, domestic/foreign; equity thành developed/emerging, small/large cap. Chi tiết giúp đặt limits/expectations nhưng đòi hỏi dữ liệu; nhóm rộng giao nhiều discretion cho manager.","trap":"Không giả định phân nhóm càng chi tiết càng tối ưu."},{"heading":"Investable universe and benchmark","body":"Asset class definitions cần phù hợp tài sản thực sự có thể đầu tư theo IPS, pháp lý và liquidity. Benchmark, expected return, volatility, correlations có thể ước tính nhất quán cùng currency và horizon. Không dùng mẫu dữ liệu cũ như quy luật vĩnh viễn.","trap":"Không đưa tài sản bị cấm vào tập feasible chỉ vì forecast cao."}],"formulas":[{"name":"Asset-class design","expr":"Homogeneity within + diversification across + mutual exclusivity + coverage of investable universe","meaning":"Xây phân nhóm đủ chi tiết để kiểm soát risk exposures.","conditions":"Framework; không cần correlations âm; tránh trùng holdings."},{"name":"Look-through exposure (supplement)","expr":"Effective class weight = direct weight + Σ fund weight × fund class weight","meaning":"Tính tổng exposure của asset class từ holdings gián tiếp.","conditions":"Cùng thời điểm, no leverage hoặc đã tính look-through leverage; không double count."}],"examples":[{"question_en":"A policy defines global equity, US equity, and a balanced fund as three non-overlapping classes. Is the design satisfactory?","steps_vi":["Global equity có thể bao gồm US equity; balanced fund có cả equity và bond exposures, nên nhóm không mutually exclusive.","Xác định class exposures theo geography và asset type; look through wrapper nếu cần."],"answer":"Redefine classes to avoid overlapping exposures.","check":"Original conceptual case; conclusions conditional on the stated facts."},{"question_en":"A portfolio allocates 30% directly to equities and 40% to a balanced fund holding 60% equities and 40% bonds. The remaining portfolio has no equity exposure. Total equity exposure is closest to:","steps_vi":["Look-through 40% × 60% cộng direct equity.","Thay số: 30+40 × 0.6.","Kết quả: 54.00%."],"answer":"54.00%","check":"Original supplemental practice; Decimal compared with an alternate expression using Fraction (square root uses float in the second method)."}],"questions":[{"stem_en":"Which pair most clearly represents different asset-class exposures rather than different vehicles?","options":["Two ETFs tracking the same equity index","Domestic government bonds and emerging-market equities","An ETF and a mutual fund tracking the same bond index"],"correct":1,"why_vi":"Asset class là nhóm tài sản có risk–return characteristics tương đối đồng nhất, không phải tên một wrapper. Phân nhóm cổ phiếu/bond theo region, size, credit, currency hoặc duration giúp kiểm soát exposure cụ thể.","trap_vi":"ETF là investment vehicle, có thể nắm nhiều lớp tài sản."},{"stem_en":"A well-specified asset class generally contains assets with:","options":["the lowest possible within-class correlations.","relatively similar risk and return characteristics.","no common economic exposures."],"correct":1,"why_vi":"Các assets cùng class nên có risk/return drivers tương tự và tương quan nội nhóm tương đối cao. Nếu nhóm quá rộng, một manager có thể thay đổi allocation giữa các exposures mà policy không kiểm soát được.","trap_vi":"Không yêu cầu correlation phải chính xác bằng 1."},{"stem_en":"Which characteristic most supports defining two separate asset classes?","options":["Meaningfully distinct risk-return behavior and diversification potential","Identical exposures and identical return series","Different fund names despite identical holdings"],"correct":0,"why_vi":"Giữa các asset classes, correlations nên thấp hơn tương quan trong class để tạo diversification. Không có yêu cầu mọi cross-class correlation phải âm. Capital market expectations cần ước tính cả covariance và volatility.","trap_vi":"Không chọn nhóm chỉ vì stand-alone expected return cao."},{"stem_en":"A policy classifies the entire same bond holding in two separate asset classes. Which criterion is violated?","options":["Mutual exclusivity","Within-class homogeneity only","The definition of inflation"],"correct":0,"why_vi":"Các nhóm phải tránh overlapping để mỗi exposure chỉ được tính một lần; cùng lúc phải bao quát đủ relevant investable universe. Multi-asset vehicle có thể cần look-through hoặc phân loại nhất quán.","trap_vi":"Không cộng toàn bộ balanced fund vào cả stocks và bonds."},{"stem_en":"Defining government and high-yield corporate bonds as separate classes primarily allows the investor to:","options":["eliminate bond market risk.","control their differing credit and risk-return exposures explicitly.","avoid estimating any return correlations."],"correct":1,"why_vi":"Chia fixed income thành sovereign, IG corporate, high yield, domestic/foreign; equity thành developed/emerging, small/large cap. Chi tiết giúp đặt limits/expectations nhưng đòi hỏi dữ liệu; nhóm rộng giao nhiều discretion cho manager.","trap_vi":"Không giả định phân nhóm càng chi tiết càng tối ưu."},{"stem_en":"Which is most appropriate when specifying classes for a restricted mandate?","options":["Include prohibited assets as mandatory exposures","Cover the relevant permitted investable universe without overlapping categories","Ignore correlations across classes"],"correct":1,"why_vi":"Asset class definitions cần phù hợp tài sản thực sự có thể đầu tư theo IPS, pháp lý và liquidity. Benchmark, expected return, volatility, correlations có thể ước tính nhất quán cùng currency và horizon. Không dùng mẫu dữ liệu cũ như quy luật vĩnh viễn.","trap_vi":"Không đưa tài sản bị cấm vào tập feasible chỉ vì forecast cao."},{"stem_en":"A portfolio allocates 30% directly to equities and 40% to a balanced fund holding 60% equities and 40% bonds. The remaining portfolio has no equity exposure. Total equity exposure is closest to:","options":["70.00%","90.00%","54.00%"],"correct":2,"why_vi":"Look-through 40% × 60% cộng direct equity. Thay số: 30+40 × 0.6 = 54.00%.","trap_vi":"Không tính toàn bộ fund là equity hoặc cộng fund internal weight trực tiếp."}],"cards":[{"front_en":"Asset class definition","back_vi":"Asset class là nhóm tài sản có risk–return characteristics tương đối đồng nhất, không phải tên một wrapper. Phân nhóm cổ phiếu/bond theo region, size, credit, currency hoặc duration giúp kiểm soát exposure cụ thể. | Exam trap: ETF là investment vehicle, có thể nắm nhiều lớp tài sản."},{"front_en":"Homogeneity within class","back_vi":"Các assets cùng class nên có risk/return drivers tương tự và tương quan nội nhóm tương đối cao. Nếu nhóm quá rộng, một manager có thể thay đổi allocation giữa các exposures mà policy không kiểm soát được. | Exam trap: Không yêu cầu correlation phải chính xác bằng 1."},{"front_en":"Diversification across classes","back_vi":"Giữa các asset classes, correlations nên thấp hơn tương quan trong class để tạo diversification. Không có yêu cầu mọi cross-class correlation phải âm. Capital market expectations cần ước tính cả covariance và volatility. | Exam trap: Không chọn nhóm chỉ vì stand-alone expected return cao."},{"front_en":"Mutually exclusive categories","back_vi":"Các nhóm phải tránh overlapping để mỗi exposure chỉ được tính một lần; cùng lúc phải bao quát đủ relevant investable universe. Multi-asset vehicle có thể cần look-through hoặc phân loại nhất quán. | Exam trap: Không cộng toàn bộ balanced fund vào cả stocks và bonds."},{"front_en":"Granularity and delegation","back_vi":"Chia fixed income thành sovereign, IG corporate, high yield, domestic/foreign; equity thành developed/emerging, small/large cap. Chi tiết giúp đặt limits/expectations nhưng đòi hỏi dữ liệu; nhóm rộng giao nhiều discretion cho manager. | Exam trap: Không giả định phân nhóm càng chi tiết càng tối ưu."},{"front_en":"Investable universe and benchmark","back_vi":"Asset class definitions cần phù hợp tài sản thực sự có thể đầu tư theo IPS, pháp lý và liquidity. Benchmark, expected return, volatility, correlations có thể ước tính nhất quán cùng currency và horizon. Không dùng mẫu dữ liệu cũ như quy luật vĩnh viễn. | Exam trap: Không đưa tài sản bị cấm vào tập feasible chỉ vì forecast cao."},{"front_en":"Asset-class design — formula or framework?","back_vi":"Homogeneity within + diversification across + mutual exclusivity + coverage of investable universe · Xây phân nhóm đủ chi tiết để kiểm soát risk exposures. · Framework; không cần correlations âm; tránh trùng holdings."},{"front_en":"Look-through exposure (supplement) — formula or framework?","back_vi":"Effective class weight = direct weight + Σ fund weight × fund class weight · Tính tổng exposure của asset class từ holdings gián tiếp. · Cùng thời điểm, no leverage hoặc đã tính look-through leverage; không double count."},{"front_en":"A portfolio allocates 30% directly to equities and 40% to a balanced fund holding 60% equities and 40% bonds. The remaining portfolio has no equity exposure. Total equity exposure is closest to:","back_vi":"Look-through 40% × 60% cộng direct equity. Thay số: 30+40 × 0.6 = 54.00%. | Không tính toàn bộ fund là equity hoặc cộng fund internal weight trực tiếp."}]},{"id":"CFA26-09-04-LOS07","letter":"g","title_en":"Portfolio Construction and Asset Allocation","outcome_en":"describe the principles of portfolio construction and the role of asset allocation in relation to the IPS","overview_vi":"Bài học 4.g: Portfolio Construction and Asset Allocation. Học bản chất khái niệm, điều kiện áp dụng, so sánh và giải quyết tình huống. Công thức ghi supplement là bài luyện thêm; câu hỏi tiếng Anh do dự án tự biên soạn.","source":[{"id":"CFA Institute Curriculum 2026 — Portfolio Management Volume 9","pages":"Physical PDF p. 169 (LOS), 188–201 (content)"},{"id":"Kaplan SchweserNotes 2026 — Book 4, Reading 86","pages":"Physical PDF pp. 123–124"},{"id":"SAPP CFA Level I 2026 — Portfolio Management slides","pages":"Physical PDF pp. 153–158"}],"sections":[{"heading":"SAA inputs","body":"Strategic asset allocation kết hợp client objectives/constraints trong IPS và long-term capital market expectations. Optimization hoặc simulation tạo policy portfolio weights. IPS và market expectations có thể có review cycles khác nhau.","trap":"Không suy SAA chỉ từ historical return ranking."},{"heading":"Feasible portfolios","body":"Risk và return objectives xác định vùng chấp nhận: ví dụ minimum expected return, maximum volatility, liquidity floor và permitted assets. Trong vùng khả thi chọn portfolio phù hợp client; efficient portfolio không phù hợp nếu vi phạm constraint.","trap":"Không chọn điểm efficient frontier nếu không đạt mục tiêu/ràng buộc."},{"heading":"Policy portfolio and benchmark","body":"SAA đặt long-term target weights và có thể hedge ratios; policy benchmark dùng indices đại diện asset classes theo weights. Actual portfolio mới là triển khai qua manager/vehicle/security. Policy return là chuẩn so sánh, không phải return bảo đảm.","trap":"Không nhầm policy weights với actual drifted weights."},{"heading":"Risk budgeting","body":"Risk budgeting xác định tổng risk phù hợp IPS và chia cho sources như SAA, tactical allocation và security selection. Risk contribution không bằng capital allocation khi assets khác volatility/correlation; thêm active risk cần giới hạn và payoff mong đợi.","trap":"Không chia đều vốn rồi gọi là chia đều risk."},{"heading":"Tactical allocation","body":"TAA chủ động lệch policy weights dựa forecast near-term để tìm added value. Khác drift do các asset returns không giống nhau. Tactical deviations có risk và phải nằm trong risk budget/limits.","trap":"Drift không phải tự động là TAA."},{"heading":"Security selection and implementation","body":"Security selection chọn chứng khoán nhằm vượt asset-class benchmark; active/passive quyết định theo skill, informational efficiency, costs và vehicle. Nonlisted infrastructure/real estate khó có broad passive exposure và thường cần selection.","trap":"Không mặc định active luôn vượt benchmark."},{"heading":"Weight drift and rebalancing","body":"Returns khác nhau làm actual weights lệch target ngay cả không trade. Corridors đặt upper/lower limits; khi vượt giới hạn có thể chuyển funds về target hoặc vùng cho phép theo policy. Xét cash flows, cost, tax và risk.","trap":"Không dùng ending weight để tính period return nếu không điều chỉnh dòng tiền."},{"heading":"TAA contribution","body":"Trong ví dụ đơn giản một kỳ không dòng tiền, TAA contribution bằng tổng (actual beginning weight − policy weight) × asset-class benchmark return. Security selection là nguồn khác; có thể tách theo convention attribution. Không nhân ending deviations với return đã xảy ra.","trap":"Không nhầm active weight với actual weight."},{"heading":"Risk parity and estimation risk","body":"MPT-based weights nhạy forecast returns, correlations và volatilities. Risk parity phân bổ theo risk contribution thay vì chỉ theo capital weights; có thể cần leverage tùy target. Không bảo đảm outperform; cần kiểm tra sensitivity, correlation regime và constraints.","trap":"Risk parity không phải equal capital allocation."}],"formulas":[{"name":"SAA process","expr":"IPS objectives/constraints + capital market expectations → optimization/simulation → policy portfolio","meaning":"Mục tiêu, constraint và expectations quyết định strategic weights.","conditions":"Framework; actual portfolio là bước implementation sau."},{"name":"Policy return","expr":"Rb = Σ wi,policy Ri","meaning":"Return của policy portfolio theo benchmark từng class.","conditions":"Beginning weights và returns cùng kỳ; không flows hoặc đã xử lý đúng."},{"name":"Ending asset weight","expr":"wi,end = wi,start(1+Ri)/(1+Rp)","meaning":"Đo drift sau returns khác nhau.","conditions":"Không trade/cash flow trong kỳ; denominators dương."},{"name":"Rebalancing trade","expr":"Trade = target weight × current portfolio value − current asset value","meaning":"Dương: buy; âm: sell để về target.","conditions":"Bỏ phí/thuế, giá cố định; nếu policy chỉ yêu cầu corridor thì có thể về band thay target."},{"name":"Simple TAA contribution","expr":"Σ (wi,actual,start − wi,policy) Ri,benchmark","meaning":"Đo allocation effect trong ví dụ một kỳ.","conditions":"Cùng asset-class benchmark returns, no interim flows; không phải full attribution."},{"name":"Risk budgeting framework","expr":"Total risk → policy exposures + tactical allocation + security selection","meaning":"Chia risk budget cho các sources of return; risk contribution không phải capital weight.","conditions":"Framework; risk contributions phụ thuộc model và correlations."}],"examples":[{"question_en":"Policy equity weight is 55% with a ±5 percentage point corridor. Strong equity gains lift actual weight to 63%. The manager made no active trades. Explain.","steps_vi":["Weight 63% vượt upper band 60%; nguyên nhân ban đầu là drift, không phải tactical decision.","Kiểm tra policy về rebalance, chuyển phần phù hợp từ equity sang assets thiếu weight, tính chi phí; nếu cố giữ overweight thì đó có thể thành tactical decision."],"answer":"Review and rebalance under the agreed policy; distinguish drift from deliberate TAA.","check":"Original conceptual case; conclusions conditional on the stated facts."},{"question_en":"A policy portfolio starts the year at 55% equities, 35% bonds and 10% cash. Their returns are 12%, 4% and 2%, respectively. Policy return is closest to:","steps_vi":["Tính weighted returns bằng beginning policy weights.","Thay số: 0.55 × 12+0.35 × 4+0.10 × 2.","Kết quả: 8.20%."],"answer":"8.20%","check":"Original supplemental practice; Decimal compared with an alternate expression using Fraction (square root uses float in the second method)."},{"question_en":"A portfolio begins with 60% stocks and 40% bonds. Stocks return 20% and bonds 0%; no trades or flows occur. The ending stock weight is closest to:","steps_vi":["Ending equity value 72, total 112, chia hai giá trị.","Thay số: 60 × 1.2/(60 × 1.2+40) × 100.","Kết quả: 64.29%."],"answer":"64.29%","check":"Original supplemental practice; Decimal compared with an alternate expression using Fraction (square root uses float in the second method)."},{"question_en":"A USD 2 million portfolio has USD 1.28 million of equities. Its equity target is 55%, with no trading costs. The signed equity trade (positive for a purchase, negative for a sale) to restore the target is closest to:","steps_vi":["Target equity value trừ current equity value; âm là sale.","Thay số: 2000000 × 0.55-1280000.","Kết quả: -180,000.00 USD."],"answer":"-180,000.00 USD","check":"Original supplemental practice; Decimal compared with an alternate expression using Fraction (square root uses float in the second method)."},{"question_en":"A two-asset policy is 50% equities and 50% bonds; actual beginning weights are 60% equities and 40% bonds. Benchmark returns are 9% and 3%. The simple tactical allocation contribution is closest to:","steps_vi":["Active weights nhân benchmark returns và cộng.","Thay số: (0.6-0.5) × 9+(0.4-0.5) × 3.","Kết quả: 0.60 percentage points."],"answer":"0.60 percentage points","check":"Original supplemental practice; Decimal compared with an alternate expression using Fraction (square root uses float in the second method)."},{"question_en":"A policy equity weight is 40% with a corridor of ±3 percentage points. The upper limit is closest to:","steps_vi":["Corridor additive theo percentage points.","Thay số: 40+3.","Kết quả: 43.00%."],"answer":"43.00%","check":"Original supplemental practice; Decimal compared with an alternate expression using Fraction (square root uses float in the second method)."}],"questions":[{"stem_en":"Strategic asset allocation is primarily derived by combining:","options":["the IPS and long-term capital market expectations.","the latest list of outperforming stocks only.","the manager's personal preferences and commission rate."],"correct":0,"why_vi":"Strategic asset allocation kết hợp client objectives/constraints trong IPS và long-term capital market expectations. Optimization hoặc simulation tạo policy portfolio weights. IPS và market expectations có thể có review cycles khác nhau.","trap_vi":"Không suy SAA chỉ từ historical return ranking."},{"stem_en":"A portfolio lies on the efficient frontier but violates the client's legal restriction. It is:","options":["infeasible for that client.","automatically suitable because it is efficient.","required by modern portfolio theory."],"correct":0,"why_vi":"Risk và return objectives xác định vùng chấp nhận: ví dụ minimum expected return, maximum volatility, liquidity floor và permitted assets. Trong vùng khả thi chọn portfolio phù hợp client; efficient portfolio không phù hợp nếu vi phạm constraint.","trap_vi":"Không chọn điểm efficient frontier nếu không đạt mục tiêu/ràng buộc."},{"stem_en":"Which portfolio most directly represents the strategic asset allocation?","options":["The policy portfolio with long-term target asset-class weights","The actual portfolio after an unplanned market drift","A list of the latest stock trades"],"correct":0,"why_vi":"SAA đặt long-term target weights và có thể hedge ratios; policy benchmark dùng indices đại diện asset classes theo weights. Actual portfolio mới là triển khai qua manager/vehicle/security. Policy return là chuẩn so sánh, không phải return bảo đảm.","trap_vi":"Không nhầm policy weights với actual drifted weights."},{"stem_en":"Risk budgeting in portfolio construction primarily involves:","options":["equalizing the number of securities in each fund.","allocating an overall acceptable risk budget among sources of return.","guaranteeing a fixed annual return."],"correct":1,"why_vi":"Risk budgeting xác định tổng risk phù hợp IPS và chia cho sources như SAA, tactical allocation và security selection. Risk contribution không bằng capital allocation khi assets khác volatility/correlation; thêm active risk cần giới hạn và payoff mong đợi.","trap_vi":"Không chia đều vốn rồi gọi là chia đều risk."},{"stem_en":"A deliberate temporary equity overweight based on a short-term forecast is:","options":["passive weight drift.","a change in the client's legal status.","tactical asset allocation."],"correct":2,"why_vi":"TAA chủ động lệch policy weights dựa forecast near-term để tìm added value. Khác drift do các asset returns không giống nhau. Tactical deviations có risk và phải nằm trong risk budget/limits.","trap_vi":"Drift không phải tự động là TAA."},{"stem_en":"Buying a particular stock above its benchmark weight because it is believed undervalued is primarily:","options":["strategic allocation between equities and bonds.","security selection.","an automatic rebalancing event."],"correct":1,"why_vi":"Security selection chọn chứng khoán nhằm vượt asset-class benchmark; active/passive quyết định theo skill, informational efficiency, costs và vehicle. Nonlisted infrastructure/real estate khó có broad passive exposure và thường cần selection.","trap_vi":"Không mặc định active luôn vượt benchmark."},{"stem_en":"A stock allocation rises above its policy corridor solely because stocks outperformed bonds. The initial deviation is:","options":["a deliberate tactical decision.","a change in the return objective.","weight drift."],"correct":2,"why_vi":"Returns khác nhau làm actual weights lệch target ngay cả không trade. Corridors đặt upper/lower limits; khi vượt giới hạn có thể chuyển funds về target hoặc vùng cho phép theo policy. Xét cash flows, cost, tax và risk.","trap_vi":"Không dùng ending weight để tính period return nếu không điều chỉnh dòng tiền."},{"stem_en":"For a simple one-period allocation effect, the relevant weight difference is between:","options":["beginning actual and policy asset-class weights.","ending asset prices and beginning NAV per share.","two unrelated portfolio benchmarks."],"correct":0,"why_vi":"Trong ví dụ đơn giản một kỳ không dòng tiền, TAA contribution bằng tổng (actual beginning weight − policy weight) × asset-class benchmark return. Security selection là nguồn khác; có thể tách theo convention attribution. Không nhân ending deviations với return đã xảy ra.","trap_vi":"Không nhầm active weight với actual weight."},{"stem_en":"Risk parity investing most directly seeks to allocate assets according to:","options":["equal dollar allocations regardless of volatility.","the highest past return only.","risk contributions."],"correct":2,"why_vi":"MPT-based weights nhạy forecast returns, correlations và volatilities. Risk parity phân bổ theo risk contribution thay vì chỉ theo capital weights; có thể cần leverage tùy target. Không bảo đảm outperform; cần kiểm tra sensitivity, correlation regime và constraints.","trap_vi":"Risk parity không phải equal capital allocation."},{"stem_en":"A policy portfolio starts the year at 55% equities, 35% bonds and 10% cash. Their returns are 12%, 4% and 2%, respectively. Policy return is closest to:","options":["6.00%","8.20%","8.40%"],"correct":1,"why_vi":"Tính weighted returns bằng beginning policy weights. Thay số: 0.55 × 12+0.35 × 4+0.10 × 2 = 8.20%.","trap_vi":"Không lấy equal weight hoặc nhập cash vào bonds."},{"stem_en":"A portfolio begins with 60% stocks and 40% bonds. Stocks return 20% and bonds 0%; no trades or flows occur. The ending stock weight is closest to:","options":["72.00%","60.00%","64.29%"],"correct":2,"why_vi":"Ending equity value 72, total 112, chia hai giá trị. Thay số: 60 × 1.2/(60 × 1.2+40) × 100 = 64.29%.","trap_vi":"Không dùng ending asset value như weight hoặc giữ beginning weight."},{"stem_en":"A USD 2 million portfolio has USD 1.28 million of equities. Its equity target is 55%, with no trading costs. The signed equity trade (positive for a purchase, negative for a sale) to restore the target is closest to:","options":["180,000.00 USD","1,100,000.00 USD","-180,000.00 USD"],"correct":2,"why_vi":"Target equity value trừ current equity value; âm là sale. Thay số: 2000000 × 0.55-1280000 = -180,000.00 USD.","trap_vi":"Phân biệt trade signed với target holding hoặc sale magnitude."},{"stem_en":"A two-asset policy is 50% equities and 50% bonds; actual beginning weights are 60% equities and 40% bonds. Benchmark returns are 9% and 3%. The simple tactical allocation contribution is closest to:","options":["0.90 percentage points","0.60 percentage points","6.60 percentage points"],"correct":1,"why_vi":"Active weights nhân benchmark returns và cộng. Thay số: (0.6-0.5) × 9+(0.4-0.5) × 3 = 0.60 percentage points.","trap_vi":"Không bỏ underweight bonds hoặc lấy total return."},{"stem_en":"A policy equity weight is 40% with a corridor of ±3 percentage points. The upper limit is closest to:","options":["43.00%","41.20%","37.00%"],"correct":0,"why_vi":"Corridor additive theo percentage points. Thay số: 40+3 = 43.00%.","trap_vi":"Không nhân 3% hoặc dùng lower limit."}],"cards":[{"front_en":"SAA inputs","back_vi":"Strategic asset allocation kết hợp client objectives/constraints trong IPS và long-term capital market expectations. Optimization hoặc simulation tạo policy portfolio weights. IPS và market expectations có thể có review cycles khác nhau. | Exam trap: Không suy SAA chỉ từ historical return ranking."},{"front_en":"Feasible portfolios","back_vi":"Risk và return objectives xác định vùng chấp nhận: ví dụ minimum expected return, maximum volatility, liquidity floor và permitted assets. Trong vùng khả thi chọn portfolio phù hợp client; efficient portfolio không phù hợp nếu vi phạm constraint. | Exam trap: Không chọn điểm efficient frontier nếu không đạt mục tiêu/ràng buộc."},{"front_en":"Policy portfolio and benchmark","back_vi":"SAA đặt long-term target weights và có thể hedge ratios; policy benchmark dùng indices đại diện asset classes theo weights. Actual portfolio mới là triển khai qua manager/vehicle/security. Policy return là chuẩn so sánh, không phải return bảo đảm. | Exam trap: Không nhầm policy weights với actual drifted weights."},{"front_en":"Risk budgeting","back_vi":"Risk budgeting xác định tổng risk phù hợp IPS và chia cho sources như SAA, tactical allocation và security selection. Risk contribution không bằng capital allocation khi assets khác volatility/correlation; thêm active risk cần giới hạn và payoff mong đợi. | Exam trap: Không chia đều vốn rồi gọi là chia đều risk."},{"front_en":"Tactical allocation","back_vi":"TAA chủ động lệch policy weights dựa forecast near-term để tìm added value. Khác drift do các asset returns không giống nhau. Tactical deviations có risk và phải nằm trong risk budget/limits. | Exam trap: Drift không phải tự động là TAA."},{"front_en":"Security selection and implementation","back_vi":"Security selection chọn chứng khoán nhằm vượt asset-class benchmark; active/passive quyết định theo skill, informational efficiency, costs và vehicle. Nonlisted infrastructure/real estate khó có broad passive exposure và thường cần selection. | Exam trap: Không mặc định active luôn vượt benchmark."},{"front_en":"Weight drift and rebalancing","back_vi":"Returns khác nhau làm actual weights lệch target ngay cả không trade. Corridors đặt upper/lower limits; khi vượt giới hạn có thể chuyển funds về target hoặc vùng cho phép theo policy. Xét cash flows, cost, tax và risk. | Exam trap: Không dùng ending weight để tính period return nếu không điều chỉnh dòng tiền."},{"front_en":"TAA contribution","back_vi":"Trong ví dụ đơn giản một kỳ không dòng tiền, TAA contribution bằng tổng (actual beginning weight − policy weight) × asset-class benchmark return. Security selection là nguồn khác; có thể tách theo convention attribution. Không nhân ending deviations với return đã xảy ra. | Exam trap: Không nhầm active weight với actual weight."},{"front_en":"Risk parity and estimation risk","back_vi":"MPT-based weights nhạy forecast returns, correlations và volatilities. Risk parity phân bổ theo risk contribution thay vì chỉ theo capital weights; có thể cần leverage tùy target. Không bảo đảm outperform; cần kiểm tra sensitivity, correlation regime và constraints. | Exam trap: Risk parity không phải equal capital allocation."},{"front_en":"SAA process — formula or framework?","back_vi":"IPS objectives/constraints + capital market expectations → optimization/simulation → policy portfolio · Mục tiêu, constraint và expectations quyết định strategic weights. · Framework; actual portfolio là bước implementation sau."},{"front_en":"Policy return — formula or framework?","back_vi":"Rb = Σ wi,policy Ri · Return của policy portfolio theo benchmark từng class. · Beginning weights và returns cùng kỳ; không flows hoặc đã xử lý đúng."},{"front_en":"Ending asset weight — formula or framework?","back_vi":"wi,end = wi,start(1+Ri)/(1+Rp) · Đo drift sau returns khác nhau. · Không trade/cash flow trong kỳ; denominators dương."},{"front_en":"Rebalancing trade — formula or framework?","back_vi":"Trade = target weight × current portfolio value − current asset value · Dương: buy; âm: sell để về target. · Bỏ phí/thuế, giá cố định; nếu policy chỉ yêu cầu corridor thì có thể về band thay target."},{"front_en":"Simple TAA contribution — formula or framework?","back_vi":"Σ (wi,actual,start − wi,policy) Ri,benchmark · Đo allocation effect trong ví dụ một kỳ. · Cùng asset-class benchmark returns, no interim flows; không phải full attribution."},{"front_en":"Risk budgeting framework — formula or framework?","back_vi":"Total risk → policy exposures + tactical allocation + security selection · Chia risk budget cho các sources of return; risk contribution không phải capital weight. · Framework; risk contributions phụ thuộc model và correlations."},{"front_en":"A policy portfolio starts the year at 55% equities, 35% bonds and 10% cash. Their returns are 12%, 4% and 2%, respectively. Policy return is closest to:","back_vi":"Tính weighted returns bằng beginning policy weights. Thay số: 0.55 × 12+0.35 × 4+0.10 × 2 = 8.20%. | Không lấy equal weight hoặc nhập cash vào bonds."},{"front_en":"A portfolio begins with 60% stocks and 40% bonds. Stocks return 20% and bonds 0%; no trades or flows occur. The ending stock weight is closest to:","back_vi":"Ending equity value 72, total 112, chia hai giá trị. Thay số: 60 × 1.2/(60 × 1.2+40) × 100 = 64.29%. | Không dùng ending asset value như weight hoặc giữ beginning weight."},{"front_en":"A USD 2 million portfolio has USD 1.28 million of equities. Its equity target is 55%, with no trading costs. The signed equity trade (positive for a purchase, negative for a sale) to restore the target is closest to:","back_vi":"Target equity value trừ current equity value; âm là sale. Thay số: 2000000 × 0.55-1280000 = -180,000.00 USD. | Phân biệt trade signed với target holding hoặc sale magnitude."},{"front_en":"A two-asset policy is 50% equities and 50% bonds; actual beginning weights are 60% equities and 40% bonds. Benchmark returns are 9% and 3%. The simple tactical allocation contribution is closest to:","back_vi":"Active weights nhân benchmark returns và cộng. Thay số: (0.6-0.5) × 9+(0.4-0.5) × 3 = 0.60 percentage points. | Không bỏ underweight bonds hoặc lấy total return."},{"front_en":"A policy equity weight is 40% with a corridor of ±3 percentage points. The upper limit is closest to:","back_vi":"Corridor additive theo percentage points. Thay số: 40+3 = 43.00%. | Không nhân 3% hoặc dùng lower limit."}]},{"id":"CFA26-09-04-LOS08","letter":"h","title_en":"ESG in Portfolio Planning and Construction","outcome_en":"describe how environmental, social, and governance (ESG) considerations may be integrated into portfolio planning and construction","overview_vi":"Bài học 4.h: ESG in Portfolio Planning and Construction. Học bản chất khái niệm, điều kiện áp dụng, so sánh và giải quyết tình huống. Công thức ghi supplement là bài luyện thêm; câu hỏi tiếng Anh do dự án tự biên soạn.","source":[{"id":"CFA Institute Curriculum 2026 — Portfolio Management Volume 9","pages":"Physical PDF p. 169 (LOS), 183–185,201–205 (content)"},{"id":"Kaplan SchweserNotes 2026 — Book 4, Reading 86","pages":"Physical PDF pp. 124–126"},{"id":"SAPP CFA Level I 2026 — Portfolio Management slides","pages":"Physical PDF pp. 145–149"}],"sections":[{"heading":"Material ESG integration","body":"ESG integration xem xét material environmental, social, governance factors trong security analysis, cash-flow forecast, discount rate, scenario và portfolio construction. Ví dụ emissions regulation tăng chi phí, labor safety tác động operating risk, governance ảnh hưởng capital allocation.","trap":"Không coi ESG integration bắt buộc loại mọi công ty điểm thấp."},{"heading":"Negative screening","body":"Negative/exclusionary screening loại industries, companies hoặc practices không phù hợp mandate. Hạn chế universe có thể thay đổi diversification, benchmark, costs và tracking error. Không bảo đảm alpha dương.","trap":"Không nhầm loại trừ với best-in-class."},{"heading":"Positive screening","body":"Positive screening chọn issuers/industries đáp ứng criteria ESG, best-in-class thường so với peers. Có thể vẫn đầu tư một công ty thuộc ngành nhiều emissions nếu tương đối tốt và phù hợp policy.","trap":"Không mặc định best-in-class là loại trừ toàn bộ ngành."},{"heading":"Thematic investing","body":"Thematic investing chọn theme liên quan ESG như renewable energy hoặc water efficiency. Theme allocation có thể tăng concentration/factor exposure; cần đánh giá toàn portfolio và chọn specialist managers khi phù hợp.","trap":"Theme label không chứng minh measurable impact."},{"heading":"Engagement and active ownership","body":"Shareholders dùng quyền biểu quyết, đối thoại, proxy instructions và collaborative engagement để tác động behavior doanh nghiệp. Client có thể giao manager hoặc proxy agent thực hiện theo stewardship policy.","trap":"Không nhầm engagement với bán toàn bộ cổ phiếu ngay lập tức."},{"heading":"Impact investing","body":"Impact investing có intention tạo positive environmental/social impact cùng financial return; cần mục tiêu, indicators và theo dõi kết quả. Khác thematic chỉ tập trung chủ đề và integration chỉ đưa material factors vào risk/return analysis.","trap":"Không gọi mọi quỹ ESG là impact fund."},{"heading":"Implementation and reporting","body":"IPS có thể quy định exclusions, preferred themes, stewardship, materiality, metrics và reporting. Kiểm tra quality của data, disclosure, methodology và trade-offs. ESG approaches có thể áp dụng nhiều asset classes, không chỉ equities.","trap":"Không coi ESG score của các providers là tương đương tuyệt đối."},{"heading":"Return impact and uncertainty","body":"Curriculum ghi nhận nghiên cứu về ESG và portfolio returns còn mixed. Chi phí và hạn chế universe có thể giảm cơ hội, trong khi tránh material risks và governance tốt có thể hỗ trợ returns. Không khẳng định causal outperformance hoặc universal risk reduction.","trap":"Không hứa ESG chắc chắn tăng return."}],"formulas":[{"name":"ESG approach selection","expr":"Negative / positive screening; integration; thematic; engagement; impact","meaning":"Phân loại theo hành động và intention; có thể kết hợp.","conditions":"Framework; không coi mọi approach bảo đảm outperformance."},{"name":"Scenario-weighted value (supplement)","expr":"Expected scenario value = Σ probability × scenario value","meaning":"Minh họa ESG risk ảnh hưởng xác suất và valuation assumptions.","conditions":"Probabilities sum to 1; cùng valuation date; không thay DCF nếu thiếu assumptions."}],"examples":[{"question_en":"A fund excludes tobacco, models carbon costs in valuation, and votes to improve directors' oversight. Classify the approaches.","steps_vi":["Excluding tobacco là negative screening; carbon costs vào valuation là ESG integration.","Voting là engagement/active ownership; có thể dùng đồng thời, không phải impact mặc nhiên."],"answer":"Negative screening, ESG integration, and active ownership.","check":"Original conceptual case; conclusions conditional on the stated facts."},{"question_en":"An analyst assigns a 30% probability to a downside ESG scenario valued at USD 60 and 70% to a base scenario valued at USD 100. The probability-weighted value is closest to:","steps_vi":["Tính expected scenario value theo probabilities đã cho.","Thay số: 0.3 × 60+0.7 × 100.","Kết quả: 88.00 USD."],"answer":"88.00 USD","check":"Original supplemental practice; Decimal compared with an alternate expression using Fraction (square root uses float in the second method)."},{"question_en":"A company's expected annual operating cash flow is USD 50 million before a new carbon-related cost of USD 6 million. Under this simplified scenario with no offsetting changes, revised operating cash flow is closest to:","steps_vi":["Material carbon cost làm giảm cash flow theo giả định.","Thay số: 50-6.","Kết quả: 44.00 USD million."],"answer":"44.00 USD million","check":"Original supplemental practice; Decimal compared with an alternate expression using Fraction (square root uses float in the second method)."}],"questions":[{"stem_en":"An analyst changes a company's forecast cash flows to reflect material climate-related costs. This is most consistent with:","options":["ESG integration.","pure negative screening.","proxy voting alone."],"correct":0,"why_vi":"ESG integration xem xét material environmental, social, governance factors trong security analysis, cash-flow forecast, discount rate, scenario và portfolio construction. Ví dụ emissions regulation tăng chi phí, labor safety tác động operating risk, governance ảnh hưởng capital allocation.","trap_vi":"Không coi ESG integration bắt buộc loại mọi công ty điểm thấp."},{"stem_en":"A client prohibits all tobacco producers from the portfolio. The approach is:","options":["positive screening.","negative screening.","shareholder engagement."],"correct":1,"why_vi":"Negative/exclusionary screening loại industries, companies hoặc practices không phù hợp mandate. Hạn chế universe có thể thay đổi diversification, benchmark, costs và tracking error. Không bảo đảm alpha dương.","trap_vi":"Không nhầm loại trừ với best-in-class."},{"stem_en":"Selecting the highest-rated ESG issuers within each permitted industry is an example of:","options":["positive screening.","negative screening of the entire market.","passive rebalancing only."],"correct":0,"why_vi":"Positive screening chọn issuers/industries đáp ứng criteria ESG, best-in-class thường so với peers. Có thể vẫn đầu tư một công ty thuộc ngành nhiều emissions nếu tương đối tốt và phù hợp policy.","trap_vi":"Không mặc định best-in-class là loại trừ toàn bộ ngành."},{"stem_en":"A portfolio dedicated to companies providing water-efficiency technologies is most directly an example of:","options":["an absolute risk objective.","thematic investing.","a pension funding formula."],"correct":1,"why_vi":"Thematic investing chọn theme liên quan ESG như renewable energy hoặc water efficiency. Theme allocation có thể tăng concentration/factor exposure; cần đánh giá toàn portfolio và chọn specialist managers khi phù hợp.","trap_vi":"Theme label không chứng minh measurable impact."},{"stem_en":"Voting at shareholder meetings to improve board oversight is most consistent with:","options":["negative screening.","active ownership.","a money market strategy."],"correct":1,"why_vi":"Shareholders dùng quyền biểu quyết, đối thoại, proxy instructions và collaborative engagement để tác động behavior doanh nghiệp. Client có thể giao manager hoặc proxy agent thực hiện theo stewardship policy.","trap_vi":"Không nhầm engagement với bán toàn bộ cổ phiếu ngay lập tức."},{"stem_en":"An investment selected specifically to generate measurable social benefits alongside financial returns is most consistent with:","options":["impact investing.","benchmark tracking alone.","a closed-end fund discount strategy."],"correct":0,"why_vi":"Impact investing có intention tạo positive environmental/social impact cùng financial return; cần mục tiêu, indicators và theo dõi kết quả. Khác thematic chỉ tập trung chủ đề và integration chỉ đưa material factors vào risk/return analysis.","trap_vi":"Không gọi mọi quỹ ESG là impact fund."},{"stem_en":"Which is most appropriate when implementing a client-specific ESG mandate?","options":["Rely solely on a fund's marketing label","Document the restrictions, implementation approach and monitoring measures","Assume ESG scores from all vendors are identical"],"correct":1,"why_vi":"IPS có thể quy định exclusions, preferred themes, stewardship, materiality, metrics và reporting. Kiểm tra quality của data, disclosure, methodology và trade-offs. ESG approaches có thể áp dụng nhiều asset classes, không chỉ equities.","trap_vi":"Không coi ESG score của các providers là tương đương tuyệt đối."},{"stem_en":"The effect of ESG approaches on investment returns is most accurately described as:","options":["dependent on implementation and materiality, with mixed empirical evidence.","always positive regardless of costs.","always negative regardless of risk reduction."],"correct":0,"why_vi":"Curriculum ghi nhận nghiên cứu về ESG và portfolio returns còn mixed. Chi phí và hạn chế universe có thể giảm cơ hội, trong khi tránh material risks và governance tốt có thể hỗ trợ returns. Không khẳng định causal outperformance hoặc universal risk reduction.","trap_vi":"Không hứa ESG chắc chắn tăng return."},{"stem_en":"An analyst assigns a 30% probability to a downside ESG scenario valued at USD 60 and 70% to a base scenario valued at USD 100. The probability-weighted value is closest to:","options":["80.00 USD","88.00 USD","72.00 USD"],"correct":1,"why_vi":"Tính expected scenario value theo probabilities đã cho. Thay số: 0.3 × 60+0.7 × 100 = 88.00 USD.","trap_vi":"Không lấy simple average hoặc đảo probabilities."},{"stem_en":"A company's expected annual operating cash flow is USD 50 million before a new carbon-related cost of USD 6 million. Under this simplified scenario with no offsetting changes, revised operating cash flow is closest to:","options":["56.00 USD million","6.00 USD million","44.00 USD million"],"correct":2,"why_vi":"Material carbon cost làm giảm cash flow theo giả định. Thay số: 50-6 = 44.00 USD million.","trap_vi":"Không cộng chi phí hoặc nhầm cost với net cash flow."}],"cards":[{"front_en":"Material ESG integration","back_vi":"ESG integration xem xét material environmental, social, governance factors trong security analysis, cash-flow forecast, discount rate, scenario và portfolio construction. Ví dụ emissions regulation tăng chi phí, labor safety tác động operating risk, governance ảnh hưởng capital allocation. | Exam trap: Không coi ESG integration bắt buộc loại mọi công ty điểm thấp."},{"front_en":"Negative screening","back_vi":"Negative/exclusionary screening loại industries, companies hoặc practices không phù hợp mandate. Hạn chế universe có thể thay đổi diversification, benchmark, costs và tracking error. Không bảo đảm alpha dương. | Exam trap: Không nhầm loại trừ với best-in-class."},{"front_en":"Positive screening","back_vi":"Positive screening chọn issuers/industries đáp ứng criteria ESG, best-in-class thường so với peers. Có thể vẫn đầu tư một công ty thuộc ngành nhiều emissions nếu tương đối tốt và phù hợp policy. | Exam trap: Không mặc định best-in-class là loại trừ toàn bộ ngành."},{"front_en":"Thematic investing","back_vi":"Thematic investing chọn theme liên quan ESG như renewable energy hoặc water efficiency. Theme allocation có thể tăng concentration/factor exposure; cần đánh giá toàn portfolio và chọn specialist managers khi phù hợp. | Exam trap: Theme label không chứng minh measurable impact."},{"front_en":"Engagement and active ownership","back_vi":"Shareholders dùng quyền biểu quyết, đối thoại, proxy instructions và collaborative engagement để tác động behavior doanh nghiệp. Client có thể giao manager hoặc proxy agent thực hiện theo stewardship policy. | Exam trap: Không nhầm engagement với bán toàn bộ cổ phiếu ngay lập tức."},{"front_en":"Impact investing","back_vi":"Impact investing có intention tạo positive environmental/social impact cùng financial return; cần mục tiêu, indicators và theo dõi kết quả. Khác thematic chỉ tập trung chủ đề và integration chỉ đưa material factors vào risk/return analysis. | Exam trap: Không gọi mọi quỹ ESG là impact fund."},{"front_en":"Implementation and reporting","back_vi":"IPS có thể quy định exclusions, preferred themes, stewardship, materiality, metrics và reporting. Kiểm tra quality của data, disclosure, methodology và trade-offs. ESG approaches có thể áp dụng nhiều asset classes, không chỉ equities. | Exam trap: Không coi ESG score của các providers là tương đương tuyệt đối."},{"front_en":"Return impact and uncertainty","back_vi":"Curriculum ghi nhận nghiên cứu về ESG và portfolio returns còn mixed. Chi phí và hạn chế universe có thể giảm cơ hội, trong khi tránh material risks và governance tốt có thể hỗ trợ returns. Không khẳng định causal outperformance hoặc universal risk reduction. | Exam trap: Không hứa ESG chắc chắn tăng return."},{"front_en":"ESG approach selection — formula or framework?","back_vi":"Negative / positive screening; integration; thematic; engagement; impact · Phân loại theo hành động và intention; có thể kết hợp. · Framework; không coi mọi approach bảo đảm outperformance."},{"front_en":"Scenario-weighted value (supplement) — formula or framework?","back_vi":"Expected scenario value = Σ probability × scenario value · Minh họa ESG risk ảnh hưởng xác suất và valuation assumptions. · Probabilities sum to 1; cùng valuation date; không thay DCF nếu thiếu assumptions."},{"front_en":"An analyst assigns a 30% probability to a downside ESG scenario valued at USD 60 and 70% to a base scenario valued at USD 100. The probability-weighted value is closest to:","back_vi":"Tính expected scenario value theo probabilities đã cho. Thay số: 0.3 × 60+0.7 × 100 = 88.00 USD. | Không lấy simple average hoặc đảo probabilities."},{"front_en":"A company's expected annual operating cash flow is USD 50 million before a new carbon-related cost of USD 6 million. Under this simplified scenario with no offsetting changes, revised operating cash flow is closest to:","back_vi":"Material carbon cost làm giảm cash flow theo giả định. Thay số: 50-6 = 44.00 USD million. | Không cộng chi phí hoặc nhầm cost với net cash flow."}]}]},{"module_id":"CFA26-09-05","subject":"Portfolio Management","module_title":"The Behavioral Biases of Individuals","level":"CFA Level I 2026","status":"Source-mapped detailed academic draft; not independently certified","language":"Vietnamese explanations, English financial terms and English exam questions","source_policy":"Original explanations and questions; source-mapped to CFAI 2026 Volume 9, Kaplan Book 4 and SAPP PM slides. Selected existing v58 legacy lesson concepts reviewed; QBank readings 87–88 sampled for question coverage; no publisher questions copied.","disclaimer_vi":"Bản học chi tiết dạng draft. Các bài số mở rộng để luyện tập là ví dụ tự biên soạn và có giả định riêng; không biến LOS describe/explain thành yêu cầu tính toán chính thức. Chưa thẩm định học thuật độc lập toàn bộ nội dung.","los":[{"id":"CFA26-09-05-LOS01","letter":"a","title_en":"Cognitive Errors and Emotional Biases","outcome_en":"compare and contrast cognitive errors and emotional biases","overview_vi":"Bài học 5.a: Cognitive Errors and Emotional Biases. Học bản chất khái niệm, điều kiện áp dụng, so sánh và giải quyết tình huống. Công thức ghi supplement là bài luyện thêm; câu hỏi tiếng Anh do dự án tự biên soạn.","source":[{"id":"CFA Institute Curriculum 2026 — Portfolio Management Volume 9","pages":"Physical PDF p. 213 (LOS), 214–215 (content)"},{"id":"Kaplan SchweserNotes 2026 — Book 4, Reading 87","pages":"Physical PDF pp. 130–131"},{"id":"SAPP CFA Level I 2026 — Portfolio Management slides","pages":"Physical PDF pp. 162"}],"sections":[{"heading":"Traditional versus behavioral finance","body":"Traditional finance giả định nhà đầu tư xử lý thông tin hợp lý để tối ưu utility, còn behavioral finance xem xét bằng chứng về cách họ thực sự ra quyết định dưới giới hạn nhận thức và cảm xúc. Các sai lệch có tính hệ thống có thể làm danh mục không tối ưu và góp phần giải thích giá thị trường.","trap":"Thiên kiến không đồng nghĩa sai số ngẫu nhiên; cũng không tự động chứng minh thị trường luôn kém hiệu quả."},{"heading":"Cognitive errors","body":"Cognitive errors xuất phát chủ yếu từ suy luận, xử lý thông tin, trí nhớ hoặc hiểu sai thống kê. Chúng có thể được phát hiện bằng kiểm tra dữ liệu và giảm bớt bằng giáo dục, quy trình phân tích có cấu trúc, hoặc bằng cách buộc người ra quyết định cập nhật chứng cứ.","trap":"Cognitive không có nghĩa mọi sai lệch đều có thể loại bỏ hoàn toàn."},{"heading":"Emotional biases","body":"Emotional biases bắt nguồn từ cảm giác, xung động hoặc trực giác hơn là suy luận có chủ ý. Chúng thường khó điều chỉnh hơn; người tư vấn có thể cần thiết kế danh mục phù hợp với hành vi có thể duy trì, trong giới hạn khả năng chịu rủi ro và mục tiêu thực tế.","trap":"Không vì khách hàng sợ lỗ mà tự động bỏ mọi tài sản rủi ro."},{"heading":"Moderate versus adapt","body":"Moderate là nhận diện và cố giảm hoặc loại bỏ bias; adapt là chấp nhận sự tồn tại của bias và điều chỉnh kế hoạch để giảm tác hại. Có thể phối hợp cả hai, ví dụ giáo dục về drawdown rồi thiết kế phân bổ mà khách hàng có thể tuân thủ.","trap":"Adapt không có nghĩa bỏ qua rủi ro tài chính hay vi phạm IPS."},{"heading":"Overlapping causes","body":"Một bias có thể chứa cả yếu tố cảm xúc lẫn nhận thức nhưng được phân loại theo đặc điểm chi phối. Phân loại giúp chọn cách can thiệp; nếu có yếu tố nhận thức có thể sửa, ưu tiên kiểm chứng dữ kiện trước khi điều chỉnh phần khó thay đổi.","trap":"CFAI xếp overconfidence vào emotional dù có thành phần cognitive."},{"heading":"Belief perseverance versus processing","body":"Belief perseverance là xu hướng giữ niềm tin cũ khi gặp chứng cứ trái chiều, thường liên hệ cognitive dissonance. Processing errors là sử dụng thông tin theo cách thiếu hợp lý dù không nhất thiết nhằm bảo vệ một quan điểm có sẵn.","trap":"Anchoring là processing; conservatism là belief perseverance."}],"formulas":[{"name":"Bias classification framework","expr":"Behavioral bias → cognitive error or emotional bias","meaning":"Phân loại theo cơ chế chi phối; cognitive có thể giảm qua giáo dục và dữ liệu; emotional thường cần adaptation.","conditions":"Một bias có thể chứa cả hai thành phần; giữ taxonomy CFAI."},{"name":"Moderation versus adaptation","expr":"Recognize → moderate if feasible → adapt when persistent","meaning":"Nhận diện, kiểm tra hậu quả, điều chỉnh quy trình hoặc thiết kế danh mục.","conditions":"Không bỏ qua objectives và ability to bear risk."}],"examples":[{"question_en":"A client repeatedly misreads probabilities and refuses to hold equities because losses cause intense distress. How should the adviser respond?","steps_vi":["Tách statistical misunderstanding (cognitive) khỏi distress (emotional). Giải thích phân phối return, dùng cùng horizon và cả cách diễn đạt gain/loss.","Sau giáo dục, nếu distress vẫn tồn tại, chọn allocation khả thi trong IPS và khả năng tài chính; không bảo đảm tránh lỗ."],"answer":"Moderate cognitive errors; adapt to persistent emotional bias where appropriate.","check":"Original conceptual case; conclusions conditional on the stated facts."}],"questions":[{"stem_en":"Behavioral finance differs from traditional finance primarily by incorporating:","options":["only differences in investors' wealth.","systematic departures from rational decision making.","the assumption that all prices are always incorrect."],"correct":1,"why_vi":"Traditional finance giả định nhà đầu tư xử lý thông tin hợp lý để tối ưu utility, còn behavioral finance xem xét bằng chứng về cách họ thực sự ra quyết định dưới giới hạn nhận thức và cảm xúc. Các sai lệch có tính hệ thống có thể làm danh mục không tối ưu và góp phần giải thích giá thị trường.","trap_vi":"Thiên kiến không đồng nghĩa sai số ngẫu nhiên; cũng không tự động chứng minh thị trường luôn kém hiệu quả."},{"stem_en":"Which response is most appropriate for a client's statistical reasoning error?","options":["Assume the bias must always be accommodated without review.","Provide education and a structured decision process.","Increase exposure to the asset that caused the error."],"correct":1,"why_vi":"Cognitive errors xuất phát chủ yếu từ suy luận, xử lý thông tin, trí nhớ hoặc hiểu sai thống kê. Chúng có thể được phát hiện bằng kiểm tra dữ liệu và giảm bớt bằng giáo dục, quy trình phân tích có cấu trúc, hoặc bằng cách buộc người ra quyết định cập nhật chứng cứ.","trap_vi":"Cognitive không có nghĩa mọi sai lệch đều có thể loại bỏ hoàn toàn."},{"stem_en":"Compared with cognitive errors, emotional biases are generally:","options":["more easily eliminated by statistical training.","more difficult to correct through information alone.","unrelated to investment decisions."],"correct":1,"why_vi":"Emotional biases bắt nguồn từ cảm giác, xung động hoặc trực giác hơn là suy luận có chủ ý. Chúng thường khó điều chỉnh hơn; người tư vấn có thể cần thiết kế danh mục phù hợp với hành vi có thể duy trì, trong giới hạn khả năng chịu rủi ro và mục tiêu thực tế.","trap_vi":"Không vì khách hàng sợ lỗ mà tự động bỏ mọi tài sản rủi ro."},{"stem_en":"An adviser accepts a persistent emotional bias and modifies the portfolio design accordingly. This is best described as:","options":["adapting to the bias.","moderating the bias through statistical training.","eliminating the bias through arbitrage."],"correct":0,"why_vi":"Moderate là nhận diện và cố giảm hoặc loại bỏ bias; adapt là chấp nhận sự tồn tại của bias và điều chỉnh kế hoạch để giảm tác hại. Có thể phối hợp cả hai, ví dụ giáo dục về drawdown rồi thiết kế phân bổ mà khách hàng có thể tuân thủ.","trap_vi":"Adapt không có nghĩa bỏ qua rủi ro tài chính hay vi phạm IPS."},{"stem_en":"A bias has both emotional and cognitive components. Which initial intervention is generally more promising?","options":["Assume the bias belongs to neither category.","Address the correctable cognitive component.","Ignore reasoning errors because emotions are involved."],"correct":1,"why_vi":"Một bias có thể chứa cả yếu tố cảm xúc lẫn nhận thức nhưng được phân loại theo đặc điểm chi phối. Phân loại giúp chọn cách can thiệp; nếu có yếu tố nhận thức có thể sửa, ưu tiên kiểm chứng dữ kiện trước khi điều chỉnh phần khó thay đổi.","trap_vi":"CFAI xếp overconfidence vào emotional dù có thành phần cognitive."},{"stem_en":"Which pairing is correct under the curriculum taxonomy?","options":["Conservatism—emotional; framing—belief perseverance","Conservatism—information processing; framing—emotional","Conservatism—belief perseverance; framing—information processing"],"correct":2,"why_vi":"Belief perseverance là xu hướng giữ niềm tin cũ khi gặp chứng cứ trái chiều, thường liên hệ cognitive dissonance. Processing errors là sử dụng thông tin theo cách thiếu hợp lý dù không nhất thiết nhằm bảo vệ một quan điểm có sẵn.","trap_vi":"Anchoring là processing; conservatism là belief perseverance."}],"cards":[{"front_en":"Traditional versus behavioral finance","back_vi":"Traditional finance giả định nhà đầu tư xử lý thông tin hợp lý để tối ưu utility, còn behavioral finance xem xét bằng chứng về cách họ thực sự ra quyết định dưới giới hạn nhận thức và cảm xúc. Các sai lệch có tính hệ thống có thể làm danh mục không tối ưu và góp phần giải thích giá thị trường. | Exam trap: Thiên kiến không đồng nghĩa sai số ngẫu nhiên; cũng không tự động chứng minh thị trường luôn kém hiệu quả."},{"front_en":"Cognitive errors","back_vi":"Cognitive errors xuất phát chủ yếu từ suy luận, xử lý thông tin, trí nhớ hoặc hiểu sai thống kê. Chúng có thể được phát hiện bằng kiểm tra dữ liệu và giảm bớt bằng giáo dục, quy trình phân tích có cấu trúc, hoặc bằng cách buộc người ra quyết định cập nhật chứng cứ. | Exam trap: Cognitive không có nghĩa mọi sai lệch đều có thể loại bỏ hoàn toàn."},{"front_en":"Emotional biases","back_vi":"Emotional biases bắt nguồn từ cảm giác, xung động hoặc trực giác hơn là suy luận có chủ ý. Chúng thường khó điều chỉnh hơn; người tư vấn có thể cần thiết kế danh mục phù hợp với hành vi có thể duy trì, trong giới hạn khả năng chịu rủi ro và mục tiêu thực tế. | Exam trap: Không vì khách hàng sợ lỗ mà tự động bỏ mọi tài sản rủi ro."},{"front_en":"Moderate versus adapt","back_vi":"Moderate là nhận diện và cố giảm hoặc loại bỏ bias; adapt là chấp nhận sự tồn tại của bias và điều chỉnh kế hoạch để giảm tác hại. Có thể phối hợp cả hai, ví dụ giáo dục về drawdown rồi thiết kế phân bổ mà khách hàng có thể tuân thủ. | Exam trap: Adapt không có nghĩa bỏ qua rủi ro tài chính hay vi phạm IPS."},{"front_en":"Overlapping causes","back_vi":"Một bias có thể chứa cả yếu tố cảm xúc lẫn nhận thức nhưng được phân loại theo đặc điểm chi phối. Phân loại giúp chọn cách can thiệp; nếu có yếu tố nhận thức có thể sửa, ưu tiên kiểm chứng dữ kiện trước khi điều chỉnh phần khó thay đổi. | Exam trap: CFAI xếp overconfidence vào emotional dù có thành phần cognitive."},{"front_en":"Belief perseverance versus processing","back_vi":"Belief perseverance là xu hướng giữ niềm tin cũ khi gặp chứng cứ trái chiều, thường liên hệ cognitive dissonance. Processing errors là sử dụng thông tin theo cách thiếu hợp lý dù không nhất thiết nhằm bảo vệ một quan điểm có sẵn. | Exam trap: Anchoring là processing; conservatism là belief perseverance."},{"front_en":"Bias classification framework — formula or framework?","back_vi":"Behavioral bias → cognitive error or emotional bias · Phân loại theo cơ chế chi phối; cognitive có thể giảm qua giáo dục và dữ liệu; emotional thường cần adaptation. · Một bias có thể chứa cả hai thành phần; giữ taxonomy CFAI."},{"front_en":"Moderation versus adaptation — formula or framework?","back_vi":"Recognize → moderate if feasible → adapt when persistent · Nhận diện, kiểm tra hậu quả, điều chỉnh quy trình hoặc thiết kế danh mục. · Không bỏ qua objectives và ability to bear risk."}]},{"id":"CFA26-09-05-LOS02","letter":"b","title_en":"Behavioral Biases and Financial Decisions","outcome_en":"discuss commonly recognized behavioral biases and their implications for financial decision making","overview_vi":"Bài học 5.b: Behavioral Biases and Financial Decisions. Học bản chất khái niệm, điều kiện áp dụng, so sánh và giải quyết tình huống. Công thức ghi supplement là bài luyện thêm; câu hỏi tiếng Anh do dự án tự biên soạn.","source":[{"id":"CFA Institute Curriculum 2026 — Portfolio Management Volume 9","pages":"Physical PDF p. 213 (LOS), 215–236 (content)"},{"id":"Kaplan SchweserNotes 2026 — Book 4, Reading 87","pages":"Physical PDF pp. 131–141"},{"id":"SAPP CFA Level I 2026 — Portfolio Management slides","pages":"Physical PDF pp. 163–202"}],"sections":[{"heading":"Cognitive dissonance","body":"Khi chứng cứ mới mâu thuẫn với niềm tin, người ra quyết định cảm thấy khó chịu và có thể giảm khó chịu bằng cách bác bỏ nguồn, diễn giải lại dữ kiện hoặc trì hoãn cập nhật. Đây là cơ chế liên hệ với nhiều belief perseverance biases, không phải một nhóm emotional riêng.","trap":"Không coi mọi khác biệt quan điểm là bằng chứng có thiên kiến."},{"heading":"Conservatism bias","body":"Conservatism là cập nhật niềm tin quá chậm so với sức mạnh của thông tin mới. Dự báo ban đầu có thể hợp lý; sai lệch nằm ở việc đặt quá nhiều trọng số vào prior. Biện pháp: ghi prior, đánh giá độ tin cậy và tác động của evidence mới, dùng quy trình cập nhật định lượng nếu phù hợp.","trap":"Không nhầm conservatism với thái độ risk aversion hoặc confirmation chủ động tìm tin thuận chiều."},{"heading":"Confirmation bias","body":"Confirmation là ưu tiên tìm, diễn giải và nhớ thông tin củng cố quan điểm hiện hữu, bỏ qua chứng cứ phản bác. Có thể dẫn tới tập trung vị thế, thesis sai kéo dài, và overconfidence. Giảm bằng red team, nghiên cứu đối lập và tiêu chí bác bỏ luận điểm định trước.","trap":"Khác conservatism: trọng tâm là chọn lọc hoặc bóp méo bằng chứng."},{"heading":"Representativeness bias","body":"Representativeness dựa vào độ giống một nhóm hoặc hình mẫu để suy diễn các thuộc tính khác mà chưa đủ dữ liệu. Ví dụ tăng trưởng doanh thu cao được xem như bằng chứng cổ phiếu chắc chắn có return cao, mặc dù giá đã phản ánh kỳ vọng. Hai dạng quan trọng là base-rate neglect và sample-size neglect.","trap":"Một công ty tốt không nhất thiết là khoản đầu tư tốt ở mọi mức giá."},{"heading":"Base-rate neglect","body":"Base rate là tần suất nền của sự kiện trong quần thể phù hợp. Nếu chỉ chú ý dấu hiệu cá biệt mà quên tỷ lệ nền, xác suất hậu nghiệm bị đánh giá sai. Dùng Bayes hoặc cây xác suất để tổng hợp prior với khả năng quan sát evidence ở từng nhóm.","trap":"Không dùng likelihood P(signal given default) làm posterior P(default given signal)."},{"heading":"Sample-size neglect","body":"Sample-size neglect là suy rộng từ mẫu quá nhỏ hoặc không đại diện, ví dụ xếp nhà quản lý có ba tháng đứng đầu là người có kỹ năng bền vững. Cần lịch sử dài hơn, kiểm tra độ bất định, tính đại diện và selection bias trước khi kết luận.","trap":"Không nhầm dữ liệu ngắn với prior probability bị bỏ qua."},{"heading":"Illusion of control","body":"Illusion of control là tin mình có thể chi phối kết quả thực ra nằm ngoài quyền kiểm soát, chẳng hạn nhân viên tin việc thường xuyên quan sát giá cổ phiếu công ty giúp họ kiểm soát lợi nhuận. Hệ quả là tập trung và giao dịch quá mức. Nên phân biệt quyết định kiểm soát được với outcomes ngẫu nhiên.","trap":"Khác overconfidence về độ chính xác dự báo; ở đây nhấn mạnh quyền kiểm soát."},{"heading":"Hindsight bias","body":"Hindsight là sau khi biết kết quả thì cho rằng kết quả đó đã dễ dự báo từ trước. Điều này làm sai đánh giá chất lượng quyết định, phóng đại kỹ năng và che lấp các kịch bản từng có thể xảy ra. Investment journal ghi thời điểm, xác suất và luận điểm giúp kiểm tra ex ante.","trap":"Không đánh giá quyết định chỉ bằng realized outcome."},{"heading":"Anchoring and adjustment","body":"Anchoring lấy một giá trị tham chiếu ban đầu, đôi khi tùy tiện, rồi điều chỉnh không đủ. Giá mua, giá mục tiêu cũ hoặc đỉnh giá có thể neo dự báo dù không còn liên quan đến fair value. Dùng mô hình định giá độc lập và so sánh range trước khi xem mốc cũ.","trap":"Không nhầm giá mua neo với endowment (định giá cao do sở hữu)."},{"heading":"Mental accounting","body":"Mental accounting tách tài sản thành các ngăn tâm lý theo nguồn tiền hoặc cách tạo lợi nhuận, thay vì xem xét tổng danh mục. Tiền thưởng có thể bị coi là dễ mất hơn tiền lương; income được đối xử khác capital gains dù cùng đóng góp total return. Nên tổng hợp balance sheet, exposures và mục tiêu.","trap":"Phân ngăn theo nghĩa vụ pháp lý hoặc cash-flow goal có thể hợp lý; bias là phân ngăn tùy tiện."},{"heading":"Framing bias","body":"Framing là thay đổi quyết định khi hai cách diễn đạt cùng một tập kết quả và xác suất. Ví dụ cùng một khoản đầu tư được mô tả bằng xác suất lãi hoặc xác suất lỗ khiến người trả lời chọn khác. Dùng cả hai cách diễn đạt, số tuyệt đối và tỷ lệ trên cùng horizon để kiểm tra tính nhất quán.","trap":"Hai phương án có cùng expected value chưa chắc giống phân phối; framing đòi hỏi thông tin tương đương."},{"heading":"Availability bias","body":"Availability là đánh giá xác suất quá cao vì sự kiện dễ nhớ, nổi bật, gần đây hoặc quen thuộc. Một tin phá sản được truyền thông rộng có thể làm nhà đầu tư đánh giá credit risk của cả ngành sai lệch. Kiểm tra dữ liệu đại diện và tần suất dài hạn thay cho mức độ dễ nhớ.","trap":"Không nhầm availability với representativeness dựa trên hình mẫu."},{"heading":"Loss aversion","body":"Loss aversion là tổn thất so với reference point gây đau đớn lớn hơn niềm vui từ lợi ích tương đương. Prospect theory gợi ý xu hướng risk seeking trong miền lỗ và risk aversion trong miền lãi. Nhà đầu tư có thể giữ loser quá lâu để tránh hiện thực hóa lỗ và bán winner quá sớm.","trap":"Loss aversion khác risk aversion trong expected utility; không nhất thiết nhà đầu tư luôn né mọi rủi ro."},{"heading":"Disposition effect","body":"Disposition effect là khuynh hướng hiện thực hóa lợi nhuận sớm và trì hoãn hiện thực hóa khoản lỗ. Quyết định bán nên dựa vào expected return, risk, taxes và alternatives từ giá hiện tại. Đặt stop hoặc review trigger có cơ sở giúp giảm hành vi giữ loser vô điều kiện.","trap":"Không phải mọi quyết định giữ loser là bias; có thể có thesis hợp lý hoặc thuế."},{"heading":"Overconfidence","body":"Overconfidence là đánh giá quá cao hiểu biết, khả năng dự báo hoặc kỹ năng bản thân. Prediction overconfidence tạo khoảng dự báo quá hẹp; certainty overconfidence đánh giá xác suất đúng quá cao. Hệ quả có thể là turnover, chi phí, leverage và concentration quá mức.","trap":"CFAI phân loại emotional; không coi thành tích ngắn hạn là bằng chứng kỹ năng."},{"heading":"Self-attribution and calibration","body":"Self-attribution có thể củng cố overconfidence: nhận công khi kết quả tốt và quy lỗi cho yếu tố bên ngoài khi kết quả xấu. Nhật ký dự báo, calibration theo nhóm xác suất, so sánh benchmark và phân tích attribution giúp tách kỹ năng khỏi may mắn.","trap":"Không xem self-attribution là nhóm thứ ba độc lập trong sơ đồ 15 bias của bài."},{"heading":"Self-control bias","body":"Self-control là khó trì hoãn thỏa mãn tức thời để đạt mục tiêu dài hạn, dẫn tới chi tiêu vượt kế hoạch, tiết kiệm thiếu và danh mục quá mạo hiểm để bù thiếu hụt. Budget, tự động tiết kiệm, kế hoạch retirement và kiểm tra funding giúp giảm tác động.","trap":"Không đồng nhất self-control với loss aversion khi bán tài sản."},{"heading":"Status quo bias","body":"Status quo là ưu tiên giữ hiện trạng vì quán tính hoặc không muốn quyết định, kể cả khi mục tiêu hoặc điều kiện đã đổi. Có thể khiến asset allocation trôi, giữ tài sản không phù hợp, bỏ qua tái cân bằng. Dùng lịch review và mặc định phù hợp IPS.","trap":"Khác endowment: không cần tài sản sở hữu được định giá cao hơn; trọng tâm là không hành động."},{"heading":"Endowment bias","body":"Endowment là đặt giá trị cao hơn cho tài sản chỉ vì đang sở hữu nó. Một phép kiểm tra hữu ích: nếu có tiền mặt bằng market value, hôm nay có mua lại cùng vị thế không? Cần xem giá trị kinh tế, chi phí chuyển đổi và nghĩa vụ thuế thực sự.","trap":"Không coi mọi reluctance to sell là endowment khi có chi phí giao dịch hợp lý."},{"heading":"Regret aversion","body":"Regret aversion là tránh quyết định vì sợ hối tiếc về kết quả xấu, có thể giữ danh mục quá bảo thủ hoặc chạy theo đám đông để giảm cảm giác trách nhiệm. Lập quy trình, cân nhắc opportunity cost, dùng phân bổ từng bước khi phù hợp và đánh giá quyết định ex ante.","trap":"Regret aversion có thể dẫn đến inaction hoặc herding; không chỉ giữ tài sản thua lỗ."},{"heading":"Bias diagnosis","body":"Một hành vi có thể do nhiều bias; xác định cơ chế chi phối từ lời giải thích trong vignette. Giữ một cổ phiếu vì giá mua là anchoring; vì sở hữu là endowment; vì sợ ghi nhận lỗ là loss aversion; vì ngại thay đổi là status quo. Phải đọc cả động cơ và hành động.","trap":"Không phân loại chỉ từ hành vi hold/sell."}],"formulas":[{"name":"Belief perseverance taxonomy","expr":"Conservatism, confirmation, representativeness, illusion of control, hindsight","meaning":"Nhóm giữ niềm tin hoặc diễn giải chứng cứ thiên lệch.","conditions":"Phân biệt conservatism với anchoring và confirmation."},{"name":"Information-processing taxonomy","expr":"Anchoring and adjustment, mental accounting, framing, availability","meaning":"Nhóm xử lý thông tin sai lệch.","conditions":"Khác nhóm emotional; đọc cơ chế chính trong vignette."},{"name":"Emotional taxonomy","expr":"Loss aversion, overconfidence, self-control, status quo, endowment, regret aversion","meaning":"Sáu bias emotional theo CFAI.","conditions":"Overconfidence có yếu tố cognitive nhưng thuộc emotional trong bài này."},{"name":"Bayesian update — supplemental","expr":"P(D given S) = P(S given D)P(D) / P(S)","meaning":"Kết hợp tỷ lệ nền và likelihood để hạn chế base-rate neglect.","conditions":"Dùng partition đầy đủ; không phải yêu cầu tính toán riêng của LOS."},{"name":"Decision journal","expr":"Forecast at t0 → probability and evidence → later outcome → calibration","meaning":"Ghi lại thông tin ex ante giúp giảm hindsight, confirmation và overconfidence.","conditions":"Không sửa forecast cũ sau khi biết kết quả."}],"examples":[{"question_en":"An investor keeps a share because it was purchased at $50, even though independent valuation is $25. Another keeps it because it belonged to a relative. Diagnose each case.","steps_vi":["Trường hợp đầu mốc $50 chi phối fair-value estimate: anchoring. Trường hợp hai sở hữu/gắn bó làm tăng perceived value: endowment nếu đó là động cơ chủ đạo.","Cả hai cùng hold nhưng lý do khác; không tự động chọn loss aversion nếu vignette không nói tránh ghi nhận lỗ."],"answer":"Anchoring and adjustment; endowment bias.","check":"Original conceptual case; conclusions conditional on the stated facts."},{"question_en":"A fund manager reads only bullish reports, then claims after a surprise loss that it was obvious. Identify the two errors.","steps_vi":["Chọn thông tin củng cố thesis là confirmation; sau sự kiện nhớ như đã dự đoán là hindsight.","Dùng independent challenge và investment journal có timestamp để phát hiện hai sai lệch."],"answer":"Confirmation and hindsight.","check":"Original conceptual case; conclusions conditional on the stated facts."},{"question_en":"A client regards a windfall as speculation money and a retirement account as completely separate from total wealth. What should be reviewed?","steps_vi":["Tổng hợp tất cả tài sản, liabilities và risk exposure; kiểm tra việc phân ngăn có lý do pháp lý hoặc mục tiêu cash flow thực tế không.","Nếu chỉ vì nguồn tiền khác nhau thì là mental accounting; khuyến nghị quyết định theo portfolio contribution."],"answer":"Mental accounting; evaluate consolidated exposures.","check":"Original conceptual case; conclusions conditional on the stated facts."},{"question_en":"A borrower population has a 2% default rate. A warning flag occurs for 80% of defaulters and 10% of non-defaulters. What is P(default given flag), in percent?","steps_vi":["Bài luyện thêm về base-rate neglect: trong 1,000 borrowers có 16 defaults flagged và 98 non-defaults flagged. Posterior = flagged defaults / all flags.","Thay số: 100 × (.02 × .8)/(.02 × .8+.98 × .1).","Kết quả: 14.04%."],"answer":"14.04%","check":"Original supplemental practice; Decimal compared with an alternate expression using Fraction (square root uses float in the second method)."},{"question_en":"An analyst's prior default probability is 5%. A signal is four times as likely under default as under no default. What is the posterior default probability, in percent?","steps_vi":["Bài luyện thêm: prior odds = 1:19; nhân likelihood ratio 4 rồi đổi odds thành probability.","Thay số: 100 × (.05 × 4)/(.05 × 4+.95).","Kết quả: 17.39%."],"answer":"17.39%","check":"Original supplemental practice; Decimal compared with an alternate expression using Fraction (square root uses float in the second method)."},{"question_en":"An investment has a 90% chance of gaining $10 and a 10% chance of losing $50. What is its expected gain, in dollars?","steps_vi":["Bài luyện thêm: cả gain frame và loss frame mô tả cùng phân phối nếu xác suất và outcomes không đổi. Tính expected value có dấu.","Thay số: .9 × 10-.1 × 50.","Kết quả: 4.00 USD."],"answer":"4.00 USD","check":"Original supplemental practice; Decimal compared with an alternate expression using Fraction (square root uses float in the second method)."}],"questions":[{"stem_en":"An analyst dismisses credible conflicting evidence to avoid discomfort about a previous forecast. The underlying mechanism is most likely:","options":["mental accounting.","self-control bias.","cognitive dissonance."],"correct":2,"why_vi":"Khi chứng cứ mới mâu thuẫn với niềm tin, người ra quyết định cảm thấy khó chịu và có thể giảm khó chịu bằng cách bác bỏ nguồn, diễn giải lại dữ kiện hoặc trì hoãn cập nhật. Đây là cơ chế liên hệ với nhiều belief perseverance biases, không phải một nhóm emotional riêng.","trap_vi":"Không coi mọi khác biệt quan điểm là bằng chứng có thiên kiến."},{"stem_en":"An analyst reads reliable new earnings data but changes a forecast by much less than the evidence warrants. Which bias is most likely?","options":["Conservatism","Availability","Regret aversion"],"correct":0,"why_vi":"Conservatism là cập nhật niềm tin quá chậm so với sức mạnh của thông tin mới. Dự báo ban đầu có thể hợp lý; sai lệch nằm ở việc đặt quá nhiều trọng số vào prior. Biện pháp: ghi prior, đánh giá độ tin cậy và tác động của evidence mới, dùng quy trình cập nhật định lượng nếu phù hợp.","trap_vi":"Không nhầm conservatism với thái độ risk aversion hoặc confirmation chủ động tìm tin thuận chiều."},{"stem_en":"After buying a bond, an analyst reads only research supporting the issuer's credit quality. Which bias is most likely?","options":["Hindsight","Confirmation","Status quo"],"correct":1,"why_vi":"Confirmation là ưu tiên tìm, diễn giải và nhớ thông tin củng cố quan điểm hiện hữu, bỏ qua chứng cứ phản bác. Có thể dẫn tới tập trung vị thế, thesis sai kéo dài, và overconfidence. Giảm bằng red team, nghiên cứu đối lập và tiêu chí bác bỏ luận điểm định trước.","trap_vi":"Khác conservatism: trọng tâm là chọn lọc hoặc bóp méo bằng chứng."},{"stem_en":"A fund selects firms resembling past successful technology businesses without evaluating current valuation. Which bias is most likely?","options":["Endowment","Framing","Representativeness"],"correct":2,"why_vi":"Representativeness dựa vào độ giống một nhóm hoặc hình mẫu để suy diễn các thuộc tính khác mà chưa đủ dữ liệu. Ví dụ tăng trưởng doanh thu cao được xem như bằng chứng cổ phiếu chắc chắn có return cao, mặc dù giá đã phản ánh kỳ vọng. Hai dạng quan trọng là base-rate neglect và sample-size neglect.","trap_vi":"Một công ty tốt không nhất thiết là khoản đầu tư tốt ở mọi mức giá."},{"stem_en":"A lender focuses on a warning signal but ignores that defaults are rare in the population. This most directly illustrates:","options":["sample-size neglect.","base-rate neglect.","loss aversion."],"correct":1,"why_vi":"Base rate là tần suất nền của sự kiện trong quần thể phù hợp. Nếu chỉ chú ý dấu hiệu cá biệt mà quên tỷ lệ nền, xác suất hậu nghiệm bị đánh giá sai. Dùng Bayes hoặc cây xác suất để tổng hợp prior với khả năng quan sát evidence ở từng nhóm.","trap_vi":"Không dùng likelihood P(signal given default) làm posterior P(default given signal)."},{"stem_en":"An investor concludes that a manager has persistent skill after two unusually strong quarters. The most direct error is:","options":["anchoring and adjustment.","sample-size neglect.","endowment bias."],"correct":1,"why_vi":"Sample-size neglect là suy rộng từ mẫu quá nhỏ hoặc không đại diện, ví dụ xếp nhà quản lý có ba tháng đứng đầu là người có kỹ năng bền vững. Cần lịch sử dài hơn, kiểm tra độ bất định, tính đại diện và selection bias trước khi kết luận.","trap_vi":"Không nhầm dữ liệu ngắn với prior probability bị bỏ qua."},{"stem_en":"A trader believes choosing a particular order-entry ritual can influence future market prices. Which bias best fits?","options":["Mental accounting","Illusion of control","Conservatism"],"correct":1,"why_vi":"Illusion of control là tin mình có thể chi phối kết quả thực ra nằm ngoài quyền kiểm soát, chẳng hạn nhân viên tin việc thường xuyên quan sát giá cổ phiếu công ty giúp họ kiểm soát lợi nhuận. Hệ quả là tập trung và giao dịch quá mức. Nên phân biệt quyết định kiểm soát được với outcomes ngẫu nhiên.","trap_vi":"Khác overconfidence về độ chính xác dự báo; ở đây nhấn mạnh quyền kiểm soát."},{"stem_en":"After an unexpected downgrade, an analyst remembers having considered it inevitable despite a prior low-probability forecast. Which bias is most likely?","options":["Hindsight","Availability","Status quo"],"correct":0,"why_vi":"Hindsight là sau khi biết kết quả thì cho rằng kết quả đó đã dễ dự báo từ trước. Điều này làm sai đánh giá chất lượng quyết định, phóng đại kỹ năng và che lấp các kịch bản từng có thể xảy ra. Investment journal ghi thời điểm, xác suất và luận điểm giúp kiểm tra ex ante.","trap_vi":"Không đánh giá quyết định chỉ bằng realized outcome."},{"stem_en":"An investor's revised fair-value estimate remains tied to an arbitrary first quoted price. Which bias is most likely?","options":["Anchoring and adjustment","Confirmation","Self-control"],"correct":0,"why_vi":"Anchoring lấy một giá trị tham chiếu ban đầu, đôi khi tùy tiện, rồi điều chỉnh không đủ. Giá mua, giá mục tiêu cũ hoặc đỉnh giá có thể neo dự báo dù không còn liên quan đến fair value. Dùng mô hình định giá độc lập và so sánh range trước khi xem mốc cũ.","trap_vi":"Không nhầm giá mua neo với endowment (định giá cao do sở hữu)."},{"stem_en":"An investor takes excessive risk only with a tax refund because it is viewed as separate from other wealth. Which bias is most likely?","options":["Mental accounting","Status quo","Illusion of control"],"correct":0,"why_vi":"Mental accounting tách tài sản thành các ngăn tâm lý theo nguồn tiền hoặc cách tạo lợi nhuận, thay vì xem xét tổng danh mục. Tiền thưởng có thể bị coi là dễ mất hơn tiền lương; income được đối xử khác capital gains dù cùng đóng góp total return. Nên tổng hợp balance sheet, exposures và mục tiêu.","trap_vi":"Phân ngăn theo nghĩa vụ pháp lý hoặc cash-flow goal có thể hợp lý; bias là phân ngăn tùy tiện."},{"stem_en":"A client changes a decision when the same probability distribution is described in loss rather than gain terms. Which bias is most likely?","options":["Conservatism","Confirmation","Framing"],"correct":2,"why_vi":"Framing là thay đổi quyết định khi hai cách diễn đạt cùng một tập kết quả và xác suất. Ví dụ cùng một khoản đầu tư được mô tả bằng xác suất lãi hoặc xác suất lỗ khiến người trả lời chọn khác. Dùng cả hai cách diễn đạt, số tuyệt đối và tỷ lệ trên cùng horizon để kiểm tra tính nhất quán.","trap_vi":"Hai phương án có cùng expected value chưa chắc giống phân phối; framing đòi hỏi thông tin tương đương."},{"stem_en":"A widely publicized default causes an investor to greatly overestimate default frequency without reviewing data. Which bias is most likely?","options":["Availability","Endowment","Self-control"],"correct":0,"why_vi":"Availability là đánh giá xác suất quá cao vì sự kiện dễ nhớ, nổi bật, gần đây hoặc quen thuộc. Một tin phá sản được truyền thông rộng có thể làm nhà đầu tư đánh giá credit risk của cả ngành sai lệch. Kiểm tra dữ liệu đại diện và tần suất dài hạn thay cho mức độ dễ nhớ.","trap_vi":"Không nhầm availability với representativeness dựa trên hình mẫu."},{"stem_en":"A client refuses to sell an impaired holding because realizing the loss feels worse than the prospect of further decline. Which bias is most likely?","options":["Availability","Loss aversion","Conservatism"],"correct":1,"why_vi":"Loss aversion là tổn thất so với reference point gây đau đớn lớn hơn niềm vui từ lợi ích tương đương. Prospect theory gợi ý xu hướng risk seeking trong miền lỗ và risk aversion trong miền lãi. Nhà đầu tư có thể giữ loser quá lâu để tránh hiện thực hóa lỗ và bán winner quá sớm.","trap_vi":"Loss aversion khác risk aversion trong expected utility; không nhất thiết nhà đầu tư luôn né mọi rủi ro."},{"stem_en":"Which behavior best illustrates the disposition effect?","options":["Selling all positions after their expected returns decline","Selling winners early while retaining losers to avoid realizing losses","Rebalancing according to previously agreed weight limits"],"correct":1,"why_vi":"Disposition effect là khuynh hướng hiện thực hóa lợi nhuận sớm và trì hoãn hiện thực hóa khoản lỗ. Quyết định bán nên dựa vào expected return, risk, taxes và alternatives từ giá hiện tại. Đặt stop hoặc review trigger có cơ sở giúp giảm hành vi giữ loser vô điều kiện.","trap_vi":"Không phải mọi quyết định giữ loser là bias; có thể có thesis hợp lý hoặc thuế."},{"stem_en":"A manager's forecast intervals repeatedly prove too narrow because the manager overestimates forecasting skill. Which bias is most likely?","options":["Mental accounting","Overconfidence","Regret aversion"],"correct":1,"why_vi":"Overconfidence là đánh giá quá cao hiểu biết, khả năng dự báo hoặc kỹ năng bản thân. Prediction overconfidence tạo khoảng dự báo quá hẹp; certainty overconfidence đánh giá xác suất đúng quá cao. Hệ quả có thể là turnover, chi phí, leverage và concentration quá mức.","trap_vi":"CFAI phân loại emotional; không coi thành tích ngắn hạn là bằng chứng kỹ năng."},{"stem_en":"A manager credits profitable trades to skill and blames every loss on bad luck. This pattern most directly reinforces:","options":["overconfidence.","mental accounting.","status quo bias."],"correct":0,"why_vi":"Self-attribution có thể củng cố overconfidence: nhận công khi kết quả tốt và quy lỗi cho yếu tố bên ngoài khi kết quả xấu. Nhật ký dự báo, calibration theo nhóm xác suất, so sánh benchmark và phân tích attribution giúp tách kỹ năng khỏi may mắn.","trap_vi":"Không xem self-attribution là nhóm thứ ba độc lập trong sơ đồ 15 bias của bài."},{"stem_en":"An investor repeatedly spends planned retirement contributions on immediate consumption. Which bias is most likely?","options":["Self-control","Hindsight","Illusion of control"],"correct":0,"why_vi":"Self-control là khó trì hoãn thỏa mãn tức thời để đạt mục tiêu dài hạn, dẫn tới chi tiêu vượt kế hoạch, tiết kiệm thiếu và danh mục quá mạo hiểm để bù thiếu hụt. Budget, tự động tiết kiệm, kế hoạch retirement và kiểm tra funding giúp giảm tác động.","trap_vi":"Không đồng nhất self-control với loss aversion khi bán tài sản."},{"stem_en":"A client leaves an obsolete asset allocation unchanged simply because changing it requires a decision. Which bias is most likely?","options":["Status quo","Endowment","Representativeness"],"correct":0,"why_vi":"Status quo là ưu tiên giữ hiện trạng vì quán tính hoặc không muốn quyết định, kể cả khi mục tiêu hoặc điều kiện đã đổi. Có thể khiến asset allocation trôi, giữ tài sản không phù hợp, bỏ qua tái cân bằng. Dùng lịch review và mặc định phù hợp IPS.","trap_vi":"Khác endowment: không cần tài sản sở hữu được định giá cao hơn; trọng tâm là không hành động."},{"stem_en":"An investor demands a higher price to sell a holding than the investor would pay to acquire an identical holding. Which bias is most likely?","options":["Endowment","Framing","Availability"],"correct":0,"why_vi":"Endowment là đặt giá trị cao hơn cho tài sản chỉ vì đang sở hữu nó. Một phép kiểm tra hữu ích: nếu có tiền mặt bằng market value, hôm nay có mua lại cùng vị thế không? Cần xem giá trị kinh tế, chi phí chuyển đổi và nghĩa vụ thuế thực sự.","trap_vi":"Không coi mọi reluctance to sell là endowment khi có chi phí giao dịch hợp lý."},{"stem_en":"An investor joins a popular trade primarily to avoid regretting being left out if it rises. Which bias is most likely?","options":["Sample-size neglect","Mental accounting","Regret aversion"],"correct":2,"why_vi":"Regret aversion là tránh quyết định vì sợ hối tiếc về kết quả xấu, có thể giữ danh mục quá bảo thủ hoặc chạy theo đám đông để giảm cảm giác trách nhiệm. Lập quy trình, cân nhắc opportunity cost, dùng phân bổ từng bước khi phù hợp và đánh giá quyết định ex ante.","trap_vi":"Regret aversion có thể dẫn đến inaction hoặc herding; không chỉ giữ tài sản thua lỗ."},{"stem_en":"A client keeps an inherited stock specifically because ownership makes it seem more valuable, not because of a loss. The best diagnosis is:","options":["endowment bias.","loss aversion.","conservatism bias."],"correct":0,"why_vi":"Một hành vi có thể do nhiều bias; xác định cơ chế chi phối từ lời giải thích trong vignette. Giữ một cổ phiếu vì giá mua là anchoring; vì sở hữu là endowment; vì sợ ghi nhận lỗ là loss aversion; vì ngại thay đổi là status quo. Phải đọc cả động cơ và hành động.","trap_vi":"Không phân loại chỉ từ hành vi hold/sell."},{"stem_en":"A borrower population has a 2% default rate. A warning flag occurs for 80% of defaulters and 10% of non-defaulters. What is P(default given flag), in percent?","options":["80.00%","14.04%","2.00%"],"correct":1,"why_vi":"Bài luyện thêm về base-rate neglect: trong 1,000 borrowers có 16 defaults flagged và 98 non-defaults flagged. Posterior = flagged defaults / all flags. Thay số: 100 × (.02 × .8)/(.02 × .8+.98 × .1) = 14.04%.","trap_vi":"Không nhầm sensitivity 80% hoặc prior 2% với posterior."},{"stem_en":"An analyst's prior default probability is 5%. A signal is four times as likely under default as under no default. What is the posterior default probability, in percent?","options":["20.00%","5.00%","17.39%"],"correct":2,"why_vi":"Bài luyện thêm: prior odds = 1:19; nhân likelihood ratio 4 rồi đổi odds thành probability. Thay số: 100 × (.05 × 4)/(.05 × 4+.95) = 17.39%.","trap_vi":"Likelihood ratio nhân odds, không nhân probability trực tiếp."},{"stem_en":"An investment has a 90% chance of gaining $10 and a 10% chance of losing $50. What is its expected gain, in dollars?","options":["9.00 USD","4.00 USD","14.00 USD"],"correct":1,"why_vi":"Bài luyện thêm: cả gain frame và loss frame mô tả cùng phân phối nếu xác suất và outcomes không đổi. Tính expected value có dấu. Thay số: .9 × 10-.1 × 50 = 4.00 USD.","trap_vi":"Không bỏ loss hoặc cộng loss như gain."}],"cards":[{"front_en":"Cognitive dissonance","back_vi":"Khi chứng cứ mới mâu thuẫn với niềm tin, người ra quyết định cảm thấy khó chịu và có thể giảm khó chịu bằng cách bác bỏ nguồn, diễn giải lại dữ kiện hoặc trì hoãn cập nhật. Đây là cơ chế liên hệ với nhiều belief perseverance biases, không phải một nhóm emotional riêng. | Exam trap: Không coi mọi khác biệt quan điểm là bằng chứng có thiên kiến."},{"front_en":"Conservatism bias","back_vi":"Conservatism là cập nhật niềm tin quá chậm so với sức mạnh của thông tin mới. Dự báo ban đầu có thể hợp lý; sai lệch nằm ở việc đặt quá nhiều trọng số vào prior. Biện pháp: ghi prior, đánh giá độ tin cậy và tác động của evidence mới, dùng quy trình cập nhật định lượng nếu phù hợp. | Exam trap: Không nhầm conservatism với thái độ risk aversion hoặc confirmation chủ động tìm tin thuận chiều."},{"front_en":"Confirmation bias","back_vi":"Confirmation là ưu tiên tìm, diễn giải và nhớ thông tin củng cố quan điểm hiện hữu, bỏ qua chứng cứ phản bác. Có thể dẫn tới tập trung vị thế, thesis sai kéo dài, và overconfidence. Giảm bằng red team, nghiên cứu đối lập và tiêu chí bác bỏ luận điểm định trước. | Exam trap: Khác conservatism: trọng tâm là chọn lọc hoặc bóp méo bằng chứng."},{"front_en":"Representativeness bias","back_vi":"Representativeness dựa vào độ giống một nhóm hoặc hình mẫu để suy diễn các thuộc tính khác mà chưa đủ dữ liệu. Ví dụ tăng trưởng doanh thu cao được xem như bằng chứng cổ phiếu chắc chắn có return cao, mặc dù giá đã phản ánh kỳ vọng. Hai dạng quan trọng là base-rate neglect và sample-size neglect. | Exam trap: Một công ty tốt không nhất thiết là khoản đầu tư tốt ở mọi mức giá."},{"front_en":"Base-rate neglect","back_vi":"Base rate là tần suất nền của sự kiện trong quần thể phù hợp. Nếu chỉ chú ý dấu hiệu cá biệt mà quên tỷ lệ nền, xác suất hậu nghiệm bị đánh giá sai. Dùng Bayes hoặc cây xác suất để tổng hợp prior với khả năng quan sát evidence ở từng nhóm. | Exam trap: Không dùng likelihood P(signal given default) làm posterior P(default given signal)."},{"front_en":"Sample-size neglect","back_vi":"Sample-size neglect là suy rộng từ mẫu quá nhỏ hoặc không đại diện, ví dụ xếp nhà quản lý có ba tháng đứng đầu là người có kỹ năng bền vững. Cần lịch sử dài hơn, kiểm tra độ bất định, tính đại diện và selection bias trước khi kết luận. | Exam trap: Không nhầm dữ liệu ngắn với prior probability bị bỏ qua."},{"front_en":"Illusion of control","back_vi":"Illusion of control là tin mình có thể chi phối kết quả thực ra nằm ngoài quyền kiểm soát, chẳng hạn nhân viên tin việc thường xuyên quan sát giá cổ phiếu công ty giúp họ kiểm soát lợi nhuận. Hệ quả là tập trung và giao dịch quá mức. Nên phân biệt quyết định kiểm soát được với outcomes ngẫu nhiên. | Exam trap: Khác overconfidence về độ chính xác dự báo; ở đây nhấn mạnh quyền kiểm soát."},{"front_en":"Hindsight bias","back_vi":"Hindsight là sau khi biết kết quả thì cho rằng kết quả đó đã dễ dự báo từ trước. Điều này làm sai đánh giá chất lượng quyết định, phóng đại kỹ năng và che lấp các kịch bản từng có thể xảy ra. Investment journal ghi thời điểm, xác suất và luận điểm giúp kiểm tra ex ante. | Exam trap: Không đánh giá quyết định chỉ bằng realized outcome."},{"front_en":"Anchoring and adjustment","back_vi":"Anchoring lấy một giá trị tham chiếu ban đầu, đôi khi tùy tiện, rồi điều chỉnh không đủ. Giá mua, giá mục tiêu cũ hoặc đỉnh giá có thể neo dự báo dù không còn liên quan đến fair value. Dùng mô hình định giá độc lập và so sánh range trước khi xem mốc cũ. | Exam trap: Không nhầm giá mua neo với endowment (định giá cao do sở hữu)."},{"front_en":"Mental accounting","back_vi":"Mental accounting tách tài sản thành các ngăn tâm lý theo nguồn tiền hoặc cách tạo lợi nhuận, thay vì xem xét tổng danh mục. Tiền thưởng có thể bị coi là dễ mất hơn tiền lương; income được đối xử khác capital gains dù cùng đóng góp total return. Nên tổng hợp balance sheet, exposures và mục tiêu. | Exam trap: Phân ngăn theo nghĩa vụ pháp lý hoặc cash-flow goal có thể hợp lý; bias là phân ngăn tùy tiện."},{"front_en":"Framing bias","back_vi":"Framing là thay đổi quyết định khi hai cách diễn đạt cùng một tập kết quả và xác suất. Ví dụ cùng một khoản đầu tư được mô tả bằng xác suất lãi hoặc xác suất lỗ khiến người trả lời chọn khác. Dùng cả hai cách diễn đạt, số tuyệt đối và tỷ lệ trên cùng horizon để kiểm tra tính nhất quán. | Exam trap: Hai phương án có cùng expected value chưa chắc giống phân phối; framing đòi hỏi thông tin tương đương."},{"front_en":"Availability bias","back_vi":"Availability là đánh giá xác suất quá cao vì sự kiện dễ nhớ, nổi bật, gần đây hoặc quen thuộc. Một tin phá sản được truyền thông rộng có thể làm nhà đầu tư đánh giá credit risk của cả ngành sai lệch. Kiểm tra dữ liệu đại diện và tần suất dài hạn thay cho mức độ dễ nhớ. | Exam trap: Không nhầm availability với representativeness dựa trên hình mẫu."},{"front_en":"Loss aversion","back_vi":"Loss aversion là tổn thất so với reference point gây đau đớn lớn hơn niềm vui từ lợi ích tương đương. Prospect theory gợi ý xu hướng risk seeking trong miền lỗ và risk aversion trong miền lãi. Nhà đầu tư có thể giữ loser quá lâu để tránh hiện thực hóa lỗ và bán winner quá sớm. | Exam trap: Loss aversion khác risk aversion trong expected utility; không nhất thiết nhà đầu tư luôn né mọi rủi ro."},{"front_en":"Disposition effect","back_vi":"Disposition effect là khuynh hướng hiện thực hóa lợi nhuận sớm và trì hoãn hiện thực hóa khoản lỗ. Quyết định bán nên dựa vào expected return, risk, taxes và alternatives từ giá hiện tại. Đặt stop hoặc review trigger có cơ sở giúp giảm hành vi giữ loser vô điều kiện. | Exam trap: Không phải mọi quyết định giữ loser là bias; có thể có thesis hợp lý hoặc thuế."},{"front_en":"Overconfidence","back_vi":"Overconfidence là đánh giá quá cao hiểu biết, khả năng dự báo hoặc kỹ năng bản thân. Prediction overconfidence tạo khoảng dự báo quá hẹp; certainty overconfidence đánh giá xác suất đúng quá cao. Hệ quả có thể là turnover, chi phí, leverage và concentration quá mức. | Exam trap: CFAI phân loại emotional; không coi thành tích ngắn hạn là bằng chứng kỹ năng."},{"front_en":"Self-attribution and calibration","back_vi":"Self-attribution có thể củng cố overconfidence: nhận công khi kết quả tốt và quy lỗi cho yếu tố bên ngoài khi kết quả xấu. Nhật ký dự báo, calibration theo nhóm xác suất, so sánh benchmark và phân tích attribution giúp tách kỹ năng khỏi may mắn. | Exam trap: Không xem self-attribution là nhóm thứ ba độc lập trong sơ đồ 15 bias của bài."},{"front_en":"Self-control bias","back_vi":"Self-control là khó trì hoãn thỏa mãn tức thời để đạt mục tiêu dài hạn, dẫn tới chi tiêu vượt kế hoạch, tiết kiệm thiếu và danh mục quá mạo hiểm để bù thiếu hụt. Budget, tự động tiết kiệm, kế hoạch retirement và kiểm tra funding giúp giảm tác động. | Exam trap: Không đồng nhất self-control với loss aversion khi bán tài sản."},{"front_en":"Status quo bias","back_vi":"Status quo là ưu tiên giữ hiện trạng vì quán tính hoặc không muốn quyết định, kể cả khi mục tiêu hoặc điều kiện đã đổi. Có thể khiến asset allocation trôi, giữ tài sản không phù hợp, bỏ qua tái cân bằng. Dùng lịch review và mặc định phù hợp IPS. | Exam trap: Khác endowment: không cần tài sản sở hữu được định giá cao hơn; trọng tâm là không hành động."},{"front_en":"Endowment bias","back_vi":"Endowment là đặt giá trị cao hơn cho tài sản chỉ vì đang sở hữu nó. Một phép kiểm tra hữu ích: nếu có tiền mặt bằng market value, hôm nay có mua lại cùng vị thế không? Cần xem giá trị kinh tế, chi phí chuyển đổi và nghĩa vụ thuế thực sự. | Exam trap: Không coi mọi reluctance to sell là endowment khi có chi phí giao dịch hợp lý."},{"front_en":"Regret aversion","back_vi":"Regret aversion là tránh quyết định vì sợ hối tiếc về kết quả xấu, có thể giữ danh mục quá bảo thủ hoặc chạy theo đám đông để giảm cảm giác trách nhiệm. Lập quy trình, cân nhắc opportunity cost, dùng phân bổ từng bước khi phù hợp và đánh giá quyết định ex ante. | Exam trap: Regret aversion có thể dẫn đến inaction hoặc herding; không chỉ giữ tài sản thua lỗ."},{"front_en":"Bias diagnosis","back_vi":"Một hành vi có thể do nhiều bias; xác định cơ chế chi phối từ lời giải thích trong vignette. Giữ một cổ phiếu vì giá mua là anchoring; vì sở hữu là endowment; vì sợ ghi nhận lỗ là loss aversion; vì ngại thay đổi là status quo. Phải đọc cả động cơ và hành động. | Exam trap: Không phân loại chỉ từ hành vi hold/sell."},{"front_en":"Belief perseverance taxonomy — formula or framework?","back_vi":"Conservatism, confirmation, representativeness, illusion of control, hindsight · Nhóm giữ niềm tin hoặc diễn giải chứng cứ thiên lệch. · Phân biệt conservatism với anchoring và confirmation."},{"front_en":"Information-processing taxonomy — formula or framework?","back_vi":"Anchoring and adjustment, mental accounting, framing, availability · Nhóm xử lý thông tin sai lệch. · Khác nhóm emotional; đọc cơ chế chính trong vignette."},{"front_en":"Emotional taxonomy — formula or framework?","back_vi":"Loss aversion, overconfidence, self-control, status quo, endowment, regret aversion · Sáu bias emotional theo CFAI. · Overconfidence có yếu tố cognitive nhưng thuộc emotional trong bài này."},{"front_en":"Bayesian update — supplemental — formula or framework?","back_vi":"P(D given S) = P(S given D)P(D) / P(S) · Kết hợp tỷ lệ nền và likelihood để hạn chế base-rate neglect. · Dùng partition đầy đủ; không phải yêu cầu tính toán riêng của LOS."},{"front_en":"Decision journal — formula or framework?","back_vi":"Forecast at t0 → probability and evidence → later outcome → calibration · Ghi lại thông tin ex ante giúp giảm hindsight, confirmation và overconfidence. · Không sửa forecast cũ sau khi biết kết quả."},{"front_en":"A borrower population has a 2% default rate. A warning flag occurs for 80% of defaulters and 10% of non-defaulters. What is P(default given flag), in percent?","back_vi":"Bài luyện thêm về base-rate neglect: trong 1,000 borrowers có 16 defaults flagged và 98 non-defaults flagged. Posterior = flagged defaults / all flags. Thay số: 100 × (.02 × .8)/(.02 × .8+.98 × .1) = 14.04%. | Không nhầm sensitivity 80% hoặc prior 2% với posterior."},{"front_en":"An analyst's prior default probability is 5%. A signal is four times as likely under default as under no default. What is the posterior default probability, in percent?","back_vi":"Bài luyện thêm: prior odds = 1:19; nhân likelihood ratio 4 rồi đổi odds thành probability. Thay số: 100 × (.05 × 4)/(.05 × 4+.95) = 17.39%. | Likelihood ratio nhân odds, không nhân probability trực tiếp."},{"front_en":"An investment has a 90% chance of gaining $10 and a 10% chance of losing $50. What is its expected gain, in dollars?","back_vi":"Bài luyện thêm: cả gain frame và loss frame mô tả cùng phân phối nếu xác suất và outcomes không đổi. Tính expected value có dấu. Thay số: .9 × 10-.1 × 50 = 4.00 USD. | Không bỏ loss hoặc cộng loss như gain."}]},{"id":"CFA26-09-05-LOS03","letter":"c","title_en":"Behavioral Finance and Market Behavior","outcome_en":"describe how behavioral biases of investors can lead to market characteristics that may not be explained by traditional finance","overview_vi":"Bài học 5.c: Behavioral Finance and Market Behavior. Học bản chất khái niệm, điều kiện áp dụng, so sánh và giải quyết tình huống. Công thức ghi supplement là bài luyện thêm; câu hỏi tiếng Anh do dự án tự biên soạn.","source":[{"id":"CFA Institute Curriculum 2026 — Portfolio Management Volume 9","pages":"Physical PDF p. 213 (LOS), 236–241 (content)"},{"id":"Kaplan SchweserNotes 2026 — Book 4, Reading 87","pages":"Physical PDF pp. 141–143"},{"id":"SAPP CFA Level I 2026 — Portfolio Management slides","pages":"Physical PDF pp. 203–209"}],"sections":[{"heading":"Market anomaly definition","body":"Market anomaly là mẫu hình quan sát có vẻ không phù hợp với mô hình định giá hoặc market efficiency đang dùng. Cần kiểm tra risk adjustment, transaction costs, mẫu nghiên cứu và khả năng tồn tại sau công bố. Behavioral finance cung cấp giả thuyết giải thích, không tự động bác bỏ mọi mô hình truyền thống.","trap":"Anomaly phụ thuộc benchmark và giả định; joint-hypothesis problem vẫn tồn tại."},{"heading":"Momentum and underreaction","body":"Momentum là xu hướng tương đối của tài sản đã tăng hoặc giảm tiếp tục cùng hướng trong một khoảng thời gian. CFAI nhấn mạnh availability (recency), hindsight và loss aversion; cập nhật chậm cũng có thể góp phần tạo underreaction. Nghiên cứu trong bài ghi nhận xu hướng dương có thể kéo dài tới khoảng hai năm rồi có reversal trong kỳ dài hơn; không phải quy luật dự báo chắc chắn.","trap":"Momentum khác reversal và không bảo đảm lợi nhuận sau chi phí."},{"heading":"Bubbles and crashes","body":"Bubble là giai đoạn giá có thể tách đáng kể khỏi fundamental value trong bối cảnh kỳ vọng quá lạc quan. Overconfidence, self-attribution, confirmation và regret aversion góp phần thúc đẩy giao dịch; khi kỳ vọng đổi, anchoring và dissonance có thể trì hoãn điều chỉnh trước khi capitulation tăng tốc giảm giá.","trap":"Không thể xác định chắc đỉnh bubble chỉ từ giá tăng nhanh."},{"heading":"Value versus growth","body":"Value stocks thường có P/E thấp, book-to-market cao; growth stocks thường ngược lại. Historical value premium có thể được giải thích bởi risk compensation hoặc mispricing do halo effect, representativeness và kỳ vọng tăng trưởng quá mức. Không khẳng định value luôn thắng growth.","trap":"Fama–French risk-factor explanation là cách giải thích thay thế, không phải bias."},{"heading":"Halo effect","body":"Halo effect là mở rộng đánh giá tốt ở một thuộc tính sang thuộc tính khác không đủ chứng cứ. Sản phẩm được ưa chuộng có thể khiến nhà đầu tư đánh giá cổ phiếu vừa ít rủi ro vừa lợi nhuận cao, bất kể mức giá. Đây là dạng representativeness trong giải thích value/growth.","trap":"Chất lượng doanh nghiệp và expected stock return là hai câu hỏi khác nhau."},{"heading":"Home bias","body":"Home bias là tỷ trọng securities nội địa cao hơn một global benchmark thích hợp. Familiarity và cảm giác hiểu doanh nghiệp địa phương có thể góp phần; chi phí, thuế, liabilities và hạn chế đầu tư cũng có thể giải thích một phần. Cần xem exposure tổng thể thay vì chỉ địa chỉ đăng ký.","trap":"Không tự động chẩn đoán bias khi domestic assets phù hợp liabilities."},{"heading":"Limits to anomaly inference","body":"Hiệu quả sau risk adjustment, cost, turnover, liquidity và out-of-sample validation quyết định một anomaly có khai thác được không. Market participants có thể vẫn nắm vị thế trong bubble vì mandate, benchmark hoặc incentive; hành vi thị trường không chỉ là tổng đơn giản của lỗi cá nhân.","trap":"Không giả định arbitrage không rủi ro đối với mọi mispricing quan sát được."},{"heading":"False anomalies","body":"Ba nguyên nhân khiến một return pattern bị nhận nhầm là anomaly là chọn sai asset-pricing model, vấn đề thống kê như small sample/survivorship/data mining, và temporary disequilibrium. Khi mẫu hình được công bố, arbitrage có thể làm nó suy yếu. Cần kiểm tra abnormal return theo benchmark phù hợp.","trap":"Một abnormal return biến mất sau risk adjustment không phải bằng chứng chắc chắn về market inefficiency."},{"heading":"Limits to arbitrage in bubbles","body":"Ngay cả nhà đầu tư nhận thấy overvaluation cũng không biết lúc nào giá đảo chiều. Short-sale constraints, borrowing cost, rủi ro phải đóng vị thế trước khi thesis đúng và pressure từ khách hàng đánh giá short-term returns có thể khiến arbitrage không hiệu quả. Đây là giải thích hợp lý bổ sung cho behavioral biases.","trap":"Không suy từ việc tham gia bubble rằng mọi người đều tin giá hợp lý."},{"heading":"Recency and trend extrapolation","body":"Availability bias có dạng recency effect: sự kiện gần đây dễ nhớ hơn nên được gán trọng số quá lớn. Investor có thể mua quỹ sau một năm vượt trội vì ngoại suy performance và sợ bỏ lỡ cơ hội. Kiểm tra persistence, costs, valuation và risk exposures thay vì dùng return gần nhất làm dự báo duy nhất.","trap":"Không nhầm return chasing với bằng chứng về manager skill."}],"formulas":[{"name":"Anomaly evaluation","expr":"Observed pattern → risk adjustment → costs → robustness","meaning":"Kiểm tra một mẫu hình có thực sự khác benchmark và có thể khai thác.","conditions":"Không coi return lịch sử là arbitrage chắc chắn."},{"name":"Behavioral feedback","expr":"Underreaction → extrapolation/overconfidence → potential overshooting → correction","meaning":"Khung minh họa momentum và bubble; diễn biến phụ thuộc môi trường.","conditions":"Không dùng làm quy luật dự đoán thời điểm thị trường."}],"examples":[{"question_en":"A growth company becomes popular, investors extrapolate recent sales and buy at increasingly high valuations. What might explain later underperformance?","steps_vi":["Representativeness/halo effect và overconfidence có thể khiến expected growth cao quá mức so với fundamentals.","Kiểm tra risk-adjusted return và factors trước khi kết luận mispricing; popular company không bảo đảm good investment."],"answer":"Potential behavioral mispricing, not conclusive evidence against all risk models.","check":"Original conceptual case; conclusions conditional on the stated facts."}],"questions":[{"stem_en":"A documented return pattern is inconsistent with a particular asset-pricing model. It is best described initially as:","options":["a potential market anomaly.","proof of a costless arbitrage.","proof that all investors are irrational."],"correct":0,"why_vi":"Market anomaly là mẫu hình quan sát có vẻ không phù hợp với mô hình định giá hoặc market efficiency đang dùng. Cần kiểm tra risk adjustment, transaction costs, mẫu nghiên cứu và khả năng tồn tại sau công bố. Behavioral finance cung cấp giả thuyết giải thích, không tự động bác bỏ mọi mô hình truyền thống.","trap_vi":"Anomaly phụ thuộc benchmark và giả định; joint-hypothesis problem vẫn tồn tại."},{"stem_en":"Which behavioral mechanism can help explain gradual price adjustment after new information?","options":["Endowment bias alone","Perfect instantaneous Bayesian updating","Conservatism bias"],"correct":2,"why_vi":"Momentum là xu hướng tương đối của tài sản đã tăng hoặc giảm tiếp tục cùng hướng trong một khoảng thời gian. CFAI nhấn mạnh availability (recency), hindsight và loss aversion; cập nhật chậm cũng có thể góp phần tạo underreaction. Nghiên cứu trong bài ghi nhận xu hướng dương có thể kéo dài tới khoảng hai năm rồi có reversal trong kỳ dài hơn; không phải quy luật dự báo chắc chắn.","trap_vi":"Momentum khác reversal và không bảo đảm lợi nhuận sau chi phí."},{"stem_en":"Which combination is most consistent with a behavioral explanation for a speculative bubble?","options":["Overconfidence and regret-driven participation","Perfectly calibrated forecasts and no feedback effects","Only a reduction in transaction costs"],"correct":0,"why_vi":"Bubble là giai đoạn giá có thể tách đáng kể khỏi fundamental value trong bối cảnh kỳ vọng quá lạc quan. Overconfidence, self-attribution, confirmation và regret aversion góp phần thúc đẩy giao dịch; khi kỳ vọng đổi, anchoring và dissonance có thể trì hoãn điều chỉnh trước khi capitulation tăng tốc giảm giá.","trap_vi":"Không thể xác định chắc đỉnh bubble chỉ từ giá tăng nhanh."},{"stem_en":"Which observation weakens a purely behavioral mispricing explanation of the value premium?","options":["Investors extrapolate unusually high past growth.","The premium is accounted for by exposures to priced risk factors.","Analysts overestimate growth persistence."],"correct":1,"why_vi":"Value stocks thường có P/E thấp, book-to-market cao; growth stocks thường ngược lại. Historical value premium có thể được giải thích bởi risk compensation hoặc mispricing do halo effect, representativeness và kỳ vọng tăng trưởng quá mức. Không khẳng định value luôn thắng growth.","trap_vi":"Fama–French risk-factor explanation là cách giải thích thay thế, không phải bias."},{"stem_en":"A popular brand leads analysts to assume its stock is both unusually safe and underpriced without valuation analysis. This illustrates:","options":["a risk budget.","settlement risk.","a halo effect."],"correct":2,"why_vi":"Halo effect là mở rộng đánh giá tốt ở một thuộc tính sang thuộc tính khác không đủ chứng cứ. Sản phẩm được ưa chuộng có thể khiến nhà đầu tư đánh giá cổ phiếu vừa ít rủi ro vừa lợi nhuận cao, bất kể mức giá. Đây là dạng representativeness trong giải thích value/growth.","trap_vi":"Chất lượng doanh nghiệp và expected stock return là hai câu hỏi khác nhau."},{"stem_en":"A globally unconstrained investor overweights domestic shares mainly because familiar firms feel safer. This is most consistent with:","options":["a value premium.","risk shifting.","home bias."],"correct":2,"why_vi":"Home bias là tỷ trọng securities nội địa cao hơn một global benchmark thích hợp. Familiarity và cảm giác hiểu doanh nghiệp địa phương có thể góp phần; chi phí, thuế, liabilities và hạn chế đầu tư cũng có thể giải thích một phần. Cần xem exposure tổng thể thay vì chỉ địa chỉ đăng ký.","trap_vi":"Không tự động chẩn đoán bias khi domestic assets phù hợp liabilities."},{"stem_en":"Before treating an apparent anomaly as an exploitable strategy, an investor should most likely:","options":["test risk-adjusted returns after realistic trading costs.","assume historical excess returns must persist.","ignore sample selection and implementation constraints."],"correct":0,"why_vi":"Hiệu quả sau risk adjustment, cost, turnover, liquidity và out-of-sample validation quyết định một anomaly có khai thác được không. Market participants có thể vẫn nắm vị thế trong bubble vì mandate, benchmark hoặc incentive; hành vi thị trường không chỉ là tổng đơn giản của lỗi cá nhân.","trap_vi":"Không giả định arbitrage không rủi ro đối với mọi mispricing quan sát được."},{"stem_en":"A return pattern disappears when an appropriate additional risk factor is included in the benchmark. The original finding most likely reflected:","options":["a guaranteed arbitrage opportunity.","an irreversible emotional bias.","asset-pricing model misspecification."],"correct":2,"why_vi":"Ba nguyên nhân khiến một return pattern bị nhận nhầm là anomaly là chọn sai asset-pricing model, vấn đề thống kê như small sample/survivorship/data mining, và temporary disequilibrium. Khi mẫu hình được công bố, arbitrage có thể làm nó suy yếu. Cần kiểm tra abnormal return theo benchmark phù hợp.","trap_vi":"Một abnormal return biến mất sau risk adjustment không phải bằng chứng chắc chắn về market inefficiency."},{"stem_en":"A manager recognizes likely overvaluation but faces withdrawals if returns lag the benchmark for months. Which factor can explain continued participation without a behavioral bias?","options":["A guaranteed ability to time the crash","Short-horizon performance incentives and limits to arbitrage","Complete elimination of short-selling risk"],"correct":1,"why_vi":"Ngay cả nhà đầu tư nhận thấy overvaluation cũng không biết lúc nào giá đảo chiều. Short-sale constraints, borrowing cost, rủi ro phải đóng vị thế trước khi thesis đúng và pressure từ khách hàng đánh giá short-term returns có thể khiến arbitrage không hiệu quả. Đây là giải thích hợp lý bổ sung cho behavioral biases.","trap_vi":"Không suy từ việc tham gia bubble rằng mọi người đều tin giá hợp lý."},{"stem_en":"An investor selects funds only on last year's exceptional returns because the recent results dominate memory. Which bias most directly explains this?","options":["Illusion of control","Status quo bias","Availability bias in its recency form"],"correct":2,"why_vi":"Availability bias có dạng recency effect: sự kiện gần đây dễ nhớ hơn nên được gán trọng số quá lớn. Investor có thể mua quỹ sau một năm vượt trội vì ngoại suy performance và sợ bỏ lỡ cơ hội. Kiểm tra persistence, costs, valuation và risk exposures thay vì dùng return gần nhất làm dự báo duy nhất.","trap_vi":"Không nhầm return chasing với bằng chứng về manager skill."}],"cards":[{"front_en":"Market anomaly definition","back_vi":"Market anomaly là mẫu hình quan sát có vẻ không phù hợp với mô hình định giá hoặc market efficiency đang dùng. Cần kiểm tra risk adjustment, transaction costs, mẫu nghiên cứu và khả năng tồn tại sau công bố. Behavioral finance cung cấp giả thuyết giải thích, không tự động bác bỏ mọi mô hình truyền thống. | Exam trap: Anomaly phụ thuộc benchmark và giả định; joint-hypothesis problem vẫn tồn tại."},{"front_en":"Momentum and underreaction","back_vi":"Momentum là xu hướng tương đối của tài sản đã tăng hoặc giảm tiếp tục cùng hướng trong một khoảng thời gian. CFAI nhấn mạnh availability (recency), hindsight và loss aversion; cập nhật chậm cũng có thể góp phần tạo underreaction. Nghiên cứu trong bài ghi nhận xu hướng dương có thể kéo dài tới khoảng hai năm rồi có reversal trong kỳ dài hơn; không phải quy luật dự báo chắc chắn. | Exam trap: Momentum khác reversal và không bảo đảm lợi nhuận sau chi phí."},{"front_en":"Bubbles and crashes","back_vi":"Bubble là giai đoạn giá có thể tách đáng kể khỏi fundamental value trong bối cảnh kỳ vọng quá lạc quan. Overconfidence, self-attribution, confirmation và regret aversion góp phần thúc đẩy giao dịch; khi kỳ vọng đổi, anchoring và dissonance có thể trì hoãn điều chỉnh trước khi capitulation tăng tốc giảm giá. | Exam trap: Không thể xác định chắc đỉnh bubble chỉ từ giá tăng nhanh."},{"front_en":"Value versus growth","back_vi":"Value stocks thường có P/E thấp, book-to-market cao; growth stocks thường ngược lại. Historical value premium có thể được giải thích bởi risk compensation hoặc mispricing do halo effect, representativeness và kỳ vọng tăng trưởng quá mức. Không khẳng định value luôn thắng growth. | Exam trap: Fama–French risk-factor explanation là cách giải thích thay thế, không phải bias."},{"front_en":"Halo effect","back_vi":"Halo effect là mở rộng đánh giá tốt ở một thuộc tính sang thuộc tính khác không đủ chứng cứ. Sản phẩm được ưa chuộng có thể khiến nhà đầu tư đánh giá cổ phiếu vừa ít rủi ro vừa lợi nhuận cao, bất kể mức giá. Đây là dạng representativeness trong giải thích value/growth. | Exam trap: Chất lượng doanh nghiệp và expected stock return là hai câu hỏi khác nhau."},{"front_en":"Home bias","back_vi":"Home bias là tỷ trọng securities nội địa cao hơn một global benchmark thích hợp. Familiarity và cảm giác hiểu doanh nghiệp địa phương có thể góp phần; chi phí, thuế, liabilities và hạn chế đầu tư cũng có thể giải thích một phần. Cần xem exposure tổng thể thay vì chỉ địa chỉ đăng ký. | Exam trap: Không tự động chẩn đoán bias khi domestic assets phù hợp liabilities."},{"front_en":"Limits to anomaly inference","back_vi":"Hiệu quả sau risk adjustment, cost, turnover, liquidity và out-of-sample validation quyết định một anomaly có khai thác được không. Market participants có thể vẫn nắm vị thế trong bubble vì mandate, benchmark hoặc incentive; hành vi thị trường không chỉ là tổng đơn giản của lỗi cá nhân. | Exam trap: Không giả định arbitrage không rủi ro đối với mọi mispricing quan sát được."},{"front_en":"False anomalies","back_vi":"Ba nguyên nhân khiến một return pattern bị nhận nhầm là anomaly là chọn sai asset-pricing model, vấn đề thống kê như small sample/survivorship/data mining, và temporary disequilibrium. Khi mẫu hình được công bố, arbitrage có thể làm nó suy yếu. Cần kiểm tra abnormal return theo benchmark phù hợp. | Exam trap: Một abnormal return biến mất sau risk adjustment không phải bằng chứng chắc chắn về market inefficiency."},{"front_en":"Limits to arbitrage in bubbles","back_vi":"Ngay cả nhà đầu tư nhận thấy overvaluation cũng không biết lúc nào giá đảo chiều. Short-sale constraints, borrowing cost, rủi ro phải đóng vị thế trước khi thesis đúng và pressure từ khách hàng đánh giá short-term returns có thể khiến arbitrage không hiệu quả. Đây là giải thích hợp lý bổ sung cho behavioral biases. | Exam trap: Không suy từ việc tham gia bubble rằng mọi người đều tin giá hợp lý."},{"front_en":"Recency and trend extrapolation","back_vi":"Availability bias có dạng recency effect: sự kiện gần đây dễ nhớ hơn nên được gán trọng số quá lớn. Investor có thể mua quỹ sau một năm vượt trội vì ngoại suy performance và sợ bỏ lỡ cơ hội. Kiểm tra persistence, costs, valuation và risk exposures thay vì dùng return gần nhất làm dự báo duy nhất. | Exam trap: Không nhầm return chasing với bằng chứng về manager skill."},{"front_en":"Anomaly evaluation — formula or framework?","back_vi":"Observed pattern → risk adjustment → costs → robustness · Kiểm tra một mẫu hình có thực sự khác benchmark và có thể khai thác. · Không coi return lịch sử là arbitrage chắc chắn."},{"front_en":"Behavioral feedback — formula or framework?","back_vi":"Underreaction → extrapolation/overconfidence → potential overshooting → correction · Khung minh họa momentum và bubble; diễn biến phụ thuộc môi trường. · Không dùng làm quy luật dự đoán thời điểm thị trường."}]}]},{"module_id":"CFA26-09-06","subject":"Portfolio Management","module_title":"Introduction to Risk Management","level":"CFA Level I 2026","status":"Source-mapped detailed academic draft; not independently certified","language":"Vietnamese explanations, English financial terms and English exam questions","source_policy":"Original explanations and questions; source-mapped to CFAI 2026 Volume 9, Kaplan Book 4 and SAPP PM slides. Selected existing v58 legacy lesson concepts reviewed; QBank readings 87–88 sampled for question coverage; no publisher questions copied.","disclaimer_vi":"Bản học chi tiết dạng draft. Các bài số mở rộng để luyện tập là ví dụ tự biên soạn và có giả định riêng; không biến LOS describe/explain thành yêu cầu tính toán chính thức. Chưa thẩm định học thuật độc lập toàn bộ nội dung.","los":[{"id":"CFA26-09-06-LOS01","letter":"a","title_en":"Risk Management Definition","outcome_en":"define risk management","overview_vi":"Bài học 6.a: Risk Management Definition. Học bản chất khái niệm, điều kiện áp dụng, so sánh và giải quyết tình huống. Công thức ghi supplement là bài luyện thêm; câu hỏi tiếng Anh do dự án tự biên soạn.","source":[{"id":"CFA Institute Curriculum 2026 — Portfolio Management Volume 9","pages":"Physical PDF p. 249 (LOS), 249–253 (content)"},{"id":"Kaplan SchweserNotes 2026 — Book 4, Reading 88","pages":"Physical PDF pp. 144"},{"id":"SAPP CFA Level I 2026 — Portfolio Management slides","pages":"Physical PDF pp. 213–214"}],"sections":[{"heading":"Risk and risk exposure","body":"Risk là exposure to uncertainty, bao gồm cả kết quả thuận lợi và bất lợi; risk exposure mô tả mức độ giá trị hoặc mục tiêu nhạy với underlying risk. Ví dụ doanh nghiệp nhập khẩu có exposure ngoại tệ ngay cả khi tỷ giá chưa biến động.","trap":"Risk driver khác exposure: biến động tỷ giá là driver, nghĩa vụ ngoại tệ là exposure."},{"heading":"Definition of risk management","body":"Risk management là quy trình xác định risk tolerance, đo lường, giám sát và điều chỉnh exposures để phù hợp tolerance trong khi theo đuổi mục tiêu. Mục tiêu là lựa chọn rủi ro được bù đắp và kiểm soát rủi ro không mong muốn, không phải giảm mọi rủi ro về zero.","trap":"Một doanh nghiệp tránh mọi uncertainty có thể từ bỏ cơ hội tạo giá trị."},{"heading":"Ex ante versus ex post","body":"Quy trình tốt đánh giá trước phân phối kết quả, lựa chọn exposure và xây kế hoạch ứng phó. Kết quả lỗ sau một cú sốc không tự chứng minh risk management thất bại nếu risk đã được nhận diện và nằm trong tolerance; lợi nhuận cũng không chứng minh quy trình tốt.","trap":"Phải phân biệt process quality với realized outcome."},{"heading":"Continuous cycle","body":"Risk management là vòng lặp: xác định mục tiêu và tolerance, nhận diện drivers, đo exposure, kiểm tra limits, điều chỉnh và theo dõi lại. Khi trạng thái thị trường, liabilities hoặc mục tiêu đổi, assumptions và phản ứng phải được cập nhật.","trap":"Không coi risk report một lần là hoàn tất quy trình."}],"formulas":[{"name":"Risk management cycle","expr":"Tolerance → identify → measure → monitor → modify → review","meaning":"Lựa chọn và quản lý risk phù hợp mục tiêu; phản hồi liên tục.","conditions":"Không phải tối thiểu hóa risk một cách vô điều kiện."}],"examples":[{"question_en":"A fund loses 4% after a pre-specified stress event. Its tolerance permitted a loss of up to 8% in that scenario. Was the loss itself evidence of failed risk management?","steps_vi":["So sánh actual event với scenario, assumptions và approved limits; không chỉ nhìn dấu âm của return.","Nếu exposure được chọn hợp lý và process thực thi đúng, loss trong tolerance không tự chứng minh failure. Vẫn review model và execution."],"answer":"No; evaluate the process and exposures ex ante.","check":"Original conceptual case; conclusions conditional on the stated facts."}],"questions":[{"stem_en":"Which best describes risk exposure?","options":["Only the actual loss already realized","A guarantee that the worst outcome will occur","The extent to which value is sensitive to an underlying uncertainty"],"correct":2,"why_vi":"Risk là exposure to uncertainty, bao gồm cả kết quả thuận lợi và bất lợi; risk exposure mô tả mức độ giá trị hoặc mục tiêu nhạy với underlying risk. Ví dụ doanh nghiệp nhập khẩu có exposure ngoại tệ ngay cả khi tỷ giá chưa biến động.","trap_vi":"Risk driver khác exposure: biến động tỷ giá là driver, nghĩa vụ ngoại tệ là exposure."},{"stem_en":"The primary objective of risk management is to:","options":["eliminate every source of uncertainty.","maximize the number of hedging contracts.","manage exposures in line with risk tolerance while pursuing objectives."],"correct":2,"why_vi":"Risk management là quy trình xác định risk tolerance, đo lường, giám sát và điều chỉnh exposures để phù hợp tolerance trong khi theo đuổi mục tiêu. Mục tiêu là lựa chọn rủi ro được bù đắp và kiểm soát rủi ro không mong muốn, không phải giảm mọi rủi ro về zero.","trap_vi":"Một doanh nghiệp tránh mọi uncertainty có thể từ bỏ cơ hội tạo giá trị."},{"stem_en":"A portfolio incurs a loss within its pre-approved stress tolerance. Which conclusion is most appropriate?","options":["The process necessarily failed because any loss is unacceptable.","The loss alone does not establish that risk management failed.","The tolerance should automatically be abandoned."],"correct":1,"why_vi":"Quy trình tốt đánh giá trước phân phối kết quả, lựa chọn exposure và xây kế hoạch ứng phó. Kết quả lỗ sau một cú sốc không tự chứng minh risk management thất bại nếu risk đã được nhận diện và nằm trong tolerance; lợi nhuận cũng không chứng minh quy trình tốt.","trap_vi":"Phải phân biệt process quality với realized outcome."},{"stem_en":"After an exposure has been hedged, the next appropriate action is generally to:","options":["continue monitoring residual risk and hedge effectiveness.","assume the risk is permanently eliminated.","stop reporting until the hedge expires."],"correct":0,"why_vi":"Risk management là vòng lặp: xác định mục tiêu và tolerance, nhận diện drivers, đo exposure, kiểm tra limits, điều chỉnh và theo dõi lại. Khi trạng thái thị trường, liabilities hoặc mục tiêu đổi, assumptions và phản ứng phải được cập nhật.","trap_vi":"Không coi risk report một lần là hoàn tất quy trình."}],"cards":[{"front_en":"Risk and risk exposure","back_vi":"Risk là exposure to uncertainty, bao gồm cả kết quả thuận lợi và bất lợi; risk exposure mô tả mức độ giá trị hoặc mục tiêu nhạy với underlying risk. Ví dụ doanh nghiệp nhập khẩu có exposure ngoại tệ ngay cả khi tỷ giá chưa biến động. | Exam trap: Risk driver khác exposure: biến động tỷ giá là driver, nghĩa vụ ngoại tệ là exposure."},{"front_en":"Definition of risk management","back_vi":"Risk management là quy trình xác định risk tolerance, đo lường, giám sát và điều chỉnh exposures để phù hợp tolerance trong khi theo đuổi mục tiêu. Mục tiêu là lựa chọn rủi ro được bù đắp và kiểm soát rủi ro không mong muốn, không phải giảm mọi rủi ro về zero. | Exam trap: Một doanh nghiệp tránh mọi uncertainty có thể từ bỏ cơ hội tạo giá trị."},{"front_en":"Ex ante versus ex post","back_vi":"Quy trình tốt đánh giá trước phân phối kết quả, lựa chọn exposure và xây kế hoạch ứng phó. Kết quả lỗ sau một cú sốc không tự chứng minh risk management thất bại nếu risk đã được nhận diện và nằm trong tolerance; lợi nhuận cũng không chứng minh quy trình tốt. | Exam trap: Phải phân biệt process quality với realized outcome."},{"front_en":"Continuous cycle","back_vi":"Risk management là vòng lặp: xác định mục tiêu và tolerance, nhận diện drivers, đo exposure, kiểm tra limits, điều chỉnh và theo dõi lại. Khi trạng thái thị trường, liabilities hoặc mục tiêu đổi, assumptions và phản ứng phải được cập nhật. | Exam trap: Không coi risk report một lần là hoàn tất quy trình."},{"front_en":"Risk management cycle — formula or framework?","back_vi":"Tolerance → identify → measure → monitor → modify → review · Lựa chọn và quản lý risk phù hợp mục tiêu; phản hồi liên tục. · Không phải tối thiểu hóa risk một cách vô điều kiện."}]},{"id":"CFA26-09-06-LOS02","letter":"b","title_en":"Risk Management Framework","outcome_en":"describe features of a risk management framework","overview_vi":"Bài học 6.b: Risk Management Framework. Học bản chất khái niệm, điều kiện áp dụng, so sánh và giải quyết tình huống. Công thức ghi supplement là bài luyện thêm; câu hỏi tiếng Anh do dự án tự biên soạn.","source":[{"id":"CFA Institute Curriculum 2026 — Portfolio Management Volume 9","pages":"Physical PDF p. 249 (LOS), 253–259 (content)"},{"id":"Kaplan SchweserNotes 2026 — Book 4, Reading 88","pages":"Physical PDF pp. 144–146"},{"id":"SAPP CFA Level I 2026 — Portfolio Management slides","pages":"Physical PDF pp. 215–218"}],"sections":[{"heading":"Seven framework elements","body":"Risk management framework gồm governance; identification and measurement; infrastructure; defined policies and processes; monitoring, mitigation and management; communications; strategic analysis or integration. Các yếu tố liên kết thành hệ thống hỗ trợ quyết định phù hợp mục tiêu doanh nghiệp.","trap":"Không đồng nhất framework với risk model hoặc phần mềm riêng lẻ."},{"heading":"Governance in framework","body":"Governance đặt hướng từ cấp cao: mục tiêu, quyền hạn, oversight và tolerance. Các bộ phận triển khai chuyển định hướng thành limits và quy trình. Framework cần phản ánh loại hoạt động, nguồn lực và rủi ro của tổ chức, không áp một thiết kế đồng nhất cho mọi nơi.","trap":"Governance khác daily position monitoring."},{"heading":"Identification and measurement","body":"Identification and measurement gồm cả định tính lẫn định lượng: lập inventory exposures, nhận diện drivers và dependencies, chọn metrics phù hợp, kiểm tra assumptions và uncertainty. Các rủi ro khó lượng hóa vẫn phải được nhận diện.","trap":"Không bỏ operational/legal risk chỉ vì không có giá thị trường."},{"heading":"Risk infrastructure","body":"Infrastructure là nhân sự, dữ liệu, hệ thống công nghệ, mô hình, quy trình thu thập và kiểm soát chất lượng cần để theo dõi profile. Dữ liệu phải nhất quán giữa đơn vị, có thể tổng hợp và truy nguyên; năng lực con người cần phù hợp độ phức tạp.","trap":"Infrastructure hỗ trợ framework, không tự thay thế judgment."},{"heading":"Policies and processes","body":"Policies and processes chuyển governance thành hướng dẫn vận hành: ai được phê duyệt, limits, exception process, escalation, kiểm soát và tài liệu. Các quy tắc phải thực thi và cập nhật khi mô hình kinh doanh thay đổi.","trap":"Board-level tolerance không phải chi tiết từng giao dịch."},{"heading":"Monitoring and mitigation","body":"Monitoring theo dõi exposure, drivers và giới hạn; mitigation điều chỉnh positions, insurance, capital hoặc quy trình khi cần. Theo dõi cả residual risk và effectiveness của biện pháp, không chỉ ghi nhận việc đã thực hiện hedge.","trap":"Không xử lý breach bằng cách tự ý sửa limit để che exposure."},{"heading":"Communication and feedback","body":"Risk reports cần đúng người, đúng thời điểm, dễ hiểu, có thông tin về mức độ, assumptions, exceptions và uncertainty. Feedback từ decision makers giúp chỉnh policies, metrics và phản ứng. Báo cáo phải có khả năng dẫn đến hành động.","trap":"Không gửi một con số VaR không có horizon/confidence rồi xem là đầy đủ."},{"heading":"Strategic integration","body":"Strategic analysis tích hợp risk-return vào phân bổ nguồn lực, định giá sản phẩm, kế hoạch và đánh giá giá trị toàn tổ chức. Nhờ đó có thể tăng exposure hấp dẫn, giảm rủi ro không được bù đắp, xem xét capital và capacity trước quyết định.","trap":"Risk management không chỉ là chức năng kiểm soát hậu kiểm."}],"formulas":[{"name":"Framework checklist","expr":"Governance; identification/measurement; infrastructure; policies/processes; monitoring/mitigation/management; communication; strategic integration","meaning":"Bảy cấu phần của framework trong CFAI.","conditions":"Có overlap trong thực tế; không thay thế bằng một metric."},{"name":"Breach workflow","expr":"Detect → escalate → evaluate → act → monitor residual risk","meaning":"Kiểm tra vi phạm giới hạn và hành động đúng authority.","conditions":"Không sửa limits tùy ý để hợp thức hóa breach."}],"examples":[{"question_en":"A risk system reports positions daily, but limit breaches are not escalated and new investment decisions ignore the reports. Identify the framework gaps.","steps_vi":["Có infrastructure/measurement nhưng thiếu communication và mitigation workflow, escalation policy không được thực thi.","Strategic integration cũng thiếu vì risk output không ảnh hưởng allocation; cần xác định authority, accountability và feedback."],"answer":"Communication, monitoring/mitigation, policies and strategic integration are deficient.","check":"Original conceptual case; conclusions conditional on the stated facts."}],"questions":[{"stem_en":"Which is a component of a complete risk management framework?","options":["A guarantee of positive realized returns","Delegation of all risk decisions to traders","Strategic integration of risk analysis into decisions"],"correct":2,"why_vi":"Risk management framework gồm governance; identification and measurement; infrastructure; defined policies and processes; monitoring, mitigation and management; communications; strategic analysis or integration. Các yếu tố liên kết thành hệ thống hỗ trợ quyết định phù hợp mục tiêu doanh nghiệp.","trap_vi":"Không đồng nhất framework với risk model hoặc phần mềm riêng lẻ."},{"stem_en":"Which framework element establishes the organization's top-level risk direction?","options":["Risk governance","Risk infrastructure","Transaction settlement"],"correct":0,"why_vi":"Governance đặt hướng từ cấp cao: mục tiêu, quyền hạn, oversight và tolerance. Các bộ phận triển khai chuyển định hướng thành limits và quy trình. Framework cần phản ánh loại hoạt động, nguồn lực và rủi ro của tổ chức, không áp một thiết kế đồng nhất cho mọi nơi.","trap_vi":"Governance khác daily position monitoring."},{"stem_en":"Which action belongs primarily to risk identification and measurement?","options":["Approving the enterprise's ultimate strategic goals","Mapping exposures to relevant risk drivers and estimating their sensitivities","Executing an insurance contract without exposure analysis"],"correct":1,"why_vi":"Identification and measurement gồm cả định tính lẫn định lượng: lập inventory exposures, nhận diện drivers và dependencies, chọn metrics phù hợp, kiểm tra assumptions và uncertainty. Các rủi ro khó lượng hóa vẫn phải được nhận diện.","trap_vi":"Không bỏ operational/legal risk chỉ vì không có giá thị trường."},{"stem_en":"A firm invests in reconciled position data, pricing systems, and qualified risk analysts. This improves:","options":["risk tolerance directly.","the definition of market risk.","risk infrastructure."],"correct":2,"why_vi":"Infrastructure là nhân sự, dữ liệu, hệ thống công nghệ, mô hình, quy trình thu thập và kiểm soát chất lượng cần để theo dõi profile. Dữ liệu phải nhất quán giữa đơn vị, có thể tổng hợp và truy nguyên; năng lực con người cần phù hợp độ phức tạp.","trap_vi":"Infrastructure hỗ trợ framework, không tự thay thế judgment."},{"stem_en":"Which element specifies approval authority and escalation procedures for limit breaches?","options":["Risk drivers","Expected utility","Defined risk policies and processes"],"correct":2,"why_vi":"Policies and processes chuyển governance thành hướng dẫn vận hành: ai được phê duyệt, limits, exception process, escalation, kiểm soát và tài liệu. Các quy tắc phải thực thi và cập nhật khi mô hình kinh doanh thay đổi.","trap_vi":"Board-level tolerance không phải chi tiết từng giao dịch."},{"stem_en":"A desk exceeds its approved exposure limit. The monitoring and mitigation process should first ensure that:","options":["the limit is silently increased to match the exposure.","the exposure is removed from the report.","the breach is identified, escalated, and addressed under policy."],"correct":2,"why_vi":"Monitoring theo dõi exposure, drivers và giới hạn; mitigation điều chỉnh positions, insurance, capital hoặc quy trình khi cần. Theo dõi cả residual risk và effectiveness của biện pháp, không chỉ ghi nhận việc đã thực hiện hedge.","trap_vi":"Không xử lý breach bằng cách tự ý sửa limit để che exposure."},{"stem_en":"Effective risk communication is most likely characterized by:","options":["reporting only profitable positions.","timely reporting with clear context and feedback to decision makers.","replacing oversight with a single annual presentation."],"correct":1,"why_vi":"Risk reports cần đúng người, đúng thời điểm, dễ hiểu, có thông tin về mức độ, assumptions, exceptions và uncertainty. Feedback từ decision makers giúp chỉnh policies, metrics và phản ứng. Báo cáo phải có khả năng dẫn đến hành động.","trap_vi":"Không gửi một con số VaR không có horizon/confidence rồi xem là đầy đủ."},{"stem_en":"Which action best illustrates strategic integration of risk analysis?","options":["Calculating yesterday's volatility without using it in decisions","Approving every high-return activity regardless of tolerance","Using risk-adjusted economics to choose between competing business investments"],"correct":2,"why_vi":"Strategic analysis tích hợp risk-return vào phân bổ nguồn lực, định giá sản phẩm, kế hoạch và đánh giá giá trị toàn tổ chức. Nhờ đó có thể tăng exposure hấp dẫn, giảm rủi ro không được bù đắp, xem xét capital và capacity trước quyết định.","trap_vi":"Risk management không chỉ là chức năng kiểm soát hậu kiểm."}],"cards":[{"front_en":"Seven framework elements","back_vi":"Risk management framework gồm governance; identification and measurement; infrastructure; defined policies and processes; monitoring, mitigation and management; communications; strategic analysis or integration. Các yếu tố liên kết thành hệ thống hỗ trợ quyết định phù hợp mục tiêu doanh nghiệp. | Exam trap: Không đồng nhất framework với risk model hoặc phần mềm riêng lẻ."},{"front_en":"Governance in framework","back_vi":"Governance đặt hướng từ cấp cao: mục tiêu, quyền hạn, oversight và tolerance. Các bộ phận triển khai chuyển định hướng thành limits và quy trình. Framework cần phản ánh loại hoạt động, nguồn lực và rủi ro của tổ chức, không áp một thiết kế đồng nhất cho mọi nơi. | Exam trap: Governance khác daily position monitoring."},{"front_en":"Identification and measurement","back_vi":"Identification and measurement gồm cả định tính lẫn định lượng: lập inventory exposures, nhận diện drivers và dependencies, chọn metrics phù hợp, kiểm tra assumptions và uncertainty. Các rủi ro khó lượng hóa vẫn phải được nhận diện. | Exam trap: Không bỏ operational/legal risk chỉ vì không có giá thị trường."},{"front_en":"Risk infrastructure","back_vi":"Infrastructure là nhân sự, dữ liệu, hệ thống công nghệ, mô hình, quy trình thu thập và kiểm soát chất lượng cần để theo dõi profile. Dữ liệu phải nhất quán giữa đơn vị, có thể tổng hợp và truy nguyên; năng lực con người cần phù hợp độ phức tạp. | Exam trap: Infrastructure hỗ trợ framework, không tự thay thế judgment."},{"front_en":"Policies and processes","back_vi":"Policies and processes chuyển governance thành hướng dẫn vận hành: ai được phê duyệt, limits, exception process, escalation, kiểm soát và tài liệu. Các quy tắc phải thực thi và cập nhật khi mô hình kinh doanh thay đổi. | Exam trap: Board-level tolerance không phải chi tiết từng giao dịch."},{"front_en":"Monitoring and mitigation","back_vi":"Monitoring theo dõi exposure, drivers và giới hạn; mitigation điều chỉnh positions, insurance, capital hoặc quy trình khi cần. Theo dõi cả residual risk và effectiveness của biện pháp, không chỉ ghi nhận việc đã thực hiện hedge. | Exam trap: Không xử lý breach bằng cách tự ý sửa limit để che exposure."},{"front_en":"Communication and feedback","back_vi":"Risk reports cần đúng người, đúng thời điểm, dễ hiểu, có thông tin về mức độ, assumptions, exceptions và uncertainty. Feedback từ decision makers giúp chỉnh policies, metrics và phản ứng. Báo cáo phải có khả năng dẫn đến hành động. | Exam trap: Không gửi một con số VaR không có horizon/confidence rồi xem là đầy đủ."},{"front_en":"Strategic integration","back_vi":"Strategic analysis tích hợp risk-return vào phân bổ nguồn lực, định giá sản phẩm, kế hoạch và đánh giá giá trị toàn tổ chức. Nhờ đó có thể tăng exposure hấp dẫn, giảm rủi ro không được bù đắp, xem xét capital và capacity trước quyết định. | Exam trap: Risk management không chỉ là chức năng kiểm soát hậu kiểm."},{"front_en":"Framework checklist — formula or framework?","back_vi":"Governance; identification/measurement; infrastructure; policies/processes; monitoring/mitigation/management; communication; strategic integration · Bảy cấu phần của framework trong CFAI. · Có overlap trong thực tế; không thay thế bằng một metric."},{"front_en":"Breach workflow — formula or framework?","back_vi":"Detect → escalate → evaluate → act → monitor residual risk · Kiểm tra vi phạm giới hạn và hành động đúng authority. · Không sửa limits tùy ý để hợp thức hóa breach."}]},{"id":"CFA26-09-06-LOS03","letter":"c","title_en":"Risk Governance","outcome_en":"define risk governance and describe elements of effective risk governance","overview_vi":"Bài học 6.c: Risk Governance. Học bản chất khái niệm, điều kiện áp dụng, so sánh và giải quyết tình huống. Công thức ghi supplement là bài luyện thêm; câu hỏi tiếng Anh do dự án tự biên soạn.","source":[{"id":"CFA Institute Curriculum 2026 — Portfolio Management Volume 9","pages":"Physical PDF p. 249 (LOS), 253–254,259–263 (content)"},{"id":"Kaplan SchweserNotes 2026 — Book 4, Reading 88","pages":"Physical PDF pp. 145–147"},{"id":"SAPP CFA Level I 2026 — Portfolio Management slides","pages":"Physical PDF pp. 219–220"}],"sections":[{"heading":"Risk governance definition","body":"Risk governance là quá trình top-down định hướng và giám sát quản trị rủi ro để phục vụ toàn enterprise. Governing body xác lập mục tiêu, tolerance, phân quyền và yêu cầu accountability; management vận hành framework phù hợp. Trách nhiệm fiduciary và regulatory có thể ảnh hưởng thiết kế.","trap":"Không chuyển toàn bộ trách nhiệm giám sát cuối cùng cho CRO."},{"heading":"Enterprise risk management","body":"ERM xem rủi ro của toàn tổ chức, không chỉ tối ưu từng silo. Exposures có thể bù trừ, cộng hưởng hoặc cùng phụ thuộc driver; quyết định tốt riêng một desk có thể gây thiệt hại cho doanh nghiệp nếu bỏ liabilities hay cash needs chung.","trap":"Không cộng máy móc standalone risk của các bộ phận."},{"heading":"CRO and risk committee","body":"Chief risk officer thường tổ chức đo lường, giám sát, phối hợp và báo cáo rủi ro; risk committee tạo diễn đàn để lãnh đạo xét risk profile và trade-offs. Cần quyền tiếp cận cấp quản trị phù hợp và khả năng thách thức đơn vị kinh doanh. Cơ cấu cụ thể tùy tổ chức.","trap":"CRO không thay board đặt mọi mục tiêu, cũng không nên chỉ phục vụ doanh thu desk."},{"heading":"Risk culture and incentives","body":"Risk culture thể hiện qua hành vi, transparency và accountability. Thưởng chỉ theo short-term gross return có thể thúc đẩy hidden tail risk; đánh giá hiệu quả nên xét risk, horizon và capital. Staff phải biết giới hạn, báo cáo vi phạm và được khuyến khích phản hồi trung thực.","trap":"Chính sách trên giấy không bảo đảm thực thi nếu incentives mâu thuẫn."},{"heading":"Oversight versus operations","body":"Board phê duyệt tolerance và giám sát hiệu quả; management đặt policy chi tiết, nguồn lực và thực hiện; risk staff đo và challenge exposures; business units vẫn sở hữu rủi ro do hoạt động của mình tạo ra. Cần phân biệt authority và accountability.","trap":"Không giả định đơn vị risk độc lập có nghĩa desk không chịu trách nhiệm."}],"formulas":[{"name":"Governance hierarchy","expr":"Board sets tolerance → management implements → CRO/committee monitor/challenge → feedback","meaning":"Enterprise perspective, phân quyền và trách nhiệm.","conditions":"Cơ cấu tùy tổ chức; board vẫn chịu oversight."}],"examples":[{"question_en":"Two desks separately hedge exposures, but their offsetting positions increase external transaction and funding costs for the firm. What governance response is appropriate?","steps_vi":["Đo exposure tổng enterprise, xem offset internal và netting khả thi thay vì chỉ tối ưu từng desk.","Board/management đặt policy cho aggregate risk; CRO và committee phối hợp, không bỏ qua legal entities hoặc collateral restrictions."],"answer":"Enterprise-wide governance and coordinated risk management.","check":"Original conceptual case; conclusions conditional on the stated facts."}],"questions":[{"stem_en":"Who normally sets an organization's high-level risk tolerance?","options":["The governing body or board","An individual portfolio trader","The external pricing-data vendor"],"correct":0,"why_vi":"Risk governance là quá trình top-down định hướng và giám sát quản trị rủi ro để phục vụ toàn enterprise. Governing body xác lập mục tiêu, tolerance, phân quyền và yêu cầu accountability; management vận hành framework phù hợp. Trách nhiệm fiduciary và regulatory có thể ảnh hưởng thiết kế.","trap_vi":"Không chuyển toàn bộ trách nhiệm giám sát cuối cùng cho CRO."},{"stem_en":"Why is an enterprise-wide risk perspective important?","options":["Each business unit's risks are necessarily independent.","Risks across units may interact and affect total enterprise value.","The largest standalone risk always determines every decision."],"correct":1,"why_vi":"ERM xem rủi ro của toàn tổ chức, không chỉ tối ưu từng silo. Exposures có thể bù trừ, cộng hưởng hoặc cùng phụ thuộc driver; quyết định tốt riêng một desk có thể gây thiệt hại cho doanh nghiệp nếu bỏ liabilities hay cash needs chung.","trap_vi":"Không cộng máy móc standalone risk của các bộ phận."},{"stem_en":"Which arrangement most supports effective risk governance?","options":["Risk oversight controlled exclusively by revenue-producing traders","No escalation route for risk-limit breaches","A CRO with access to senior governance and a risk committee reviewing exposures"],"correct":2,"why_vi":"Chief risk officer thường tổ chức đo lường, giám sát, phối hợp và báo cáo rủi ro; risk committee tạo diễn đàn để lãnh đạo xét risk profile và trade-offs. Cần quyền tiếp cận cấp quản trị phù hợp và khả năng thách thức đơn vị kinh doanh. Cơ cấu cụ thể tùy tổ chức.","trap_vi":"CRO không thay board đặt mọi mục tiêu, cũng không nên chỉ phục vụ doanh thu desk."},{"stem_en":"Which compensation design is most likely to undermine a sound risk culture?","options":["Evaluation incorporating risk and longer-term outcomes","Rewards based solely on short-term revenue without regard to risk","Accountability for escalation of material limit breaches"],"correct":1,"why_vi":"Risk culture thể hiện qua hành vi, transparency và accountability. Thưởng chỉ theo short-term gross return có thể thúc đẩy hidden tail risk; đánh giá hiệu quả nên xét risk, horizon và capital. Staff phải biết giới hạn, báo cáo vi phạm và được khuyến khích phản hồi trung thực.","trap_vi":"Chính sách trên giấy không bảo đảm thực thi nếu incentives mâu thuẫn."},{"stem_en":"Which activity is primarily an operating management responsibility rather than high-level governance?","options":["Establishing the enterprise's ultimate risk direction","Overseeing management on behalf of the governing body","Implementing detailed procedures consistent with board-approved tolerance"],"correct":2,"why_vi":"Board phê duyệt tolerance và giám sát hiệu quả; management đặt policy chi tiết, nguồn lực và thực hiện; risk staff đo và challenge exposures; business units vẫn sở hữu rủi ro do hoạt động của mình tạo ra. Cần phân biệt authority và accountability.","trap_vi":"Không giả định đơn vị risk độc lập có nghĩa desk không chịu trách nhiệm."}],"cards":[{"front_en":"Risk governance definition","back_vi":"Risk governance là quá trình top-down định hướng và giám sát quản trị rủi ro để phục vụ toàn enterprise. Governing body xác lập mục tiêu, tolerance, phân quyền và yêu cầu accountability; management vận hành framework phù hợp. Trách nhiệm fiduciary và regulatory có thể ảnh hưởng thiết kế. | Exam trap: Không chuyển toàn bộ trách nhiệm giám sát cuối cùng cho CRO."},{"front_en":"Enterprise risk management","back_vi":"ERM xem rủi ro của toàn tổ chức, không chỉ tối ưu từng silo. Exposures có thể bù trừ, cộng hưởng hoặc cùng phụ thuộc driver; quyết định tốt riêng một desk có thể gây thiệt hại cho doanh nghiệp nếu bỏ liabilities hay cash needs chung. | Exam trap: Không cộng máy móc standalone risk của các bộ phận."},{"front_en":"CRO and risk committee","back_vi":"Chief risk officer thường tổ chức đo lường, giám sát, phối hợp và báo cáo rủi ro; risk committee tạo diễn đàn để lãnh đạo xét risk profile và trade-offs. Cần quyền tiếp cận cấp quản trị phù hợp và khả năng thách thức đơn vị kinh doanh. Cơ cấu cụ thể tùy tổ chức. | Exam trap: CRO không thay board đặt mọi mục tiêu, cũng không nên chỉ phục vụ doanh thu desk."},{"front_en":"Risk culture and incentives","back_vi":"Risk culture thể hiện qua hành vi, transparency và accountability. Thưởng chỉ theo short-term gross return có thể thúc đẩy hidden tail risk; đánh giá hiệu quả nên xét risk, horizon và capital. Staff phải biết giới hạn, báo cáo vi phạm và được khuyến khích phản hồi trung thực. | Exam trap: Chính sách trên giấy không bảo đảm thực thi nếu incentives mâu thuẫn."},{"front_en":"Oversight versus operations","back_vi":"Board phê duyệt tolerance và giám sát hiệu quả; management đặt policy chi tiết, nguồn lực và thực hiện; risk staff đo và challenge exposures; business units vẫn sở hữu rủi ro do hoạt động của mình tạo ra. Cần phân biệt authority và accountability. | Exam trap: Không giả định đơn vị risk độc lập có nghĩa desk không chịu trách nhiệm."},{"front_en":"Governance hierarchy — formula or framework?","back_vi":"Board sets tolerance → management implements → CRO/committee monitor/challenge → feedback · Enterprise perspective, phân quyền và trách nhiệm. · Cơ cấu tùy tổ chức; board vẫn chịu oversight."}]},{"id":"CFA26-09-06-LOS04","letter":"d","title_en":"Risk Tolerance","outcome_en":"explain how risk tolerance affects risk management","overview_vi":"Bài học 6.d: Risk Tolerance. Học bản chất khái niệm, điều kiện áp dụng, so sánh và giải quyết tình huống. Công thức ghi supplement là bài luyện thêm; câu hỏi tiếng Anh do dự án tự biên soạn.","source":[{"id":"CFA Institute Curriculum 2026 — Portfolio Management Volume 9","pages":"Physical PDF p. 249 (LOS), 263–264 (content)"},{"id":"Kaplan SchweserNotes 2026 — Book 4, Reading 88","pages":"Physical PDF pp. 146–147"},{"id":"SAPP CFA Level I 2026 — Portfolio Management slides","pages":"Physical PDF pp. 221"}],"sections":[{"heading":"Risk tolerance","body":"Risk tolerance xác định loại rủi ro nào có thể chấp nhận, loại nào không, và mức exposure tổng thể có thể chịu để đạt mục tiêu. Nó phản ánh financial resources, liabilities, strategy, stakeholders và khả năng tồn tại dưới stress. Tolerance cần cụ thể đủ để triển khai.","trap":"Không chỉ dựa vào mong muốn return hoặc độ ưa rủi ro của CEO."},{"heading":"Capacity and survival","body":"Tolerance phải tính khả năng hấp thụ loss, đáp ứng obligations và duy trì hoạt động trong adverse scenarios. Một pension plan thiếu funding hoặc doanh nghiệp có cash obligations gần hạn có thể cần giới hạn khác với tổ chức dư capital; không chỉ nhìn volatility tài sản.","trap":"Tolerance và willingness không luôn giống financial capacity."},{"heading":"Tolerance operationalization","body":"Tolerance định tính cần chuyển thành risk limits, thresholds, capital allocation và kịch bản stress phù hợp. Một số rủi ro có thể bị cấm vì không liên quan core business; loại khác được chấp nhận để thu risk premium. Limits nên phản ánh mục tiêu tổng thể và theo dõi được.","trap":"Không dùng cùng một mức VaR cho mọi đơn vị mà bỏ đặc điểm rủi ro."},{"heading":"Review and escalation","body":"Tolerance cần được xem xét khi mục tiêu, capital, liabilities, business mix hoặc môi trường đổi. Breach cần escalation và xử lý theo policy; không mặc nhiên điều chỉnh tolerance sau khi xảy ra loss chỉ để hợp thức hóa quyết định cũ.","trap":"Không nhầm review hợp lệ với retroactive rationalization."}],"formulas":[{"name":"Risk tolerance framework","expr":"Objectives + capacity + acceptable risk types + limits","meaning":"Xác định loại risk chấp nhận và mức exposure tổng thể.","conditions":"Xem liabilities, funding và stress; định kỳ review."}],"examples":[{"question_en":"A pension fund's liabilities become payable earlier while the asset mix is unchanged. What should management review?","steps_vi":["Cash-flow mismatch và khả năng thanh toán trong stress tăng dù historical volatility của assets không đổi.","Review risk tolerance, funding và liquidity limits; trình cấp có thẩm quyền nếu cần đổi policy."],"answer":"Reassess tolerance in light of liabilities and financial capacity.","check":"Original conceptual case; conclusions conditional on the stated facts."}],"questions":[{"stem_en":"An organization's risk tolerance should primarily reflect:","options":["the highest return recently achieved by a competitor.","the preferences of one trader regardless of liabilities.","its objectives, financial capacity, and acceptable exposures."],"correct":2,"why_vi":"Risk tolerance xác định loại rủi ro nào có thể chấp nhận, loại nào không, và mức exposure tổng thể có thể chịu để đạt mục tiêu. Nó phản ánh financial resources, liabilities, strategy, stakeholders và khả năng tồn tại dưới stress. Tolerance cần cụ thể đủ để triển khai.","trap_vi":"Không chỉ dựa vào mong muốn return hoặc độ ưa rủi ro của CEO."},{"stem_en":"A firm with substantial near-term obligations should assess risk tolerance by emphasizing:","options":["its ability to meet obligations under adverse scenarios.","the average return of its best asset alone.","the fact that all losses are temporary."],"correct":0,"why_vi":"Tolerance phải tính khả năng hấp thụ loss, đáp ứng obligations và duy trì hoạt động trong adverse scenarios. Một pension plan thiếu funding hoặc doanh nghiệp có cash obligations gần hạn có thể cần giới hạn khác với tổ chức dư capital; không chỉ nhìn volatility tài sản.","trap_vi":"Tolerance và willingness không luôn giống financial capacity."},{"stem_en":"Which action best translates risk tolerance into practical controls?","options":["Define exposure limits and stress thresholds consistent with objectives","Use only the most recent accounting profit","Remove all measures for difficult-to-quantify risks"],"correct":0,"why_vi":"Tolerance định tính cần chuyển thành risk limits, thresholds, capital allocation và kịch bản stress phù hợp. Một số rủi ro có thể bị cấm vì không liên quan core business; loại khác được chấp nhận để thu risk premium. Limits nên phản ánh mục tiêu tổng thể và theo dõi được.","trap_vi":"Không dùng cùng một mức VaR cho mọi đơn vị mà bỏ đặc điểm rủi ro."},{"stem_en":"Which event most clearly warrants reassessment of enterprise risk tolerance?","options":["A desire to conceal an existing limit breach","A material change in liabilities and available capital","A small price fluctuation already within approved assumptions"],"correct":1,"why_vi":"Tolerance cần được xem xét khi mục tiêu, capital, liabilities, business mix hoặc môi trường đổi. Breach cần escalation và xử lý theo policy; không mặc nhiên điều chỉnh tolerance sau khi xảy ra loss chỉ để hợp thức hóa quyết định cũ.","trap_vi":"Không nhầm review hợp lệ với retroactive rationalization."}],"cards":[{"front_en":"Risk tolerance","back_vi":"Risk tolerance xác định loại rủi ro nào có thể chấp nhận, loại nào không, và mức exposure tổng thể có thể chịu để đạt mục tiêu. Nó phản ánh financial resources, liabilities, strategy, stakeholders và khả năng tồn tại dưới stress. Tolerance cần cụ thể đủ để triển khai. | Exam trap: Không chỉ dựa vào mong muốn return hoặc độ ưa rủi ro của CEO."},{"front_en":"Capacity and survival","back_vi":"Tolerance phải tính khả năng hấp thụ loss, đáp ứng obligations và duy trì hoạt động trong adverse scenarios. Một pension plan thiếu funding hoặc doanh nghiệp có cash obligations gần hạn có thể cần giới hạn khác với tổ chức dư capital; không chỉ nhìn volatility tài sản. | Exam trap: Tolerance và willingness không luôn giống financial capacity."},{"front_en":"Tolerance operationalization","back_vi":"Tolerance định tính cần chuyển thành risk limits, thresholds, capital allocation và kịch bản stress phù hợp. Một số rủi ro có thể bị cấm vì không liên quan core business; loại khác được chấp nhận để thu risk premium. Limits nên phản ánh mục tiêu tổng thể và theo dõi được. | Exam trap: Không dùng cùng một mức VaR cho mọi đơn vị mà bỏ đặc điểm rủi ro."},{"front_en":"Review and escalation","back_vi":"Tolerance cần được xem xét khi mục tiêu, capital, liabilities, business mix hoặc môi trường đổi. Breach cần escalation và xử lý theo policy; không mặc nhiên điều chỉnh tolerance sau khi xảy ra loss chỉ để hợp thức hóa quyết định cũ. | Exam trap: Không nhầm review hợp lệ với retroactive rationalization."},{"front_en":"Risk tolerance framework — formula or framework?","back_vi":"Objectives + capacity + acceptable risk types + limits · Xác định loại risk chấp nhận và mức exposure tổng thể. · Xem liabilities, funding và stress; định kỳ review."}]},{"id":"CFA26-09-06-LOS05","letter":"e","title_en":"Risk Budgeting","outcome_en":"describe risk budgeting and its role in risk governance","overview_vi":"Bài học 6.e: Risk Budgeting. Học bản chất khái niệm, điều kiện áp dụng, so sánh và giải quyết tình huống. Công thức ghi supplement là bài luyện thêm; câu hỏi tiếng Anh do dự án tự biên soạn.","source":[{"id":"CFA Institute Curriculum 2026 — Portfolio Management Volume 9","pages":"Physical PDF p. 249 (LOS), 264–267 (content)"},{"id":"Kaplan SchweserNotes 2026 — Book 4, Reading 88","pages":"Physical PDF pp. 147–148"},{"id":"SAPP CFA Level I 2026 — Portfolio Management slides","pages":"Physical PDF pp. 222–224"}],"sections":[{"heading":"Risk budgeting definition","body":"Risk budgeting phân bổ vốn hoặc hoạt động dựa trên risk characteristics và mức risk được chấp nhận, nhằm chuyển tolerance thành quyết định thực tế. Budget có thể một chiều (volatility, beta, VaR, scenario loss) hoặc nhiều chiều; không nhất thiết chỉ dùng tiền đầu tư.","trap":"Capital budget không tự nói exposure risk của từng vị thế."},{"heading":"Single-dimensional budget","body":"Một risk budget có thể dùng beta target cho equity exposure, volatility target cho portfolio hoặc VaR limit cho loss quantile. Chọn thước đo phù hợp đặc điểm và horizon; một metric đơn giản có thể hữu ích nhưng không phản ánh hết tail, liquidity và dependencies.","trap":"Cùng volatility target không bảo đảm cùng drawdown profile."},{"heading":"Risk factors versus asset classes","body":"Những tài sản khác tên có thể cùng phụ thuộc equity market, rates, credit spreads, FX, inflation hoặc liquidity. Risk factor budgeting xem sensitivity và contribution theo driver để nhận ra concentration ẩn; cùng danh mục có nhiều cách phân rã risk đồng thời.","trap":"Các cách phân rã theo factor có thể không cộng thành 100% nếu overlap hoặc metric khác nhau."},{"heading":"Risk contribution and diversification","body":"Đóng góp risk phụ thuộc weights, sensitivities và covariance. Với volatility, contribution của tài sản vào risk toàn danh mục có thể khác standalone volatility và thậm chí âm nếu hedge. Budget theo contribution nên dùng cùng metric và methodology.","trap":"Không cộng individual VaR/volatility trừ khi có giả định phụ thuộc thích hợp."},{"heading":"Governance bridge","body":"Risk budget tạo cầu nối giữa tolerance cấp enterprise và giới hạn phân bổ cho managers, desks hoặc factors. Nó hỗ trợ so sánh incremental risk với expected reward và cho phép nhận exposure có hiệu quả hơn trong mức risk tổng thể. Budget cần review khi correlation và exposures đổi.","trap":"Không nhất thiết dùng hết budget nếu cơ hội không hấp dẫn."}],"formulas":[{"name":"Risk budget dimensions","expr":"Volatility, beta, VaR, scenario loss, factor exposures","meaning":"Các metric có thể dùng đơn lẻ hoặc phối hợp để triển khai tolerance.","conditions":"Không trộn các đơn vị khác nhau trong một tổng vô nghĩa."},{"name":"Portfolio beta — supplemental","expr":"βp = Σ wiβi","meaning":"Beta exposure của portfolio theo weights.","conditions":"Cùng market benchmark và kỳ ước tính; bài luyện thêm."},{"name":"Volatility contribution — supplemental","expr":"RCi = wi(Σw)i / σp; ΣRCi = σp","meaning":"Risk contribution theo covariance matrix, không bằng capital weight.","conditions":"Differentiable volatility, σp dương; ví dụ mở rộng từ PM LM1."}],"examples":[{"question_en":"A portfolio reports equal weights in two funds but both primarily hold highly correlated equities. Is its risk budget necessarily diversified?","steps_vi":["Capital weights không phải factor risk allocation. Hai fund có thể tập trung vào cùng equity driver.","Phân tích aggregate beta, factor exposures, correlation và risk contributions trước khi điều chỉnh."],"answer":"No; risk-factor budgeting is more informative than vehicle counts.","check":"Original conceptual case; conclusions conditional on the stated facts."},{"question_en":"An equity portfolio allocates 40% to beta 1.5 and 60% to beta 0.7. What is portfolio beta?","steps_vi":["Bài luyện thêm: weighted beta dùng capital weights và cùng market proxy.","Thay số: .4 × 1.5+.6 × .7.","Kết quả: 1.02 ."],"answer":"1.02 ","check":"Original supplemental practice; Decimal compared with an alternate expression using Fraction (square root uses float in the second method)."},{"question_en":"A $20 million portfolio has a 6% stress-loss limit. Under a scenario it loses $900,000. How much unused stress-loss capacity remains, in dollars?","steps_vi":["Bài luyện thêm: đổi limit % sang dollars rồi trừ scenario loss.","Thay số: 20000000 × .06-900000.","Kết quả: 300,000.00 USD."],"answer":"300,000.00 USD","check":"Original supplemental practice; Decimal compared with an alternate expression using Fraction (square root uses float in the second method)."},{"question_en":"A two-asset portfolio has weights 0.5 each, volatilities 10% and 20%, and zero correlation. What is portfolio variance in squared decimal units, multiplied by 10,000?","steps_vi":["Bài luyện thêm: variance uses squared weights; covariance term = 0 vì correlation bằng zero. Scale 10,000 theo stem.","Thay số: 10000 × (.5^2 × .1^2+.5^2 × .2^2).","Kết quả: 125.00 ."],"answer":"125.00 ","check":"Original supplemental practice; Decimal compared with an alternate expression using Fraction (square root uses float in the second method)."},{"question_en":"A portfolio has $8 million in equity with beta 1.25 and $2 million in cash with beta zero. What is total portfolio beta?","steps_vi":["Bài luyện thêm: cash beta zero; equity weight 0.8.","Thay số: 8/10 × 1.25.","Kết quả: 1.00 ."],"answer":"1.00 ","check":"Original supplemental practice; Decimal compared with an alternate expression using Fraction (square root uses float in the second method)."}],"questions":[{"stem_en":"Risk budgeting is best described as allocating investments based on:","options":["their nominal capital weights alone.","the order in which positions were purchased.","their risk characteristics and permitted exposures."],"correct":2,"why_vi":"Risk budgeting phân bổ vốn hoặc hoạt động dựa trên risk characteristics và mức risk được chấp nhận, nhằm chuyển tolerance thành quyết định thực tế. Budget có thể một chiều (volatility, beta, VaR, scenario loss) hoặc nhiều chiều; không nhất thiết chỉ dùng tiền đầu tư.","trap_vi":"Capital budget không tự nói exposure risk của từng vị thế."},{"stem_en":"Which is an example of a single-dimensional risk budget?","options":["A target portfolio standard deviation","A list of asset names with no exposure measures","An unbounded allocation based on gross revenue"],"correct":0,"why_vi":"Một risk budget có thể dùng beta target cho equity exposure, volatility target cho portfolio hoặc VaR limit cho loss quantile. Chọn thước đo phù hợp đặc điểm và horizon; một metric đơn giản có thể hữu ích nhưng không phản ánh hết tail, liquidity và dependencies.","trap_vi":"Cùng volatility target không bảo đảm cùng drawdown profile."},{"stem_en":"A portfolio holds equities and equity-sensitive hedge funds. Which approach best detects their common exposure?","options":["Risk-factor budgeting","Counting legal vehicles only","Ignoring correlations between strategies"],"correct":0,"why_vi":"Những tài sản khác tên có thể cùng phụ thuộc equity market, rates, credit spreads, FX, inflation hoặc liquidity. Risk factor budgeting xem sensitivity và contribution theo driver để nhận ra concentration ẩn; cùng danh mục có nhiều cách phân rã risk đồng thời.","trap_vi":"Các cách phân rã theo factor có thể không cộng thành 100% nếu overlap hoặc metric khác nhau."},{"stem_en":"Why can two assets with equal capital weights consume different amounts of a volatility risk budget?","options":["Their volatilities and covariances with the portfolio differ.","Equal capital weights imply equal risk contributions.","Their acquisition dates are different."],"correct":0,"why_vi":"Đóng góp risk phụ thuộc weights, sensitivities và covariance. Với volatility, contribution của tài sản vào risk toàn danh mục có thể khác standalone volatility và thậm chí âm nếu hedge. Budget theo contribution nên dùng cùng metric và methodology.","trap_vi":"Không cộng individual VaR/volatility trừ khi có giả định phụ thuộc thích hợp."},{"stem_en":"The main governance role of a risk budget is to:","options":["guarantee that all business units earn the same return.","translate high-level tolerance into actionable allocation decisions.","replace all oversight and risk reporting."],"correct":1,"why_vi":"Risk budget tạo cầu nối giữa tolerance cấp enterprise và giới hạn phân bổ cho managers, desks hoặc factors. Nó hỗ trợ so sánh incremental risk với expected reward và cho phép nhận exposure có hiệu quả hơn trong mức risk tổng thể. Budget cần review khi correlation và exposures đổi.","trap_vi":"Không nhất thiết dùng hết budget nếu cơ hội không hấp dẫn."},{"stem_en":"An equity portfolio allocates 40% to beta 1.5 and 60% to beta 0.7. What is portfolio beta?","options":["1.10","2.20","1.02"],"correct":2,"why_vi":"Bài luyện thêm: weighted beta dùng capital weights và cùng market proxy. Thay số: .4 × 1.5+.6 × .7 = 1.02 .","trap_vi":"Không dùng simple mean hoặc tổng beta không có weights."},{"stem_en":"A $20 million portfolio has a 6% stress-loss limit. Under a scenario it loses $900,000. How much unused stress-loss capacity remains, in dollars?","options":["1,200,000.00 USD","2,100,000.00 USD","300,000.00 USD"],"correct":2,"why_vi":"Bài luyện thêm: đổi limit % sang dollars rồi trừ scenario loss. Thay số: 20000000 × .06-900000 = 300,000.00 USD.","trap_vi":"Không nhầm tổng budget với headroom."},{"stem_en":"A two-asset portfolio has weights 0.5 each, volatilities 10% and 20%, and zero correlation. What is portfolio variance in squared decimal units, multiplied by 10,000?","options":["225.00","125.00","500.00"],"correct":1,"why_vi":"Bài luyện thêm: variance uses squared weights; covariance term = 0 vì correlation bằng zero. Scale 10,000 theo stem. Thay số: 10000 × (.5^2 × .1^2+.5^2 × .2^2) = 125.00 .","trap_vi":"Không dùng bình quân volatility rồi bình phương hoặc bỏ bình phương weights."},{"stem_en":"A portfolio has $8 million in equity with beta 1.25 and $2 million in cash with beta zero. What is total portfolio beta?","options":["1.00","1.25","0.80"],"correct":0,"why_vi":"Bài luyện thêm: cash beta zero; equity weight 0.8. Thay số: 8/10 × 1.25 = 1.00 .","trap_vi":"Không dùng beta equity riêng hoặc weight riêng."}],"cards":[{"front_en":"Risk budgeting definition","back_vi":"Risk budgeting phân bổ vốn hoặc hoạt động dựa trên risk characteristics và mức risk được chấp nhận, nhằm chuyển tolerance thành quyết định thực tế. Budget có thể một chiều (volatility, beta, VaR, scenario loss) hoặc nhiều chiều; không nhất thiết chỉ dùng tiền đầu tư. | Exam trap: Capital budget không tự nói exposure risk của từng vị thế."},{"front_en":"Single-dimensional budget","back_vi":"Một risk budget có thể dùng beta target cho equity exposure, volatility target cho portfolio hoặc VaR limit cho loss quantile. Chọn thước đo phù hợp đặc điểm và horizon; một metric đơn giản có thể hữu ích nhưng không phản ánh hết tail, liquidity và dependencies. | Exam trap: Cùng volatility target không bảo đảm cùng drawdown profile."},{"front_en":"Risk factors versus asset classes","back_vi":"Những tài sản khác tên có thể cùng phụ thuộc equity market, rates, credit spreads, FX, inflation hoặc liquidity. Risk factor budgeting xem sensitivity và contribution theo driver để nhận ra concentration ẩn; cùng danh mục có nhiều cách phân rã risk đồng thời. | Exam trap: Các cách phân rã theo factor có thể không cộng thành 100% nếu overlap hoặc metric khác nhau."},{"front_en":"Risk contribution and diversification","back_vi":"Đóng góp risk phụ thuộc weights, sensitivities và covariance. Với volatility, contribution của tài sản vào risk toàn danh mục có thể khác standalone volatility và thậm chí âm nếu hedge. Budget theo contribution nên dùng cùng metric và methodology. | Exam trap: Không cộng individual VaR/volatility trừ khi có giả định phụ thuộc thích hợp."},{"front_en":"Governance bridge","back_vi":"Risk budget tạo cầu nối giữa tolerance cấp enterprise và giới hạn phân bổ cho managers, desks hoặc factors. Nó hỗ trợ so sánh incremental risk với expected reward và cho phép nhận exposure có hiệu quả hơn trong mức risk tổng thể. Budget cần review khi correlation và exposures đổi. | Exam trap: Không nhất thiết dùng hết budget nếu cơ hội không hấp dẫn."},{"front_en":"Risk budget dimensions — formula or framework?","back_vi":"Volatility, beta, VaR, scenario loss, factor exposures · Các metric có thể dùng đơn lẻ hoặc phối hợp để triển khai tolerance. · Không trộn các đơn vị khác nhau trong một tổng vô nghĩa."},{"front_en":"Portfolio beta — supplemental — formula or framework?","back_vi":"βp = Σ wiβi · Beta exposure của portfolio theo weights. · Cùng market benchmark và kỳ ước tính; bài luyện thêm."},{"front_en":"Volatility contribution — supplemental — formula or framework?","back_vi":"RCi = wi(Σw)i / σp; ΣRCi = σp · Risk contribution theo covariance matrix, không bằng capital weight. · Differentiable volatility, σp dương; ví dụ mở rộng từ PM LM1."},{"front_en":"An equity portfolio allocates 40% to beta 1.5 and 60% to beta 0.7. What is portfolio beta?","back_vi":"Bài luyện thêm: weighted beta dùng capital weights và cùng market proxy. Thay số: .4 × 1.5+.6 × .7 = 1.02 . | Không dùng simple mean hoặc tổng beta không có weights."},{"front_en":"A $20 million portfolio has a 6% stress-loss limit. Under a scenario it loses $900,000. How much unused stress-loss capacity remains, in dollars?","back_vi":"Bài luyện thêm: đổi limit % sang dollars rồi trừ scenario loss. Thay số: 20000000 × .06-900000 = 300,000.00 USD. | Không nhầm tổng budget với headroom."},{"front_en":"A two-asset portfolio has weights 0.5 each, volatilities 10% and 20%, and zero correlation. What is portfolio variance in squared decimal units, multiplied by 10,000?","back_vi":"Bài luyện thêm: variance uses squared weights; covariance term = 0 vì correlation bằng zero. Scale 10,000 theo stem. Thay số: 10000 × (.5^2 × .1^2+.5^2 × .2^2) = 125.00 . | Không dùng bình quân volatility rồi bình phương hoặc bỏ bình phương weights."},{"front_en":"A portfolio has $8 million in equity with beta 1.25 and $2 million in cash with beta zero. What is total portfolio beta?","back_vi":"Bài luyện thêm: cash beta zero; equity weight 0.8. Thay số: 8/10 × 1.25 = 1.00 . | Không dùng beta equity riêng hoặc weight riêng."}]},{"id":"CFA26-09-06-LOS06","letter":"f","title_en":"Financial and Non-Financial Sources of Risk","outcome_en":"identify financial and non-financial sources of risk and describe how they may interact","overview_vi":"Bài học 6.f: Financial and Non-Financial Sources of Risk. Học bản chất khái niệm, điều kiện áp dụng, so sánh và giải quyết tình huống. Công thức ghi supplement là bài luyện thêm; câu hỏi tiếng Anh do dự án tự biên soạn.","source":[{"id":"CFA Institute Curriculum 2026 — Portfolio Management Volume 9","pages":"Physical PDF p. 249 (LOS), 267–277 (content)"},{"id":"Kaplan SchweserNotes 2026 — Book 4, Reading 88","pages":"Physical PDF pp. 148–150"},{"id":"SAPP CFA Level I 2026 — Portfolio Management slides","pages":"Physical PDF pp. 225–231"}],"sections":[{"heading":"Financial versus non-financial sources","body":"Theo taxonomy Curriculum LM6, financial risk gồm market, credit và liquidity risk. Non-financial risk gồm settlement, legal, regulatory, accounting, tax, model, tail và operational risk; nguồn chủ yếu là quy trình hoặc yếu tố bên ngoài không thuần túy từ financial markets. Tổn thất tiền không tự làm một rủi ro thuộc financial.","trap":"Settlement và solvency risk được xếp non-financial trong Kaplan Reading 88; CFAI bàn solvency dưới mục non-financial. Không áp taxonomy này cho mọi tài liệu khác."},{"heading":"Market risk","body":"Market risk phát sinh do giá equity, interest rates, exchange rates và commodity prices thay đổi. Tác động tùy exposure, duration, beta, leverage và hedges. Không phải mọi thay đổi giá đều cùng hướng với kết quả kinh doanh.","trap":"Credit spread move có thể là market exposure; actual nonpayment là credit risk."},{"heading":"Credit risk","body":"Credit risk là khả năng counterparty hoặc borrower không thực hiện nghĩa vụ thanh toán. Phân tích khả năng default, exposure và mức recovery; với derivatives, exposure có thể thay đổi theo market value và netting/collateral. Credit deterioration có thể làm giá giảm trước default.","trap":"Không nhầm default probability với loss given default."},{"heading":"Liquidity risk","body":"Liquidity risk theo khung bài gồm khó bán tài sản ở giá hợp lý do thị trường thiếu người mua hoặc depth, đặc biệt khi vị thế lớn hoặc thị trường stress. Bid–ask spread, size, time to sell và price impact là chỉ báo; thanh khoản huy động vốn cũng có thể liên hệ solvency.","trap":"Giá giảm do rates tăng không tự động là liquidity loss."},{"heading":"Settlement and Herstatt risk","body":"Settlement risk xảy ra khi một bên đã giao tiền hoặc tài sản nhưng chưa nhận được đối ứng; timing, hệ thống thanh toán và khác múi giờ có thể làm phát sinh exposure. Delivery-versus-payment hoặc payment-versus-payment giảm rủi ro principal nếu khả thi.","trap":"Khác credit risk nói chung: dấu hiệu đặc trưng là lệch thời điểm hoàn thành hai vế."},{"heading":"Legal risk","body":"Legal risk liên quan kiện tụng, trách nhiệm pháp lý hoặc hợp đồng không thể thực thi. Ambiguous terms, jurisdiction và enforceability của netting/collateral có thể làm hedge mất hiệu lực dự kiến. Legal review và hợp đồng phù hợp giúp giảm exposure.","trap":"Regulatory risk nhấn mạnh thay đổi/tuân thủ quy định; legal có thể liên hệ nhưng không đồng nhất."},{"heading":"Regulatory risk","body":"Regulatory risk liên quan thay đổi quy định hoặc việc không tuân thủ các yêu cầu quản lý. Tổ chức có thể phải tăng capital, đổi sản phẩm hoặc chịu sanctions; compliance monitoring và scenario analysis hỗ trợ quản lý. Không đưa giả định pháp lý của một quốc gia áp dụng cho tất cả.","trap":"Không nhầm regulatory với thay đổi market prices."},{"heading":"Accounting and tax risk","body":"Accounting risk liên quan sai sót, thay đổi nguyên tắc hoặc cách ghi nhận làm biến động reported results, covenant hoặc capital. Tax risk liên quan thay đổi luật thuế, diễn giải hoặc nghĩa vụ thuế không dự kiến. Cả hai có thể tác động cash flows và decisions.","trap":"Phân biệt thuế phải nộp với chênh lệch giữa book và economic value."},{"heading":"Model risk","body":"Model risk là kết quả sai hoặc quyết định sai do model specification, assumptions, calibration, inputs hoặc cách dùng không phù hợp. Một model có thể tốt trong normal markets nhưng thất bại khi regime đổi. Validation, benchmark models và sensitivity giúp kiểm soát.","trap":"Model output không phải sự thật chắc chắn; kiểm tra input lẫn cấu trúc."},{"heading":"Tail risk","body":"Tail risk là nguy cơ extreme outcomes xảy ra thường xuyên hoặc nghiêm trọng hơn mô hình giả định, đặc biệt với fat tails và dependencies thay đổi. Curriculum xếp nó trong non-financial risks khi nhấn mạnh modeling/underestimation, dù có liên hệ chặt market risk. Dùng stress và tail metrics bổ sung.","trap":"Không đồng nhất VaR quantile với maximum loss."},{"heading":"Operational risk","body":"Operational risk bắt nguồn từ quy trình nội bộ, con người, hệ thống không đầy đủ hoặc sự kiện bên ngoài ảnh hưởng hoạt động, như lỗi nhập lệnh, fraud, IT outages hoặc thiên tai. Controls, reconciliation, access management và business continuity giúp giảm frequency hoặc severity.","trap":"Tổn thất do trader nhập sai không phải market risk chỉ vì xảy ra trong giao dịch."},{"heading":"Solvency risk","body":"Solvency risk trong cách dùng riêng của CFAI LM6 là nguy cơ tổ chức không thể tiếp tục hoạt động vì cạn tiền để đáp ứng obligations, ngay cả khi tài sản vẫn lớn hơn liabilities. Có thể phát sinh từ kết hợp market, credit, liquidity hoặc operational shocks. Ngay cả tài sản dài hạn có giá trị cũng không bảo đảm đủ cash vào ngày phải trả.","trap":"Không đánh giá khả năng tồn tại chỉ từ mark-to-market tài sản tại một thời điểm."},{"heading":"Individual risk exposures","body":"Cá nhân chịu nhiều rủi ro giống doanh nghiệp, cộng thêm health, mortality, longevity và property/casualty risks. Mortality sớm có thể làm dependents mất income; longevity có thể khiến tài sản retirement không đủ. Insurance và planning cần phù hợp cash-flow needs.","trap":"Mortality và longevity là hai hướng rủi ro khác nhau."},{"heading":"Risk interactions","body":"Risk không độc lập: market loss có thể gây margin calls, forced sales, liquidity deterioration, counterparty default và solvency stress; operational failures có thể làm exposure bị đo sai và lỗ tăng. Quan hệ có thể nonlinear, nên stress test kết hợp drivers và feedback.","trap":"Không giả định cộng các loss riêng lẻ luôn phản ánh joint stress."},{"heading":"Wrong-way risk and concentration","body":"Khi counterparty credit quality xấu đi đúng lúc positive exposure tăng, risk trở nên nghiêm trọng hơn so với giả định độc lập. Tương tự concentration vào một ngành hoặc funding source có thể làm nhiều exposures cùng suy giảm. Cần stress chung và xem collateral thực tế.","trap":"Hedge có thể tạo counterparty exposure mới; không chỉ nhìn net market sensitivity."}],"formulas":[{"name":"Risk-source taxonomy","expr":"Financial: market, credit, liquidity. Non-financial: settlement, legal, regulatory, accounting, tax, model, tail, operational.","meaning":"Phân loại theo nguồn phát sinh; solvency và personal exposures cần xét riêng.","conditions":"Taxonomy của LM6; risk interactions có thể vượt ranh giới nhóm."},{"name":"Loss severity — supplemental","expr":"LGD rate = 1 − recovery rate","meaning":"Tỷ lệ tổn thất khi default dưới giả định recovery cùng exposure.","conditions":"Không bao gồm probability of default."},{"name":"Joint stress map","expr":"Driver shock → market/credit loss → funding strain → forced sales → liquidity/solvency","meaning":"Khung nhận diện tương tác nonlinear.","conditions":"Không phải mọi shock đều diễn tiến theo chuỗi này."}],"examples":[{"question_en":"A pricing outage understates margin requirements. A market shock then forces liquidation at distressed prices. Identify the risks.","steps_vi":["Outage/failed control là operational risk; sai estimate có thể là model/data risk. Market shock tạo mark-to-market loss.","Margin/funding strain dẫn tới forced sale và liquidity loss; nếu không đáp ứng obligations có thể dẫn đến solvency risk."],"answer":"Interacting operational, market, liquidity and potentially solvency risks.","check":"Original conceptual case; conclusions conditional on the stated facts."},{"question_en":"A bond with exposure $500,000 defaults and recovers 35% of exposure. What is the conditional dollar loss?","steps_vi":["Bài luyện thêm: conditional loss = exposure minus recovery dollars.","Thay số: 500000 × (1-.35).","Kết quả: 325,000.00 USD."],"answer":"325,000.00 USD","check":"Original supplemental practice; Decimal compared with an alternate expression using Fraction (square root uses float in the second method)."},{"question_en":"A position with market value $2 million must be sold at a 3% liquidity discount, with no other price move. What is the dollar liquidity loss?","steps_vi":["Bài luyện thêm: price impact so với mark ban đầu.","Thay số: 2000000 × .03.","Kết quả: 60,000.00 USD."],"answer":"60,000.00 USD","check":"Original supplemental practice; Decimal compared with an alternate expression using Fraction (square root uses float in the second method)."}],"questions":[{"stem_en":"Which risk is classified as non-financial in this reading's taxonomy?","options":["Market risk","Credit risk","Settlement risk"],"correct":2,"why_vi":"Theo taxonomy Curriculum LM6, financial risk gồm market, credit và liquidity risk. Non-financial risk gồm settlement, legal, regulatory, accounting, tax, model, tail và operational risk; nguồn chủ yếu là quy trình hoặc yếu tố bên ngoài không thuần túy từ financial markets. Tổn thất tiền không tự làm một rủi ro thuộc financial.","trap_vi":"Settlement và solvency risk được xếp non-financial trong Kaplan Reading 88; CFAI bàn solvency dưới mục non-financial. Không áp taxonomy này cho mọi tài liệu khác."},{"stem_en":"A bond portfolio loses value after risk-free yields rise. The immediate source of loss is primarily:","options":["market risk.","settlement risk.","accounting risk."],"correct":0,"why_vi":"Market risk phát sinh do giá equity, interest rates, exchange rates và commodity prices thay đổi. Tác động tùy exposure, duration, beta, leverage và hedges. Không phải mọi thay đổi giá đều cùng hướng với kết quả kinh doanh.","trap_vi":"Credit spread move có thể là market exposure; actual nonpayment là credit risk."},{"stem_en":"A borrower fails to make a contractually required interest payment. The primary risk realized is:","options":["liquidity risk of the secondary market.","credit risk.","model risk."],"correct":1,"why_vi":"Credit risk là khả năng counterparty hoặc borrower không thực hiện nghĩa vụ thanh toán. Phân tích khả năng default, exposure và mức recovery; với derivatives, exposure có thể thay đổi theo market value và netting/collateral. Credit deterioration có thể làm giá giảm trước default.","trap_vi":"Không nhầm default probability với loss given default."},{"stem_en":"A fund must sell a large position at a substantial discount because there are few buyers. Which risk is most directly illustrated?","options":["Credit risk","Liquidity risk","Legal risk"],"correct":1,"why_vi":"Liquidity risk theo khung bài gồm khó bán tài sản ở giá hợp lý do thị trường thiếu người mua hoặc depth, đặc biệt khi vị thế lớn hoặc thị trường stress. Bid–ask spread, size, time to sell và price impact là chỉ báo; thanh khoản huy động vốn cũng có thể liên hệ solvency.","trap_vi":"Giá giảm do rates tăng không tự động là liquidity loss."},{"stem_en":"A bank pays one currency but the counterparty fails before delivering the other currency. Which risk is most specifically illustrated?","options":["Market risk alone","Tax risk","Settlement risk"],"correct":2,"why_vi":"Settlement risk xảy ra khi một bên đã giao tiền hoặc tài sản nhưng chưa nhận được đối ứng; timing, hệ thống thanh toán và khác múi giờ có thể làm phát sinh exposure. Delivery-versus-payment hoặc payment-versus-payment giảm rủi ro principal nếu khả thi.","trap_vi":"Khác credit risk nói chung: dấu hiệu đặc trưng là lệch thời điểm hoàn thành hai vế."},{"stem_en":"A court rules that an otherwise profitable derivative contract is unenforceable. The most direct risk is:","options":["market risk.","availability bias.","legal risk."],"correct":2,"why_vi":"Legal risk liên quan kiện tụng, trách nhiệm pháp lý hoặc hợp đồng không thể thực thi. Ambiguous terms, jurisdiction và enforceability của netting/collateral có thể làm hedge mất hiệu lực dự kiến. Legal review và hợp đồng phù hợp giúp giảm exposure.","trap_vi":"Regulatory risk nhấn mạnh thay đổi/tuân thủ quy định; legal có thể liên hệ nhưng không đồng nhất."},{"stem_en":"A newly imposed capital requirement materially changes the economics of a business line. Which risk is most directly illustrated?","options":["Settlement risk","Regulatory risk","Mental accounting"],"correct":1,"why_vi":"Regulatory risk liên quan thay đổi quy định hoặc việc không tuân thủ các yêu cầu quản lý. Tổ chức có thể phải tăng capital, đổi sản phẩm hoặc chịu sanctions; compliance monitoring và scenario analysis hỗ trợ quản lý. Không đưa giả định pháp lý của một quốc gia áp dụng cho tất cả.","trap_vi":"Không nhầm regulatory với thay đổi market prices."},{"stem_en":"A transaction's expected after-tax return falls after a change in tax treatment. Which risk is most directly illustrated?","options":["Settlement risk","Tax risk","Market risk"],"correct":1,"why_vi":"Accounting risk liên quan sai sót, thay đổi nguyên tắc hoặc cách ghi nhận làm biến động reported results, covenant hoặc capital. Tax risk liên quan thay đổi luật thuế, diễn giải hoặc nghĩa vụ thuế không dự kiến. Cả hai có thể tác động cash flows và decisions.","trap_vi":"Phân biệt thuế phải nộp với chênh lệch giữa book và economic value."},{"stem_en":"A pricing model materially undervalues options because it assumes an unsuitable distribution. Which risk is most direct?","options":["Model risk","Settlement risk","Regulatory risk"],"correct":0,"why_vi":"Model risk là kết quả sai hoặc quyết định sai do model specification, assumptions, calibration, inputs hoặc cách dùng không phù hợp. Một model có thể tốt trong normal markets nhưng thất bại khi regime đổi. Validation, benchmark models và sensitivity giúp kiểm soát.","trap_vi":"Model output không phải sự thật chắc chắn; kiểm tra input lẫn cấu trúc."},{"stem_en":"An institution's normal-distribution model severely understates extreme downside events. Which specific risk is highlighted?","options":["Tax risk","Endowment bias","Tail risk"],"correct":2,"why_vi":"Tail risk là nguy cơ extreme outcomes xảy ra thường xuyên hoặc nghiêm trọng hơn mô hình giả định, đặc biệt với fat tails và dependencies thay đổi. Curriculum xếp nó trong non-financial risks khi nhấn mạnh modeling/underestimation, dù có liên hệ chặt market risk. Dùng stress và tail metrics bổ sung.","trap_vi":"Không đồng nhất VaR quantile với maximum loss."},{"stem_en":"An employee enters an order with the wrong quantity due to a failed control. Which is the primary source of risk?","options":["Credit risk","Operational risk","Framing bias"],"correct":1,"why_vi":"Operational risk bắt nguồn từ quy trình nội bộ, con người, hệ thống không đầy đủ hoặc sự kiện bên ngoài ảnh hưởng hoạt động, như lỗi nhập lệnh, fraud, IT outages hoặc thiên tai. Controls, reconciliation, access management và business continuity giúp giảm frequency hoặc severity.","trap_vi":"Tổn thất do trader nhập sai không phải market risk chỉ vì xảy ra trong giao dịch."},{"stem_en":"A firm cannot meet obligations after margin calls and failed asset sales. The ultimate risk most directly threatening its survival is:","options":["hindsight bias.","solvency risk.","accounting classification risk alone."],"correct":1,"why_vi":"Solvency risk trong cách dùng riêng của CFAI LM6 là nguy cơ tổ chức không thể tiếp tục hoạt động vì cạn tiền để đáp ứng obligations, ngay cả khi tài sản vẫn lớn hơn liabilities. Có thể phát sinh từ kết hợp market, credit, liquidity hoặc operational shocks. Ngay cả tài sản dài hạn có giá trị cũng không bảo đảm đủ cash vào ngày phải trả.","trap_vi":"Không đánh giá khả năng tồn tại chỉ từ mark-to-market tài sản tại một thời điểm."},{"stem_en":"A retiree outlives the assets set aside to support retirement spending. This is most directly:","options":["settlement risk.","longevity risk.","mortality risk from premature death."],"correct":1,"why_vi":"Cá nhân chịu nhiều rủi ro giống doanh nghiệp, cộng thêm health, mortality, longevity và property/casualty risks. Mortality sớm có thể làm dependents mất income; longevity có thể khiến tài sản retirement không đủ. Insurance và planning cần phù hợp cash-flow needs.","trap_vi":"Mortality và longevity là hai hướng rủi ro khác nhau."},{"stem_en":"Which sequence best illustrates interacting risks?","options":["Independent risks always offset in equal amounts.","Market losses trigger margin calls, forcing sales into an illiquid market.","Higher reporting frequency automatically removes all risk."],"correct":1,"why_vi":"Risk không độc lập: market loss có thể gây margin calls, forced sales, liquidity deterioration, counterparty default và solvency stress; operational failures có thể làm exposure bị đo sai và lỗ tăng. Quan hệ có thể nonlinear, nên stress test kết hợp drivers và feedback.","trap_vi":"Không giả định cộng các loss riêng lẻ luôn phản ánh joint stress."},{"stem_en":"A derivative counterparty is more likely to default precisely when the contract becomes valuable to the firm. This illustrates:","options":["adverse interaction between credit and market exposure.","complete elimination of counterparty risk.","a purely operational loss unrelated to market conditions."],"correct":0,"why_vi":"Khi counterparty credit quality xấu đi đúng lúc positive exposure tăng, risk trở nên nghiêm trọng hơn so với giả định độc lập. Tương tự concentration vào một ngành hoặc funding source có thể làm nhiều exposures cùng suy giảm. Cần stress chung và xem collateral thực tế.","trap_vi":"Hedge có thể tạo counterparty exposure mới; không chỉ nhìn net market sensitivity."},{"stem_en":"A bond with exposure $500,000 defaults and recovers 35% of exposure. What is the conditional dollar loss?","options":["325,000.00 USD","175,000.00 USD","500,000.00 USD"],"correct":0,"why_vi":"Bài luyện thêm: conditional loss = exposure minus recovery dollars. Thay số: 500000 × (1-.35) = 325,000.00 USD.","trap_vi":"Không nhầm recovery amount với loss given default."},{"stem_en":"A position with market value $2 million must be sold at a 3% liquidity discount, with no other price move. What is the dollar liquidity loss?","options":["60,000.00 USD","1,940,000.00 USD","6,000.00 USD"],"correct":0,"why_vi":"Bài luyện thêm: price impact so với mark ban đầu. Thay số: 2000000 × .03 = 60,000.00 USD.","trap_vi":"Phân biệt sale proceeds và loss; 3% không phải 0.3%."}],"cards":[{"front_en":"Financial versus non-financial sources","back_vi":"Theo taxonomy Curriculum LM6, financial risk gồm market, credit và liquidity risk. Non-financial risk gồm settlement, legal, regulatory, accounting, tax, model, tail và operational risk; nguồn chủ yếu là quy trình hoặc yếu tố bên ngoài không thuần túy từ financial markets. Tổn thất tiền không tự làm một rủi ro thuộc financial. | Exam trap: Settlement và solvency risk được xếp non-financial trong Kaplan Reading 88; CFAI bàn solvency dưới mục non-financial. Không áp taxonomy này cho mọi tài liệu khác."},{"front_en":"Market risk","back_vi":"Market risk phát sinh do giá equity, interest rates, exchange rates và commodity prices thay đổi. Tác động tùy exposure, duration, beta, leverage và hedges. Không phải mọi thay đổi giá đều cùng hướng với kết quả kinh doanh. | Exam trap: Credit spread move có thể là market exposure; actual nonpayment là credit risk."},{"front_en":"Credit risk","back_vi":"Credit risk là khả năng counterparty hoặc borrower không thực hiện nghĩa vụ thanh toán. Phân tích khả năng default, exposure và mức recovery; với derivatives, exposure có thể thay đổi theo market value và netting/collateral. Credit deterioration có thể làm giá giảm trước default. | Exam trap: Không nhầm default probability với loss given default."},{"front_en":"Liquidity risk","back_vi":"Liquidity risk theo khung bài gồm khó bán tài sản ở giá hợp lý do thị trường thiếu người mua hoặc depth, đặc biệt khi vị thế lớn hoặc thị trường stress. Bid–ask spread, size, time to sell và price impact là chỉ báo; thanh khoản huy động vốn cũng có thể liên hệ solvency. | Exam trap: Giá giảm do rates tăng không tự động là liquidity loss."},{"front_en":"Settlement and Herstatt risk","back_vi":"Settlement risk xảy ra khi một bên đã giao tiền hoặc tài sản nhưng chưa nhận được đối ứng; timing, hệ thống thanh toán và khác múi giờ có thể làm phát sinh exposure. Delivery-versus-payment hoặc payment-versus-payment giảm rủi ro principal nếu khả thi. | Exam trap: Khác credit risk nói chung: dấu hiệu đặc trưng là lệch thời điểm hoàn thành hai vế."},{"front_en":"Legal risk","back_vi":"Legal risk liên quan kiện tụng, trách nhiệm pháp lý hoặc hợp đồng không thể thực thi. Ambiguous terms, jurisdiction và enforceability của netting/collateral có thể làm hedge mất hiệu lực dự kiến. Legal review và hợp đồng phù hợp giúp giảm exposure. | Exam trap: Regulatory risk nhấn mạnh thay đổi/tuân thủ quy định; legal có thể liên hệ nhưng không đồng nhất."},{"front_en":"Regulatory risk","back_vi":"Regulatory risk liên quan thay đổi quy định hoặc việc không tuân thủ các yêu cầu quản lý. Tổ chức có thể phải tăng capital, đổi sản phẩm hoặc chịu sanctions; compliance monitoring và scenario analysis hỗ trợ quản lý. Không đưa giả định pháp lý của một quốc gia áp dụng cho tất cả. | Exam trap: Không nhầm regulatory với thay đổi market prices."},{"front_en":"Accounting and tax risk","back_vi":"Accounting risk liên quan sai sót, thay đổi nguyên tắc hoặc cách ghi nhận làm biến động reported results, covenant hoặc capital. Tax risk liên quan thay đổi luật thuế, diễn giải hoặc nghĩa vụ thuế không dự kiến. Cả hai có thể tác động cash flows và decisions. | Exam trap: Phân biệt thuế phải nộp với chênh lệch giữa book và economic value."},{"front_en":"Model risk","back_vi":"Model risk là kết quả sai hoặc quyết định sai do model specification, assumptions, calibration, inputs hoặc cách dùng không phù hợp. Một model có thể tốt trong normal markets nhưng thất bại khi regime đổi. Validation, benchmark models và sensitivity giúp kiểm soát. | Exam trap: Model output không phải sự thật chắc chắn; kiểm tra input lẫn cấu trúc."},{"front_en":"Tail risk","back_vi":"Tail risk là nguy cơ extreme outcomes xảy ra thường xuyên hoặc nghiêm trọng hơn mô hình giả định, đặc biệt với fat tails và dependencies thay đổi. Curriculum xếp nó trong non-financial risks khi nhấn mạnh modeling/underestimation, dù có liên hệ chặt market risk. Dùng stress và tail metrics bổ sung. | Exam trap: Không đồng nhất VaR quantile với maximum loss."},{"front_en":"Operational risk","back_vi":"Operational risk bắt nguồn từ quy trình nội bộ, con người, hệ thống không đầy đủ hoặc sự kiện bên ngoài ảnh hưởng hoạt động, như lỗi nhập lệnh, fraud, IT outages hoặc thiên tai. Controls, reconciliation, access management và business continuity giúp giảm frequency hoặc severity. | Exam trap: Tổn thất do trader nhập sai không phải market risk chỉ vì xảy ra trong giao dịch."},{"front_en":"Solvency risk","back_vi":"Solvency risk trong cách dùng riêng của CFAI LM6 là nguy cơ tổ chức không thể tiếp tục hoạt động vì cạn tiền để đáp ứng obligations, ngay cả khi tài sản vẫn lớn hơn liabilities. Có thể phát sinh từ kết hợp market, credit, liquidity hoặc operational shocks. Ngay cả tài sản dài hạn có giá trị cũng không bảo đảm đủ cash vào ngày phải trả. | Exam trap: Không đánh giá khả năng tồn tại chỉ từ mark-to-market tài sản tại một thời điểm."},{"front_en":"Individual risk exposures","back_vi":"Cá nhân chịu nhiều rủi ro giống doanh nghiệp, cộng thêm health, mortality, longevity và property/casualty risks. Mortality sớm có thể làm dependents mất income; longevity có thể khiến tài sản retirement không đủ. Insurance và planning cần phù hợp cash-flow needs. | Exam trap: Mortality và longevity là hai hướng rủi ro khác nhau."},{"front_en":"Risk interactions","back_vi":"Risk không độc lập: market loss có thể gây margin calls, forced sales, liquidity deterioration, counterparty default và solvency stress; operational failures có thể làm exposure bị đo sai và lỗ tăng. Quan hệ có thể nonlinear, nên stress test kết hợp drivers và feedback. | Exam trap: Không giả định cộng các loss riêng lẻ luôn phản ánh joint stress."},{"front_en":"Wrong-way risk and concentration","back_vi":"Khi counterparty credit quality xấu đi đúng lúc positive exposure tăng, risk trở nên nghiêm trọng hơn so với giả định độc lập. Tương tự concentration vào một ngành hoặc funding source có thể làm nhiều exposures cùng suy giảm. Cần stress chung và xem collateral thực tế. | Exam trap: Hedge có thể tạo counterparty exposure mới; không chỉ nhìn net market sensitivity."},{"front_en":"Risk-source taxonomy — formula or framework?","back_vi":"Financial: market, credit, liquidity. Non-financial: settlement, legal, regulatory, accounting, tax, model, tail, operational. · Phân loại theo nguồn phát sinh; solvency và personal exposures cần xét riêng. · Taxonomy của LM6; risk interactions có thể vượt ranh giới nhóm."},{"front_en":"Loss severity — supplemental — formula or framework?","back_vi":"LGD rate = 1 − recovery rate · Tỷ lệ tổn thất khi default dưới giả định recovery cùng exposure. · Không bao gồm probability of default."},{"front_en":"Joint stress map — formula or framework?","back_vi":"Driver shock → market/credit loss → funding strain → forced sales → liquidity/solvency · Khung nhận diện tương tác nonlinear. · Không phải mọi shock đều diễn tiến theo chuỗi này."},{"front_en":"A bond with exposure $500,000 defaults and recovers 35% of exposure. What is the conditional dollar loss?","back_vi":"Bài luyện thêm: conditional loss = exposure minus recovery dollars. Thay số: 500000 × (1-.35) = 325,000.00 USD. | Không nhầm recovery amount với loss given default."},{"front_en":"A position with market value $2 million must be sold at a 3% liquidity discount, with no other price move. What is the dollar liquidity loss?","back_vi":"Bài luyện thêm: price impact so với mark ban đầu. Thay số: 2000000 × .03 = 60,000.00 USD. | Phân biệt sale proceeds và loss; 3% không phải 0.3%."}]},{"id":"CFA26-09-06-LOS07","letter":"g","title_en":"Measuring and Modifying Risk Exposures","outcome_en":"describe methods for measuring and modifying risk exposures and factors to consider in choosing among the methods","overview_vi":"Bài học 6.g: Measuring and Modifying Risk Exposures. Học bản chất khái niệm, điều kiện áp dụng, so sánh và giải quyết tình huống. Công thức ghi supplement là bài luyện thêm; câu hỏi tiếng Anh do dự án tự biên soạn.","source":[{"id":"CFA Institute Curriculum 2026 — Portfolio Management Volume 9","pages":"Physical PDF p. 249 (LOS), 277–294 (content)"},{"id":"Kaplan SchweserNotes 2026 — Book 4, Reading 88","pages":"Physical PDF pp. 150–152"},{"id":"SAPP CFA Level I 2026 — Portfolio Management slides","pages":"Physical PDF pp. 232–237"}],"sections":[{"heading":"Risk drivers and metrics","body":"Risk drivers là yếu tố kinh tế, ngành và thị trường tạo biến động exposure. Risk metrics mô tả mức độ nhạy hoặc phân phối tổn thất; cần chọn metric theo exposure, horizon, mục tiêu và loại risk. Không một chỉ số nào đo đầy đủ mọi risk.","trap":"Phân biệt driver (yield) và metric (duration)."},{"heading":"Standard deviation and beta","body":"Standard deviation đo độ phân tán return quanh mean, cả upside và downside. Beta đo sensitivity với market return trong bối cảnh diversified portfolio. Volatility có thể thiếu thông tin tail và liquidity; beta phụ thuộc market proxy và estimation period.","trap":"Beta không phải total risk của một tài sản đứng riêng."},{"heading":"Duration","body":"Duration là thước đo first-order sensitivity của bond price với yield. Modified duration cho xấp xỉ phần trăm giá thay đổi khi yield đổi nhỏ; dollar duration/PVBP chuyển thành tiền. Với biến động lớn cần convexity và xem option exposure.","trap":"100 basis points = 0.01 ở dạng decimal."},{"heading":"Delta and gamma","body":"Delta đo thay đổi giá derivative theo biến động nhỏ underlying; gamma đo tốc độ thay đổi delta theo underlying. Delta-neutral không đảm bảo hedge trước biến động lớn vì gamma và các driver khác. Các Greeks phải dùng đúng unit và vị thế long/short.","trap":"Gamma không đo sensitivity với implied volatility."},{"heading":"Vega and rho","body":"Vega đo sensitivity giá option với volatility, rho với interest rates. Cần biết vega được báo theo một volatility percentage point hay một đơn vị decimal; rho tương tự đối với rate. Hedge market exposure có thể thêm volatility hoặc rate exposure.","trap":"Không dùng vega như delta theo biến động underlying price."},{"heading":"Value at Risk","body":"VaR là loss threshold tại horizon và tail probability/confidence cho trước. One-day 99% VaR 2 triệu nghĩa là xác suất loss vượt ngưỡng xấp xỉ 1% theo model (với phân phối liên tục); không nói loss lớn nhất hoặc average loss khi breach. Báo cáo đầy đủ currency, horizon, confidence.","trap":"99% confidence không phải 99% xác suất mất ít nhất VaR."},{"heading":"CVaR and tail loss","body":"Conditional VaR hoặc expected shortfall đo average tail loss vượt VaR theo cách diễn đạt Curriculum. Với continuous distribution, CVaR tại confidence cố định không thấp hơn VaR; trong discrete distributions cần quy ước quantile và weighting phù hợp. Không xem nó là maximum loss.","trap":"VaR threshold khác CVaR average; không suy CVaR chỉ từ VaR."},{"heading":"VaR model limitations","body":"VaR phụ thuộc distribution, data window, parameters, correlations và method; historical, parametric và simulation có thể khác. Fat tails hoặc regime change làm estimates không đáng tin. Backtesting và stress bổ sung thông tin, nhưng cũng không bảo đảm mọi cú sốc được dự báo.","trap":"VaR nhỏ không chứng minh không có tail risk hoặc funding risk."},{"heading":"Credit risk metrics","body":"Credit assessment xem probability of default, loss severity/recovery, exposure, ratings và financial ratios. Loss given default là loss conditional on default; expected credit loss có thể dùng PD × LGD × EAD trong mô hình một kỳ đơn giản. Không nhầm conditional loss với unconditional expected loss.","trap":"Recovery rate và LGD bổ sung nhau nếu dùng cùng exposure convention."},{"heading":"Liquidity and operational metrics","body":"Liquidity có thể đánh giá bid–ask spread, market depth, time to liquidation, stress discounts và funding indicators. Operational risk khó định lượng, cần incident/loss data, controls assessment, scenarios và key risk indicators. Metrics nên tương ứng nguồn risk thay vì áp beta cho mọi vấn đề.","trap":"Spread nhỏ cho lệnh nhỏ không bảo đảm thanh khoản cho vị thế lớn."},{"heading":"Stress testing and scenario analysis","body":"Stress testing xét các biến động giá hoặc exposure cực đoan cụ thể; scenario analysis là tập hợp stress tests cùng một chủ đề hoặc một tập drivers nhất quán, ước tính effects lên portfolio/enterprise. Không nhất thiết gán probability; hữu ích với tail, nonlinear exposure và interactions mà VaR bình thường bỏ sót.","trap":"Stress loss không phải VaR nếu chưa xác định probability model."},{"heading":"Risk prevention and avoidance","body":"Avoidance là không thực hiện hoạt động tạo rủi ro không phù hợp, ví dụ không tham gia thị trường không hiểu. Prevention giảm khả năng sự kiện hoặc severity bằng controls, training, maintenance và quy trình. Lựa chọn phải cân nhắc lợi ích kinh tế bị từ bỏ.","trap":"Không coi avoidance là cách tối ưu mặc định cho rủi ro có reward hấp dẫn."},{"heading":"Risk acceptance and self-insurance","body":"Acceptance là giữ risk vì nằm trong tolerance hoặc biện pháp giảm risk quá đắt. Self-insurance giữ loss exposure và chuẩn bị reserves hoặc funding để chi trả. Khác external insurance, không chuyển exposure sang bên thứ ba. Cần xem aggregate loss và capacity.","trap":"Reserve không loại bỏ uncertainty của actual loss."},{"heading":"Diversification as mitigation","body":"Diversification phân tán exposure giữa các nguồn risk không hoàn toàn đồng biến, giảm concentration. Tác dụng phụ thuộc correlation, weights và common drivers; không loại bỏ systematic hoặc extreme joint risk. Có thể dùng kết hợp insurance, hedges và limits.","trap":"Không đơn giản tăng số holdings cùng factor."},{"heading":"Risk transfer via insurance","body":"Risk transfer trong cách phân biệt của bài chủ yếu là chuyển financial consequence của sự kiện được bảo hiểm sang insurer để đổi premium. Deductible, coverage limits, exclusions và insurer credit quality xác định residual exposure. Không phải insurance trả mọi khoản lỗ.","trap":"Premium là chi phí chắc chắn; payout phụ thuộc điều khoản và sự kiện."},{"heading":"Risk shifting via derivatives","body":"Risk shifting dùng derivatives để đổi risk profile: forwards, futures, swaps hoặc options có thể giảm FX, rate hoặc commodity exposure bằng offsetting position. Có thể phát sinh basis, counterparty, liquidity, margin hoặc premium cost. Option hedge có asymmetric payoff khác linear forward.","trap":"Hedge một risk driver không có nghĩa giảm tất cả rủi ro."},{"heading":"Insurance pooling and reinsurance","body":"Insurer tập hợp nhiều risks ít tương quan để ước tính aggregate claims, định premium và phân tán tổn thất; reinsurance chuyển một phần risk sang insurer khác. Catastrophe bonds có thể chuyển một phần disaster exposure tới investors theo trigger. Pooling khó hiệu quả khi claims cùng phụ thuộc một catastrophe.","trap":"Insurer vẫn chịu risk; pooling không triệt tiêu common shock."},{"heading":"Surety and fidelity bonds","body":"Surety bond bảo vệ bên được bảo đảm khi third party không hoàn thành nghĩa vụ theo hợp đồng; fidelity bond thường bảo vệ tổ chức trước tổn thất do employee dishonesty. Indemnity hoặc hold-harmless clauses cũng phân bổ trách nhiệm tổn thất giữa các bên. Kiểm tra scope và enforceability.","trap":"Không nhầm surety với bảo hiểm lợi nhuận đầu tư hoặc futures margin."},{"heading":"Deductibles and moral hazard","body":"Deductible giữ lại lớp loss đầu tiên cho insured, giúp giảm small claims và tạo động lực phòng ngừa; insurance chuyển phần loss được bảo hiểm vượt deductible theo limits. Exclusions và controls xử lý trường hợp không thể pool hoặc moral hazard. Có thể phối hợp self-insurance cho loss nhỏ với insurance cho loss lớn.","trap":"Deductible không phải premium; retained risk không biến mất sau khi mua policy."},{"heading":"Choosing modification methods","body":"Chọn prevention, avoidance, acceptance, transfer hoặc shifting theo expected benefit, total cost, availability, residual risk, interactions và governance objectives. Tính cả direct premiums, trading costs, foregone upside, collateral/funding và implementation risks. Giải pháp có thể kết hợp nhiều cách.","trap":"Chi phí thấp nhất riêng lẻ không đồng nghĩa phương án tốt nhất toàn enterprise."}],"formulas":[{"name":"Volatility and beta","expr":"σ = sqrt(Var(R)); βi = Cov(Ri,Rm)/Var(Rm)","meaning":"Hai thước đo total dispersion và market sensitivity.","conditions":"Cùng horizon; beta không đo toàn bộ tail risk."},{"name":"Duration approximation — supplemental","expr":"ΔP/P ≈ −Dmod Δy","meaning":"Thay đổi tương đối của bond price theo yield nhỏ.","conditions":"Yield dạng decimal; bỏ convexity chỉ phù hợp biến động nhỏ."},{"name":"Greek sensitivity — supplemental","expr":"ΔV ≈ delta × ΔS + 0.5 × gamma × (ΔS)^2","meaning":"Xấp xỉ change do underlying; vega/rho nếu volatility/rates đổi.","conditions":"Greeks tại điểm ban đầu, đơn vị nhất quán; không phải pricing model đầy đủ."},{"name":"VaR interpretation","expr":"VaRα(L) = loss quantile at confidence α","meaning":"Ngưỡng loss với tail probability 1−α; nêu horizon và currency.","conditions":"Không phải maximum loss; continuous model cho xác suất vượt gần 1−α."},{"name":"Conditional VaR","expr":"CVaRα = E[L given L > VaRα] (continuous case)","meaning":"Trung bình loss trong tail, không phải threshold.","conditions":"Discrete case cần xử lý phần mass tại quantile; ví dụ equal-weight tail rõ ràng."},{"name":"Expected credit loss — supplemental","expr":"EL = PD × LGD × EAD","meaning":"Loss kỳ vọng một kỳ với exposure và severity đã cho.","conditions":"Giả định EAD/LGD cố định hoặc conditional phù hợp; conditional loss = LGD × EAD."},{"name":"Stress scenario","expr":"Revalue positions under specified joint shocks","meaning":"Xem hậu quả adverse scenarios và dependencies.","conditions":"Không gán probability nếu chưa có model."},{"name":"Insurance payout — supplemental","expr":"Payout = min(limit, max(covered loss − deductible, 0))","meaning":"Phần loss được chuyển theo giả định deductible và payout limit.","conditions":"Chỉ áp dụng hợp đồng minh họa; premium, exclusions và credit risk riêng."},{"name":"Forward hedge — supplemental","expr":"Long foreign-currency forward: domestic cost = foreign amount × contracted rate","meaning":"Khóa chi phí FX khi notional/maturity match.","conditions":"Rate domestic per foreign; bỏ phí, credit và basis risk trong bài tính."},{"name":"Risk modification decision","expr":"Compare benefit, cost, residual risks, capacity and governance","meaning":"Chọn avoid/prevent, accept/diversify, transfer, shift hoặc kết hợp.","conditions":"Không mặc định hedging toàn phần hoặc mức phí thấp nhất tối ưu."}],"examples":[{"question_en":"An exporter wants protection against a weaker foreign currency but wishes to retain gains from a stronger one. Compare a forward and an option.","steps_vi":["Short foreign-currency forward khóa domestic receipts với notional/maturity phù hợp, bỏ upside do currency mạnh.","Put option on foreign currency tạo floor nhưng giữ upside sau premium; so sánh cost, basis, credit và liquidity."],"answer":"An option may better preserve upside, at the cost of its premium.","check":"Original conceptual case; conclusions conditional on the stated facts."},{"question_en":"A risk committee receives only a 99% one-day VaR figure. What information is missing?","steps_vi":["VaR chỉ cho threshold, không biết tail severity, model assumptions hay khả năng thanh khoản.","Bổ sung CVaR, stress scenarios, exposure concentration, liquidity and funding metrics, validation và limit context."],"answer":"VaR alone is inadequate for a full risk assessment.","check":"Original conceptual case; conclusions conditional on the stated facts."},{"question_en":"A bond portfolio worth $4 million has modified duration 5. A small parallel yield increase is 20 bps. Ignoring convexity, what is the approximate dollar change?","steps_vi":["Bài luyện thêm: Δy = 0.002, ΔP ≈ -P × duration × Δy.","Thay số: -4000000 × 5 × .002.","Kết quả: -40,000.00 USD."],"answer":"-40,000.00 USD","check":"Original supplemental practice; Decimal compared with an alternate expression using Fraction (square root uses float in the second method)."},{"question_en":"An option has delta 0.40 and gamma 0.03 per dollar. The underlying increases $4; other inputs are unchanged. What is the second-order approximate change in option value?","steps_vi":["Bài luyện thêm: delta term cộng half gamma term, đơn vị dollars per option.","Thay số: .4 × 4+.5 × .03 × 4^2.","Kết quả: 1.84 USD."],"answer":"1.84 USD","check":"Original supplemental practice; Decimal compared with an alternate expression using Fraction (square root uses float in the second method)."},{"question_en":"A portfolio has 1-day 95% VaR of $3 million. Under the model, how many of 200 independent comparable days are expected to exceed the threshold?","steps_vi":["Bài luyện thêm: tail probability 5%; expected count = n × p, không phải số ngày chắc chắn.","Thay số: 200 × .05.","Kết quả: 10.00 days."],"answer":"10.00 days","check":"Original supplemental practice; Decimal compared with an alternate expression using Fraction (square root uses float in the second method)."},{"question_en":"A discrete model has 100 equally likely loss outcomes. The worst five are $6, $8, $10, $12, and $14 million. What is the mean loss in this worst 5% tail, in millions?","steps_vi":["Bài luyện thêm: tail đã được xác định rõ, lấy average của đúng 5 outcomes.","Thay số: (6+8+10+12+14)/5.","Kết quả: 10.00 million USD."],"answer":"10.00 million USD","check":"Original supplemental practice; Decimal compared with an alternate expression using Fraction (square root uses float in the second method)."},{"question_en":"A loan has EAD $3 million, one-year PD 2%, and LGD 60%. Under a simple constant-exposure model, what is expected credit loss?","steps_vi":["Bài luyện thêm: expected default exposure 60,000, nhân conditional loss rate 60%.","Thay số: 3000000 × .02 × .6.","Kết quả: 36,000.00 USD."],"answer":"36,000.00 USD","check":"Original supplemental practice; Decimal compared with an alternate expression using Fraction (square root uses float in the second method)."},{"question_en":"An insured covered loss is $150,000; deductible $20,000; maximum insurer payout $100,000. Under the stated contract, what is the retained loss excluding premium?","steps_vi":["Bài luyện thêm: loss after deductible 130,000 nhưng cap payout 100,000. Retained = loss minus payout.","Thay số: 150000-100000.","Kết quả: 50,000.00 USD."],"answer":"50,000.00 USD","check":"Original supplemental practice; Decimal compared with an alternate expression using Fraction (square root uses float in the second method)."},{"question_en":"An importer must pay EUR 500,000 in three months. A matching forward locks USD 1.12 per EUR. Ignoring transaction costs, what is the locked dollar cost?","steps_vi":["Bài luyện thêm: mua EUR forward, quote USD per EUR nên nhân notional.","Thay số: 500000 × 1.12.","Kết quả: 560,000.00 USD."],"answer":"560,000.00 USD","check":"Original supplemental practice; Decimal compared with an alternate expression using Fraction (square root uses float in the second method)."},{"question_en":"An exporter will receive EUR 200,000. A short EUR forward locks USD 1.08 per EUR. At maturity spot is USD 1.02. Relative to an unhedged receipt, what is the dollar benefit of the hedge?","steps_vi":["Bài luyện thêm: contracted receipts trừ unhedged spot receipts; không tính cost/credit risk.","Thay số: 200000 × (1.08-1.02).","Kết quả: 12,000.00 USD."],"answer":"12,000.00 USD","check":"Original supplemental practice; Decimal compared with an alternate expression using Fraction (square root uses float in the second method)."}],"questions":[{"stem_en":"Which pairing correctly distinguishes a risk driver from a risk metric?","options":["Duration—driver; interest-rate changes—metric","Interest-rate changes—driver; duration—metric","Value at risk—driver; inflation—metric"],"correct":1,"why_vi":"Risk drivers là yếu tố kinh tế, ngành và thị trường tạo biến động exposure. Risk metrics mô tả mức độ nhạy hoặc phân phối tổn thất; cần chọn metric theo exposure, horizon, mục tiêu và loại risk. Không một chỉ số nào đo đầy đủ mọi risk.","trap_vi":"Phân biệt driver (yield) và metric (duration)."},{"stem_en":"Which measure is most directly related to systematic equity risk in a diversified portfolio?","options":["Stand-alone standard deviation only","Beta","Bid–ask spread"],"correct":1,"why_vi":"Standard deviation đo độ phân tán return quanh mean, cả upside và downside. Beta đo sensitivity với market return trong bối cảnh diversified portfolio. Volatility có thể thiếu thông tin tail và liquidity; beta phụ thuộc market proxy và estimation period.","trap_vi":"Beta không phải total risk của một tài sản đứng riêng."},{"stem_en":"For a small parallel yield change, the most directly relevant fixed-income risk metric is:","options":["equity beta.","option vega.","modified duration."],"correct":2,"why_vi":"Duration là thước đo first-order sensitivity của bond price với yield. Modified duration cho xấp xỉ phần trăm giá thay đổi khi yield đổi nhỏ; dollar duration/PVBP chuyển thành tiền. Với biến động lớn cần convexity và xem option exposure.","trap_vi":"100 basis points = 0.01 ở dạng decimal."},{"stem_en":"A delta-neutral option portfolio loses money after a large underlying price movement. Which omitted sensitivity is most directly relevant?","options":["Gamma","Rho","Credit recovery rate"],"correct":0,"why_vi":"Delta đo thay đổi giá derivative theo biến động nhỏ underlying; gamma đo tốc độ thay đổi delta theo underlying. Delta-neutral không đảm bảo hedge trước biến động lớn vì gamma và các driver khác. Các Greeks phải dùng đúng unit và vị thế long/short.","trap_vi":"Gamma không đo sensitivity với implied volatility."},{"stem_en":"Which metric measures the change in an option's value associated with a change in implied volatility?","options":["Vega","Gamma","Duration of the underlying bond alone"],"correct":0,"why_vi":"Vega đo sensitivity giá option với volatility, rho với interest rates. Cần biết vega được báo theo một volatility percentage point hay một đơn vị decimal; rho tương tự đối với rate. Hedge market exposure có thể thêm volatility hoặc rate exposure.","trap_vi":"Không dùng vega như delta theo biến động underlying price."},{"stem_en":"A one-day 95% VaR of $4 million is best interpreted as:","options":["the maximum possible loss on any day.","the average loss on the worst 5% of days.","a loss threshold exceeded with about 5% probability under the model."],"correct":2,"why_vi":"VaR là loss threshold tại horizon và tail probability/confidence cho trước. One-day 99% VaR 2 triệu nghĩa là xác suất loss vượt ngưỡng xấp xỉ 1% theo model (với phân phối liên tục); không nói loss lớn nhất hoặc average loss khi breach. Báo cáo đầy đủ currency, horizon, confidence.","trap_vi":"99% confidence không phải 99% xác suất mất ít nhất VaR."},{"stem_en":"Which metric is intended to describe average loss in the extreme tail beyond the VaR threshold?","options":["Beta","Modified duration","Conditional VaR"],"correct":2,"why_vi":"Conditional VaR hoặc expected shortfall đo average tail loss vượt VaR theo cách diễn đạt Curriculum. Với continuous distribution, CVaR tại confidence cố định không thấp hơn VaR; trong discrete distributions cần quy ước quantile và weighting phù hợp. Không xem nó là maximum loss.","trap_vi":"VaR threshold khác CVaR average; không suy CVaR chỉ từ VaR."},{"stem_en":"Two models produce different VaR estimates for the same portfolio. The most appropriate interpretation is that:","options":["one model necessarily establishes the maximum possible loss.","the portfolio has no measurable risk.","VaR depends on assumptions and inputs and should be supplemented by other analyses."],"correct":2,"why_vi":"VaR phụ thuộc distribution, data window, parameters, correlations và method; historical, parametric và simulation có thể khác. Fat tails hoặc regime change làm estimates không đáng tin. Backtesting và stress bổ sung thông tin, nhưng cũng không bảo đảm mọi cú sốc được dự báo.","trap_vi":"VaR nhỏ không chứng minh không có tail risk hoặc funding risk."},{"stem_en":"Holding exposure and recovery fixed, which change increases expected credit loss?","options":["A higher probability of default","A lower probability of default","A higher recovery rate"],"correct":0,"why_vi":"Credit assessment xem probability of default, loss severity/recovery, exposure, ratings và financial ratios. Loss given default là loss conditional on default; expected credit loss có thể dùng PD × LGD × EAD trong mô hình một kỳ đơn giản. Không nhầm conditional loss với unconditional expected loss.","trap_vi":"Recovery rate và LGD bổ sung nhau nếu dùng cùng exposure convention."},{"stem_en":"Which metric is most directly useful in assessing market liquidity risk?","options":["The option's gamma alone","An investor's subjective loss aversion","Estimated price impact of liquidating the position"],"correct":2,"why_vi":"Liquidity có thể đánh giá bid–ask spread, market depth, time to liquidation, stress discounts và funding indicators. Operational risk khó định lượng, cần incident/loss data, controls assessment, scenarios và key risk indicators. Metrics nên tương ứng nguồn risk thay vì áp beta cho mọi vấn đề.","trap_vi":"Spread nhỏ cho lệnh nhỏ không bảo đảm thanh khoản cho vị thế lớn."},{"stem_en":"What is a principal advantage of scenario analysis relative to relying only on normal-market volatility?","options":["It guarantees a correct probability for every scenario.","It eliminates the need to identify risk drivers.","It can examine joint adverse shocks and nonlinear losses."],"correct":2,"why_vi":"Stress testing xét các biến động giá hoặc exposure cực đoan cụ thể; scenario analysis là tập hợp stress tests cùng một chủ đề hoặc một tập drivers nhất quán, ước tính effects lên portfolio/enterprise. Không nhất thiết gán probability; hữu ích với tail, nonlinear exposure và interactions mà VaR bình thường bỏ sót.","trap_vi":"Stress loss không phải VaR nếu chưa xác định probability model."},{"stem_en":"A firm decides not to enter a business with unacceptable legal exposure. This is most directly:","options":["risk shifting.","risk avoidance.","risk transfer through insurance."],"correct":1,"why_vi":"Avoidance là không thực hiện hoạt động tạo rủi ro không phù hợp, ví dụ không tham gia thị trường không hiểu. Prevention giảm khả năng sự kiện hoặc severity bằng controls, training, maintenance và quy trình. Lựa chọn phải cân nhắc lợi ích kinh tế bị từ bỏ.","trap_vi":"Không coi avoidance là cách tối ưu mặc định cho rủi ro có reward hấp dẫn."},{"stem_en":"A company retains expected small losses and sets aside funds to absorb them. This is best described as:","options":["risk transfer to an insurer.","self-insurance.","risk avoidance."],"correct":1,"why_vi":"Acceptance là giữ risk vì nằm trong tolerance hoặc biện pháp giảm risk quá đắt. Self-insurance giữ loss exposure và chuẩn bị reserves hoặc funding để chi trả. Khác external insurance, không chuyển exposure sang bên thứ ba. Cần xem aggregate loss và capacity.","trap_vi":"Reserve không loại bỏ uncertainty của actual loss."},{"stem_en":"A manager reduces concentration by combining exposures with imperfectly correlated losses. This is primarily:","options":["internal risk mitigation through diversification.","risk transfer through an insurance contract.","avoidance of all market risk."],"correct":0,"why_vi":"Diversification phân tán exposure giữa các nguồn risk không hoàn toàn đồng biến, giảm concentration. Tác dụng phụ thuộc correlation, weights và common drivers; không loại bỏ systematic hoặc extreme joint risk. Có thể dùng kết hợp insurance, hedges và limits.","trap_vi":"Không đơn giản tăng số holdings cùng factor."},{"stem_en":"A business buys a policy that reimburses covered fire losses above a deductible. This is primarily:","options":["risk shifting through a forward contract.","risk transfer.","risk acceptance without mitigation."],"correct":1,"why_vi":"Risk transfer trong cách phân biệt của bài chủ yếu là chuyển financial consequence của sự kiện được bảo hiểm sang insurer để đổi premium. Deductible, coverage limits, exclusions và insurer credit quality xác định residual exposure. Không phải insurance trả mọi khoản lỗ.","trap_vi":"Premium là chi phí chắc chắn; payout phụ thuộc điều khoản và sự kiện."},{"stem_en":"An importer fixes the exchange rate for a future foreign-currency payment using a forward. This is primarily:","options":["risk shifting.","self-insurance.","risk avoidance by ceasing imports."],"correct":0,"why_vi":"Risk shifting dùng derivatives để đổi risk profile: forwards, futures, swaps hoặc options có thể giảm FX, rate hoặc commodity exposure bằng offsetting position. Có thể phát sinh basis, counterparty, liquidity, margin hoặc premium cost. Option hedge có asymmetric payoff khác linear forward.","trap_vi":"Hedge một risk driver không có nghĩa giảm tất cả rủi ro."},{"stem_en":"An insurer transfers part of its concentrated catastrophe exposure to another insurer. This is best described as:","options":["reinsurance.","self-insurance.","risk avoidance by canceling all coverage."],"correct":0,"why_vi":"Insurer tập hợp nhiều risks ít tương quan để ước tính aggregate claims, định premium và phân tán tổn thất; reinsurance chuyển một phần risk sang insurer khác. Catastrophe bonds có thể chuyển một phần disaster exposure tới investors theo trigger. Pooling khó hiệu quả khi claims cùng phụ thuộc một catastrophe.","trap_vi":"Insurer vẫn chịu risk; pooling không triệt tiêu common shock."},{"stem_en":"A company wants coverage if a contractor fails to perform a specified contractual obligation. Which instrument is most directly relevant?","options":["A long equity index future","A fidelity bond covering employee theft","A surety bond"],"correct":2,"why_vi":"Surety bond bảo vệ bên được bảo đảm khi third party không hoàn thành nghĩa vụ theo hợp đồng; fidelity bond thường bảo vệ tổ chức trước tổn thất do employee dishonesty. Indemnity hoặc hold-harmless clauses cũng phân bổ trách nhiệm tổn thất giữa các bên. Kiểm tra scope và enforceability.","trap_vi":"Không nhầm surety với bảo hiểm lợi nhuận đầu tư hoặc futures margin."},{"stem_en":"Why might an insurance contract include a deductible?","options":["To make every covered loss costless to the insured","To retain part of the loss with the insured and reduce incentives for avoidable claims","To remove all underwriting risk from the insurer"],"correct":1,"why_vi":"Deductible giữ lại lớp loss đầu tiên cho insured, giúp giảm small claims và tạo động lực phòng ngừa; insurance chuyển phần loss được bảo hiểm vượt deductible theo limits. Exclusions và controls xử lý trường hợp không thể pool hoặc moral hazard. Có thể phối hợp self-insurance cho loss nhỏ với insurance cho loss lớn.","trap_vi":"Deductible không phải premium; retained risk không biến mất sau khi mua policy."},{"stem_en":"Which consideration is most appropriate when choosing a risk modification method?","options":["Only the lowest upfront cash payment","Only the largest possible reduction of one isolated risk metric","The net benefit and residual enterprise risk relative to governance objectives"],"correct":2,"why_vi":"Chọn prevention, avoidance, acceptance, transfer hoặc shifting theo expected benefit, total cost, availability, residual risk, interactions và governance objectives. Tính cả direct premiums, trading costs, foregone upside, collateral/funding và implementation risks. Giải pháp có thể kết hợp nhiều cách.","trap_vi":"Chi phí thấp nhất riêng lẻ không đồng nghĩa phương án tốt nhất toàn enterprise."},{"stem_en":"A bond portfolio worth $4 million has modified duration 5. A small parallel yield increase is 20 bps. Ignoring convexity, what is the approximate dollar change?","options":["-40,000.00 USD","40,000.00 USD","-400,000.00 USD"],"correct":0,"why_vi":"Bài luyện thêm: Δy = 0.002, ΔP ≈ -P × duration × Δy. Thay số: -4000000 × 5 × .002 = -40,000.00 USD.","trap_vi":"Dấu âm khi yields tăng; 20 bps không phải 2%."},{"stem_en":"An option has delta 0.40 and gamma 0.03 per dollar. The underlying increases $4; other inputs are unchanged. What is the second-order approximate change in option value?","options":["1.84 USD","1.60 USD","2.08 USD"],"correct":0,"why_vi":"Bài luyện thêm: delta term cộng half gamma term, đơn vị dollars per option. Thay số: .4 × 4+.5 × .03 × 4^2 = 1.84 USD.","trap_vi":"Không bỏ gamma hoặc bỏ hệ số 1/2."},{"stem_en":"A portfolio has 1-day 95% VaR of $3 million. Under the model, how many of 200 independent comparable days are expected to exceed the threshold?","options":["10.00 days","190.00 days","5.00 days"],"correct":0,"why_vi":"Bài luyện thêm: tail probability 5%; expected count = n × p, không phải số ngày chắc chắn. Thay số: 200 × .05 = 10.00 days.","trap_vi":"95% là confidence, không phải breach probability."},{"stem_en":"A discrete model has 100 equally likely loss outcomes. The worst five are $6, $8, $10, $12, and $14 million. What is the mean loss in this worst 5% tail, in millions?","options":["6.00 million USD","14.00 million USD","10.00 million USD"],"correct":2,"why_vi":"Bài luyện thêm: tail đã được xác định rõ, lấy average của đúng 5 outcomes. Thay số: (6+8+10+12+14)/5 = 10.00 million USD.","trap_vi":"Không nhầm smallest tail loss hay maximum loss với mean tail loss."},{"stem_en":"A loan has EAD $3 million, one-year PD 2%, and LGD 60%. Under a simple constant-exposure model, what is expected credit loss?","options":["36,000.00 USD","1,800,000.00 USD","24,000.00 USD"],"correct":0,"why_vi":"Bài luyện thêm: expected default exposure 60,000, nhân conditional loss rate 60%. Thay số: 3000000 × .02 × .6 = 36,000.00 USD.","trap_vi":"Không nhầm unconditional expected loss với conditional loss hoặc recovery."},{"stem_en":"An insured covered loss is $150,000; deductible $20,000; maximum insurer payout $100,000. Under the stated contract, what is the retained loss excluding premium?","options":["50,000.00 USD","20,000.00 USD","30,000.00 USD"],"correct":0,"why_vi":"Bài luyện thêm: loss after deductible 130,000 nhưng cap payout 100,000. Retained = loss minus payout. Thay số: 150000-100000 = 50,000.00 USD.","trap_vi":"Retained loss gồm deductible và phần vượt coverage cap."},{"stem_en":"An importer must pay EUR 500,000 in three months. A matching forward locks USD 1.12 per EUR. Ignoring transaction costs, what is the locked dollar cost?","options":["446,428.57 USD","560,000.00 USD","500,000.00 USD"],"correct":1,"why_vi":"Bài luyện thêm: mua EUR forward, quote USD per EUR nên nhân notional. Thay số: 500000 × 1.12 = 560,000.00 USD.","trap_vi":"Không đảo quote hoặc bỏ FX rate."},{"stem_en":"An exporter will receive EUR 200,000. A short EUR forward locks USD 1.08 per EUR. At maturity spot is USD 1.02. Relative to an unhedged receipt, what is the dollar benefit of the hedge?","options":["-12,000.00 USD","216,000.00 USD","12,000.00 USD"],"correct":2,"why_vi":"Bài luyện thêm: contracted receipts trừ unhedged spot receipts; không tính cost/credit risk. Thay số: 200000 × (1.08-1.02) = 12,000.00 USD.","trap_vi":"Không đảo dấu hoặc nhầm total locked proceeds với incremental benefit."}],"cards":[{"front_en":"Risk drivers and metrics","back_vi":"Risk drivers là yếu tố kinh tế, ngành và thị trường tạo biến động exposure. Risk metrics mô tả mức độ nhạy hoặc phân phối tổn thất; cần chọn metric theo exposure, horizon, mục tiêu và loại risk. Không một chỉ số nào đo đầy đủ mọi risk. | Exam trap: Phân biệt driver (yield) và metric (duration)."},{"front_en":"Standard deviation and beta","back_vi":"Standard deviation đo độ phân tán return quanh mean, cả upside và downside. Beta đo sensitivity với market return trong bối cảnh diversified portfolio. Volatility có thể thiếu thông tin tail và liquidity; beta phụ thuộc market proxy và estimation period. | Exam trap: Beta không phải total risk của một tài sản đứng riêng."},{"front_en":"Duration","back_vi":"Duration là thước đo first-order sensitivity của bond price với yield. Modified duration cho xấp xỉ phần trăm giá thay đổi khi yield đổi nhỏ; dollar duration/PVBP chuyển thành tiền. Với biến động lớn cần convexity và xem option exposure. | Exam trap: 100 basis points = 0.01 ở dạng decimal."},{"front_en":"Delta and gamma","back_vi":"Delta đo thay đổi giá derivative theo biến động nhỏ underlying; gamma đo tốc độ thay đổi delta theo underlying. Delta-neutral không đảm bảo hedge trước biến động lớn vì gamma và các driver khác. Các Greeks phải dùng đúng unit và vị thế long/short. | Exam trap: Gamma không đo sensitivity với implied volatility."},{"front_en":"Vega and rho","back_vi":"Vega đo sensitivity giá option với volatility, rho với interest rates. Cần biết vega được báo theo một volatility percentage point hay một đơn vị decimal; rho tương tự đối với rate. Hedge market exposure có thể thêm volatility hoặc rate exposure. | Exam trap: Không dùng vega như delta theo biến động underlying price."},{"front_en":"Value at Risk","back_vi":"VaR là loss threshold tại horizon và tail probability/confidence cho trước. One-day 99% VaR 2 triệu nghĩa là xác suất loss vượt ngưỡng xấp xỉ 1% theo model (với phân phối liên tục); không nói loss lớn nhất hoặc average loss khi breach. Báo cáo đầy đủ currency, horizon, confidence. | Exam trap: 99% confidence không phải 99% xác suất mất ít nhất VaR."},{"front_en":"CVaR and tail loss","back_vi":"Conditional VaR hoặc expected shortfall đo average tail loss vượt VaR theo cách diễn đạt Curriculum. Với continuous distribution, CVaR tại confidence cố định không thấp hơn VaR; trong discrete distributions cần quy ước quantile và weighting phù hợp. Không xem nó là maximum loss. | Exam trap: VaR threshold khác CVaR average; không suy CVaR chỉ từ VaR."},{"front_en":"VaR model limitations","back_vi":"VaR phụ thuộc distribution, data window, parameters, correlations và method; historical, parametric và simulation có thể khác. Fat tails hoặc regime change làm estimates không đáng tin. Backtesting và stress bổ sung thông tin, nhưng cũng không bảo đảm mọi cú sốc được dự báo. | Exam trap: VaR nhỏ không chứng minh không có tail risk hoặc funding risk."},{"front_en":"Credit risk metrics","back_vi":"Credit assessment xem probability of default, loss severity/recovery, exposure, ratings và financial ratios. Loss given default là loss conditional on default; expected credit loss có thể dùng PD × LGD × EAD trong mô hình một kỳ đơn giản. Không nhầm conditional loss với unconditional expected loss. | Exam trap: Recovery rate và LGD bổ sung nhau nếu dùng cùng exposure convention."},{"front_en":"Liquidity and operational metrics","back_vi":"Liquidity có thể đánh giá bid–ask spread, market depth, time to liquidation, stress discounts và funding indicators. Operational risk khó định lượng, cần incident/loss data, controls assessment, scenarios và key risk indicators. Metrics nên tương ứng nguồn risk thay vì áp beta cho mọi vấn đề. | Exam trap: Spread nhỏ cho lệnh nhỏ không bảo đảm thanh khoản cho vị thế lớn."},{"front_en":"Stress testing and scenario analysis","back_vi":"Stress testing xét các biến động giá hoặc exposure cực đoan cụ thể; scenario analysis là tập hợp stress tests cùng một chủ đề hoặc một tập drivers nhất quán, ước tính effects lên portfolio/enterprise. Không nhất thiết gán probability; hữu ích với tail, nonlinear exposure và interactions mà VaR bình thường bỏ sót. | Exam trap: Stress loss không phải VaR nếu chưa xác định probability model."},{"front_en":"Risk prevention and avoidance","back_vi":"Avoidance là không thực hiện hoạt động tạo rủi ro không phù hợp, ví dụ không tham gia thị trường không hiểu. Prevention giảm khả năng sự kiện hoặc severity bằng controls, training, maintenance và quy trình. Lựa chọn phải cân nhắc lợi ích kinh tế bị từ bỏ. | Exam trap: Không coi avoidance là cách tối ưu mặc định cho rủi ro có reward hấp dẫn."},{"front_en":"Risk acceptance and self-insurance","back_vi":"Acceptance là giữ risk vì nằm trong tolerance hoặc biện pháp giảm risk quá đắt. Self-insurance giữ loss exposure và chuẩn bị reserves hoặc funding để chi trả. Khác external insurance, không chuyển exposure sang bên thứ ba. Cần xem aggregate loss và capacity. | Exam trap: Reserve không loại bỏ uncertainty của actual loss."},{"front_en":"Diversification as mitigation","back_vi":"Diversification phân tán exposure giữa các nguồn risk không hoàn toàn đồng biến, giảm concentration. Tác dụng phụ thuộc correlation, weights và common drivers; không loại bỏ systematic hoặc extreme joint risk. Có thể dùng kết hợp insurance, hedges và limits. | Exam trap: Không đơn giản tăng số holdings cùng factor."},{"front_en":"Risk transfer via insurance","back_vi":"Risk transfer trong cách phân biệt của bài chủ yếu là chuyển financial consequence của sự kiện được bảo hiểm sang insurer để đổi premium. Deductible, coverage limits, exclusions và insurer credit quality xác định residual exposure. Không phải insurance trả mọi khoản lỗ. | Exam trap: Premium là chi phí chắc chắn; payout phụ thuộc điều khoản và sự kiện."},{"front_en":"Risk shifting via derivatives","back_vi":"Risk shifting dùng derivatives để đổi risk profile: forwards, futures, swaps hoặc options có thể giảm FX, rate hoặc commodity exposure bằng offsetting position. Có thể phát sinh basis, counterparty, liquidity, margin hoặc premium cost. Option hedge có asymmetric payoff khác linear forward. | Exam trap: Hedge một risk driver không có nghĩa giảm tất cả rủi ro."},{"front_en":"Insurance pooling and reinsurance","back_vi":"Insurer tập hợp nhiều risks ít tương quan để ước tính aggregate claims, định premium và phân tán tổn thất; reinsurance chuyển một phần risk sang insurer khác. Catastrophe bonds có thể chuyển một phần disaster exposure tới investors theo trigger. Pooling khó hiệu quả khi claims cùng phụ thuộc một catastrophe. | Exam trap: Insurer vẫn chịu risk; pooling không triệt tiêu common shock."},{"front_en":"Surety and fidelity bonds","back_vi":"Surety bond bảo vệ bên được bảo đảm khi third party không hoàn thành nghĩa vụ theo hợp đồng; fidelity bond thường bảo vệ tổ chức trước tổn thất do employee dishonesty. Indemnity hoặc hold-harmless clauses cũng phân bổ trách nhiệm tổn thất giữa các bên. Kiểm tra scope và enforceability. | Exam trap: Không nhầm surety với bảo hiểm lợi nhuận đầu tư hoặc futures margin."},{"front_en":"Deductibles and moral hazard","back_vi":"Deductible giữ lại lớp loss đầu tiên cho insured, giúp giảm small claims và tạo động lực phòng ngừa; insurance chuyển phần loss được bảo hiểm vượt deductible theo limits. Exclusions và controls xử lý trường hợp không thể pool hoặc moral hazard. Có thể phối hợp self-insurance cho loss nhỏ với insurance cho loss lớn. | Exam trap: Deductible không phải premium; retained risk không biến mất sau khi mua policy."},{"front_en":"Choosing modification methods","back_vi":"Chọn prevention, avoidance, acceptance, transfer hoặc shifting theo expected benefit, total cost, availability, residual risk, interactions và governance objectives. Tính cả direct premiums, trading costs, foregone upside, collateral/funding và implementation risks. Giải pháp có thể kết hợp nhiều cách. | Exam trap: Chi phí thấp nhất riêng lẻ không đồng nghĩa phương án tốt nhất toàn enterprise."},{"front_en":"Volatility and beta — formula or framework?","back_vi":"σ = sqrt(Var(R)); βi = Cov(Ri,Rm)/Var(Rm) · Hai thước đo total dispersion và market sensitivity. · Cùng horizon; beta không đo toàn bộ tail risk."},{"front_en":"Duration approximation — supplemental — formula or framework?","back_vi":"ΔP/P ≈ −Dmod Δy · Thay đổi tương đối của bond price theo yield nhỏ. · Yield dạng decimal; bỏ convexity chỉ phù hợp biến động nhỏ."},{"front_en":"Greek sensitivity — supplemental — formula or framework?","back_vi":"ΔV ≈ delta × ΔS + 0.5 × gamma × (ΔS)^2 · Xấp xỉ change do underlying; vega/rho nếu volatility/rates đổi. · Greeks tại điểm ban đầu, đơn vị nhất quán; không phải pricing model đầy đủ."},{"front_en":"VaR interpretation — formula or framework?","back_vi":"VaRα(L) = loss quantile at confidence α · Ngưỡng loss với tail probability 1−α; nêu horizon và currency. · Không phải maximum loss; continuous model cho xác suất vượt gần 1−α."},{"front_en":"Conditional VaR — formula or framework?","back_vi":"CVaRα = E[L given L > VaRα] (continuous case) · Trung bình loss trong tail, không phải threshold. · Discrete case cần xử lý phần mass tại quantile; ví dụ equal-weight tail rõ ràng."},{"front_en":"Expected credit loss — supplemental — formula or framework?","back_vi":"EL = PD × LGD × EAD · Loss kỳ vọng một kỳ với exposure và severity đã cho. · Giả định EAD/LGD cố định hoặc conditional phù hợp; conditional loss = LGD × EAD."},{"front_en":"Stress scenario — formula or framework?","back_vi":"Revalue positions under specified joint shocks · Xem hậu quả adverse scenarios và dependencies. · Không gán probability nếu chưa có model."},{"front_en":"Insurance payout — supplemental — formula or framework?","back_vi":"Payout = min(limit, max(covered loss − deductible, 0)) · Phần loss được chuyển theo giả định deductible và payout limit. · Chỉ áp dụng hợp đồng minh họa; premium, exclusions và credit risk riêng."},{"front_en":"Forward hedge — supplemental — formula or framework?","back_vi":"Long foreign-currency forward: domestic cost = foreign amount × contracted rate · Khóa chi phí FX khi notional/maturity match. · Rate domestic per foreign; bỏ phí, credit và basis risk trong bài tính."},{"front_en":"Risk modification decision — formula or framework?","back_vi":"Compare benefit, cost, residual risks, capacity and governance · Chọn avoid/prevent, accept/diversify, transfer, shift hoặc kết hợp. · Không mặc định hedging toàn phần hoặc mức phí thấp nhất tối ưu."},{"front_en":"A bond portfolio worth $4 million has modified duration 5. A small parallel yield increase is 20 bps. Ignoring convexity, what is the approximate dollar change?","back_vi":"Bài luyện thêm: Δy = 0.002, ΔP ≈ -P × duration × Δy. Thay số: -4000000 × 5 × .002 = -40,000.00 USD. | Dấu âm khi yields tăng; 20 bps không phải 2%."},{"front_en":"An option has delta 0.40 and gamma 0.03 per dollar. The underlying increases $4; other inputs are unchanged. What is the second-order approximate change in option value?","back_vi":"Bài luyện thêm: delta term cộng half gamma term, đơn vị dollars per option. Thay số: .4 × 4+.5 × .03 × 4^2 = 1.84 USD. | Không bỏ gamma hoặc bỏ hệ số 1/2."},{"front_en":"A portfolio has 1-day 95% VaR of $3 million. Under the model, how many of 200 independent comparable days are expected to exceed the threshold?","back_vi":"Bài luyện thêm: tail probability 5%; expected count = n × p, không phải số ngày chắc chắn. Thay số: 200 × .05 = 10.00 days. | 95% là confidence, không phải breach probability."},{"front_en":"A discrete model has 100 equally likely loss outcomes. The worst five are $6, $8, $10, $12, and $14 million. What is the mean loss in this worst 5% tail, in millions?","back_vi":"Bài luyện thêm: tail đã được xác định rõ, lấy average của đúng 5 outcomes. Thay số: (6+8+10+12+14)/5 = 10.00 million USD. | Không nhầm smallest tail loss hay maximum loss với mean tail loss."},{"front_en":"A loan has EAD $3 million, one-year PD 2%, and LGD 60%. Under a simple constant-exposure model, what is expected credit loss?","back_vi":"Bài luyện thêm: expected default exposure 60,000, nhân conditional loss rate 60%. Thay số: 3000000 × .02 × .6 = 36,000.00 USD. | Không nhầm unconditional expected loss với conditional loss hoặc recovery."},{"front_en":"An insured covered loss is $150,000; deductible $20,000; maximum insurer payout $100,000. Under the stated contract, what is the retained loss excluding premium?","back_vi":"Bài luyện thêm: loss after deductible 130,000 nhưng cap payout 100,000. Retained = loss minus payout. Thay số: 150000-100000 = 50,000.00 USD. | Retained loss gồm deductible và phần vượt coverage cap."},{"front_en":"An importer must pay EUR 500,000 in three months. A matching forward locks USD 1.12 per EUR. Ignoring transaction costs, what is the locked dollar cost?","back_vi":"Bài luyện thêm: mua EUR forward, quote USD per EUR nên nhân notional. Thay số: 500000 × 1.12 = 560,000.00 USD. | Không đảo quote hoặc bỏ FX rate."},{"front_en":"An exporter will receive EUR 200,000. A short EUR forward locks USD 1.08 per EUR. At maturity spot is USD 1.02. Relative to an unhedged receipt, what is the dollar benefit of the hedge?","back_vi":"Bài luyện thêm: contracted receipts trừ unhedged spot receipts; không tính cost/credit risk. Thay số: 200000 × (1.08-1.02) = 12,000.00 USD. | Không đảo dấu hoặc nhầm total locked proceeds với incremental benefit."}]}]}];
